INSERT INTO safety_incidents VALUES ('cc08253b06eecba8c48ea9ec6eb30ef7442b4371', 'Health Canada', '2026-05-07', 2026, '2026-05', 'Canada', 'Canada', '', 'Medical Devices', 'Unauthorized health products, including drugs, natural health products and medical devices, sold online', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Read the information Health Canada has posted on the dangers of buying&nbsp;drugs,&nbsp;natural health products&nbsp;or&nbsp;medical devices online.Look for health products that have been authorized by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Medicine Number (DIN-HM).&nbsp;Consumers can also check whether products have been authorized for sale by searching Health Canada''s&nbsp;Drug Product Database', '82041');
