INSERT INTO safety_incidents VALUES ('7eb1080641aa9ff2303f0b6f997cee0d50a52b0e', 'Health Canada', '2026-04-30', 2026, '2026-04', 'Canada', 'Canada', '', 'Toys & Childcare', 'Stephan Baby Boo Bunnie and Friends Comfort Toys—Distilled Water Filled Cube Component', 'Injury', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled toy’s plastic cube and take it away from children.&nbsp; Consumers should contact Stephan Baby for a refund or store credit. Consumers with proof of purchase will receive a full refund. Consumers without proof of purchase will receive store credit. Consumers will be asked to write in permanent marker “Recalled” on the indented area of the cube and upload a photo of the toy and the marked cube to https://recall.stephanbaby.com/&nbsp;to receive ', '82006');
