INSERT INTO safety_incidents VALUES ('2485cf2cf6eee1af274a73b94872f46650066a2d', 'Health Canada', '2026-04-16', 2026, '2026-04', 'Canada', 'Canada', '', 'Electrical & Electronics', 'ATX Computer Power Supplies', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should stop using the recalled computer power supplies immediately and contact Apex Gaming PCs Inc. for a free remedy. The company will provide, at no cost a permanent, heat-resistant adhesive safety label containing appropriate electrical shock hazard and “No User-Serviceable Parts” warnings to be affixed to the unit. Or a replacement unit will be shipped free of charge, and consumers will be provided with instructions and a prepaid shipping label to return the original unit. Consumer', '81804');
INSERT INTO safety_incidents VALUES ('cc73f5aa9a5ab96b6676ce0845b503da5200d516', 'Health Canada', '2026-04-16', 2026, '2026-04', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Fisher & Paykel Branded 30”, 36” & 48” Freestanding Professional Gas Ranges with a gas oven', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;stop using&nbsp;the recalled&nbsp;oven until it has been inspected and serviced.&nbsp;Consumers may continue to use the stovetop.For more information, consumers can contact Fisher &amp; Paykel by telephone at 1-866-936-7872, Option 2, during normal business hours Monday to Friday, 8 am to 8 pm EST, by email at rbservicecanada@fisherpaykel.com with the Title “Ignitor Inspection”, or visit the company website.Joint recall with Health Canada, the United States', '81825');
INSERT INTO safety_incidents VALUES ('080b78c4aa7f13a9123713beb18eda81a41f1e99', 'Health Canada', '2026-04-16', 2026, '2026-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'Generac portable generators', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;stop using&nbsp;the recalled&nbsp;portable generators&nbsp;and&nbsp;contact Generac&nbsp;to&nbsp;determine&nbsp;if their product is included in this recall.&nbsp;If your unit is included in the&nbsp;recall, and&nbsp;has either not yet been filled with fuel or&nbsp;exhibited&nbsp;leakage after fueling as described above, please contact your dealer to arrange for a free repair at the dealer’s location.&nbsp;&nbsp;&nbsp;For more information, consumers can cont', '81890');
