INSERT INTO safety_incidents VALUES ('7b1cec07d4ef66a11fdb2f0d20eb84278bcea73f', 'Health Canada', '2026-04-15', 2026, '2026-04', 'Canada', 'Canada', '', 'Chemicals', 'Mini T Designer Fireplace and T-Lite 3 Designer Fireplace', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should&nbsp;immediately&nbsp;stop using them and safely dispose of the items in such a way that they cannot be used again.&nbsp;&nbsp;Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database for dangerous products and&nbsp;take action to remove&nbsp;items of concern.Health Canada&nbsp;would like to&nbsp;remind&nbsp;consumers&nbsp;to report any health or safety incidents related to the use of these products or any other consumer prod', '81895');
INSERT INTO safety_incidents VALUES ('41409ef1796808520b8b6e9b84d8eaa5823551f3', 'Health Canada', '2026-04-15', 2026, '2026-04', 'Canada', 'Canada', '', 'Drugs', 'Nitrous Oxide Chargers', 'Product Safety', 'Other', 'Respiratory', 'Product safety', 'Serious', 0, 0, 'Do not inhale nitrous oxide products for recreational purposes.Seek immediate medical attention from a health care professional (physician, nurse, pharmacist, Canadian Poison Centre) if you have used nitrous oxide recreationally or for medical purposes and have experienced any side effects.For Poison Centre access you can contact 1-844 POISON-X, in Quebec 1-800-463-5060, or contact your local poison centre directly. Health Canada has also published&nbsp;information about stopping substance use.R', '81896');
