INSERT INTO safety_incidents VALUES ('6f53459fd3361e56e6b49420b5eea8777895af58', 'Health Canada', '2026-04-10', 2026, '2026-04', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Axe deodorant body spray in various scents and Dove anti-perspirant in various scents', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled TJ Trading Co. Inc. products and return them to the place of purchase for a refund. For more information, consumers can contact TJ Trading Co. Inc., by telephone at 416-661-9506 ext 227, Monday to Friday: 9:00 a.m. – 5:00 p.m.Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, t', '81873');
INSERT INTO safety_incidents VALUES ('da7b74ae09d4740c804bafa4d2116799b7d7bf3b', 'Health Canada', '2026-04-10', 2026, '2026-04', 'Canada', 'Canada', '', 'Electrical & Electronics', 'DRESBE LED Christmas Headbands Light Up Christmas Tree Hair Hoop Xmas Candy Cane Festival Headwear for Women(2pcs)', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled DRESBE LED Christmas Headbands Light Up Christmas Tree Hair Hoop Xmas Candy Cane Festival Headwear for Women(2pcs) and dispose of the product. Contact Dresbe for information on how to properly dispose of the product. &nbsp;For more information, consumers can contact DRESBE by email at&nbsp;dresberecall@shineprom.com.&nbsp; Consumers will need to email a photograph of disposal to receive the refund.Please note that the Canada Consumer Product S', '81875');
