INSERT INTO safety_incidents VALUES ('e7afc06adfde006a8ef8012c20e3cc508a13f4d6', 'Health Canada', '2026-04-09', 2026, '2026-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'HEAD Alpine Ski Boots', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact HEAD Canada Inc. to receive a free repair or replacement. Recalled boots with fluorescent yellow shells will be replaced with a newer equivalent model. Owners of boots with fluorescent yellow sole pad inserts will be provided with free replacement sole pad inserts.For more information, consumers can contact HEAD Canada Inc. by telephone at 1-800-265-7257 from 7 a.m. – 4 p.m. EST, Monday to Friday, by email at info@ca.head.c', '81790');
INSERT INTO safety_incidents VALUES ('df571b96f32ac13e9e8f76183524def60656d6a4', 'Health Canada', '2026-04-09', 2026, '2026-04', 'Canada', 'Canada', '', 'Household Items', 'BISSELL brand Steam Shot™ OmniReach ™ and Steam Shot ™ Omni Steam Cleaners attachments', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact BISSELL to receive free new attachments. Consumers should visit www.steamshot2026.com to register for the recall and for instructions on how to participate in the recall, including how to upload a photo showing proof of disposal of the affected products.For more information, consumers can contact&nbsp;BISSELL&nbsp;by telephone&nbsp;at&nbsp;1-855-739-1702 from 9:00 am to 7:00 pm ET&nbsp;Monday through Saturday,&nbsp;by emai', '81815');
INSERT INTO safety_incidents VALUES ('414d18c6470a61d411bb7f1a174dc7f653966bd3', 'Health Canada', '2026-04-09', 2026, '2026-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'SCUBAPRO Monorail Weight Pockets', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled SCUBAPRO Monorail Weight Pocket and contact SCUBAPRO for a free repair.For more information, consumers can contact SCUBAPRO by telephone at 1-800-790-3757 from 7 a.m. to 5 p.m. PT Monday through Friday, by email at mwpockets@scubapro.com or visit the company website at https://scubapro.johnsonoutdoors.com/us/recalls or https://scubapro.johnsonoutdoors.com and click on “Recalls” at the bottom of the page for more information.Joint recall with H', '81819');
