INSERT INTO safety_incidents VALUES ('d9c0a345787fd5740dcdc62992d63050bdb6fb59', 'Health Canada', '2026-04-09', 2026, '2026-04', 'Canada', 'Canada', '', 'Chemicals', 'Rexall Methyl Hydrate / Methanol, Pro-Line Methyl Hydrate, Pro-Line Lacquer Thinner and Pro-Line Paint Thinner', 'Labelling And Packaging', 'Chemical / Toxic Substance', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;stop using&nbsp;the recalled&nbsp;products&nbsp;and&nbsp;return them to the retail location where they were&nbsp;purchased&nbsp;for replacement.&nbsp;For more information, consumers can contact&nbsp;Rexall Solutions&nbsp;by telephone&nbsp;at&nbsp;1-877 505-2425 extension 207, between 9 a.m. to 3 p.m. EST, Monday through Friday&nbsp;or&nbsp;by email at&nbsp;diana@rexallsolutions.com.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits ', '81869');
INSERT INTO safety_incidents VALUES ('7e3b7a6d6c45b5febd0128657899927eea82fef0', 'Health Canada', '2026-04-09', 2026, '2026-04', 'Canada', 'Canada', '', 'Toys & Childcare', 'Kollide Magnet Game (lot # 4345460825)', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, look at the label for the affected lot number and contact What Do You Meme, LLC with a photo of the lot number and proof of purchase to receive a free replacement.For more information, consumers can contact What Do You Meme, LLC email at customerservice@relatable.com or visit Product Recalls – Relatable.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away', '81870');
