INSERT INTO safety_incidents VALUES ('75892b76a69f73fcff6706e35ada6b5c829b28f8', 'Health Canada', '2026-04-09', 2026, '2026-04', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized injectable peptide drugs (often sold online and marketed for “anti-aging”, bodybuilding, or “wellness”)', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Not Reported', 0, 0, 'If you have used an unauthorized injectable peptide drug and you feel unwell or have concerns, contact a healthcare professional (physician, nurse practitioner, pharmacist).Dispose of these products safely by following municipal or regional guidance for chemicals and other hazardous waste or take the product to your local pharmacy for proper disposal.Use prescription drugs under the care of a healthcare professional and only buy prescription drugs from licensed pharmacies. Be aware of the risks ', '81874');
