INSERT INTO safety_incidents VALUES ('736ab25767754e4293822601b861a02c1c5812c5', 'Health Canada', '2026-04-03', 2026, '2026-04', 'Canada', 'Canada', '', 'Food & Food Contact', 'Creamy Garlic and Spinach Salad', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '81848');
INSERT INTO safety_incidents VALUES ('096b77d4ad2778e1ee65faf94c1ab033ee8ffd0a', 'Health Canada', '2026-04-02', 2026, '2026-04', 'Canada', 'Canada', '', 'Household Items', 'Universal Broadmoore Canopy Bed Frames', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should not move the recalled bed frames and contact Samson immediately for a free repair and installation of four metal brackets and mounting hardware.For more information, consumers can contact Samson International by telephone at 1-800-357-0701 from 8 a.m. to 5 p.m. ET Monday through Friday, by email at samson@rsvpcomm.com, or visit the company website&nbsp;and click “important recall information”.Joint recall with Health Canada, the United States Consumer Product Safety Commission (', '81797');
INSERT INTO safety_incidents VALUES ('6b5d2c90afa8fc01ee9259584f37b13bc0c138b6', 'Health Canada', '2026-04-02', 2026, '2026-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'Condor HMS Triple Carabiners', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled carabiner and contact OCUN NA for a free replacement. Consumers will be asked to fill out the recall form and email it to recall@ocun.com, and follow the instructions to receive a prepaid return shipping label and return the recalled product. For more information, consumers can contact OCUN NA LLC by email at recall@ocun.com or visit the company recall website.Joint recall with Health Canada, the United States Consumer Product Safety Commissio', '81805');
INSERT INTO safety_incidents VALUES ('51122bdf75a8675cb5da62355854315f876f749a', 'Health Canada', '2026-04-02', 2026, '2026-04', 'Canada', 'Canada', '', 'Dairy', 'Cheese - Shredded Parmesan Cheese; Cheese Curds; Feta Cheese; Goat cheese; Mozzarella cheese', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '81810');
INSERT INTO safety_incidents VALUES ('59898aa2a0779e4ce826c55a88304c799cf3a777', 'Health Canada', '2026-04-02', 2026, '2026-04', 'Canada', 'Canada', '', 'Other', 'Mompush Velo stroller', 'Injury', 'Instability / Fall Risk', 'Fall Injury', 'Tip-over hazard - Fall hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Mompush Velo stroller and contact Mamababy Inc. to arrange for refund or replacement.For more information, consumers can contact Mamababy Inc. by email at support@mompush.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to th', '81827');
