INSERT INTO safety_incidents VALUES ('10d8ab730442b1e3e377791a578e594736927191', 'Health Canada', '2026-03-26', 2026, '2026-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Petzl NOMIC and ERGONOMIC Ice Axes', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Petzl for a free replacement shaft.For more information, consumers can contact Petzl by telephone toll-free at 1-877-807-3805 from 8:00 a.m. to 4:00 p.m. MT Monday through Friday, by email at Returns@petzl.com or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Petzl America, Inc.Please note that the Canada Consumer Product Safety Act prohibits rec', '81781');
INSERT INTO safety_incidents VALUES ('dfa645d10fbdd3e0736e381a55aafbe020fc5d8b', 'Health Canada', '2026-03-26', 2026, '2026-03', 'Canada', 'Canada', '', 'Specialized Products', 'DIY Sauna Heater Kits', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled ​DIY ​Sauna ​H​eater ​K​its and register on the DIY Cold Plunge website for a full refund.For more information, consumers can contact DIY Cold Plunge by email at orders@diycoldplung​e​.com &nbsp;or visit the company website www.diycoldplunge.com/pages/recall. Consumers will be asked to submit written and photo proof that the product has been destroyed/disposed of or request a prepaid shipping label to return the product. &nbsp; &nbsp;Joint rec', '81787');
