INSERT INTO safety_incidents VALUES ('4689e2020e4cae15e802c34cdcd2d523778482b1', 'Health Canada', '2026-03-25', 2026, '2026-03', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized and counterfeit health products, including prescription and injectable drugs.', 'Unauthorized Product - Product Safety', 'Other', 'Not Specified', 'Unauthorized product - Product safety', 'Not Reported', 0, 0, 'Do not buy or use unauthorized or counterfeit health products. When receiving cosmetic treatments, read product labels (or ask your healthcare professional to show you the product label) to confirm a product has been authorized for sale by Health Canada. Authorized health products have an eight-digit DIN, Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM).You can also check whether products have been authorized for sale by searching Health Canada''s&nbsp;Drug Product Database, Licen', '81792');
