INSERT INTO safety_incidents VALUES ('4a2638bda6f4ed2cd8885bbeef71585dcfbd7977', 'Health Canada', '2026-03-23', 2026, '2026-03', 'Canada', 'Canada', '', 'Toys & Childcare', 'Bear Shaped Fridge Magnets', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Gummy bear shaped magnets and dispose of the product. Consumers should confirm that they disposed of the product by clicking the confirmation link in the email notice sent by SHEIN. Upon receiving confirmation, SHEIN Canada will issue the consumer a full refund. For more information, consumers can contact SHEIN Canada by telephone toll-free at 888-971-5568, from 9 a.m. to 6 p.m. PT Monday through Friday, by email at cacsteam@shein.com or visit', '81786');
INSERT INTO safety_incidents VALUES ('11caf80f539103b82955b9d160ad144705184441', 'Health Canada', '2026-03-20', 2026, '2026-03', 'Canada', 'Canada', '', 'Processed', 'Long and Short Nakki', 'Mustard', 'Allergen', 'Not Specified', 'Mustard', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '81709');
INSERT INTO safety_incidents VALUES ('a4fe6370395a42472465dc7cddec7cd5bcd80d18', 'Health Canada', '2026-03-20', 2026, '2026-03', 'Canada', 'Canada', '', 'Toys & Childcare', 'ToyTexx Portable Magnetic Strategy 20 Magnet Kit with Rope & Storage Bag', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, keep it out of reach of children and return it to the place of purchase for a full refund. Alternatively, consumers may safely dispose of the product in accordance with local municipal hazardous waste guidelines.For more information, consumers can contact Toytexx Inc. by telephone at 905-766-1187, 10:00 AM to 5:00 PM ET Monday to Friday, by email at info@toytexx.com or visit the company websitePlease note that the Canada Consumer Prod', '81773');
INSERT INTO safety_incidents VALUES ('0f58b303a6c06b8e53b69a236213b6dc21acdc06', 'Health Canada', '2026-03-20', 2026, '2026-03', 'Canada', 'Canada', '', 'Household Items', 'Zebra Blinds by B&B Blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;stop using&nbsp;the recalled&nbsp;product&nbsp;and&nbsp;contact B&amp;B Blinds for&nbsp;additional&nbsp;information.For more information, consumers can contact&nbsp;B&amp;B Blinds&nbsp;by telephone&nbsp;at&nbsp;403-243-0815&nbsp;Monday to Friday&nbsp;(MT), 9:00 AM – 4:30 PM,&nbsp;or&nbsp;by email at&nbsp;bbblinds4561@gmail.com.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed,&nbsp;sold&nb', '81775');
INSERT INTO safety_incidents VALUES ('00c83dc36e307b6b2e02e912f88c4476ac3c58d0', 'Health Canada', '2026-03-20', 2026, '2026-03', 'Canada', 'Canada', '', 'Household Items', 'Vevor Retractable Baby Gates', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled baby gates and contact MARIFEL LTD for a full refund. Consumers should destroy the gate by cutting through the mesh and sending a photo of the destroyed gate to recalling@vevor.com.For more information, consumers can contact MARIFEL LTD by telephone at 855-599-6320, by email at recalling@vevor.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or e', '81779');
