INSERT INTO safety_incidents VALUES ('d38f04b3e76c11047dda186dc4f02a75de46dc74', 'Health Canada', '2026-03-19', 2026, '2026-03', 'Canada', 'Canada', '', 'Household Items', 'Wagner 900 Series Power Steamers', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled steamers and contact Wagner for a free repair kit consisting of a hose sleeve, nozzle cover, and funnel. For more information, consumers can contact Wagner by telephone at&nbsp;1-800-962-6118, 9 a.m. to 5 p.m. ET Monday through Friday, by email at&nbsp;us-wagnerrecall@wagner-group.com&nbsp;or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Wagner Spray Tech Corporati', '81762');
