INSERT INTO safety_incidents VALUES ('b873952553666f156e6f4dec3eb1c73a68385245', 'Health Canada', '2026-03-16', 2026, '2026-03', 'Canada', 'Canada', '', 'Toys & Childcare', 'Addo Play "Out To Impress" Sand Art Creations and Creative Candles', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of them as per the following guidelines: If the sand is still in its packaging, place it in a heavy-duty plastic bag and double-tape it securely. If the sand has been used, keep people away from areas where the sand was used until the area has been cleaned. To clean the area where the product was used, use wet cloths to avoid generating dust, wear gloves and a mask, double-bag the sand in a heavy-duty plastic bag and doubl', '81731');
