INSERT INTO safety_incidents VALUES ('aeb5bcd2ddde7908a9fa5afc864f540793142c18', 'Health Canada', '2026-03-12', 2026, '2026-03', 'Canada', 'Canada', '', 'Toys & Childcare', 'Cool Fidget Toy Stress Ball Fridget Magnet Stones for Adults, Magnetic Roller Ball for Craft Office Home Kitchen Refrigerator, Rare Earth Magnets Stress Relief Desk Toy Decoration', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose of it in household waste. Contact the manufacturer with proof of disposal for a refund.For more information, consumers can contact Shenzhenshi Tengxing Dianzikejimaoyi Co., Ltd.&nbsp;by email at 2295852269@qq.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or s', '81724');
INSERT INTO safety_incidents VALUES ('ea887d9ec2b8816d91fa22b10741b34c4a833ce1', 'Health Canada', '2026-03-12', 2026, '2026-03', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Salt of the Earth Cedar and Amyris Replenish Cream', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;stop using the recalled products and dispose of them or contact&nbsp;Salt of the Earth&nbsp;for a refund.For more information, consumers can contact&nbsp;Salt of the Earth&nbsp;by&nbsp;email at&nbsp;recallinfo2026@gmail.com.&nbsp;&nbsp;Please note that, in addition to the requirements of the&nbsp;Cosmetic Regulations,&nbsp;the&nbsp;Food and Drugs Act&nbsp;(FDA)&nbsp;prohibits&nbsp;the sale of cosmetics that are either made with hazardous substances, or unde', '81728');
INSERT INTO safety_incidents VALUES ('f2876ecb3315146dc850d297d245ba1263c0a65d', 'Health Canada', '2026-03-12', 2026, '2026-03', 'Canada', 'Canada', '', 'Drugs', 'Nitrous Oxide Chargers', 'Product Safety', 'Other', 'Respiratory', 'Product safety', 'Serious', 0, 0, 'Do not inhale nitrous oxide products for recreational purposes.Seek immediate medical attention from a health care professional (physician, nurse, pharmacist, Canadian Poison Centre) if you have used nitrous oxide recreationally or for medical purposes and have experienced any side effects.For Poison Centre access you can contact 1-844 POISON-X, in Quebec 1-800-463-5060, or contact your local poison centre directly. Health Canada has also published&nbsp;information about stopping substance use.R', '81742');
