INSERT INTO safety_incidents VALUES ('02e5347504413af4adc7d6f05abb41149f7e9cac', 'Health Canada', '2026-02-27', 2026, '2026-02', 'Canada', 'Canada', '', 'Other', 'Joovy – Tricycoo Tricycle-Stroller', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard - Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, remove the storage bag located in the rear, contact EI Brand Management Inc and register on the company website to obtain more information. A repair kit will be provided and shipped once available.For more information, consumers can visit EI Brand Management Inc’s company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada', '81651');
