INSERT INTO safety_incidents VALUES ('c268bdd47d52a0078a5df59bde013914da2e60fa', 'Health Canada', '2026-02-26', 2026, '2026-02', 'Canada', 'Canada', '', 'Household Items', 'Window Opening Control Devices applied to Andersen 100 Series Casement Windows', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;close and lock windows utilizing the recalled window opening control device and contact Andersen Windows to share the Product ID number located on the label on the upper right corner of the window, to determine if it is included in the recall. A local Andersen Windows dealer and an authorized service provider will perform an onsite repair of recalled products. Uninstalled window opening control devices should be returned to the point of purchase.For more in', '81642');
