INSERT INTO safety_incidents VALUES ('6a58e874f67c56f5f003a0604634466b25342c1b', 'Health Canada', '2026-02-23', 2026, '2026-02', 'Canada', 'Canada', '', 'Household Items', 'PureVolt Photoelectric Smoke Detector', 'Unauthorized Products', 'Flammability / Overheating', 'Not Specified', 'Unauthorized products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to Addison Électronique for a refund. Consumers should replace the recalled product with one that bears a Canadian certification mark.For more information, consumers can contact Addison Électronique by telephone at 514-376-1740 extension 304, from 8 a.m. to 5 p.m. ET, or by email at info@addison-electronique.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, s', '81632');
INSERT INTO safety_incidents VALUES ('0cf7aba2cc445baa193f49d3f0d05459abfafda4', 'Health Canada', '2026-02-23', 2026, '2026-02', 'Canada', 'Canada', '', 'Cannabis', 'Cannabis Cartel QUADS Dubai Inspired Chocolate edible cannabis', 'Contamination', 'Other', 'Not Specified', 'Product contamination', 'Not Reported', 0, 0, 'Stop using the products&nbsp;if&nbsp;they are&nbsp;part of the recall.Return the products&nbsp;to the store where you bought&nbsp;them&nbsp;or dispose of&nbsp;them. Dispose of any products that you have opened safely and out of the reach of children and youth.&nbsp;&nbsp;Report any health or safety complaints you have about these or other cannabis products by filling out the&nbsp;Cannabis Reporting Form&nbsp;online.&nbsp;', '81635');
