INSERT INTO safety_incidents VALUES ('61117488c4d8468b272c09561ddc066ffb0542db', 'Health Canada', '2026-02-12', 2026, '2026-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'Hydromassage Rotary jets found inside some Highlife Collection spas', 'Drowning', 'Entrapment', 'Entrapment', 'Entrapment hazard - Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, turn off the affected Hydromassage Rotary jets by turning the jet face clockwise and contact Watkins Wellness for instructions on how to receive free replacement jet inserts. For more information, consumers can contact Watkins Wellness by telephone toll-free at 1-888-450-5748 from 8:00 a.m. to 5:00 p.m. EST, Monday through Friday, by email at jetrecall@watkinsmfg.com or visit the Hot Spring Spas website.&nbsp; Joint recall with Health', '81593');
