INSERT INTO safety_incidents VALUES ('6113f9aca7ad3353964ceeefcc396bc869cd6099', 'Health Canada', '2026-02-11', 2026, '2026-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'Impulso RC Handlebars', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Impulso RC handlebars and if you have not been contacted by Bianchi, reach out to your local Bianchi dealer to arrange for a free replacement handlebar of a different design.For more information, consumers can contact F.I.V.E. Bianchi S.p.A by email at recall@bianchi.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.He', '81595');
