INSERT INTO safety_incidents VALUES ('09da97e83ab2e54b2044366a100391404996e4e3', 'Health Canada', '2026-02-09', 2026, '2026-02', 'Canada', 'Canada', '', 'Drugs', 'MAR-AMLODIPINE', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'Immediately check your medication bottle to ensure it only contains MAR-Amlodipine 5 mg tablets.MAR-Amlodipine 5 mg tablets are white to off-white, flat and eight-sided, with a line across the middle. One side has "210" and "5" printed on it, and the other side is blank.Midodrine 2.5 mg tablets are white, round, and marked with ''M2'' on one side and have a line down the middle on the other side.If your bottle contains any unusual tablets or if you are unsure,&nbsp;return it to your pharmacy.If yo', '81586');
