INSERT INTO safety_incidents VALUES ('3716b1fa107c58a01e13d3dc758af9c8e8730af4', 'Health Canada', '2026-01-21', 2026, '2026-01', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized and counterfeit versions of glucagon-like peptide-1 (GLP-1) receptor agonist drugs.', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Only buy prescription drugs from a licensed pharmacy.Do not buy or use unauthorized products.Look for drugs that have been authorized by Health Canada by checking for the eight-digit Drug Identification Number (DIN) on the label and by searching Health Canada''s&nbsp;Drug Product Database.Speak with your healthcare professional if you have used an unauthorized GLP-1 product and have concerns about your health.Know the risks of buying drugs over the Internet and know how to choose a safe online ph', '81518');
