INSERT INTO safety_incidents VALUES ('7cf440a2ffa16ac808e4e3647ff2b6340840f5b7', 'Health Canada', '2026-01-09', 2026, '2026-01', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'The Paris Apothecary Aristocrat Beard Oil and Beard Balm', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of them or contact The Paris Apothecary for a refund.For more information, consumers can contact The Paris Apothecary by email at theparisapothecary@gmail.com or visit The Paris Apothecary retail store Tuesday to Sunday, between 10:00 a.m. and 6:00 p.m. EST. Please note that, in addition to the requirements of the Cosmetic Regulation the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with haz', '81462');
INSERT INTO safety_incidents VALUES ('1094bed400b1a895c7ee48e56992abd0aefad093', 'Health Canada', '2026-01-09', 2026, '2026-01', 'Canada', 'Canada', '', 'Drugs', 'Counterfeit Cialis (20 mg tadalafil tablets) and Viagra (100 mg sildenafil tablets)', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Immediately  stop using and safely dispose of the products.  Consult  a health care professional (physician, nurse, pharmacist) if you have taken any  of these products and have health concerns.   Only  buy your prescription drugs from&nbsp;licensed pharmacies.&nbsp;If you have  questions about whether a pharmacy is legitimate, contact the&nbsp;pharmacy regulatory authority&nbsp;in your province or territory. Read information on buying safe sexual  enhancement products, including signs that your', '81463');
