INSERT INTO safety_incidents VALUES ('93931c9c7c0dcbb71e96a0517b044283971d9f0c', 'Health Canada', '2025-12-24', 2025, '2025-12', 'Canada', 'Canada', '', 'Electrical & Electronics', 'STIHL BR800 Backpack Blower', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately&nbsp;stop using any&nbsp;STIHL BR 800 Backpack Blower&nbsp;affected by this recall&nbsp;and&nbsp;return&nbsp;it&nbsp;to&nbsp;their preferred servicing STIHL dealer for inspection (and replacement, if necessary) of the fan wheel.&nbsp;For more information, consumers can contact&nbsp;STIHL&nbsp;Limited (Canada) Customer Service and After Sales Technical Support (English &amp; French)&nbsp;by telephone&nbsp;at 519-681-3000&nbsp;Monday to Friday between 7:00am and 6', '81402');
INSERT INTO safety_incidents VALUES ('a9d3873c7518b4d1b453f527f2a25d638f1d349e', 'Health Canada', '2025-12-24', 2025, '2025-12', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized drugs, including injectable peptides and controlled drugs', 'Unauthorized Product - Product Safety', 'Other', 'Not Specified', 'Unauthorized product - Product safety', 'Not Reported', 0, 0, 'Do not use these products. Consult a health care professional if you have used unauthorized health products and have health concerns.Only buy prescription drugs from licensed pharmacies.Do not buy or use unauthorized drugs. Read product labels to confirm a product has been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check whether products have ', '81403');
