INSERT INTO safety_incidents VALUES ('79724bb6f0bd77873a76423efd26f37ed049d5e8', 'Health Canada', '2025-12-24', 2025, '2025-12', 'Canada', 'Canada', '', 'Other', 'Vegan Bacon Slice', 'Wheat', 'Allergen', 'Not Specified', 'Wheat', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionIf you have celiac disease or other gluten-related disorders, do not consume the recalled product&nbsp;as it&nbsp;may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more', '81422');
