INSERT INTO safety_incidents VALUES ('a32479f86b0898cf186637773db065f35284609a', 'Health Canada', '2025-12-19', 2025, '2025-12', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'BEB Bubbly Wash', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled BEB Bubbly Wash and contact Canadian Hospital Specialties Ltd. (CHS) for a replacement. For more information, consumers can contact Canadian Hospital Specialties Ltd. (CHS) by email at recalls@chsltd.com.Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Heal', '81378');
