INSERT INTO safety_incidents VALUES ('5c4928d181f6dff21b60f544e53c606598ec856f', 'Health Canada', '2025-12-09', 2025, '2025-12', 'Canada', 'Canada', '', 'Drugs', 'Nitrous Oxide Chargers', 'Product Safety', 'Other', 'Respiratory', 'Product safety', 'Serious', 0, 0, 'Do not inhale nitrous oxide products for recreational purposes.Seek immediate medical attention from a health care professional (physician, nurse, pharmacist, Canadian Poison Centre) if you have used nitrous oxide recreationally or for medical purposes and have experienced any side effects.For Poison Centre access you can contact 1-844 POISON-X, in Quebec 1-800-463-5060, or contact your local poison centre directly. Health Canada has also published&nbsp;information about stopping substance use.R', '81345');
INSERT INTO safety_incidents VALUES ('075084f7640185ac540b3d707d83b1453313b2a5', 'Health Canada', '2025-12-08', 2025, '2025-12', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Oster French Door Toaster Countertop Ovens', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Oster French Door Toaster Countertop Ovens and contact Sunbeam Products Inc. to arrange to obtain a free repair kit, including installation instructions. For more information, consumers can contact Sunbeam Products Inc. toll free at 1-800-667-8623 from 9 a.m. to 5 p.m. ET Monday through Friday, or online at https://recall.oster.com&nbsp; or www.oster.com and click on “Product Recalls” at the top of the page for more information.Joint recall wi', '78113');
