INSERT INTO safety_incidents VALUES ('98feb8cf092e43f12ee789a34953569185dd85b9', 'Health Canada', '2025-12-05', 2025, '2025-12', 'Canada', 'Canada', '', 'Drugs', 'Counterfeit Viagra (100 mg sildenafil tablets) and counterfeit Cialis (20 mg tadalafil tablets)', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Immediately stop using and safely dispose of the product.Consult a health care professional (physician, nurse, pharmacist) if you have taken these products and have health concerns.Only buy your prescription drugs from licensed pharmacies. If you have questions about whether a pharmacy is legitimate, contact the pharmacy regulatory authority in your province or territory. Read information on buying safe sexual enhancement products, including signs that your product is fake.Report any health prod', '81235');
