INSERT INTO safety_incidents VALUES ('acadfe392580fac400ad410ac92297a59cf07dcc', 'Health Canada', '2025-11-25', 2025, '2025-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Prestige Solo, Prestige Excellence, and Aerco Esteem Condensing Gas Boilers', 'Poisoning Hazard', 'Other', 'Poisoning / Ingestion', 'Poisoning hazard', 'Not Reported', 0, 0, 'Consumers should immediately contact Triangle Tube to schedule a free boiler inspection and if applicable, free installation of a new boiler ignition system if their ignition system has not yet been replaced. Consumers who continue using the recalled boilers while awaiting repair should have working carbon monoxide alarms on each level of their homes and outside sleeping areas. Consumers who do not have a carbon monoxide alarm can contact Triangle Tube to have one shipped to them free of charge.', '81276');
