INSERT INTO safety_incidents VALUES ('424d0cdf58d2f85fc5c5fbeb84d5fb6d823db93b', 'Health Canada', '2025-11-24', 2025, '2025-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Vaast A/1 bicycles and frames', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Vaast A/1 bicycles and frames and contact Super Wheels Inc. for a replacement bicycle frameset. For more information, consumers can contact Super Wheels Inc. (formerly Allite Inc.) by telephone toll-free at 1-855-430-6240, from 8 a.m. to 5 p.m. ET, Monday through Friday, by email at info@vaastbikes.com, or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sol', '81252');
