INSERT INTO safety_incidents VALUES ('f399d9e595acad945e6b202321ed56fceaecbcef', 'Health Canada', '2025-11-19', 2025, '2025-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Gniby Rechargeable Green Powerful Tactical Flashlight with Adjustable Focus, Green Laser Pointer', 'Injury', 'Other', 'Eye Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have this affected product should immediately stop using it and safely dispose of it in accordance with municipal electronic waste requirements. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer', '81237');
