INSERT INTO safety_incidents VALUES ('aa667ea68d717972466f0a4016b7107e1fc5d5f7', 'Health Canada', '2025-11-13', 2025, '2025-11', 'Canada', 'Canada', '', 'Toys & Childcare', 'MÖBI Zippee Activity Toy', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and cut the strings with spherical ends and upload photo to the Firm’s website for a full refund.For more information and to register for recall, visit the company website at www.playmobi.com/recall or www.playmobi.com and click on "Recall" on the bottom of the page. Consumers will be directed to upload photos of the cut spherical ends and a photo showing the date and their initials written on the main toy cylinder for a full refund. F', '78423');
