INSERT INTO safety_incidents VALUES ('17baf832f2352c5ad8cfbcb0075ac77cfae0e8dd', 'Health Canada', '2025-11-13', 2025, '2025-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Trek and Electra brand bicycles', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact their local authorized Trek retailer for free replacement of the back wheel. For more information, consumers can contact the Trek Customer Care Team by telephone at 1-800-373-4594, Monday through Friday, from 8 am to 6 pm CT, by email at customercare@trekbikes.com,&nbsp;or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Trek Bicycle Corporation.P', '78485');
INSERT INTO safety_incidents VALUES ('27205cee4f3a0cdf1be39b84c7aca311061a6642', 'Health Canada', '2025-11-13', 2025, '2025-11', 'Canada', 'Canada', '', 'Other', 'Q’Straint QRT-DELUXE and Q’Straint QRT-MAX retractors', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Q’Straint QRT-DELUXE and Q’Straint QRT-MAX retractors and contact the Q’Straint Customer Service Team to arrange for a free replacement.For more information, consumers can contact Q’Straint Customer Service Team by telephone at 1-800-987-9987, 8:00 a.m. to 5:00 p.m. ET, Monday to Friday, or by email at cs@qstraint.sure-lok.com Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or ', '78494');
INSERT INTO safety_incidents VALUES ('037c1a434d9fc2dd9461cd346d5103cd75f697c4', 'Health Canada', '2025-11-13', 2025, '2025-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Belkin Boost Charge USB-C PD Power Bank 20K', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Belkin Boost Charge USB-C PD Power Bank 20K and safely dispose of the product in such a way that the product cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries.&nbsp; Batteries are considered hazardous waste. Do not place them in household garbage.&nbsp;&nbsp; For more information, consumers can contact Belkin International Inc toll-free at 1 800-223-5546. For Englis', '81200');
