INSERT INTO safety_incidents VALUES ('434aa7ead14c6175c3f9a9286b2952d4eae37245', 'Health Canada', '2025-11-06', 2025, '2025-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Peloton Original Series Bike+ Model PL02 Seat Post', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should stop using the recalled exercise bikes and contact Peloton for a free replacement seat post that can be self-installed using the self-installation instructions provided by Peloton. For more information, consumers can contact Peloton by telephone toll-free at&nbsp;(833) 821-0099&nbsp;from 6 a.m. to 12 a.m. ET, 7 days a week or online&nbsp;at&nbsp;https://www.onepeloton.com/en-CA/bike-plus-replacement/checkout.&nbsp;Please note that the Canada Consumer Product Safety Act prohibits', '78451');
