INSERT INTO safety_incidents VALUES ('1403f889cfb624b781dfb003c35e5920cd2fb666', 'Health Canada', '2025-11-06', 2025, '2025-11', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products labelled to contain prescription, controlled or other drug ingredients', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Not Reported', 0, 0, 'Immediately stop using products obtained from Ezra Healing. Consult a licensed health care professional if you have used these products and have health concerns.Only buy prescription drugs from licensed pharmacies. Be aware of the risks of buying health products online.Do not buy or use unauthorized drugs. Read product labels to confirm a product has been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number ', '78463');
