INSERT INTO safety_incidents VALUES ('5f8d6400e8bf96c671bbd0c700508c912794739e', 'Health Canada', '2025-10-30', 2025, '2025-10', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Various Grundens children’s rain jackets with drawstrings', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled rain jackets and remove the drawstring to eliminate the hazard.For more information, consumers can contact Grundens toll-free at 800-323-7327, from 8 a.m. to 4 p.m. PT, Monday through Thursday, and 8 a.m. to 12 p.m. on Friday, by email at recall@Grundens.com or online at https://grundens.com/pages/recall or&nbsp;www.grundens.com and click on “Recall” at the bottom of the page.Joint recall with Health Canada, the United States Consumer Product ', '78315');
INSERT INTO safety_incidents VALUES ('aa88d9e23450d2ef08b03ee44e1d0beaa95dbb9e', 'Health Canada', '2025-10-30', 2025, '2025-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'Werner Stealth and Covert Kayak Paddles', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Werner Paddles for a full refund in the form of a check or store credit redeemable online. Consumers should fill out a recall form at https://wernerpaddles.com/pages/covert-stealth-recall-consumers. To collect the refund or obtain the store credit, consumers should follow the instructions on the Werner website and destroy the recalled kayak paddle by cutting the paddle into four equal pieces, halfway through each blade and', '78344');
