INSERT INTO safety_incidents VALUES ('85428b8d0935f0a4a7f6b1b33736b5d5a95e27ca', 'Health Canada', '2025-10-21', 2025, '2025-10', 'Canada', 'Canada', '', 'Chemicals', 'Northlight Bio Ethanol Portable Tabletop Fireplaces', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Rona for further instructions on how to return the product. Consumers should provide a valid proof of purchase in order to return the product. For more information, consumers can contact Rona by phone at 1-866-283-2239, from 8:30 a.m. to 7:00 p.m. (EST), Monday to Sunday.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Cana', '78327');
