INSERT INTO safety_incidents VALUES ('afb28be4671c789d1c1e71ca204b52d5839c3d97', 'Health Canada', '2025-10-16', 2025, '2025-10', 'Canada', 'Canada', '', 'Household Items', 'Byron Emperador Dining Tables and Byron Reeded Stone Dining Tables and Desks', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact RH US, LLC for a full refund of the purchase price and to coordinate pick up of the recalled desk or table, free of charge. RH will issue the refund following receipt of the recalled desk or table.For more information, consumers can contact RH US, LLC by telephone at 1-833-359-5394, from 6:00am – 7:00pm PT, Monday through Friday, and 8:00am – 5:00pm PT on Saturday and Sunday, by email at recall@rh.com,&nbsp;or online at ht', '78281');
INSERT INTO safety_incidents VALUES ('9a69f52f0bc9c93db5a73b888d33ead7d2394f78', 'Health Canada', '2025-10-16', 2025, '2025-10', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Vesta Tankless Hot Water Heater', 'Poisoning Hazard', 'Drowning Risk', 'Poisoning / Ingestion', 'Poisoning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled water heater and contact VESTA.DS to have a certified technician install the free repair. For more information, consumers can contact VESTA.DS by telephone at 1-888-505-5525, from 8:30am to 6pm ET, Monday through Friday, by email at condensingwaterheater@realtimeresults.net or online at www.recallrtr.com/condensingwaterheater or at https://www.vestahws.com and click on “Recall” under the “Documents/Support” tab at the top of the page for more ', '78282');
