INSERT INTO safety_incidents VALUES ('00e19b98202d145e857394ba42522a77bde65edc', 'Health Canada', '2025-10-10', 2025, '2025-10', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Great Powerful Green, Red and Violet 15 cm Laser Pointer Pens', 'Injury', 'Other', 'Eye Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return to the place of purchase for a refund or replacement.For more information, consumers can contact Oxygen Discount by email at pointerrecall@gmail.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other ', '78258');
INSERT INTO safety_incidents VALUES ('b63f531d4086e1211029e9adbaaea00e0603d08d', 'Health Canada', '2025-10-10', 2025, '2025-10', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Gniby LED Pointer, 3 in 1 rechargeable interactive laser toy for cats and dogs', 'Injury', 'Other', 'Eye Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have the affected product should immediately stop using it and safely dispose of the product in accordance with municipal electronic waste requirements.Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the C', '78259');
INSERT INTO safety_incidents VALUES ('071b4620d37f3000b51da16ea5ed31da4b3cdce1', 'Health Canada', '2025-10-10', 2025, '2025-10', 'Canada', 'Canada', '', 'Radiopharmaceuticals', 'Atlantiscan', 'Packaging', 'Other', 'Fracture / Blunt Trauma', 'Packaging', 'Serious', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '78268');
INSERT INTO safety_incidents VALUES ('b296714aa4173de22b3a4eaa8d13ce674c9b8020', 'Health Canada', '2025-10-10', 2025, '2025-10', 'Canada', 'Canada', '', 'Cannabis', 'Coterie Double-Infused Fruity Pebbles Blunt Pre-roll cannabis extract', 'Contamination', 'Other', 'Fracture / Blunt Trauma', 'Microbial contamination', 'Not Reported', 0, 0, 'Stop using the products if they are part of the recallReturn the products to the store where you bought them or dispose of them. Dispose of any products that you have opened safely and out of the reach of children and youth.Report any health or safety complaints you have about these or other cannabis products by filling out the Cannabis Reporting Form online.', '78279');
