INSERT INTO safety_incidents VALUES ('6dd30dc8293a0282d03aed5b2af36cb16681b962', 'Health Canada', '2025-10-02', 2025, '2025-10', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Rocco Donna Professional hair products', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose them according to municipal hazardous waste guidelines. For more information, consumers can contact Mat&amp;Max by visiting the company website.Please note that, in addition to the requirements of the Cosmetic Regulation the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Health Canada would like to remind consumers ', '78149');
INSERT INTO safety_incidents VALUES ('9e9c9341f6593d1073f212174dbe6d5ce5946b18', 'Health Canada', '2025-10-02', 2025, '2025-10', 'Canada', 'Canada', '', 'Household Items', 'Baby Walkers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the affected products and safely dispose of them in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Product Incident Report', '78166');
INSERT INTO safety_incidents VALUES ('13719c09b2c9279e6eed71437d2edae29e1d576c', 'Health Canada', '2025-10-02', 2025, '2025-10', 'Canada', 'Canada', '', 'Cannabis', 'Wintermint Chillows cannabis extract, Cinnamon Chillows cannabis extract', 'Suspected Quality Concern - Labelling And Packaging', 'Other', 'Not Specified', 'Suspected quality concern - Labelling and packaging', 'Not Reported', 0, 0, 'Stop using the products if they are part of the recall.Return the products to the store where you bought them or dispose of them. Dispose of any products that you have opened safely and out of the reach of children and youth.Report any health or safety complaints you have about these or other cannabis products by filling out the Cannabis Reporting Form online.', '78168');
