INSERT INTO safety_incidents VALUES ('7b9ed2f34d23ed878041990da8f7ba6e69630a4d', 'Health Canada', '2025-09-23', 2025, '2025-09', 'Canada', 'Canada', '', 'Drugs', 'Acetaminophen', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Continue to use acetaminophen for pain and/or fever during pregnancy, as directed. Always follow the directions on the label.Do not take more than the recommended dose. Taking too much acetaminophen can cause harms including serious harm to your liver.If you are pregnant or breastfeeding, talk to your health care provider if you have questions about the use of any medications.Contact a health care provider if:pain lasts more than 5 days; orfever lasts more than 3 days.What Health Canada is doing', '78118');
