INSERT INTO safety_incidents VALUES ('4695ee2df4bc125a5c8bc75fd411f2c6096bc0d0', 'Health Canada', '2025-08-22', 2025, '2025-08', 'Canada', 'Canada', '', 'Drugs', 'DRAXIMAGE SODIUM IODIDE I131 SOLUTION, USP DIAGNOSTIC', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '77965');
