INSERT INTO safety_incidents VALUES ('04cf072a77f22ed837e1d0b5e1bcef79edae4692', 'Health Canada', '2025-08-21', 2025, '2025-08', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Kiwi Electronic Recliner and Swivel Gliders with USB Port', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled recliners and contact Babyletto to receive a free repair kit. Consumers should register at babylettorecall.com to receive their free repair kit and installation instructions. Once consumers have completed the repair, consumers should dispose of the original USB module in accordance with municipal electronic waste requirements.For more information, consumers can contact Babyletto by their toll-free number at 866-621-9483, from 11 a.m. to 3 p.m.', '77891');
INSERT INTO safety_incidents VALUES ('efdca134c7278feb57194731d14e09c77b14714b', 'Health Canada', '2025-08-21', 2025, '2025-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Various Inkari Plush Alpaca Toys', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, destroy the product and contact the company with proof of destruction for a refund.For more information, consumers can contact Inkari B.V. by email at support@inkari-alpaca.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this prod', '77929');
INSERT INTO safety_incidents VALUES ('9d4d7e1a52a6525ac756c0eae6b95591380ad652', 'Health Canada', '2025-08-21', 2025, '2025-08', 'Canada', 'Canada', '', 'Household Items', 'SOLSTICE S85 and JACUZZI JA85/JAP85 pool heat pumps', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should register their affected heat pump through the following website: https://avisqualite.ca/en/&nbsp;to arrange for installation of a replacement part.&nbsp; Pending repair, consumers should maintain the water in their pool to a temperature that is below 90°F (32°C).For more information, consumers can visit https://avisqualite.ca/en/.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health ', '77930');
INSERT INTO safety_incidents VALUES ('d46cd98ff7398de8c115be616ff857e1a5668639', 'Health Canada', '2025-08-21', 2025, '2025-08', 'Canada', 'Canada', '', 'Drugs', 'COPAXONE (glatiramer acetate)', 'New Safety Information - Product Safety - Adverse Reaction', 'Allergen', 'Allergic Reaction', 'New safety information - Product safety - Adverse reaction', 'Not Reported', 0, 0, '', '77932');
INSERT INTO safety_incidents VALUES ('4dc4c00779b39c64b07b9641a23a4b535ad1fb47', 'Health Canada', '2025-08-21', 2025, '2025-08', 'Canada', 'Canada', '', 'Other', 'Gochujang', 'Wheat', 'Allergen', 'Not Specified', 'Wheat', 'Moderate', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionIf you have celiac disease or other gluten-related disorders, do not consume the recalled product&nbsp;as it&nbsp;may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more', '77933');
INSERT INTO safety_incidents VALUES ('79de61d4f498158ffaebc004c561809b39d0694c', 'Health Canada', '2025-08-21', 2025, '2025-08', 'Canada', 'Canada', '', 'Drugs', 'Glatiramer acetate', 'Product Safety - New Safety Information', 'Allergen', 'Allergic Reaction', 'Product safety - New safety information', 'Not Reported', 0, 0, 'If you experience anaphylactic reaction symptoms, stop taking glatiramer acetate and seek immediate medical help by calling 9-1-1.Do not restart taking glatiramer acetate if you have experienced anaphylaxis unless your healthcare provider has identified another clear cause for the anaphylaxis.Report any health product-related&nbsp;side effects&nbsp;to Health Canada.What healthcare professionals should doInform patients and/or caregivers of the signs and symptoms of anaphylactic reactions, which ', '77939');
