INSERT INTO safety_incidents VALUES ('e86a11d01e344f6a0b04895f9e1c5397a555bc0b', 'Health Canada', '2025-08-15', 2025, '2025-08', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Foniq Atom wireless party speaker with karaoke microphone', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the wireless microphone component of the Foniq Atom and contact Automobility to receive instructions for destroying their old microphone. Upon receiving photographic proof of destruction, Automobility will arrange to provide consumers with a free replacement wireless microphone that is compatible with the Foniq Atom speaker and which has received the appropriate ISED (Innovation, Science and Economic Development Canada) certification. For more information,', '77899');
