INSERT INTO safety_incidents VALUES ('967ad8627c8455cd8836af31dc080819eaabe739', 'Health Canada', '2025-08-07', 2025, '2025-08', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Various Fieldsheer branded heated socks', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled heated socks and contact Fieldsheer Apparel Technologies for a refund or replacement. The included lithium-ion battery packs should be disposed of according to local municipal hazardous waste guidelines.For more information, consumers can contact Fieldsheer Apparel Technologies by telephone at 1-888-908-3610, Monday to Friday from 8:00 a.m. to 4:00 p.m. PT, by email at cs@fieldsheer.com or visit the company website.Joint recall with Health Can', '77819');
