INSERT INTO safety_incidents VALUES ('22c5f290bc3782781a27a8965e6740e4c14a6c3d', 'Health Canada', '2025-08-05', 2025, '2025-08', 'Canada', 'Canada', '', 'Other', 'MY25 Norco Sight VLT CX model e-bicycle', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled e-bicycles and contact a Norco retailer to schedule a free replacement of the seatstay.For more information, consumers can contact Norco Rider Support by telephone at 1-800-663-8916, from 9 a.m. to 8 p.m. EST, Monday through Friday, or by email at warranty@norco.com.This notice is for information only and is not being conducted under the requirements of the Motor Vehicle Safety Act or the Canada Consumer Product Safety Act.&nbsp;', '77805');
