INSERT INTO safety_incidents VALUES ('a5597c6368f8dad475a77b228b0d6764d36c2224', 'Health Canada', '2025-08-01', 2025, '2025-08', 'Canada', 'Canada', '', 'Household Items', 'Terrug Fluffy Area Rug', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled area rug, destroy it, and contact Terrug for a refund.For more information, consumers can contact Terrug by email at zhenaius@163.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by fil', '77790');
