INSERT INTO safety_incidents VALUES ('c92c71ac7043be76314d5da32fe0adfe7028d252', 'Health Canada', '2025-08-01', 2025, '2025-08', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Cookies n'' Cream Fudge', 'Wheat - Gluten', 'Allergen', 'Not Specified', 'Wheat - Gluten', 'Moderate', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionIf you have celiac disease or other gluten-related disorders, do not consume the recalled product&nbsp;as it&nbsp;may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more', '77806');
INSERT INTO safety_incidents VALUES ('baf989b7eef5d6c9bae79ff4e6911f67ff9e5b4c', 'Health Canada', '2025-08-01', 2025, '2025-08', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized injectable peptide drugs', 'Unauthorized Product - Product Safety', 'Other', 'Not Specified', 'Unauthorized product - Product safety', 'Not Reported', 0, 0, 'Consult a health care professional (physician, nurse practitioner, pharmacist) if you have used an unauthorized injectable drug and have health concerns.Follow municipal or regional guidelines on how to dispose of chemicals and other hazardous waste or return the product to your local pharmacy for proper disposal.Only buy prescription drugs from licensed pharmacies. Be aware of the risks of buying health products online.Do not buy or use unauthorized drugs. You can read product labels to confirm', '77807');
INSERT INTO safety_incidents VALUES ('955f9a54889e5aac8a7bedf4bab8e6ff1ef878b3', 'Health Canada', '2025-08-01', 2025, '2025-08', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Getas Fish Crackers, Ny.Siok Shrimp Crackers', 'Egg', 'Allergen', 'Not Specified', 'Egg', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '77808');
