INSERT INTO safety_incidents VALUES ('73d058938ec74ad44410bfc68d0845cc0f0721c9', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Toys & Childcare', 'Tegu Floating Stacker (Rainbow and Big top models)', 'Choking', 'Small Parts / Choking Hazard', 'Poisoning / Ingestion', 'Choking hazard - Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled floating stacker toy and contact Tegu to arrange for a replacement.For more information, consumers can contact Tegu by telephone at 1-877-TEGU TOY (1-877-834-8869) from 10:00am to 7:00pm ET, Monday-Friday, by email at &nbsp;service@tegu.com or online at www.tegu.com and click ‘Recall’ at top of the page.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Tegu Holding Inc.Please note that the Cana', '77716');
INSERT INTO safety_incidents VALUES ('a25fcebec0590a922b1a7aec8ed5a4215a4f67f8', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Tools & Machinery', 'RIDGID 18 brushless 21-degree and 30-degree framing nailers', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled RIDGID 18V brushless 21-degree and 30-degree framing nailers and visit the company’s website to verify if their nailer is included in this recall and to obtain instructions on how to send the nailer back to TTI Consumer Power Tools, Inc. for repair.For more information, consumers can contact TTI Consumer Power Tools, Inc. by telephone at 1-800-597-9624, from 9:00 a.m to 5:00 p.m. ET, Monday through Friday, or visit the company website.Joint re', '77752');
