INSERT INTO safety_incidents VALUES ('0b3b303085bc19db58159b7d0696405e83f86c64', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Household Items', 'Cosco 2-Step Kitchen Stool', 'Injury', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the safety bar on the recalled kitchen stool and store it away from children until repaired. Contact Dorel Home Furnishings Inc. to receive a free repair kit, including shipping. The repair kit includes a sliding locking mechanism that attaches to the safety bar to prevent the safety bar from detaching or breaking during use. Consumers will also receive installation instructions and an additional warning label to place onto the product.&nbsp; &nbsp;For mor', '77780');
INSERT INTO safety_incidents VALUES ('9967e169bcbc7b9e03fa70db8a91de0851933bf3', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Toys & Childcare', 'KidKraft Farm to Table Model Play Kitchen', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled KidKraft Farm to Table Model Play Kitchen and contact Backyard Kids for free replacement hooks. Ensure that the play kitchens are always securely anchored against a wall using the tip-over prevention kits that were provided with these units. The company will provide new tip-over prevention kits upon request.For instructions on how to remove the units’ existing hooks and to participate in the recall, consumers should visit www.kidkraft.com/page', '77783');
INSERT INTO safety_incidents VALUES ('2fcca050027057d0fee1c7e7cd960352ff807757', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Solacea Portable Fire Pot', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled fire pots and dispose of them in accordance with local waste requirements.For more information, consumers can contact VYSO Co. by email at hello@solacea.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer pro', '77786');
INSERT INTO safety_incidents VALUES ('09a52e6941e9c424fbd4432b82fb79e9392081d1', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'DT Swiss carbon fiber wheelsets', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled DT Swiss carbon fiber wheelsets and contact DT Swiss for a replacement if applicable.&nbsp;For more information, consumers can contact DT Swiss by email at recall@dtswiss.com, by telephone at 1-800-000-1994 from 8:30 am to 3:30pm Central Time, or visit the company website.&nbsp;Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.&nbsp;Health Canada woul', '77791');
INSERT INTO safety_incidents VALUES ('8f386eb6c8ebd834b783194b45b3101e94d58a97', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'DESIGNME Hold.Me three way hairspray', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled DESIGNME Hold.Me Three-way hairspray and return it to the retailer for proper relabelling.For more information, consumers can contact DESIGNME by telephone at 514-737-1291, Monday to Friday, 9:00 AM to 5:00 PM EST, or by email at info@designmehair.com.Please note that, in addition to the requirements of the Cosmetic Regulations the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under', '77793');
