INSERT INTO safety_incidents VALUES ('c325cc9e312196d4c1a5d48fc280e54d7e921711', 'Health Canada', '2025-07-31', 2025, '2025-07', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'REF Stockholm dry shampoo', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled REF Stockholm dry shampoo and return it to the retailer for a refund or to obtain a credit.For more information, consumers can contact REF Stockholm by email at Edward.ernstberger@refstockholm.Please note that, in addition to the requirements of the Cosmetic Regulations&nbsp;the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Health Cana', '77798');
