INSERT INTO safety_incidents VALUES ('133c67d667895b81b4383edc6c80eb7f915d55c4', 'Health Canada', '2025-07-30', 2025, '2025-07', 'Canada', 'Canada', '', 'Other', 'Momentum Vida E+ model e-bicycle', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled e-bicycles and contact an authorized Giant Bicycle dealer for a free inspection and a fork replacement, as necessary.For more information, consumers can contact Giant Bicycle Canada Inc. by telephone at 1-877-708-1928, from 8 a.m. to 5 p.m. PT, Monday through Friday, by email at canada@giantbicycle.com or visit https://www.giant-bicycles.com/ca/recall-support for more information.This notice is for information only and is not being conducted u', '77776');
