INSERT INTO safety_incidents VALUES ('415d741521309826fd2bc168ebac5551396c748f', 'Health Canada', '2025-07-29', 2025, '2025-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Certain Models of Honda Outboard Engines', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Honda outboard engine. Unfortunately, service parts are currently unavailable due to supply chain constraints. Honda Canada anticipates having sufficient parts to complete the recall service by late fall of 2025. Once parts are available, all known customers will be notified by mail to schedule a service appointment at their Honda marine dealership for a software update and part replacement.For more information, consumers can contact Honda Can', '77773');
INSERT INTO safety_incidents VALUES ('9c1f8f3a4e9448c79c44ee3f348eb4255a8d7e86', 'Health Canada', '2025-07-29', 2025, '2025-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Vevor Single Post Handrails', 'Injury', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Vevor for a full refund.&nbsp; To receive refund, consumers can provide photographic evidence of disposal or destruction of the recalled handrails to recalling@vevor.ca.For more information, consumers can contact Vevor Inc. by email at recalling@vevor.ca &nbsp;or visit the company website. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away i', '77774');
INSERT INTO safety_incidents VALUES ('b4e84f6a202c8319ba45fef088d93d136153918b', 'Health Canada', '2025-07-29', 2025, '2025-07', 'Canada', 'Canada', '', 'Drugs', 'Fucidin tablet 250mg', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected. Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns. Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '77778');
