INSERT INTO safety_incidents VALUES ('624a1e7d00af7d33e9c88685066cb544d50a86ed', 'Health Canada', '2025-07-21', 2025, '2025-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Select Bestway, Intex and Polygroup Above-Ground Pools (48-Inches and Taller)', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately determine if their pool is part of the recall, and if so, contact Bestway, Intex or Polygroup to request a repair kit. Consumers should ensure that children cannot access the pool unattended or, alternatively, drain the pool until the repair can be installed.For more information, consumers can contact: Bestway toll-free at&nbsp;(888) 875-5620&nbsp;from 7:30 a.m. to 4:00 p.m. MT Monday through Friday,&nbsp;online, or email at&nbsp;PoolRemedySupport@bestwaycorp.us.Inte', '77742');
INSERT INTO safety_incidents VALUES ('d02eec64c7d851143759f6fb8649ad67f1a57ff0', 'Health Canada', '2025-07-21', 2025, '2025-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'AstroAI 4 Litre/6 Can Mini Fridge', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled minifridge and check to see if the serial number located on the back of the unit matches affected units.&nbsp; If it does, contact AstroAI by phone or email for a free replacement.For more information, consumers can contact AstroAI by telephone at 877-278-7624 from 9 a.m. to 5 p.m. PT, Monday through Friday, by email at recall@astroai.com, or online at&nbsp;https://www.astroai.com/product-recall&nbsp;or&nbsp;www.astroai.com&nbsp;and click on R', '77743');
