INSERT INTO safety_incidents VALUES ('7e8cdc554e33fa1c3ed2529f7cbe539ae841ed3e', 'Health Canada', '2025-07-18', 2025, '2025-07', 'Canada', 'Canada', '', 'Chemicals', 'American Crafts Resin Starter Kit', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose of the item in accordance with local hazardous waste guidelines.For further information, consumers may directly contact the retailer/importer from whom they purchased the recalled product. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related ', '77733');
INSERT INTO safety_incidents VALUES ('c027a89310e2ae585aef4c4fb7b0a644bfb3e8bf', 'Health Canada', '2025-07-18', 2025, '2025-07', 'Canada', 'Canada', '', 'Processed', 'Salami, Cacciatore', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedConsumers who are unsure if they have purchased the affected products are advised to contact their retailerFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you s', '77735');
