INSERT INTO safety_incidents VALUES ('0629ffc40352b34d0d4278f74a97294e640c0dcd', 'Health Canada', '2025-07-17', 2025, '2025-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'iStore Branded Magnetic Wireless Power Banks 5000 mAH Charger', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled iStore branded magnetic wireless bank and contact iStore for a full refund.For more information, consumers can contact iStore by telephone at 1-800-268-4049, from 9 a.m. to 5 p.m. EST, Monday to Friday, by email at recall@istore.ca.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and iStore.&nbsp; Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redist', '77661');
INSERT INTO safety_incidents VALUES ('20d8fa4805b24868ab73400c199f68e1a8ad6689', 'Health Canada', '2025-07-17', 2025, '2025-07', 'Canada', 'Canada', '', 'Household Items', 'Pura 4 Smart Home Fragrance Diffuser with detachable covers', 'Choking', 'Small Parts / Choking Hazard', 'Poisoning / Ingestion', 'Ingestion hazard - Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the device in areas accessible to children and pets, discard the cover of affected units and contact the company to obtain a replacement cover.For more information, consumers can contact Pura Scents, Inc. by telephone at 1-855-394-5292, Monday to Friday, from 9:00 a.m. to 5:00 p.m. MT, by email at replacement@pura.com, or by visiting the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Pura', '77711');
