INSERT INTO safety_incidents VALUES ('d2c977bc2edf3b589eda0f54c01bd751ef1db474', 'Health Canada', '2025-07-08', 2025, '2025-07', 'Canada', 'Canada', '', 'Drugs', 'NRA-AMLODIPINE 5MG', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'Check your medication bottle to ensure it only contains NRA-AMLODIPINE 5 mg tablets.If your bottle contains&nbsp;any&nbsp;round&nbsp;tablets, which are not the correct shape, or if you''re unsure, return the bottle to your pharmacy for a replacement.If you are unable to get a replacement immediately, continue to take your medication as directed, but&nbsp;do not take the round tablets as these are the wrong medication.Contact your health care professional if you are dizzy, have unusually low blood', '77705');
INSERT INTO safety_incidents VALUES ('00cc3d33d82bfa6da662ec3e1712a0d8ed4475c4', 'Health Canada', '2025-07-08', 2025, '2025-07', 'Canada', 'Canada', '', 'Drugs', 'Natrol DHEA Mood & Stress 25mg', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use this product. Consult your health care professional if you have used this product and have health concerns.Return the product to your local pharmacy for proper disposal.Do not buy or use unauthorized drugs. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check whether products ', '77707');
