INSERT INTO safety_incidents VALUES ('2417863f5f1adec5ab2f38999202896131ba2c7e', 'Health Canada', '2025-07-03', 2025, '2025-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Polaris and 509 branded helmets', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled helmets and contact 509 or Polaris for a replacement, refund, or repair, depending on the model of helmet.For more information, consumers can contact 509 by phone at 1-877-743-3509 from 8am to 4pm (PST) Monday to Friday or by email at support@ride509.com. Consumers can also contact Polaris at 1-800-POLARIS (765-2747) from 7am to 8pm (CST) Monday to Friday and 10am-2pm (CST) on Saturday or by email at owner.connections@polaris.com.Joint recall ', '77032');
INSERT INTO safety_incidents VALUES ('28fa5feb3a6a5ea49ce96798370bd370f9523601', 'Health Canada', '2025-07-03', 2025, '2025-07', 'Canada', 'Canada', '', 'Other', 'AGV Tourmodular Motorcycle Helmet', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled helmet and contact Dainese for a free repair, replacement or refund. For more information, consumers can contact Dainese S.p.A by completing the form on the company’s website , by telephone at 1-949-625-0412, 8:00 am PST – 4:00 pm PST or by email at consumer.tourmodular@dainese.comPlease note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would l', '77658');
INSERT INTO safety_incidents VALUES ('3e1b4ab18a7a0b07727307d236d09a78943b4703', 'Health Canada', '2025-07-03', 2025, '2025-07', 'Canada', 'Canada', '', 'Tools & Machinery', 'Yardworks and Worx electric corded chainsaws and pole saws', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Positec Canada, Ltd. for product replacement directions.For more information, consumers can contact Positec Canada, Ltd. by telephone toll-free at 1-888-997-8871 from 9:00 a.m. to 6:00 p.m. EST, by email at chainsawrecall@positecgroup.com or visit the recall website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Positec Canada, Ltd.Please note that the Canada Consumer Pr', '77663');
INSERT INTO safety_incidents VALUES ('4e5ddeeaabbccb9ddbd46c0768ede4654b364603', 'Health Canada', '2025-07-03', 2025, '2025-07', 'Canada', 'Canada', '', 'Processed', 'Anchovy Fillets in Olive Oil', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Sign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation and recall processReport a food safety or labelling concern', '77665');
