INSERT INTO safety_incidents VALUES ('a034ab565f99995de7e17e4c4244d497a2427d35', 'Health Canada', '2025-07-02', 2025, '2025-07', 'Canada', 'Canada', '', 'Household Items', 'Minka Vortic Flow Series light fixtures', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Minka Lighting to schedule a free inspection and an on-site repair to replace the connection component. For more information, consumers can contact Minka Lighting toll-free at 888-770-7027 from 7:30 a.m. to 5 p.m. CT Monday through Friday, by email at&nbsp;vortic@realtimeresults.net, or online at&nbsp;https://www.recallrtr.com/vortic&nbsp; or https://www.minkagroup.net&nbsp;and click on “Recall” at the bottom of the page.P', '77651');
