INSERT INTO safety_incidents VALUES ('2baed5caa20644c8b1ebd6c05a273191f3a0f75d', 'Health Canada', '2025-06-30', 2025, '2025-06', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Deuter Micro Star Children''s Sleeping Bag', 'Injury', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled children’s sleeping bag and return it to the point of purchase to receive a full refund. For more information, consumers can contact ROI Recreation Outfitters Inc by telephone at 604-320-3350 Monday to Friday from 8:30am- 4:30pm PST, by email at cs@roirecreation.com or visit the company website. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health', '77649');
