INSERT INTO safety_incidents VALUES ('487d448633c4f2dab56df4249c5b251f4fcf2b6a', 'Health Canada', '2025-06-30', 2025, '2025-06', 'Canada', 'Canada', '', 'Natural Health Products', 'Virility for Men (Yi Li Xiao Capsule)', 'Product Safety - Undeclared Substance', 'Allergen', 'Not Specified', 'Product safety - Undeclared substance', 'Not Reported', 0, 0, 'Stop using Virility for Men (Yi Li Xiao Capsule).Consult your health care professional if you have used this product and have health concerns.Report any health product-related side effects&nbsp;or complaints to Health Canada.Contact Yexin Likang International Health Inc. at frankzhangsap@yahoo.ca if you have questions about the recall.', '77660');
