INSERT INTO safety_incidents VALUES ('764aa1068204228b10fd7105ee98c6132c73f535', 'Health Canada', '2025-06-29', 2025, '2025-06', 'Canada', 'Canada', '', 'Fresh', 'Sliced Mushrooms', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '77655');
