INSERT INTO safety_incidents VALUES ('879d76f867e9a9ebb18009146ca0c126ac65f2dd', 'Health Canada', '2025-06-27', 2025, '2025-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Anker Power Bank A1647 and Anker Zolo Power Banks A1681', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Anker Power Bank A1647 and Anker Zolo Power Banks A1681 and A1689 and contact Anker for a free replacement unit or receive a voucher for use on Anker’s official website.&nbsp; Safely dispose of the items in such a way that they cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries.&nbsp; Batteries are considered hazardous waste. Do not place them in household garbage.&n', '77650');
INSERT INTO safety_incidents VALUES ('59cce5befe982e4216b4fcf175463eeb9d07f894', 'Health Canada', '2025-06-27', 2025, '2025-06', 'Canada', 'Canada', '', 'Medical Devices', 'Unauthorized blood glucose monitors, also referred to as glucose-reading devices or non-invasive glucose monitors', 'Unauthorized Product - Inaccurate Test Or Measurement Results', 'Other', 'Not Specified', 'Unauthorized product - Inaccurate test or measurement results', 'Not Reported', 0, 0, 'Only use blood glucose monitors that have been authorized by Health Canada.  If you suspect that you are using an unauthorized product, stop using it immediately and replace it with an authorized monitor.  Talk to your health care provider about which  blood glucose monitor is right for you.   Only  use devices listed on&nbsp;Health Canada''s Medical Device Active  Licence Listing&nbsp;(MDALL).  Report any health product-related side effects or complaints to Health Canada.', '77654');
