INSERT INTO safety_incidents VALUES ('66ff0774a743c7c287bd9050e633730e5308dfd7', 'Health Canada', '2025-06-26', 2025, '2025-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Converta camping suspension stretchers', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled suspension stretchers and contact The Coleman Company Inc. for a free repair kit, including installation instructions.&nbsp;Consumers should visit the Coleman Company online at https://recall.coleman.com/ to verify whether their model is affected and to register for a free repair kit. For additional questions, call toll-free at 800-345-3278 from 9 a.m. to 5 p.m. ET Monday through Friday.Joint recall with Health Canada, the United States Consum', '77575');
INSERT INTO safety_incidents VALUES ('884ad94d37db3701844fbf32151d7638522963f6', 'Health Canada', '2025-06-26', 2025, '2025-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Bell Cadence Youth Helmets', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled helmets and contact Bell Sports for a refund. To receive a refund, consumers should (1) destroy the helmet by cutting off the straps, upload photos of the helmet with the straps cut to consumersupport-bell@bellhelmets.com to prove destruction, and dispose of the recalled helmet; or (2) contact Bell at (800) 456-2355, between 8:00 a.m. and 5 p.m. CT, Monday through Friday, or (3) Go to www.thebellgarage.com and click on the recall banner at the', '77631');
INSERT INTO safety_incidents VALUES ('ed7afbd7a3b88b7c2d5841e184ebea968e76616c', 'Health Canada', '2025-06-26', 2025, '2025-06', 'Canada', 'Canada', '', 'Tools & Machinery', 'DR Power 62-volt 5.0 Ah LiPRO rechargeable lithium-ion battery packs', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should stop using the rechargeable battery packs immediately and contact DR Power for a prorated refund based on age of the battery pack. For more information, consumers can contact DR Power&nbsp;toll-free at 1-800-940-6923 from 8:30 a.m. to 5:00 p.m. ET Monday through Friday, email at recalls@DRPower.com, or online at&nbsp;http://drpower.com/recalls&nbsp;or at&nbsp;www.drpower.com and click on “Product Recalls” for more information.Please note that the Canada Consumer Product Safety A', '77647');
