INSERT INTO safety_incidents VALUES ('ad20cee6e038a587ae8935901ab88ea05766687e', 'Health Canada', '2025-06-13', 2025, '2025-06', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'göt2b glued Blasting Freeze Spray', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard - Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Magic BM Trading Co. Ltd. for additional information.For more information, consumers can contact Magic BM Trading Co. Ltd. by telephone at (416) 256-9588, or by email at sales@magicbm.com.Please note that, in addition to the requirements of the Cosmetic Regulation the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.H', '77590');
