INSERT INTO safety_incidents VALUES ('8679e313f9655b773bb0ec57a45c6bdc459a431b', 'Health Canada', '2025-06-13', 2025, '2025-06', 'Canada', 'Canada', '', 'Medical Devices', 'Oracare Baby Brush toothbrush', 'Product Safety - Product Quality', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Product safety - Product quality', 'Not Reported', 0, 0, 'Stop using the Oracare Baby Brush toothbrush immediately.  Seek immediate medical attention from a health care professional if injury has occurred from using Oracare Baby Brush toothbrush.  Report any health product-related side effects or complaints to Health Canada.', '77607');
