INSERT INTO safety_incidents VALUES ('0f3a7c843371f773af07be570b89a2c078476b0d', 'Health Canada', '2025-06-12', 2025, '2025-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Manual Retractable Pool Covers', 'Drowning', 'Entrapment', 'Entrapment', 'Entrapment hazard - Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately contact Endless Pools for a free inspection and a free repair and only use the recalled products with close supervision. Endless Pools will inspect the pool covers and correct any installation as necessary to remedy the entrapment and drowning risks. Endless Pools is contacting all known purchasers directly.For more information, consumers can contact Endless Pools at 1-800-910-2714, Monday through Friday, from 8:00 a.m. to 5:00 p.m. EST, by email at poolhelp@endlessp', '77544');
INSERT INTO safety_incidents VALUES ('5eab80046363b1dd7e4603cec8c15f6a625bfa48', 'Health Canada', '2025-06-12', 2025, '2025-06', 'Canada', 'Canada', '', 'Household Items', 'Bugaboo Giraffe High Chair', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled high chair and contact Bugaboo to receive a free repair kit. &nbsp;Bugaboo is contacting all known purchasers directly.For more information, consumers can contact Bugaboo’s Customer Service team by telephone at 1-800-460-2922, Monday -Thursday 7:00 am – 4:00 pm, Friday 7:00am – 1:00 pm PST, by email at service.us@bugaboo.com or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US C', '77573');
INSERT INTO safety_incidents VALUES ('725d818ebfe497c1f410b3257619bc4670d1de8f', 'Health Canada', '2025-06-12', 2025, '2025-06', 'Canada', 'Canada', '', 'Tools & Machinery', 'RYOBI branded 40V cordless 24” hedge trimmer', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled hedge trimmers and visit the company''s website&nbsp;to determine if their trimmer is included in this recall and to obtain instructions on how to receive a free replacement trimmer.For more information, consumers can contact TTI Outdoor Power Equipment Inc. by telephone at 1-800-597-9624 from 9:00 a.m. to 5:00 p.m. ET, Monday through Friday, or visit the company''s website.Joint recall with Health Canada, the United States Consumer Product Safe', '77574');
INSERT INTO safety_incidents VALUES ('2d2f709fbe30c7b18e32192b0e4203b4ab28e0fe', 'Health Canada', '2025-06-12', 2025, '2025-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Yamaha Corporation PA-300C AC Power Adaptors', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Yamaha Corporation PA-300C AC Power Adaptors and contact Yamaha Canada to receive a replacement or have their product serviced. For more information, consumers can contact Yamaha Canada Music Ltd. by telephone at 416-708-1945, from 8:30am to 5pm EST, or visit the company website to fill out a claim form:EN:&nbsp;Yamaha PA-300C AC Power Adaptor RecallFR:&nbsp;Rappel volontaire de l’adaptateur secteur Yamaha PA-300C&nbsp;Please note that the Can', '77585');
