INSERT INTO safety_incidents VALUES ('11d5a1bb861578ff5677b4e8be9a488c8ebe8902', 'Health Canada', '2025-06-10', 2025, '2025-06', 'Canada', 'Canada', '', 'Processed', 'Genoa Salami Sweet, Genoa Salami Hot, Mild Genova Salami', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedConsumers who are unsure if they have purchased the affected product are advised to contact their retailerFood contaminated with Salmonella may not look or smell spoiled but can still make you sick. Young ', '77571');
INSERT INTO safety_incidents VALUES ('1335ed96b172d0ae50ce001ee4b27cc61de6ecc9', 'Health Canada', '2025-06-10', 2025, '2025-06', 'Canada', 'Canada', '', 'Household Items', 'Harriet Bee Wooden Height Adjustable Chair', 'Falls', 'Entrapment', 'Entrapment', 'Entrapment hazard - Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Harriet Bee Wooden Height Adjustable Chair and contact the company for a refund.For more information, consumers can contact Sichuan Rongyixing Huwai Yundong Co., Ltd. by telephone at +8613568623674 from 9:20 a.m. to 6:00 p.m. EST, Monday through Friday, or by email at wenjuangao1@163.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada ', '77572');
