INSERT INTO safety_incidents VALUES ('8febb65ef80d32efb1422b11e08eccc00fc50c7e', 'Health Canada', '2025-06-06', 2025, '2025-06', 'Canada', 'Canada', '', 'Drugs', 'Seasonique (DIN 02346176)', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Not Reported', 0, 0, 'Do not stop taking Seasonique. Do not skip taking any blue–greenCheck your package. If your package contains an extra row of yellow pills in Tray 1 and/or 2 of the blister cards, do not take them. Instead, return it to your pharmacy for a replacement or an alternative product.If you cannot get to a pharmacy right away, take the next blue–green pill in the proper order as noted in the instructions until you are able to contact your pharmacist and obtain a replacement or alternative product.If you', '77566');
