INSERT INTO safety_incidents VALUES ('6608fc10408f190c746ed490f55985cfd03c7325', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'HTP ELU Elite Ultra Wall Hung Gas-fired Boiler', 'Fire', 'Flammability / Overheating', 'Poisoning / Ingestion', 'Poisoning hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact a licensed installer to schedule a repair. If the boiler must remain operational to avoid freezing, ONLY operate the boiler with the front cover installed, and ONLY if there is a functional carbon monoxide detector in the boiler room and in the living space.If you do not have a record of your installer, contact a local plumbing &amp; heating contractor and have them contact HTP to obtain a free repair kit (HTP Part No. 4270', '77273');
INSERT INTO safety_incidents VALUES ('8da8c921a1a66a075f7a9ab2e74f2281405d62da', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Rinnai i-Series Plus Boilers', 'Poisoning Hazard', 'Other', 'Poisoning / Ingestion', 'Poisoning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled boilers and contact Rinnai America Corporation for a free repair by a certified technician.For more information, consumers can contact Rinnai America Corporation by telephone at 800-621-9419, from 8:00 am to 8:00 pm ET, Monday through Friday, by email at recall@rinnai.us or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Rinnai America Corporation.Please note that th', '77507');
INSERT INTO safety_incidents VALUES ('f0aaa36998e274bc9c5957c127f982987d760c35', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Other', 'Tehina', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serio', '77518');
INSERT INTO safety_incidents VALUES ('5715b465aa6adfd2671b0c52b4d13fda92d8e095', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Lutron Power Interface for LED Tape Lights', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled power interfaces and any connected lighting, turn off the power at the circuit breaker, and contact Lutron to arrange for a free replacement power interface. For more information, consumers can contact Lutron at 1-800-239-0495 from 8:00 a.m. to 5:30 p.m. ET Monday through Friday, by email at productrecall@lutron.com, or online at https://residential.lutron.com/us/en/safety/safety-recall or https://www.lutron.com/us/en and click on “Safety Noti', '77534');
INSERT INTO safety_incidents VALUES ('812bec87e97613f4cc5a62f3a14d9c92b91580a5', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Baseus Portable Chargers', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Baseus Portable Chargers&nbsp; and contact Baseus to receive a free replacement charger. The replacement portable charger will have the same model number (BS-30KP365) and a different serial number ending in the letter “A". Consumers will need to submit a photo of the recalled portable charger showing the model number and serial number to the firm’s&nbsp;recall registration page. Consumers without an order number will need to submit a photo of ', '77537');
INSERT INTO safety_incidents VALUES ('4779c20fedd18b6e81326dbbebaf8d71c7771c0a', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Building Materials And Supplies', 'Vevor Cable Railing Kits', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled cable railing kits and contact Vevor for a refund.For more information, consumers can contact Vevor by email at recalling@vevor.ca or visit the company’s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consume', '77541');
INSERT INTO safety_incidents VALUES ('48b78002e4aa6a15939a5ea5de98f548f7763510', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Tools & Machinery', 'DR Power Equipment lithium-ion battery-powered chainsaws', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled chainsaws and contact DR Power for a refund.&nbsp; Consumers will receive a pro-rated refund for the chainsaw tool based on the chainsaw’s age. Consumers will need to show proof of the chainsaw’s destruction by uploading a photo and filling out the recall form online. For instructions on destroying the chainsaw, visit&nbsp; https://www.drpower.com/BPC-recall. Consumers who choose to dispose of the chainsaw’s lithium-ion battery should recycle ', '77542');
INSERT INTO safety_incidents VALUES ('cc69e5082371843f847209b7e01815897f27ffcf', 'Health Canada', '2025-06-05', 2025, '2025-06', 'Canada', 'Canada', '', 'Drugs', 'Seasonale tablet', 'Packaging', 'Other', 'Not Specified', 'Packaging', 'Serious', 0, 0, 'Do not stop taking Seasonale. Do not skip taking any active (pink) pills until the very last row of tray 3 (which is the placebo [white] pills).Check your package. If it contains placebo (white) pills in tray 1 or 2 of the blister cards, do not take them, and return the product to your pharmacy for a replacement or alternative product.If you cannot get to a pharmacy right away, take the next active (pink) pill in the proper order as noted in the instructions until you are able to contact your ph', '77548');
