INSERT INTO safety_incidents VALUES ('750823dd039b7631d544c8bf67f16a6fdb03c22a', 'Health Canada', '2025-06-04', 2025, '2025-06', 'Canada', 'Canada', '', 'Other', 'Chill Pill Magnetic Haptic Fidget Toys Red Bumpy', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled FidgetThings Chill Pill Magnetic Haptic Fidget Toy Red Bumpy and Contact FidgetThings via email at fidgetthings@gmail.com to receive a pre-paid label to return the toy, or for instructions on how to dispose of the toy, to receive a full refund. FidgetThings is notifying all known purchasers directly.For more information, consumers can contact Fidget Things by email at fidgetthings@gmail.com or visit the company website.Please note that the Can', '77538');
INSERT INTO safety_incidents VALUES ('d018526cab81dcc1a12c32799a75a18657142cde', 'Health Canada', '2025-06-04', 2025, '2025-06', 'Canada', 'Canada', '', 'Frozen', 'Frozen Breaded Shrimp Patties, Frozen Tempura Shrimp Roll', 'Egg - Soy - Milk', 'Allergen', 'Not Specified', 'Egg - Soy - Milk', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '77545');
