INSERT INTO safety_incidents VALUES ('1c272b2a16673f26e78da71ff4fefbf641546e93', 'Health Canada', '2025-06-02', 2025, '2025-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Jigs of Discovery branded rod and reel combo kits', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled rod and reel combo kit and contact Lil Anglers to receive a refund.For more information, consumers can contact Lil Anglers toll-free by telephone at 844-347-4543, from 8 a.m. to 4:30 p.m., C.S.T. Monday&nbsp;through Friday, by email at info@anything-possible.com or visit the company website at https://www.kidcastersrecall.com or&nbsp;https://www.kidscasters.com and click on ”Recall Information”.Please note that the Canada Consumer Product Safe', '77517');
