INSERT INTO safety_incidents VALUES ('37ca32cd43ec1778a47f54f3ae5821bf6132ecbb', 'Health Canada', '2025-05-30', 2025, '2025-05', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Various Life Basis brand Radon Detectors', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Life Basis radon detector and dispose of it in accordance with municipal electronic waste requirements.&nbsp; &nbsp;Consumers can contact Life Basis for more information.&nbsp; Consumers should only purchase electronic radon monitors that have passed performance testing by the Canadian National Radon Proficiency Program (C-NRPP), the Canadian radon certification program recognized by Health Canada. Health Canada provides guidance for measuring', '77444');
INSERT INTO safety_incidents VALUES ('5d7b8af0fdde474afbadd36c84dd7ee49bca5822', 'Health Canada', '2025-05-30', 2025, '2025-05', 'Canada', 'Canada', '', 'Electrical & Electronics', 'InkBird Wifi Radon Detector model RD-2', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled InkBird Wifi Radon Detector and contact InkBird for a full refund.Consumers should only purchase electronic radon monitors that have passed performance testing by the Canadian National Radon Proficiency Program (C-NRPP), the Canadian radon certification program recognized by Health Canada. Health Canada provides guidance for measuring radon in homes: Guide for radon measurements in homes - Canada.ca.To learn about ways to measure the radon gas', '77461');
