INSERT INTO safety_incidents VALUES ('fbb6119861bd2d187de48c2c9637e8923a1d7ff2', 'Health Canada', '2025-05-28', 2025, '2025-05', 'Canada', 'Canada', '', 'Cannabis', 'Terroir – Royal Gorilla cannabis extract, lot 0002091', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased, or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '77512');
