INSERT INTO safety_incidents VALUES ('56d6df704cb98946ab96f2f824a6f102dd4a9a74', 'Health Canada', '2025-05-27', 2025, '2025-05', 'Canada', 'Canada', '', 'Drugs', 'Sivem ezetimibe 10 mg tablets', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'Check your medication bottle to ensure it only contains Sivem ezetimibe 10 mg tablets.Sivem ezetimibe 10 mg is a white oblong tablet, with “93" stamped on one side and "A11" on the other.Perindopril 4 mg is a spotted light green oblong tablet, with “4” stamped on one side and nothing stamped on the other. The tablet is scored (indented) on both middle edges.If the bottle contains any unusual tablets, or if you are unsure, return it to your pharmacy immediately. Your pharmacist will check the tab', '77495');
INSERT INTO safety_incidents VALUES ('63c6e9a2274253b9315d2226eacfb2235dfc8b2c', 'Health Canada', '2025-05-27', 2025, '2025-05', 'Canada', 'Canada', '', 'Household Items', 'bblüv Gröw Convertible Baby High chair', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact bblüv to obtain a replacement part.For more information, consumers can contact bblüv Inc. by telephone at 1-855-808-2636, from 9 a.m. to 4 p.m. (EST), by email at info@bbluvgroup.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or sa', '77504');
