INSERT INTO safety_incidents VALUES ('1cdff00459efafee41fde9d5a61eabf42586880d', 'Health Canada', '2025-05-23', 2025, '2025-05', 'Canada', 'Canada', '', 'Household Items', 'ZGRMBO Tabletop fire box', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers who have this affected product should immediately stop using it and safely dispose of it in such a way that it cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Product Inciden', '77489');
