INSERT INTO safety_incidents VALUES ('d18fa1e690ba92560ec9330ec2332f7d8c3d3a5e', 'Health Canada', '2025-05-18', 2025, '2025-05', 'Canada', 'Canada', '', 'Other', 'Tahini', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serio', '77471');
INSERT INTO safety_incidents VALUES ('a4a95517ba8ea205bb94c7cd94f3380bcf750ae4', 'Health Canada', '2025-05-16', 2025, '2025-05', 'Canada', 'Canada', '', 'Jewellery', 'Boutique Chic All Smiles Spinner Necklace, Bracelet and Ring', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled jewellery away from children and return it to the place of purchase for a full refund.For more information, consumers may contact Creative Education of Canada Inc. by telephone toll-free at 1-800-982-2642 or by email at&nbsp;productsafety@greatpretenders.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to rep', '77382');
INSERT INTO safety_incidents VALUES ('1e7e76792e2ed68e7dc62835abba05bde74f947f', 'Health Canada', '2025-05-16', 2025, '2025-05', 'Canada', 'Canada', '', 'Building Materials And Supplies', 'Ashland 10-inch and 14-inch Two-Bar Casement Window Hinge Tracks', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately close and lock the casement windows with the recalled hinge tracks and contact Amesbury Truth to arrange for a free window inspection by a professional, who will install free replacement hinge tracks for those which are out of specification. Consumers should leave the windows closed and locked until they can be inspected.For more information, consumers can contact Amesbury Truth by telephone at 1-844-329-9697 from 8 a.m. to 5 p.m. CT, Monday through Friday, by email ', '77453');
INSERT INTO safety_incidents VALUES ('919854de670697739b59b43bbde4c79707d6b963', 'Health Canada', '2025-05-16', 2025, '2025-05', 'Canada', 'Canada', '', 'Natural Health Products', 'ALLEVIATE Relief Stick', 'Product Safety', 'Allergen', 'Not Specified', 'Product safety', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '77462');
INSERT INTO safety_incidents VALUES ('5b2495e76689c910c21bae26cb4355c83c65710e', 'Health Canada', '2025-05-16', 2025, '2025-05', 'Canada', 'Canada', '', 'Drugs', 'Counterfeit Viagra (100 mg sildenafil tablets)', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Immediately stop using and safely dispose of the product.Consult a health care professional (physician, nurse, pharmacist) if you have taken this product and have health concerns.Only buy your prescription drugs from&nbsp;licensed pharmacies.&nbsp;If you have questions about whether a pharmacy is legitimate, contact the&nbsp;pharmacy regulatory authority&nbsp;in your province or territory. Read information on buying safe sexual enhancement products, including signs that your product is fake.Repo', '77463');
