INSERT INTO safety_incidents VALUES ('61ebfe60b0fecfb2f6d162997a2111d37324af6c', 'Health Canada', '2025-05-15', 2025, '2025-05', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Hanchen Home Radon Detector', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Hanchen Home Radon Detector device and dispose of it in accordance with municipal electronic waste requirements.&nbsp;&nbsp;&nbsp;Consumers should only purchase electronic radon monitors that have passed performance testing by the Canadian National Radon Proficiency Program (C-NRPP), the Canadian radon certification program recognized by Health Canada. Health Canada provides guidance for measuring radon in homes: Guide for radon measurements i', '77403');
INSERT INTO safety_incidents VALUES ('7af98300612811638832250ae04c93c412d98c0a', 'Health Canada', '2025-05-15', 2025, '2025-05', 'Canada', 'Canada', '', 'Toys & Childcare', 'Rollers Tile for PlayTab Modular Activity Board', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Rollers Tile and contact Fat Brain Toy Co. for information on how to dispose of the product and to obtain a replacement. For more information, consumers can contact Fat Brain Toy Co. by visiting the company website fatbraintoys.com and click "Recall" at the top of the page for more information.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health C', '77446');
