INSERT INTO safety_incidents VALUES ('2b893df8d2adc7fc1d9b7bc21dd1168358e13677', 'Health Canada', '2025-05-13', 2025, '2025-05', 'Canada', 'Canada', '', 'Chemicals', 'DeckWise® Deck & Wood Brightener', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled DeckWise® Deck &amp; Wood Brightener (16oz) product and dispose of it according to municipal hazardous waste guidelines. .&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; For more information, consumers can contact DeckWise by telephone at 1-866-427-2547, from 8:30am&nbsp; to 5:00pm EST, by', '77442');
INSERT INTO safety_incidents VALUES ('56e2752ab35779d6bc2e03841d003ecdd72885e7', 'Health Canada', '2025-05-13', 2025, '2025-05', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Various Hair Dryers sold on AliExpress.com', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact AliExpress to receive a full refund. Consumers must destroy the recalled hair dryer by cutting the cord and disposing of it. Consumers must send a photo of the destroyed hair dryer to us_product_recall@aliexpress.com by directly replying to the recall email sent by AliExpress.For more information, consumers can contact AliExpress online service at https://helpcenter.aliexpress.com/s/BuyerHelp/home?language=en_US&amp;m_stati', '77443');
