INSERT INTO safety_incidents VALUES ('1df4769691ae7af90a84e5c22fe5b044c7ba237f', 'Health Canada', '2025-05-03', 2025, '2025-05', 'Canada', 'Canada', '', 'Drugs', 'JAMP-Pregabalin 50 mg capsules', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Check your medication bottle to ensure it only contains 50 mg capsules.The 50 mg capsule is white with “PG” and “50” printed on it in black ink.The 150 mg capsule is white with “PG” and “150” printed on it in black ink.If it contains any 150 mg capsules, or if you are unsure, return it to your pharmacy immediately. Your pharmacist will check the capsules and provide you with a replacement, if needed.If you are unable to return your capsules to the pharmacy right away, talk to your pharmacist or ', '77398');
