INSERT INTO safety_incidents VALUES ('57b43ae855aef813a4823ec8b5feba875a2ce3d4', 'Health Canada', '2025-05-01', 2025, '2025-05', 'Canada', 'Canada', '', 'Household Items', 'Ninja Foodi Tendercrisp multi-cookers'' pressure cooking lid', 'Burns', 'Explosion', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Ninja Foodi multi-cookers’ pressure-cooking function and dispose of the existing pressure-cooking lid to prevent use. Consumers should contact SharkNinja to transmit confirmation of disposal of the lid and arrange for a replacement lid.For more information, consumers can contact SharkNinja by telephone Toll Free at 1-888-370-1733, from 9:00 a.m. to 9:00 p.m. ET, Monday through Friday and 9:00 a.m. to 6:00 p.m. Saturday, by email at sharkninja@', '77361');
