INSERT INTO safety_incidents VALUES ('31d98bbad2307e55f589bd51901addc4b70beb23', 'Health Canada', '2025-04-19', 2025, '2025-04', 'Canada', 'Canada', '', 'Other', 'Frozen pastries', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedConsumers who are unsure if they have purchased the recalled products are advised to contact their retailerFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you s', '77301');
INSERT INTO safety_incidents VALUES ('296e92d07a065d67f723ae5f54209b20da6d41a7', 'Health Canada', '2025-04-18', 2025, '2025-04', 'Canada', 'Canada', '', 'Drugs', 'JAMP Valproic Acid Oral Solution 250 mg/5 mL (DIN 02532441)', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Not Reported', 0, 0, 'Do not stop taking this medication or delay taking a scheduled dose, as valproic acid is an important drug for preventing seizures.Speak with your pharmacist as soon as possible. Your pharmacist will check if the product is affected by the recall and provide a replacement if needed.Do not ingest the crystals. If you cannot get to your pharmacy right away, check your product for crystals and ensure that no crystals are present in a dose before taking it or giving it to someone under your care.Con', '77302');
