INSERT INTO safety_incidents VALUES ('b0cd3cbf89d3488b940378a3102199e28c79b483', 'Health Canada', '2025-04-17', 2025, '2025-04', 'Canada', 'Canada', '', 'Household Items', 'VEVOR Wooden High Chair for Babies & Toddlers', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact VEVOR to receive instructions on how to obtain a full refund.For more information, consumers can contact VEVOR by email at recalling@vevor.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consum', '77283');
