INSERT INTO safety_incidents VALUES ('899f3bd1789989bf7d4cf4c5fe6be1ebec14bd6b', 'Health Canada', '2025-04-12', 2025, '2025-04', 'Canada', 'Canada', '', 'Processed', 'Black Forest Ham Sandwich', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Listeria monocytogenes&nbsp;may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and', '77270');
