INSERT INTO safety_incidents VALUES ('136f1a87b2e78a346bad9c1c74739fd3aaf04cbd', 'Health Canada', '2025-04-11', 2025, '2025-04', 'Canada', 'Canada', '', 'Household Items', 'HARPPA 4-in-1 Convertible High chair for Babies and Toddlers', 'Falls', 'Entrapment', 'Entrapment', 'Fall hazard - Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact HARPPA to receive instructions on how to obtain a full refund.For more information, consumers can contact HARPPA by email at Harpparecall@163.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other con', '77258');
