INSERT INTO safety_incidents VALUES ('76bddf267c9e517ea035ca8a283fe97ccef8bdc1', 'Health Canada', '2025-04-11', 2025, '2025-04', 'Canada', 'Canada', '', 'Drugs', 'NRA-Quetiapine XR', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected. Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns. Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '77266');
