INSERT INTO safety_incidents VALUES ('94bbd09698afb9e1492d06938fede52aa160b884', 'Health Canada', '2025-04-10', 2025, '2025-04', 'Canada', 'Canada', '', 'Toys & Childcare', 'Fisher-Price 3-in-1 SnugaPuppy Activity Center', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled tissue box toy, remove it from the activity center, keep it away from children and contact Fisher-Price to receive a free replacement toy for the activity center. Consumers will be asked to permanently mark the tissue box toy with the word "Recall" and the unique identifier, mark "X" on two parts of the pretend tissues, and upload a photo of the marked toy at https://service.mattel.com/us/recall.aspx. Upon receipt of the replacement confirmati', '77243');
