INSERT INTO safety_incidents VALUES ('21b22dd9cc6c0df0759059d8006f7874aaba7ffa', 'Health Canada', '2025-03-20', 2025, '2025-03', 'Canada', 'Canada', '', 'Clothing & Textiles', 'SHEIN EVRYDAY Kids’ Pajama Sets', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled sleepwear away from children, stop using them and contact SHEIN for a full refund. SHEIN is contacting all known purchasers directly.For more information, consumers can contact SHEIN by email at cacsteam@shein.com or online at https://ca.shein.com/ and click on “Recalls” at the bottom of the page for more information.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away ', '77130');
INSERT INTO safety_incidents VALUES ('e8ff0fb6212a6340fa33b2d365b1197a06a7f03b', 'Health Canada', '2025-03-20', 2025, '2025-03', 'Canada', 'Canada', '', 'Household Items', 'Multi-Mode Blue Blocking Sleep Lamp with Lithium-Ion Batteries', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard - Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Multi-Mode Sleep Lamp and contact BlockBlueLight to request a full refund in the original form of payment, a store credit or a free replacement lamp. Consumers should safely dispose of the product in such a way that it cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries. Batteries are considered hazardous waste. Do not place them in household garbage.For more informat', '77140');
