INSERT INTO safety_incidents VALUES ('7052c5f078120111d4c297ef4ddba86473db0860', 'Health Canada', '2025-03-19', 2025, '2025-03', 'Canada', 'Canada', '', 'Medical Devices', 'Continuous glucose monitoring smart device software applications', 'Inaccurate Test Or Measurement Results', 'Other', 'Not Specified', 'Inaccurate test or measurement results', 'Not Reported', 0, 0, 'If you feel unwell, check your glucose levels using your continuous glucose monitor or an alternative method, and seek medical attention if necessary.Actively monitor your glucose levels until you have determined whether the app is alerting you properly.Review the instructions provided with your continuous glucose monitor when installing, setting up, and updating glucose monitoring apps on your smart device.Check your alert settings and volume, and refer to your device’s manual to ensure the saf', '77131');
