INSERT INTO safety_incidents VALUES ('3d9df3384d81b9c5324a32b3e9ddbe575513cd29', 'Health Canada', '2025-03-13', 2025, '2025-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Black Diamond Vision Harness', 'Injury', 'Other', 'Eye Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled harness and return the product to Black Diamond Equipment for a full refund or voucher.To receive a refund or voucher, visit the Black Diamond Equipment website&nbsp;and follow the instructions to initiate the return process.For more information, consumers can contact Black Diamond Equipment by telephone at 1-866-306-0865, from 9:00 a.m. to 4:00 p.m. MT, Monday&nbsp;through Friday, by email at VisionHarnessRecall@bdel.com,&nbsp;or visit the&nb', '77106');
INSERT INTO safety_incidents VALUES ('4432e24f5e974db0b0da532d97f9ef569e021827', 'Health Canada', '2025-03-13', 2025, '2025-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'BMC Kaius 01 Bicycles and Framesets', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bicycles and contact an authorized BMC dealer for a free inspection and a free replacement of the forks.&nbsp;For more information, consumers can contact BMC USA by telephone at 1-888-262-7755 from 8:00 a.m. to 5:00 p.m. PT Monday through Friday, by email or visit the company website&nbsp;.&nbsp;Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and BMC USA.&nbsp;Please note that the Canada Consumer', '77108');
