INSERT INTO safety_incidents VALUES ('f6ab0c1e62c251803cb423067600669363f19ba3', 'Health Canada', '2025-03-12', 2025, '2025-03', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Teckwe Hair Dryer Brushes', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Teckwe Hair Dryer Brush and destroy the hair dryer brush by unplugging it, cutting the cord, and disposing of it in accordance with municipal electronic waste requirements. Consumers should send an image of the destroyed hair dryer to SHEIN Distribution Canada Limited at cacsteam@shein.com&nbsp;for a full refund. &nbsp;For more information, consumers can contact SHEIN Distribution Canada Limited by telephone at 1-203-990-1005, by email at cacs', '77035');
INSERT INTO safety_incidents VALUES ('311b3202ccb463809293de9ef28ab220d2ea7ee2', 'Health Canada', '2025-03-12', 2025, '2025-03', 'Canada', 'Canada', '', 'Clothing & Textiles', 'DUNLOP Purofort FoodPro Safety Boots', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to the store where it was purchased to obtain a refund.For more information, consumers can contact Chaussures Régence Inc. by telephone at 1-888-412-2866, Monday to Thursday from 8:00 a.m. to 4:30 p.m. EST, and Friday from 8:00 a.m. to 3:30 p.m. EST, by email at ra@regence.ca or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or e', '77089');
