INSERT INTO safety_incidents VALUES ('e6be99ec96006d746692c5824049f00238dbd174', 'Health Canada', '2025-03-11', 2025, '2025-03', 'Canada', 'Canada', '', 'Tools & Machinery', 'Yardworks 15-Amp Electric Corded Snowblower, 22-in', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to any Canadian Tire Store for a full refund.For more information, consumers may contact the Canadian Tire Call Centre by telephone toll-free at 1-800-387-8803.&nbsp; The call centre is open Monday to Friday from 8:00 a.m. to 9:00 p.m. EST, and on Saturday and Sunday from 9:00 a.m. to 5:00 p.m. EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even', '72962');
