INSERT INTO safety_incidents VALUES ('34754248aaf46594f0d420533f1946dcb4232c50', 'Health Canada', '2025-02-27', 2025, '2025-02', 'Canada', 'Canada', '', 'Household Items', 'Certain Kichler Ellerbeck Wall Sconces', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the product and contact Kichler Lighting LLC for a replacement.For more information, consumers can contact the Kichler Lighting LLC at 1-866-558-5706, from 8:00 a.m. to 4:30 p.m. ET, Monday through Friday, or online at www.kichler.com/customer-care/contact-us and use the webform to submit a "Product Questions" email to request more information.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Kichler Lighti', '76986');
INSERT INTO safety_incidents VALUES ('c5de304349eb56f65d7ac7d3316d4963fc4a78f7', 'Health Canada', '2025-02-27', 2025, '2025-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Starmaker USB-A Wall Charger', 'Fire', 'Electrical Fault', 'Electric Shock', 'Electrical hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return the product for a refund or dispose of the product in accordance with municipal electronic waste requirements.For more information, consumers can contact Pro Line Sports Ltd. by telephone at 1-877-407-3001, from Monday to Friday, between 9:00 AM and 5:00 PM AST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would li', '76990');
INSERT INTO safety_incidents VALUES ('ee9303df57e978ea6fe1541057656b0f59d07c4b', 'Health Canada', '2025-02-27', 2025, '2025-02', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Forever 21, Too Cute t-shirt and short pajama set', 'Fire', 'Flammability / Overheating', 'Laceration / Cut', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and destroy it by cutting the top and bottom in half and disposing of them. Consumers should e-mail a photo of the destroyed garment to the company at recall@forever21.com to receive a full refund. For more information, consumers can also view the recall on the company’s X and Facebook account at x.com/forever21 and www.facebook.com/forever21.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC', '77014');
INSERT INTO safety_incidents VALUES ('6def6f276064e10231c42b1e95a93c4b8ccd8ab7', 'Health Canada', '2025-02-27', 2025, '2025-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Goal Zero 4x HPP to 1x HPP+ Solar Series Combiner', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Goal Zero 4x HPP to 1x HPP+ Solar Series Combiner and contact Goal Zero for a refund.For more information, consumers can contact Goal Zero by toll-free telephone at 888-794-6250 from 9 a.m. to 5 p.m. MT, Monday through Friday, visit the company website https://goalzero.com/pages/notices-recalls, or www.goalzero.com and click on "Notices/Recalls" at the bottom of the page.Please note that the Canada Consumer Product Safety Act prohibits recalle', '77015');
INSERT INTO safety_incidents VALUES ('f7df2170fc292e90c2088ab2e203446d61861caa', 'Health Canada', '2025-02-27', 2025, '2025-02', 'Canada', 'Canada', '', 'Cannabis', 'Cloudz - Cloudz 7g dried cannabis flowers, Lot BA25DF1', 'Contamination', 'Other', 'Not Specified', 'Microbial contamination', 'Not Reported', 0, 0, 'Consumers should verify whether their product is affected. If you wish to return affected product, please contact the retail store where the product was purchased.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '77017');
INSERT INTO safety_incidents VALUES ('cf9b50f479fdd24bc8411911310c42af92bd186f', 'Health Canada', '2025-02-27', 2025, '2025-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Prestige Solo, Prestige Excellence, and Aerco Esteem Condensing Gas Boilers', 'Poisoning Hazard', 'Other', 'Poisoning / Ingestion', 'Poisoning hazard', 'Not Reported', 0, 0, 'Consumers should immediately contact Triangle Tube to schedule a free boiler inspection and if applicable, free installation of a new boiler ignition system. Consumers who continue using the recalled boilers while awaiting repair should have working carbon monoxide alarms on each level of their homes and outside sleeping areas. Consumers who do not have a carbon monoxide alarm can contact Triangle Tube to have one shipped to them free of charge.For more information, consumers can contact Triangl', '77029');
