INSERT INTO safety_incidents VALUES ('6c6ac0f60898cb5af3a02759caf0308c37e3bce1', 'Health Canada', '2025-02-21', 2025, '2025-02', 'Canada', 'Canada', '', 'Other', 'Travel Car Seat For Toddler', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and safely dispose of the items in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Pr', '76979');
