INSERT INTO safety_incidents VALUES ('37c5b962511a837018d1448eb7f988a4bd4b9a9f', 'Health Canada', '2025-02-20', 2025, '2025-02', 'Canada', 'Canada', '', 'Other', 'Kubota MX5400DTC tractors', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Kubota MX5400DTC Tractor and to contact a local dealer for a no-charge repair/replacement of the clutch cable.&nbsp; For more information, consumers can contact Kubota Canada Ltd. toll free at 1-800-405- 6916, from 8:30 a.m. to 4:30 p.m. ET, Monday through Friday, by email at kcl_g.customerservice@kubota.ca or through the company''s website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Kubot', '76897');
