INSERT INTO safety_incidents VALUES ('99ffdba6c0e8651bb8e01a71cce648887b196605', 'Health Canada', '2025-02-19', 2025, '2025-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'LoGest Climbing Ropes with Carabiners and LoGest Climbing Ropes with Heavy-Duty Metal Hooks', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled climbing ropes, uninstall them, and register for a full refund at&nbsp;www.LoGestRopeRecall.com. Consumers will receive a form to sign as part of the disposal of the climbing ropes. Consumers must follow the disposal directions on the form and email a photo of the disposed rope to&nbsp;LoGestRecall@gmail.com&nbsp;to receive their refund. Full refunds will be issued via Amazon to the original form of payment associated with the order. Amazon is', '76966');
INSERT INTO safety_incidents VALUES ('974c93cb1217d66c7492e2c10f66388d4e088168', 'Health Canada', '2025-02-19', 2025, '2025-02', 'Canada', 'Canada', '', 'Other', 'John Deere ZTrak™ Zero Turn Mowers with Kawasaki Engines', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard - Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled mowers and contact an authorized John Deere dealer for a free repair. For more information, consumers can contact Deere &amp; Company by telephone at 1-800-537-8233, from 8 a.m. to 6 p.m. EST, Monday through Friday&nbsp;and 9 a.m. to 3 p.m. EST Saturdays, or visit the company website at https://www.deere.com/en/parts-and-service/recall-information/.&nbsp;Consumers can also visit Kawasaki Motors Corp. USA’s website online at&nbsp;www.kawasakien', '76973');
