INSERT INTO safety_incidents VALUES ('af12263cc5d560bf35c92f83495182d8246f437f', 'Health Canada', '2025-02-19', 2025, '2025-02', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Original Date Square, Chocolate Date Square', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Salmonella may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serious and som', '76980');
