INSERT INTO safety_incidents VALUES ('34faedf0ba542df2a177886ffebc12e944f5e3c0', 'Health Canada', '2025-02-18', 2025, '2025-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Powerextra 4000mAh V6 Battery Replacement for Portable Vacuums', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled battery and safely dispose of them according to municipal guidelines. Batteries are considered hazardous waste. Do not place them in household garbage.&nbsp;For more information, consumers can contact Shenzhen Haiming Electronic Commerce Co., Ltd. by email at haiming10082020@yeah.net.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada woul', '76815');
INSERT INTO safety_incidents VALUES ('2adeafc5d311104e22207f81d92825a2245380f5', 'Health Canada', '2025-02-18', 2025, '2025-02', 'Canada', 'Canada', '', 'Chemicals', 'NOW Eucalyptus Globulus Oil', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled NOW Eucalyptus Globulus Oil, keep it out of reach of children and return it to the retailer for a refund.For more information, consumers can contact Puresource Natural Products by telephone at 1-800-265-7245, Monday to Friday, from 8:30 am to 5:00 pm EST or by email at recall@puresource.ca. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Cana', '76967');
INSERT INTO safety_incidents VALUES ('bce85b74ecb753852a89377b1c93e8d2b31073d9', 'Health Canada', '2025-02-18', 2025, '2025-02', 'Canada', 'Canada', '', 'Drugs', 'BD ChloraPrep™ Clear - 1mL Applicator', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '76970');
