INSERT INTO safety_incidents VALUES ('0769243ebe3efd0f58ebc585a6730f1c5f8c862f', 'Health Canada', '2025-02-07', 2025, '2025-02', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'amika Mirrorball High Shine + Protect Antioxidant Shampoo', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Mirrorball shampoo and return the product to the place of purchase with proof of purchase to obtain a refund.For more information, consumers can contact amika by telephone at 1-888-262-3713, Monday to Friday, 9am to 5:30pm EST, by email at mirrorball@rqa-inc.com or visit the company website.Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either', '76924');
