INSERT INTO safety_incidents VALUES ('687855ccf69daa6997057f7699e34366fbecf19a', 'Health Canada', '2025-02-06', 2025, '2025-02', 'Canada', 'Canada', '', 'Toys & Childcare', 'First Act America’s Got Talent Microphone', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled America’s Got Talent Microphone and contact Jazwares, LLC for a full refund. Once registered for a refund, consumers should dispose of the microphone in accordance with municipal waste regulations.For more information, consumers can contact Jazwares, LLC by telephone at 1-888-341-0881, from 9:00 a.m. to 4:00 p.m. PST, by email at micrecall@jazwares.com or visit the company website. Joint recall with Health Canada, the United States Consumer Pr', '76717');
INSERT INTO safety_incidents VALUES ('cf21f22c6c9453849fd0bbadfb4a6c2bba0a7434', 'Health Canada', '2025-02-06', 2025, '2025-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'Bobcat & Steiner AirFX Finish Mower Deck', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should inspect and determine whether locking pins can be inserted while the deck is in the upright or tilted position during maintenance or service. Contact Doosan Bobcat North America or a Bobcat dealer to obtain a free repair which will be available in the near future. Until then, if the locking pins cannot be inserted, obtain two straps, each rated for 1,500 lbs, and wrap a strap around each front tractor axle, securing each strap to the mower deck when performing service or mainten', '76814');
INSERT INTO safety_incidents VALUES ('a60a68dda08fdaf6619b1725ffd164c90a32e847', 'Health Canada', '2025-02-06', 2025, '2025-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'ARIENS DELUXE - PLATINUM - and PROFESSIONAL-Series Snow Throwers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Ariens® Company or an authorized dealer for a free repair. The dealer locator is available at https://www.ariens.com/en-us/dealer-locator. For more information, consumers can contact Ariens Company toll-free at 877-740-7060, from 8 a.m. to 4 p.m. CT, Monday through Friday or visit the company website&nbsp;and click on "Safety Recalls".Joint recall with Health Canada, the United States Consumer Product Safety Commission (US', '76901');
INSERT INTO safety_incidents VALUES ('6a7b6b7f38db02dc9e28e01955c5bc020c4dcf8c', 'Health Canada', '2025-02-06', 2025, '2025-02', 'Canada', 'Canada', '', 'Tools & Machinery', 'RYOBI 40 Volt Brushless 21” Cordless Walk-Behind Mowers', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled mowers and contact TTIOPE for instructions on how to safely disable the mower and receive a free replacement 21” walk-behind mower. For more information, consumers can contact TTI Outdoor Power Equipment Inc. toll free at 800-597-9624 from 9 a.m. to 5 p.m. ET, Monday through Friday, or online at ryobitools.com/support/safety or ryobitools.com and click on Important Recall Information for more information. Joint recall with Health Canada, the U', '76902');
