INSERT INTO safety_incidents VALUES ('82093a2d3839a525e740d6d6d2d33b4a7885f141', 'Health Canada', '2025-01-30', 2025, '2025-01', 'Canada', 'Canada', '', 'Toys & Childcare', 'Pearhead 0-6 m Learning Kit', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Pearhead 0-6 m Learning Kit and contact Pearhead, Inc. to receive a refund and replacement wooden egg shaker.For more information, consumers can contact Pearhead, Inc. by email at service@pearhead.com, or visit the company website at&nbsp;https://pearhead.com/pages/product-recall.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Pearhead, Inc.Please note that the Canada Consumer Product Safety ', '76877');
INSERT INTO safety_incidents VALUES ('d701751f58563040037dcd5485458fd4f0641505', 'Health Canada', '2025-01-30', 2025, '2025-01', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Ivy City Mini Bella Bunny Pajamas, Mini Camille Pajamas and Mini Petra Nightgown', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled pajamas and contact Ivy City for a full refund. Consumers should destroy the garments by cutting them in half and disposing of them. Consumers should email Ivy City a photo of the destroyed garment at hello@ivycityco.com to receive a refund. Ivy City is contacting all known purchasers directly.For more information, consumers can contact Ivy City by telephone at 1-888-915-8609, from 9am to 4pm MT, Monday through Friday, by email at hello@ivycit', '76879');
