INSERT INTO safety_incidents VALUES ('2e69a597a3faa4b427bebf2eb7fb886658b1f2bc', 'Health Canada', '2025-01-16', 2025, '2025-01', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Lexmark specialty printers', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled printers and contact Lexmark to receive a free repair part. For more information, consumers can contact Lexmark by telephone at 1-866-470-1574, from 9:00 a.m. to 9:00 p.m. ET, Monday through Friday, by email at safety@lexmark.com, or online at www.lexmark.com/recall or www.lexmark.com and click on “Recall” at the bottom of the page for more information.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CP', '76797');
INSERT INTO safety_incidents VALUES ('ddbd4fe37d56d5339da0bcc053a9bcd6d24bf4f0', 'Health Canada', '2025-01-16', 2025, '2025-01', 'Canada', 'Canada', '', 'Household Items', 'Northern Tool Adjustable Swivel Shop Stools with Backrests', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, detach the stool seat from its hydraulic cylinder, and dispose of each piece according to municipal waste guidelines. To receive a free replacement stool, complete the form at https://www.northerntool.com/recall-details-20230.&nbsp; For more information, consumers can contact Northern Tool + Equipment Company, Inc., by telephone at 1-888-518-0342, from 8 a.m. to 5 p.m. CST, Monday through Friday, by email at inquiry@northerntool.com, ', '76813');
