INSERT INTO safety_incidents VALUES ('817e887b9eb289439444dd77a62bed25f64f5692', 'Health Canada', '2024-12-23', 2024, '2024-12', 'Canada', 'Canada', '', 'Household Items', 'VEVOR Baby Gate', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact VEVOR to arrange a return for refund.For more information, consumers can contact VEVOR by email at recalling@vevor.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic b', '76731');
