INSERT INTO safety_incidents VALUES ('07d05f90136f2a407c62d5e5017107a95e960b26', 'Health Canada', '2024-12-20', 2024, '2024-12', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Unbranded Blue Beam Laser Pointer and JD-303 Green Laser Pointer', 'Injury', 'Other', 'Eye Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled lasers and return them to the place of purchase for a full refund.For more information, consumers can contact International Camouflage Ltd. by telephone at 1-877-315-2266, Monday to Friday 9am to 6pm PST, or by email at sales@camouflage.ca.Handheld lasers that are Class 3B or Class 4 fall under Table 3 of the Canada Consumer Product Safety Act general prohibitions. These products may pose an eye injury hazard to children, adult users and bysta', '76711');
