INSERT INTO safety_incidents VALUES ('a5984e0839e5afbefb35c48984e66165e06a8ace', 'Health Canada', '2024-12-17', 2024, '2024-12', 'Canada', 'Canada', '', 'Household Items', 'Qaba Toddler Kitchen Helper 2 Step Stool', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Qaba Toddler Kitchen Helper 2 Step Stool and contact Aosom Canada for instructions on how to correct the product for continued use.&nbsp; For more information, consumers can contact Aosom Canada by telephone at 416-792-6088 or 1-877-792-6080, Monday to Friday, from 9:00 am and 5:00 pm EST, by email at customerservice@aosom.ca, or by visiting the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products', '76649');
