INSERT INTO safety_incidents VALUES ('4a8e6a377c98c1e7d21c5ae113eb8d912a64f9c8', 'Health Canada', '2024-12-16', 2024, '2024-12', 'Canada', 'Canada', '', 'Veterinary Drugs', 'ANTIHISTAMINE ORAL', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '76709');
INSERT INTO safety_incidents VALUES ('3af1fb2ed4c042840f50c2a31a5a3ff3cbad09b3', 'Health Canada', '2024-12-13', 2024, '2024-12', 'Canada', 'Canada', '', 'Fresh', 'Field cucumbers, slicer cucumbers', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedConsumers who are unsure if they have purchased the recalled product are advised to contact their retailerFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you si', '76632');
INSERT INTO safety_incidents VALUES ('154ef3a3195bc29be2374e0c1ac3cb9eb3f6518b', 'Health Canada', '2024-12-13', 2024, '2024-12', 'Canada', 'Canada', '', 'Toys & Childcare', 'Balloon blowing kits', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and dispose of the items according to municipal hazardous waste guidelines.Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Produ', '76683');
