INSERT INTO safety_incidents VALUES ('0b87fb0fc1c85384ba9906a9a7dfc726711b6824', 'Health Canada', '2024-12-12', 2024, '2024-12', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Yoto Mini Speakers', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact the company to receive a free battery replacement kit. Consumers who already received the smart cable should still register for the free battery replacement kit.For more information, consumers can contact Yoto Inc. by telephone at 844-370-0426 (English) or 844-364-2473 (French),&nbsp;9:00 am to 5:00 pm CDT, by email at minihelp@yotoplay.com or visit the company website.Joint recall with Health Canada, the United States Cons', '75329');
