INSERT INTO safety_incidents VALUES ('a3190d0e938171f6db7f5c795db550f501e0a2e5', 'Health Canada', '2024-12-11', 2024, '2024-12', 'Canada', 'Canada', '', 'Toys & Childcare', 'Snappy Plush cat model', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and either throw them away or return them to where they were purchased for a refund.&nbsp;For more information, consumers can contact Groupe Ricochet Inc. by telephone at 450-939-3429, between 8 a.m. - 5 p.m, Monday to Friday.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.&nbsp;Health Canada would like to remind consumers to report any hea', '76541');
INSERT INTO safety_incidents VALUES ('831268f5e167743c34348b0736869befb8a2854b', 'Health Canada', '2024-12-11', 2024, '2024-12', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Petidoux Celebration Girl’s Summer Pajama Sets', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled pajama set and contact Petidoux to receive a full refund. Consumers should destroy the garments by cutting them in half and disposing of them. Consumers may send a photo of the destroyed garment to customerservice@petidoux.com&nbsp;to receive a full refund or a store credit worth 1.25 times the purchase price. &nbsp;For more information, consumers can contact Petidoux by telephone at 1-888-381-7171, from 9 a.m. to 5 p.m. ET Monday through Frid', '76665');
INSERT INTO safety_incidents VALUES ('5ba4c48a940e9a411ce438a3da7b9ad6a5a5832f', 'Health Canada', '2024-12-11', 2024, '2024-12', 'Canada', 'Canada', '', 'Household Items', 'Maison Lavande candles in a ceramic container', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products, dispose of them and contact La Maison Lavande for a refund.For more information, consumers can contact La Maison Lavande by phone at 450-473-3009, by email at bougie@maisonlavande.ca, or visit the company''s recall website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or sa', '76667');
INSERT INTO safety_incidents VALUES ('bce5e2a7e2be7ee739433dc9b692bb2b0e992394', 'Health Canada', '2024-12-11', 2024, '2024-12', 'Canada', 'Canada', '', 'Household Items', 'Medical King Bed Assist Rail Adult Portable Bed Rails', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bed rails and contact Medical King for a free repair kit or a replacement bed rail, depending on the model.For more information, consumers can contact Medical King by telephone at 888-715-2630, 9 a.m. to 5 p.m. ET, Monday through Friday, or visit the company website at https://medicalkingusa.com/products/recalls&nbsp;or&nbsp;https://medicalkingusa.com&nbsp;and click on “Product Recalls” at the top of the page for more informationPlease note th', '76668');
INSERT INTO safety_incidents VALUES ('c4f7427c382dd41293efa7d903a7243916649109', 'Health Canada', '2024-12-11', 2024, '2024-12', 'Canada', 'Canada', '', 'Chemicals', 'MG Chemicals 801B Super Contact Cleaner with PPE, 413B Heavy Duty Flux Remover and 4140 Flux Remover for PC Board', 'Fire', 'Chemical / Toxic Substance', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to MG Chemicals for a refund or disposal.&nbsp; For more information, consumers may contact MG Chemicals Ltd by telephone toll-free at 1-800-340-0772, Monday to Friday, from 7:30 a.m. to 4:00 p.m. EST, or by email&nbsp;at info@mgchemicals.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind con', '76669');
INSERT INTO safety_incidents VALUES ('48e11fa45dceee9d346fba4215c0749a38657054', 'Health Canada', '2024-12-11', 2024, '2024-12', 'Canada', 'Canada', '', 'Nuts, Grains, And Seeds', 'Bitter Apricot Kernels', 'Contamination', 'Other', 'Poisoning / Ingestion', 'Contamination', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedApricot kernels naturally contain amygdalin, which can release cyanide after being eaten. The human body can eliminate small amounts of cyanide, but larger amounts can result in cyanide poisoning, which co', '76675');
