INSERT INTO safety_incidents VALUES ('38da5e31d6e0fedd25cc232b3974242ca7b501ff', 'Health Canada', '2024-11-07', 2024, '2024-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Wolf Dual Fuel range with infrared griddle', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Wolf Dual Fuel Range and contact Wolf Appliance to schedule a free repair in their home.&nbsp; &nbsp;For more information, consumers can contact &nbsp;Wolf Appliance by telephone at 1-800-200-7820 from 8 a.m. to 4:30 p.m. CT Monday through Friday, by email at &nbsp;support@wolfappliance.com or online at www.wolfappliance.com/recall or www.subzero-wolf.com and click on “Important Recall Information” at the bottom of the website for more informa', '76415');
INSERT INTO safety_incidents VALUES ('6876a0a9acd9574ba6cfab3fe8f22eadfaacd5aa', 'Health Canada', '2024-11-07', 2024, '2024-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Quad Lock MAG Battery Pack', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Quad Lock MAG Battery Pack (QMA-BPK-5000)&nbsp;and contact Quad Lock. Consumers should safely dispose of the items in such a way that they cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries.&nbsp; Batteries are considered hazardous waste. Do not place them in household garbage.&nbsp; For more information, consumers can contact Quad Lock by telephone toll-free at 833-', '76445');
INSERT INTO safety_incidents VALUES ('e3950c476edd6f2b0afcce0e0006d95bf10ad947', 'Health Canada', '2024-11-07', 2024, '2024-11', 'Canada', 'Canada', '', 'Household Items', 'Various models of GoveeLife and Govee Smart Electric Space Heaters', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard - Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled heaters and register for a refund at https://recall.goveelife.com/heater-recall. For more information, consumers can contact Govee Moments Trading Limited via telephone 1-833-772-5360, Monday to Friday 9:00 am to –5:00 pm EST, by email at heatersupport@goveelife.com or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC), and Govee Moments Trading Limited.Please note that the', '76452');
