INSERT INTO safety_incidents VALUES ('cda9ed8101fbdf1803631abdd1291812462c58bd', 'Health Canada', '2024-10-28', 2024, '2024-10', 'Canada', 'Canada', '', 'Grain Products', 'Homestyle Waffles', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '76396');
