INSERT INTO safety_incidents VALUES ('8b751d0192c39264aff1d2eaa85f8923d319d6d6', 'Health Canada', '2024-10-25', 2024, '2024-10', 'Canada', 'Canada', '', 'Processed', 'Ham in Jelly (Jelly Pork); Ham Jelly Coppacotta Wageners; Lean Ham Jelly', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '76341');
INSERT INTO safety_incidents VALUES ('dca87738e633d3d53d496055934d1b2a1d2bfd2b', 'Health Canada', '2024-10-25', 2024, '2024-10', 'Canada', 'Canada', '', 'Chemicals', 'Aqua Mix - Grout Deep Clean', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Aqua Mix - Grout Deep Clean and contact Custom Building Products of Canada Ltd. for a refund.For more information, consumers can contact Custom Building Products of Canada Ltd. by telephone at 1-800-272-8786, Monday through Friday, from 7:00 am to 8:00 pm (EST), by email at customersupport@cbpmail.net or by visiting the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed,', '76378');
INSERT INTO safety_incidents VALUES ('77cc54e9117acbd338d89d4c156318c408bd3d61', 'Health Canada', '2024-10-25', 2024, '2024-10', 'Canada', 'Canada', '', 'Household Items', 'Baby walkers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and safely dispose of the items in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Pr', '76380');
INSERT INTO safety_incidents VALUES ('9bc7c4d327239a860a63da47ad42850be9913a86', 'Health Canada', '2024-10-25', 2024, '2024-10', 'Canada', 'Canada', '', 'Grain Products', 'Organic Waffles', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '76395');
INSERT INTO safety_incidents VALUES ('d521207ab7114a2faf6fed02b191be7e70cc412b', 'Health Canada', '2024-10-24', 2024, '2024-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'PowerBlock Commercial Pro 100 adjustable dumbbell system', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the 5 lb grip handles and contact PowerBlock, Inc. to receive replacement decals and a replacement handle.&nbsp; For more information, consumers can contact Power Block, Inc. by telephone at 1-800-997-3999, from 8:30 a.m. to 5:00 p.m. ET, Monday through Friday, or by email at questions@powerblock.com or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Power Block, Inc.Please note ', '75884');
INSERT INTO safety_incidents VALUES ('6d3a26372ce4a90fe35251e9b12c468e30d293e0', 'Health Canada', '2024-10-24', 2024, '2024-10', 'Canada', 'Canada', '', 'Frozen', 'Fish Cake', 'Egg', 'Allergen', 'Not Specified', 'Egg', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '75897');
