INSERT INTO safety_incidents VALUES ('73e119f87914cfff30f44e35121043b9f3231d05', 'Health Canada', '2024-10-01', 2024, '2024-10', 'Canada', 'Canada', '', 'Suv', 'SUV recalled by GENERAL MOTORS', 'Brakes', 'Radiation', 'Not Specified', 'Brakes', 'Not Reported', 0, 0, '', '76108');
INSERT INTO safety_incidents VALUES ('d1ef703df111287b85fcbad40b8461a54e88537b', 'Health Canada', '2024-10-01', 2024, '2024-10', 'Canada', 'Canada', '', 'Chemicals', 'Various Ballistol Cleaning Oils and Gun Maintenance Products', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Ballistol products and contact North Sylva Sports to obtain a replacement label.For more information, consumers can contact North Sylva Sports by telephone at (416) 242-4867 Ext 781, Monday to Friday from 9:00 a.m. to 4:00 p.m. EST, or by email.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any', '76222');
INSERT INTO safety_incidents VALUES ('4945cc028164018e4593bb7005e641440c54315f', 'Health Canada', '2024-10-01', 2024, '2024-10', 'Canada', 'Canada', '', 'Rv Trailer', 'RV Trailer recalled by BRINKLEY RV', 'Structure', 'Other', 'Not Specified', 'Structure', 'Not Reported', 0, 0, '', '76243');
INSERT INTO safety_incidents VALUES ('2cd5958804f34f633ccc05a285387a0ccd53aba3', 'Health Canada', '2024-09-27', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'M-Eslon capsule', 'Labelling', 'Other', 'Not Specified', 'Labelling', 'Serious', 0, 0, 'Check your M-Eslon (morphine sulfate) medication bottle or package. If your prescription is for 30 mg, the capsules should be pink and clear. If it contains 60 mg capsules (orange and clear), or if you are unsure,&nbsp;do not take these capsules&nbsp;and contact your pharmacy immediately. Your pharmacist will check the capsules and provide you with a replacement if needed. Return the affected product to your pharmacy for proper disposal.Call 911 immediately&nbsp;and seek immediate medical attent', '76224');
INSERT INTO safety_incidents VALUES ('ff959f2fce5e48a77dedaaa1cb3df0745b733260', 'Health Canada', '2024-09-27', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'Mint-Risperidon 0.25 mg tablet', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '76225');
INSERT INTO safety_incidents VALUES ('0949ba0729b8f483b497fff637640c15746181cb', 'Health Canada', '2024-09-27', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'M-Eslon (morphine sulfate) bottles labelled to contain 30 mg extended-release capsules may contain 60 mg extended-release capsules', 'Product Safety', 'Other', 'Poisoning / Ingestion', 'Product safety', 'Not Reported', 0, 0, 'Check your M-Eslon (morphine sulfate) medication bottle or package. If your prescription is for 30 mg, the capsules should be pink and clear. If it contains 60 mg capsules (orange and clear), or if you are unsure,&nbsp;do not take these capsules&nbsp;and contact your pharmacy immediately. Your pharmacist will check the capsules and provide you with a replacement if needed. Return the affected product to your pharmacy for proper disposal.Call 911 immediately&nbsp;and seek immediate medical attent', '76226');
