INSERT INTO safety_incidents VALUES ('4af802a8ecff22e16ea5d486ed25ad29f6af59ad', 'Health Canada', '2024-09-25', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'Cromolyn eye drops', 'Product Quality', 'Other', 'Eye Injury', 'Product quality', 'Moderate', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for&nbsp;proper disposal.Consult a health care professional if you have used this product and have health concerns.Contact Pendopharm Division of Pharmascience Inc. by calling 1-888-550-6060 or emailing&nbsp;medinfo@pendopharm.com&nbsp;if you have questions about this recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '76185');
INSERT INTO safety_incidents VALUES ('a40ca037ddc2a51522f2d6fb443fe2d009a6d588', 'Health Canada', '2024-09-25', 2024, '2024-09', 'Canada', 'Canada', '', 'Chemicals', 'Various MG Chemicals Industrial Strength products', 'Labelling And Packaging', 'Chemical / Toxic Substance', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return to MG Chemicals for a refund. &nbsp;For more information, consumers may contact MG Chemicals Ltd by telephone toll-free at 1-800-340-0772, Monday to Friday, from 7:30 a.m. to 4:00 p.m. EST or by email.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incide', '76190');
