INSERT INTO safety_incidents VALUES ('dae3c2291a3f5ceb3ce0caf56c8796f2db992ee2', 'Health Canada', '2024-09-25', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'All lots of Cromolyn Eye Drops, 5 mL & 10 mL formats (DIN 02009277)', 'Product Safety', 'Other', 'Eye Injury', 'Product safety', 'Not Reported', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for proper disposal.Consult a health care professional if you have used this product and have health concerns.Contact Pendopharm Division of Pharmascience Inc. by calling 1-888-550-6060 or emailing medinfo@pendopharm.com if you have questions about this recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '76202');
