INSERT INTO safety_incidents VALUES ('f5fad401b7856f9917af5f6cdb29383abfc5d34a', 'Health Canada', '2024-09-24', 2024, '2024-09', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Anker 334 MagGo Battery (PowerCore 10K), Model: A1642', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the product and visit the company website&nbsp;to determine if your product has an affected serial number. If your product is verified to be included in the recall, safely dispose of the product in a way that it cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries.&nbsp; Batteries are considered hazardous waste. Do not place them in household garbage.For more information, consumers', '76186');
