INSERT INTO safety_incidents VALUES ('676986bfd9224034878d7a213b187497ac0c41a5', 'Health Canada', '2024-09-20', 2024, '2024-09', 'Canada', 'Canada', '', 'Chemicals', 'Various Buck Bomb attractant/scent products and other hunting related products', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Buck Bomb for a replacement label.For more information, consumers can contact Buck Bomb by telephone at 1-877-269-8490, Monday through Friday, from 8:00 am – 5:00 pm CT, by email at recallnotice2024@gsmorg.com&nbsp;or&nbsp;by visiting the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to ', '76045');
