INSERT INTO safety_incidents VALUES ('e2d43e7fe471fcd6576253333b3d528c03c05dd8', 'Health Canada', '2024-09-20', 2024, '2024-09', 'Canada', 'Canada', '', 'Other', 'Kilimanjaro E-Bike Rack Hitch Mounted Platform Carrier', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Kilimanjaro products and return them to Costco for a full refund.For more information, consumers can contact Kilimanjaro support by telephone at 1-888-449-9608, Monday through Friday, 12:00 PM to 7:30 PM ET, by email at recall@kilimanjarogear.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to', '76052');
INSERT INTO safety_incidents VALUES ('7656390018751452db1414a0002a5b7273d23eff', 'Health Canada', '2024-09-20', 2024, '2024-09', 'Canada', 'Canada', '', 'Other', 'Feed Me Vegan Real Food Protein & Oats bars', 'Milk', 'Allergen', 'Not Specified', 'Milk', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '76178');
