INSERT INTO safety_incidents VALUES ('37a37da09d4880ba5cffc169d275bbc92fbdd8c4', 'Health Canada', '2024-09-19', 2024, '2024-09', 'Canada', 'Canada', '', 'Household Items', 'Caframo Cabinet Heater', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Caframo Cabinet Heaters and contact Caframo Limited for further information or follow the steps here. For more information, consumers can contact Caframo Limited by telephone at 1-800-567-3556 ext. 1, Monday to Friday, from 8:00 am to 4:30 pm (EST), by email at contactus@caframo.com, or visit the company’s website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Caframo Limited.Please note tha', '75828');
INSERT INTO safety_incidents VALUES ('93dea79bcc662b0e02550bce6ea05aff88076bc5', 'Health Canada', '2024-09-19', 2024, '2024-09', 'Canada', 'Canada', '', 'Household Items', 'Lucid upholstered square tufted platform beds', 'Injury', 'Instability / Fall Risk', 'Fall Injury', 'Injury hazard - Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled beds and contact Lucid for a free replacement product.Consumers must send a photo of the bed, as well as a photo of the support rails on the underside of the bed or a photo of the law label to recall@lucidmattress.com to receive their replacement product.For more information, consumers can contact Lucid toll-free at 1-888-910-0236, from 10 a.m to 6 p.m., EST, Monday through Thursday, or 10 a.m to 4 p.m., EST Friday, by email&nbsp;or visit the ', '76029');
