INSERT INTO safety_incidents VALUES ('f377bdf82cd98db13e9e2af7cd3cae7a6f618c95', 'Health Canada', '2024-09-16', 2024, '2024-09', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Trollmaster™ PRO3+ Kit, Trollmaster™ PRO Angler Kit and Trollmaster™ Pro', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Trollmaster™ PRO3+ Kit, Trollmaster™ PRO Angler Kit and Trollmaster™ Pro and contact CMP Group Ltd. for new installation instructions.For more information, consumers can contact CMP Group Ltd. by telephone toll-free at 1-800-295-3625, from 8 a.m to 5 p.m. ET, Monday through Friday, by email at&nbsp;sales@cmpgroup.net or visit online at https://trollmasters.com/ or https://cmpgroup.net/steering-and-controls/ and click on “Safety and Product Not', '75983');
INSERT INTO safety_incidents VALUES ('ba0677589aa639e3e5e2cfa791e270df7a168654', 'Health Canada', '2024-09-16', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'Refresh Lacri-Lube Ophthalmic ointment', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for&nbsp;proper disposal.Seek medical attention if you have used this product and are experiencing signs of infection, such as eye pain and discharge, fever, or facial pain or pressure.Consult a health care professional if you have used this product and have health concerns.Contact AbbVie Corporation of Canada by calling 1-888-704-8270 or emailing&nbsp;service@abbvie.com&nbsp;if you have questions about this recall.Report any heal', '76044');
