INSERT INTO safety_incidents VALUES ('407a3740a801bb0cdcba52569fd9a1b7cde49b0e', 'Health Canada', '2024-09-13', 2024, '2024-09', 'Canada', 'Canada', '', 'Biologic Or Vaccine', 'Panhematin 268 mg/vial powder for solution', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Serious', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '76042');
INSERT INTO safety_incidents VALUES ('bd1ca9d830f01f2948402bd9a674e65e9d2119b2', 'Health Canada', '2024-09-13', 2024, '2024-09', 'Canada', 'Canada', '', 'Drugs', 'Refresh Lacri-Lube, 3.5 g tube', 'Contamination', 'Other', 'Eye Injury', 'Contamination', 'Not Reported', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for proper disposal.Seek medical attention if you have used this product and are experiencing signs of infection, such as eye pain and discharge, fever, or facial pain or pressure.Consult a health care professional if you have used this product and have health concerns.Contact AbbVie Corporation of Canada by calling 1-888-704-8270 or emailing service@abbvie.com if you have questions about this recall.Report any health product-rela', '76043');
