INSERT INTO safety_incidents VALUES ('56d089e1d53df50878051a7e9404106292a4055f', 'Health Canada', '2024-09-12', 2024, '2024-09', 'Canada', 'Canada', '', 'Other', 'AirJet and HydroJet Spa Pumps', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled spa pumps and contact Bestway to receive a free replacement or a pump refund of CAD $137 for an AirJet Spa Pump or CAD $259 for a HydroJet spa pump.For more information, consumers can contact Bestway by telephone at 1-888-943-2396, from 8:00 am to 5:00 pm EST, Monday through Friday, or visit the company website&nbsp;and click on “Recall and Safety” at the bottom of the page.Joint recall with Health Canada, the United States Consumer Product Sa', '75841');
INSERT INTO safety_incidents VALUES ('1f5f49e64f45cbaa32153aff824750bb2627f813', 'Health Canada', '2024-09-12', 2024, '2024-09', 'Canada', 'Canada', '', 'Toys & Childcare', 'Stanley-Branded Stanley JR Kids Wheelbarrow and 7-piece Garden Set’s long hoe and rake', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the long hoe and rake from the Garden Set,&nbsp;visit Red Toolbox’s recall website for information on how to obtain a free replacement long hoe and rake, upload a photograph disposing these items and upload a photograph showing the 12.2023 manufacturing date on the white label on the bottom of the wheelbarrow. The long hoe and rake should be disposed of in accordance with local environmental requirements.For more information, consumers can contact Red Tool', '75922');
INSERT INTO safety_incidents VALUES ('60c1e432c1745714f373aaeaccd7f68fcc11d5d5', 'Health Canada', '2024-09-12', 2024, '2024-09', 'Canada', 'Canada', '', 'Sports & Leisure', 'Petzl GYM, PANDION, and PANJI Harnesses', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Petzl GYM, PANDION, and PANJI harnesses and contact the company to have the product modified.For more information, consumers can contact Petzl toll-free at 877-807-3805, from 8 a.m. to 4 p.m. MT, Monday through Friday, or by email at&nbsp;Returns@petzl.com. Consumers can also visit the company’s website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Petzl America, Inc.Please note that the Ca', '76026');
