INSERT INTO safety_incidents VALUES ('356c2cd3c6a28a19f46310af17376fef8b3481e9', 'Health Canada', '2024-09-11', 2024, '2024-09', 'Canada', 'Canada', '', 'Electrical & Electronics', '15 inch Submersible RGB Aquarium Light remote', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact NICREW to receive a replacement remote.For more information, consumers can contact NICREW by email at nicrew@support.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic', '76034');
