INSERT INTO safety_incidents VALUES ('98f9c89cdd7966eb9e86bec23262f03bbc01ed30', 'Health Canada', '2024-09-10', 2024, '2024-09', 'Canada', 'Canada', '', 'Food & Food Contact', 'Imported raw Enoki mushrooms', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Not Reported', 0, 0, 'Always buy raw Enoki mushrooms from the refrigerated section at the grocery store.Refrigerate and store raw Enoki mushrooms at 4°C (40°F) or below, as soon as you get home from the grocery store.Keep raw Enoki mushrooms separate from foods that will not be cooked to avoid potential cross- contamination and prevent the spread of bacteria, if present.Wash your hands with warm water and soap for at least 20 seconds before and after handling raw Enoki mushrooms. Also, wash utensils, countertops, and', '76024');
