INSERT INTO safety_incidents VALUES ('f1c7097dd04aaa31248129f11908012e4c89484f', 'Health Canada', '2024-09-04', 2024, '2024-09', 'Canada', 'Canada', '', 'Chemicals', 'Guncer Ceramic Gun Oil, Gunex Special Gun Oil, and Universal Oil', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Ballistol products and contact North Sylva Sports to obtain a replacement label.For more information, consumers can contact North Sylva Sports by telephone at (416) 242-4867 Ext 781, Monday to Friday, from 9:00 a.m. to 4:00 p.m. EST, or by&nbsp;email&nbsp;at&nbsp;luis@northsylva.com.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed, sold or even given away in Canada.Health Ca', '75996');
