INSERT INTO safety_incidents VALUES ('dd93842707b0cef39e77b804820194b7273914fa', 'Health Canada', '2024-08-29', 2024, '2024-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Dumbbell Toy from the Fisher-Price Baby Biceps Gift Set', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled dumbbell toy, take it away from young children, and contact Fisher-Price to receive a partial refund.For more information, consumers can contact Mattel Canada by telephone at 1-855-853-6224, between 9 a.m. and 6 p.m. EST, Monday to Friday or visit the company website https://service.mattel.com/us/recall.aspx.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Mattel.Please note that the Canada Co', '75972');
INSERT INTO safety_incidents VALUES ('b1e907323e37cdde60357bb9534b3cf91abb404a', 'Health Canada', '2024-08-29', 2024, '2024-08', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Samsung Slide-In Electric Ranges', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers using the recalled ranges without knob locks or covers are cautioned to ensure that children and pets are kept away from the knobs, to not leave objects on the range when not in use, and to check that the knobs are off before leaving home or going to sleep. Consumers should contact Samsung Canada to receive a free set of knob locks or covers compatible with their model of electric slide-in range to install.&nbsp;Consumers with Wi-Fi enabled ranges can enable the “Cooktop On” notificati', '75974');
INSERT INTO safety_incidents VALUES ('405175dbb74af12caa3521a2707ca4c79558ef55', 'Health Canada', '2024-08-29', 2024, '2024-08', 'Canada', 'Canada', '', 'Sports & Leisure', 'Gasaciods Children’s Multi-Purpose Helmets', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled helmets, safely dispose of it and contact Fengwang Sports for a refund.&nbsp; To receive a refund, consumers must cut off the helmet straps and take pictures as proof destruction. Send the pictures to Fengwang Sports by email at george66305@163.com. &nbsp;For more information, consumers can contact Fengwang Sports by referring to the “Support Center” page on Temu’s official website (See the link: https://www.temu.com/support-center.html). The ', '75979');
