INSERT INTO safety_incidents VALUES ('bdc36613b55103bf28fc653fce36db8073987763', 'Health Canada', '2024-08-27', 2024, '2024-08', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized UMARY Hyaluronic Acid Dietary Supplement', 'Undeclared Substance', 'Allergen', 'Not Specified', 'Undeclared substance', 'Not Reported', 0, 0, 'Do not use this product. Consult a health care professional if you have used this product and have health concerns. Return the products to your local pharmacy for proper disposal.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check whether products have been authorized for sale by search', '75517');
