INSERT INTO safety_incidents VALUES ('e78bef27402d8b2d5ecf719147bcd481bd7a4b5a', 'Health Canada', '2024-08-24', 2024, '2024-08', 'Canada', 'Canada', '', 'Natural Health Products', 'Health First Ashwagandha Supreme capsules', 'Product Safety', 'Allergen', 'Allergic Reaction', 'Product safety', 'Not Reported', 0, 0, 'Do not use this product if you have a dairy allergy.Consult a health care professional if you have used this product and have health concerns.If you have questions about this recall, contact Health First Network by calling toll-free at 1-888-333-6353 (and press 3), or by email at&nbsp;info@healthfirst.ca.Report any health product-related side effects or complaints to Health Canada.', '75965');
