INSERT INTO safety_incidents VALUES ('1197bfb54e6f1eeff86fb765879320d2cab1200c', 'Health Canada', '2024-08-23', 2024, '2024-08', 'Canada', 'Canada', '', 'Other', 'Various Car Strap Booster Pads and Car Seat Cushions', 'Injury', 'Entrapment', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and safely dispose of the items in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Pr', '75959');
