INSERT INTO safety_incidents VALUES ('0dc845e254664d72f231ffafda817dd846a57a5b', 'Health Canada', '2024-08-19', 2024, '2024-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Geilipo balloon blowing toy', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Geilipo balloon blowing toys and dispose of them according to municipal hazardous waste guidelines. Consumers can contact SHEIN Canada for a refund.For more information, consumers can contact SHEIN Canada via the customer service support portal at https://ca.shein.com. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remin', '75860');
INSERT INTO safety_incidents VALUES ('fe57c2c9a0a8df90736445e75280ed37d95b2e0d', 'Health Canada', '2024-08-19', 2024, '2024-08', 'Canada', 'Canada', '', 'Cannabis', 'Coterie Double Infused Sour Apple Blunt Pre-rolls cannabis extract, Lot L24135H', 'Contamination', 'Other', 'Fracture / Blunt Trauma', 'Microbial contamination', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased, or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.&nbsp;', '75934');
INSERT INTO safety_incidents VALUES ('3365fbe976decb9884d1af50718e14e4a1202c42', 'Health Canada', '2024-08-19', 2024, '2024-08', 'Canada', 'Canada', '', 'Drugs', 'JAMP-Mycophenolate 250mg', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'If you are taking this medication, speak with your pharmacist as soon as possible. Your pharmacist will check if your product is affected by the recall and provide a replacement if needed. Given the capsule format, it is not possible to know whether your capsule is overweight or underweight by looking at it.Continue taking your medication until you speak with your pharmacist, as mycophenolate is an important drug in preventing organ rejection in kidney, heart or liver transplant patients.Contact', '75936');
