INSERT INTO safety_incidents VALUES ('605b5238c316aef07bfd37e6c29b71ee5caa7c38', 'Health Canada', '2024-08-19', 2024, '2024-08', 'Canada', 'Canada', '', 'Processed', 'Back bacon', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '75941');
