INSERT INTO safety_incidents VALUES ('927d8ba0dad8dde71116174c8df46a29e8808722', 'Health Canada', '2024-08-16', 2024, '2024-08', 'Canada', 'Canada', '', 'Drugs', 'JAMP-Mycophenolate 250 mg capsules', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'If you are taking this medication, speak with your pharmacist as soon as possible. Your pharmacist will check if your product is affected by the recall and provide a replacement if needed. Given the capsule format, it is not possible to know whether your capsule is overweight or underweight by looking at it.Continue taking your medication until you speak with your pharmacist, as mycophenolate is an important drug in preventing organ rejection in kidney, heart or liver transplant patients.Contact', '75935');
