INSERT INTO safety_incidents VALUES ('4d1846fa434549e4dcb802916e52d4477cae57d6', 'Health Canada', '2024-08-15', 2024, '2024-08', 'Canada', 'Canada', '', 'Household Items', 'South Shore Balka, Yodi and Dylan Cribs', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled cribs and contact South Shore Furniture Ltd. for a refund.For more information, consumers can contact South Shore Furniture Ltd. (Les Industries de la Rive Sud Ltée) by telephone at 1-800-290-0465 Monday to Friday between 8:30 am and 5:00 pm EST, or visit the company website to request a refund via email through the “Contact us” section or the “Recall information” section.Please note that the Canada Consumer Product Safety Act prohibits recall', '75814');
INSERT INTO safety_incidents VALUES ('6a135cd7e5c2fa30311fc02a2ca2e154dc699d99', 'Health Canada', '2024-08-15', 2024, '2024-08', 'Canada', 'Canada', '', 'Chemicals', 'The Unscented Company Laundry Whitener/Brightener', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact The Unscented Company’s customer service.For more information, consumers can contact The Unscented Company by telephone at 1-855-933-1555, from Monday to Friday, 9am to 5pm or by email at hello@unscentedco.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safe', '75905');
INSERT INTO safety_incidents VALUES ('cbf48a6a8d615bac3d969cd4cbbd2d6aec52f953', 'Health Canada', '2024-08-15', 2024, '2024-08', 'Canada', 'Canada', '', 'Sports & Leisure', 'DeWALT Battery Electric Walk Behind Lawn Mowers', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and bring the products to an authorized service center where the mowers will be repaired. Consumers can locate an authorized service center by calling DeWALT or by visiting their website. For more information, consumers can contact DeWALT by telephone at 1-800-990-6421, Monday to Friday, from 8 a.m. to 6 p.m. ET, or visit the company website at https://www.dewalt.ca/push-mowers-recall. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&', '75911');
