INSERT INTO safety_incidents VALUES ('5942b5961125a00bbfecd1b767329fa3e6140bf1', 'Health Canada', '2024-08-13', 2024, '2024-08', 'Canada', 'Canada', '', 'Other', 'TonGass pool drain covers', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Pool owners/operators and consumers should immediately stop using pools with the recalled pool drain covers.&nbsp; To receive a refund, consumers should remove the drain cover from the pool, take a photo, and send it to the recalling firm by email at tongass@126.com.&nbsp; For more information, consumers can contact TonGass by telephone at the Amazon Toll Free Number: 1-888-280-4331, by email at tongass@126.com or online.Please note that the Canada Consumer Product Safety Act prohibits recalled ', '75909');
