INSERT INTO safety_incidents VALUES ('2109a046a39770e02889f66482032b01db978615', 'Health Canada', '2024-08-09', 2024, '2024-08', 'Canada', 'Canada', '', 'Cannabis', 'Emprise CBN+CBD Softgels, NuLeaf Naturals Full Spectrum Hemp Multicannabinoid Oil and Oil Softgels, and Ultra Plus MultiCannabinoid Oil and Softgels', 'Labelling And Packaging - Suspected Quality Concern', 'Other', 'Not Specified', 'Labelling and packaging - Suspected quality concern', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased, or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '75613');
