INSERT INTO safety_incidents VALUES ('57ff11f9b58e3a579f07c666fadcaa363186c4a7', 'Health Canada', '2024-08-08', 2024, '2024-08', 'Canada', 'Canada', '', 'Sports & Leisure', 'Kuat Transfer v2 hitch-mounted bicycle carrier', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products or take temporary precautions using a safety strap to reduce the chance of malfunction and contact the company for a free repair kit to permanently correct the defect.For more information, go to www.kuat.com/recalls and follow the instructions for submitting information or email info@kuatracks.com or call the Kuat Customer Service Team (English and French) at 1-877-822-5828, Monday to Friday, from 8:30am to 5:30pm CST. Each repair kit', '75853');
INSERT INTO safety_incidents VALUES ('8a57d0b52853f098ffd7b8c96e8ca36b8519c4e0', 'Health Canada', '2024-08-08', 2024, '2024-08', 'Canada', 'Canada', '', 'Frozen', 'Frozen Shredded Young Coconut', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serio', '75906');
