INSERT INTO safety_incidents VALUES ('b7532e1babd73552606c1c469f24a14366058102', 'Health Canada', '2024-08-07', 2024, '2024-08', 'Canada', 'Canada', '', 'Health Products', 'Various unauthorized health products known as “poppers”', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Not Reported', 0, 0, 'Stop using the products listed in the table. Consult your health care professional if you have used these products and have health concerns, and for advice on which health products are best for you and your family.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check if products have been', '74391');
