INSERT INTO safety_incidents VALUES ('0472f4a352bdec00042b6217113c1fa792b7ee2b', 'Health Canada', '2024-08-07', 2024, '2024-08', 'Canada', 'Canada', '', 'Food & Food Contact', 'Melons', 'Contamination', 'Other', 'Not Specified', 'Microbial contamination', 'Not Reported', 0, 0, 'When handling melons, follow our food safety tips, such as:Choose melons that are firm. Do not buy melons that are bruised or damaged. Melons can become contaminated through bruises and damaged parts of the rind. Some melons may have blemishes on one side. This is usually where the melon was resting on the ground during growth. It is safe to choose this melon.If buying pre-cut melons, make sure they are refrigerated.Wash your hands thoroughly with warm water and soap for at least 20 seconds befo', '75895');
INSERT INTO safety_incidents VALUES ('4e9d52e6f4ff4a212335f1f4b38409be547b87ae', 'Health Canada', '2024-08-07', 2024, '2024-08', 'Canada', 'Canada', '', 'Drugs', 'JAMP Rabeprazole - 10mg delayed-release Tablet', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Contact the recalling firm if you have any questions about the recall. Report any health product safety complaints to the recalling company or market authorization holder.Return affected product to your local pharmacy or place of purchase for proper disposal.Report any health product related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety complaints&nbsp;to Health Canada', '75902');
