INSERT INTO safety_incidents VALUES ('f9bef05cb6114024960250dabbbc8ce7daf3fc81', 'Health Canada', '2024-08-06', 2024, '2024-08', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Lovely Angel Children’s Nightgowns', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled nightgowns and contact Lovely Angel to receive a full refund. Consumers should destroy the garments by cutting them in half and disposing of them in accordance with provincial and municipal laws. For more information, consumers can contact Lovely Angel by email at wangmaxime@163.com or visit Lovely Angel’s online store. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even gi', '73371');
