INSERT INTO safety_incidents VALUES ('a98c568bf3c1a7e75667a2692dcd0d6e5e9fb46c', 'Health Canada', '2024-08-06', 2024, '2024-08', 'Canada', 'Canada', '', 'Drugs', 'JAMP Digoxin 0.125 MG, 0.0625MG', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'If you are taking this medication, speak with your pharmacist as soon as possible. Your pharmacist will check if your product is affected and provide a replacement if needed. It may not be possible to know if you are getting the correct dose of digoxin by looking at the tablets. Overweight or underweight tablets may look like normal-sized tablets.Continue taking your JAMP Digoxin 0.0625 or 0.125 mg tablets until you speak with your pharmacist, as digoxin is an important drug when you have a hear', '75893');
