INSERT INTO safety_incidents VALUES ('a5291d16593fcbcd6282ec2928a4dd0853f8e8d1', 'Health Canada', '2024-08-05', 2024, '2024-08', 'Canada', 'Canada', '', 'Drugs', 'ratio-ECTOSONE (TEVA-ECTOSONE) 0.1% regular and 0.05% mild lotions', 'Product Quality - Labelling', 'Other', 'Not Specified', 'Product quality - Labelling', 'Serious', 0, 0, 'Do not use the affected products. Consult a health care professional if you have used these products and have health concerns.Return the products to your local pharmacy for&nbsp;proper disposal.Contact Teva Canada Ltd. toll-free at 1-800-268-4129 if you have questions about the recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '75725');
INSERT INTO safety_incidents VALUES ('0da0ea7f02dc210c97c10c6173898f323bf8c141', 'Health Canada', '2024-08-04', 2024, '2024-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Oat Banana & Mango Baby Cereal', 'Other', 'Other', 'Not Specified', 'Other', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Cronobacter&nbsp;may not look or smell spoiled but can still make you sick. Although&nbsp;Cronobacter&nbsp;is not commonly linked to human illness, in rare cases it can cause se', '75880');
