INSERT INTO safety_incidents VALUES ('c2dfca9dd4234d95b5e809d3cb998162f52b37a4', 'Health Canada', '2024-08-02', 2024, '2024-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Toy Race Cars', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled race cars and dispose of them according to municipal waste guidelines.For more information, consumers can contact PK Douglass Inc. by &nbsp;telephone at 1-800-600-6203, from 8:30 am to 4:30 pm EST or by email at sales@pkdouglass.com. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or ', '75891');
INSERT INTO safety_incidents VALUES ('d3d96f1bd9372f515fa994596c47d79d072d9605', 'Health Canada', '2024-08-02', 2024, '2024-08', 'Canada', 'Canada', '', 'Cannabis', 'Canna Farms Tangerine Dream dried cannabis, Lot 24AER-DF1', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Clients should verify whether their product is affected.Affected clients may contact Canna Farms Ltd. at 1-855-882-0988.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '75892');
