INSERT INTO safety_incidents VALUES ('1bf350fd38ffd38f633bce9a0f98c49b588b2dab', 'Health Canada', '2024-08-02', 2024, '2024-08', 'Canada', 'Canada', '', 'Medical Devices', 'Unauthorized Platelet Rich Plasma (PRP) treatments, Botox and medical devices', 'Product Safety - Unauthorized Product', 'Other', 'Radiation Exposure', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not receive unauthorized treatments from MedSkin Laser Center. Consult a licensed practitioner if you have received a treatment from MedSkin Laser Center and have health concerns.Check the status of those presenting themselves as practitioners with the College of Physicians and Surgeons in your province or territory.Report concerns regarding the illegal practice of medicine to the College of Physicians and Surgeons in your province or territory.Read product labels to verify that health produc', '75899');
