INSERT INTO safety_incidents VALUES ('7f33bfbe9dece13c0f3561694a27cdaecce3d0e4', 'Health Canada', '2024-07-16', 2024, '2024-07', 'Canada', 'Canada', '', 'Food & Food Contact', 'Sunseed “Vita Prima” and Vitakraft “Vita Smart” Hedgehog Food', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and discard or return it to the place of purchase for a refund.For more information, consumers can contact Vitakraft Sun Seed, Inc. by telephone toll-free at 1-800-221-6175, extension 123, Monday through Friday, from 8:30 a.m. to 5:00 p.m. EST, or by email.&nbsp;Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to rem', '75818');
INSERT INTO safety_incidents VALUES ('701903d0d69fccd91c21cff012dcc05217deef81', 'Health Canada', '2024-07-16', 2024, '2024-07', 'Canada', 'Canada', '', 'Drugs', 'Luscious Eyelash & Eyebrow Growth Serum', 'Product Safety', 'Allergen', 'Eye Injury', 'Product safety', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '75819');
