INSERT INTO safety_incidents VALUES ('7310df696a8becebab9cc135eb1aa3e4cf34cf13', 'Health Canada', '2024-07-15', 2024, '2024-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Multi-Purpose Kids’ Bike Helmets', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Multi-Purpose Kids’ Bike Helmets, safely dispose of it and contact Chau River Sports Outdoors for a refund. To receive a refund, consumers must cut off the helmet straps and take pictures as proof destruction. Send the pictures to Chau River Sports Outdoors by email at lexi_kuyou@163.com.&nbsp; For more information, consumers can contact Chau River Sports Outdoors by email at lexi_kuyou@163.com or use consumer support via “Support Center” page', '75815');
