INSERT INTO safety_incidents VALUES ('23cc2271540cba8fe1c220a7ee3d4b20895e80fa', 'Health Canada', '2024-07-12', 2024, '2024-07', 'Canada', 'Canada', '', 'Other', 'Feed Me Vegan Real Food Protein & Oats – Frosted Blueberry Cobbler', 'Milk', 'Allergen', 'Not Specified', 'Milk', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '75816');
