INSERT INTO safety_incidents VALUES ('2c57fd2b47047b5197ddb07ee8133a8e5bfe5ac2', 'Health Canada', '2024-07-11', 2024, '2024-07', 'Canada', 'Canada', '', 'Other', 'Best Lighting High Bay LED Light Fixtures', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately inspect the fixture for any sign of pin degradation, a loose LED board or discoloration of the lens. Consumers should immediately stop using light fixtures that show any sign of a loose LED board or discoloration of the lens and turn the circuit off. Customers can contact Best Lighting Products for more information and register online www.highbayrecall.net to schedule a free inspection and on-site repair to replace the plastic pins with metal pins.Joint recall with H', '75800');
