INSERT INTO safety_incidents VALUES ('d96e58d8123955e03dbe6f22348f502fa2c71ac6', 'Health Canada', '2024-07-05', 2024, '2024-07', 'Canada', 'Canada', '', 'Medical Devices', 'Philips Respironics Continuous Positive Airway Pressure (CPAP) machines, BiLevel Positive Airway Pressure (BiLevel PAP) machines and mechanical ventilators', 'Performance', 'Explosion', 'Not Specified', 'Performance', 'Not Reported', 0, 0, 'Register your device on the Philips recall website or call its recall hotline at 1-877-907-7508. Philips has established a registration process where you can look up your device serial number and begin a claim if your unit is affected.If you have an affected product talk to your physician, or medical device provider first before stopping or changing how you use your product, as the benefits of using these devices may outweigh the risks for many users.Be sure to clean your device only according t', '62729');
