INSERT INTO safety_incidents VALUES ('f9262bb62f6791570b0bcede8e3cacdf74f6901d', 'Health Canada', '2024-07-05', 2024, '2024-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'True Manufacturing Commercial Refrigerators with Secop Compressors', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled refrigerators and contact True Manufacturing Co. Ltd. for a free repair. True Manufacturing is contacting all known purchasers directly.For more information, consumers can contact True Manufacturing Co. Ltd. toll-free at 1-855-203-0185, from 8 a.m. to 4:30 p.m. CT, Monday through Friday, by email at info@true-secopcompressor-retrofit.com, or online.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being r', '75761');
INSERT INTO safety_incidents VALUES ('3e98dd572801046a997543ad1c572ca73681daf0', 'Health Canada', '2024-07-05', 2024, '2024-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Anker 321 Power Banks (PowerCore 5K)', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and safely dispose of them in a way that they cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries. Batteries are considered hazardous waste. Do not place them in household garbage.&nbsp; For users verified to be part of the recall batch, Anker will send a new power bank free of charge.For more information, consumers can contact Anker by telephone at 1-800-988-', '75772');
INSERT INTO safety_incidents VALUES ('5c156d82a930497cd98cf3c1223d2ba4e4628017', 'Health Canada', '2024-07-05', 2024, '2024-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Soundcore A3102 Speaker (Black) and AnkerWork A3302 PowerConf S3 Speakerphone', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and safely dispose of them in a way that they cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries. Batteries are considered hazardous waste. Do not place them in household garbage. For users verified to be part of the recall batch, Anker will send a new speaker or speakerphone free of charge.&nbsp; For more information, consumers can contact Anker by telephon', '75773');
