INSERT INTO safety_incidents VALUES ('08455d70ea3530958fb5d45e61289670f6a7703d', 'Health Canada', '2024-07-04', 2024, '2024-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Hatch Baby Rest 1st Generation Sound Machine AC Adapter', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled power adapters sold with Rest 1st Generation sound machines and contact the company for a free replacement power adapter. Consumers should cut the cord on the recalled power adapter, take a photo of the adapter&nbsp;showing the model number and the cut cord, upload the photo and provide their name and mailing address at www.hatch.co/adapterrecall.&nbsp;&nbsp;For more information, consumers can contact Hatch Baby Inc by telephone at 888-918-461', '75785');
