INSERT INTO safety_incidents VALUES ('595a578c0c29cd9180981b113e70507f055b8f0d', 'Health Canada', '2024-06-28', 2024, '2024-06', 'Canada', 'Canada', '', 'Other', 'UberBoost Inflatable Booster Car Seat', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and safely dispose of the items in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Pr', '75742');
INSERT INTO safety_incidents VALUES ('a909e70261f38f598527949356f233f8153ddcaa', 'Health Canada', '2024-06-28', 2024, '2024-06', 'Canada', 'Canada', '', 'Drugs', 'Festal Plus tablets (labelled in Korean)', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use this product. Consult a health care professional if you have used this product and have health concerns.  Return the product to your local pharmacy for proper disposal.  Buy your prescription drugs from licensed pharmacies.Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug ', '75762');
INSERT INTO safety_incidents VALUES ('ac99043e6e6009521f6038b92cd334ecdeeaf3af', 'Health Canada', '2024-06-28', 2024, '2024-06', 'Canada', 'Canada', '', 'Non-Alcoholic', 'Elevate Snapchill Coffee', 'Clostridium Botulinum', 'Microbiological Contamination', 'Not Specified', 'Clostridium botulinum', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Clostridium botulinum toxin may not look or smell spoiled but can still make you sick. Symptoms in adults can include facial paralysis or loss of facial expression, unreactive or fix', '75763');
