INSERT INTO safety_incidents VALUES ('92e01800e5abd16f4d9f55c7642c81214456ff1a', 'Health Canada', '2024-06-27', 2024, '2024-06', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Mayoral One-Piece Sleepsuits', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to the store where purchased for a refund.For more information, consumers can contact Mayoral Canada Inc. by email at&nbsp;mayoral.canada@mayoral.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any oth', '75553');
INSERT INTO safety_incidents VALUES ('08b066b7ae487037a52fc03ffd020c496ae0d401', 'Health Canada', '2024-06-27', 2024, '2024-06', 'Canada', 'Canada', '', 'Household Items', 'Daikin, Amana and Goodman-branded heat pumps', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'If your unit has not already received the corrective update and there is not an immediate need for air conditioning, turn off and stop using the recalled product. Contact Daikin Comfort Technologies Manufacturing, L.P. (“DCT”) to have your units software remotely updated for consumers whose units are connected to WiFi. Consumers with systems not connected to WiFi should register for the recall at www.goodmanmfg.com/fit-recall to receive instructions to perform the update.For more information, co', '75581');
