INSERT INTO safety_incidents VALUES ('7e3dfd555fefa92dd586549b4a55549a3633c710', 'Health Canada', '2024-06-20', 2024, '2024-06', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'StyleCraft Instinct Cordless Hair Clipper', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact StyleCraft, LLC to arrange for a free battery replacement.For more information, consumers can contact StyleCraft, LLC by telephone at 1-888-864-6409, from 8:30 a.m. to 5:30 p.m. ET, Monday through Friday, by email at CSteam@stylecraftus.com, or visit the company website and click on “Recall” at the bottom of the page.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and StyleCra', '75643');
INSERT INTO safety_incidents VALUES ('8deb4b2faf28c055620a9272c6843401bd5bbc4d', 'Health Canada', '2024-06-20', 2024, '2024-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Babboe N.V. Cargo bicycles', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled cargo-bicycles and contact the company to coordinate retrieval of the bicycles. The Company will provide a refund of the purchase price following retrieval of the cargo-bicycle. For more information, consumers can contact Babboe by telephone toll-free at 1-833-746-7280, from 8 a.m. to 5 p.m. ET, Monday through Friday, by email at service.ca@babboe.com or online.Joint recall with Health Canada, the United States Consumer Product Safety Commissi', '75666');
INSERT INTO safety_incidents VALUES ('eec53a88e6ac1a8914858d64116a7e1c8da3a6a7', 'Health Canada', '2024-06-20', 2024, '2024-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Ascent® Series and Venturist® Series 8-ounce and 20-ounce Blending Containers and Blade Bases', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Vita-Mix Corporation for a free repair kit consisting of a protective shroud to attach over the blade base and additional instructional labels.&nbsp;&nbsp;For more information, consumers may contact Vita-Mix Corporation by telephone toll-free at 1-855-215-5178, Monday through Friday, from 7:00 a.m. to 4:00 p.m. CT, by email at service@vitamix.com, or obtain information online at BlendingCupBowlRecall.expertinquiry.com or h', '75685');
INSERT INTO safety_incidents VALUES ('329593bafbc0624c48e96e235776ef9d896e28ce', 'Health Canada', '2024-06-20', 2024, '2024-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Goal Zero Yeti Link Expansion Module (and associated EC8 cables)', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Goal Zero LLC for replacement kit. Consumers should dispose of the affected products in accordance with municipal electronic waste requirements.For more information, consumers can contact Goal Zero LLC by telephone at 1-800-794-6250, Monday through Friday, 8:00 am to 5:00 pm MT, by email at support@goalzero.com or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commissio', '75686');
