INSERT INTO safety_incidents VALUES ('3932826370e9c388560b2d59841ba21d65faa321', 'Health Canada', '2024-06-17', 2024, '2024-06', 'Canada', 'Canada', '', 'Chemicals', 'JANCHUN Epoxy Resin', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and keep it out of reach of children.For more information, consumers can contact JANCHUN by email at after-sale@janchun.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by filli', '75661');
INSERT INTO safety_incidents VALUES ('5fb566dca3dd5427fcdacd3ce7970a85f239c681', 'Health Canada', '2024-06-17', 2024, '2024-06', 'Canada', 'Canada', '', 'Toys & Childcare', 'Sizkii Geometric Stacker', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers who have the affected product should immediately stop using it and safely dispose of it in such a way that it cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Product Incident', '75663');
