INSERT INTO safety_incidents VALUES ('651d52761c0849dcb387d5d5b570a675b8914db3', 'Health Canada', '2024-06-15', 2024, '2024-06', 'Canada', 'Canada', '', 'Drugs', 'Dianeal PD4 2.5% Dextrose peritoneal dialysis solution (3,000 mL and 5,000 mL); Physioneal 40 2.27% Glucose peritoneal dialysis solution (2,500 mL)', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Immediately check your stock to see if your product is affected. If you have an affected product, do not use it, and immediately speak to your health care provider to obtain a replacement.Consult a health care professional if you have used the affected product and you have health concerns.Contact Baxter Corporation toll-free at 1-888-719-9955 if you have questions about the recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '75672');
