INSERT INTO safety_incidents VALUES ('e86c57ef40ac64fd087d362c5776eace8843ddbb', 'Health Canada', '2024-06-13', 2024, '2024-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Black Diamond Neve Strap Crampons', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled crampons and contact Black Diamond Equipment for a full refund and visit www.blackdiamondequipment.com/en_US/content/neve-strap-recall/ for information on how to initiate the return and refund process.For more information, consumers may also contact Black Diamond Equipment by phone at 1-866-306-0865 to connect with the customer service team,&nbsp;Monday to Thursday, 10am-12pm, 1pm-3-pm and Friday, 10am-12pm MST or by email at&nbsp;NeveStrapRec', '75655');
