INSERT INTO safety_incidents VALUES ('4e2e95dcd1824f9f7262f7bd346500be90bebebc', 'Health Canada', '2024-06-10', 2024, '2024-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Wild Country Ropeman 1 Ascenders', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to any authorized Wild Country dealer or to Wild Country directly for a replacement product. For more information, consumers can contact Wild Country by telephone toll-free at 1-844-412-7013, from 9:00 a.m. to 5:00 p.m. MT, Monday through Friday, by email&nbsp;or visit the company’s website.Joint recall with Health Canada, the United States Consumer Product Safety Commission and Salewa USA, LLC.Please note that the Can', '75611');
INSERT INTO safety_incidents VALUES ('9a49926d2fff81e0e8580650df778cdcf09a233f', 'Health Canada', '2024-06-10', 2024, '2024-06', 'Canada', 'Canada', '', 'Chemicals', 'Various Super Lube Products by Kano Laboratories (Consumer Sizes)', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products, keep them out of reach of children, and contact Kano Laboratories for a refund. Consumers will need to provide proof of possession by emailing a photo of their product to&nbsp;info@super-lube.com&nbsp;to receive their full refund.For more information, consumers can contact Kano Laboratories by telephone at 800-253-5823, Monday through Friday from 8:30 a.m. to 5:00 p.m. ET, by email at info@super-lube.com or visit the company website ', '75638');
