INSERT INTO safety_incidents VALUES ('39fedd4b7fd7be48195364d1520793490e0b8d81', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Household Items', 'Fodoss Baby Bedside Bassinet', 'Injury', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Entrapment hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Fodoss Baby Bedside Bassinet and safely dispose of it in such a way that it cannot be used again.For more information, consumers can contact Little Beetle by email at baby_cribs@163.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this prod', '75518');
INSERT INTO safety_incidents VALUES ('5d285cbed637550b0c02b8ae74b4aa0bb6aae89e', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Good Earth Lighting 12 inch Rechargeable LED Motion-Activated Light Bar', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard - Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Good Earth Lighting to receive a free replacement light of equal value to the recalled light, including shipping. After successfully registering with the company, consumers should dispose of the lithium-ion battery powered lights according to municipal electrical waste guidelines.&nbsp;For more information, consumers can contact Good Earth Lighting by telephone toll-free at 1-800-291-8838 Ext 9 from 8:30 a.m. to 5:00 p.m. C', '75580');
INSERT INTO safety_incidents VALUES ('b9db89404cd01681e7f4e4c298b34ce798397981', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Food & Food Contact', 'FURminator deShedding Ultra Premium Dog Conditioner (1 Gallon)', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, dispose of it according to municipal waste guidelines, and contact the company for refund and additional information. Do not pour the product down the toilet or drain.For more information, consumers can contact Spectrum Brands Pet LLC by telephone toll-free at 1-888-837-6688, between 8:00 a.m. and 4:30 p.m. CST, Monday through Friday, or visit the company’s website&nbsp;for information to register for a full refund.Joint recall with H', '75609');
INSERT INTO safety_incidents VALUES ('bcbef2167882bea8da7b3d8d23f24667ef39570c', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Household Items', 'À la Cuisine Electric Kettles', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and go to one of the following locations: Hart Stores, Maison en Gros, Hart Home or Hart Maison&nbsp;receive a new kettle of equal value.For more information, consumers can visit one of the following outlets: Hart Stores, Maison en Gros, Hart Home or Hart Maison . Telephone numbers and hours of operation are available at the following link: https://www.hartstores.com/fr/mw-store-locator.Please note that the Canada Consumer Product Safe', '75614');
INSERT INTO safety_incidents VALUES ('d96d8509e885a10f6caf64232c07474614c5a5f0', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Various Kawasaki Engines used in certain Bad Boy Mowers, Bobcat, Cub Cadet, Hustler, John Deere, and Kubota Brand Lawn and Garden Equipment', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard - Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Kawasaki Engines and contact Turf Care Products Canada to schedule a free repair. Consumers can contact Turf Care Products Canada at 905-836-0988 from 7 a.m. to 4:30 p.m. ET, Monday through Friday, or online at www.turfcare.ca.John Deere owners should contact Deere &amp; Company toll-free at 800-537-8233 from 8 a.m. to 6 p.m. ET Monday through Friday and 9 a.m. to 3 p.m. ET Saturday, or online at www.deere.com and click on “Product Recall Info', '75615');
INSERT INTO safety_incidents VALUES ('40e78e614986cfa7161cd6b337c8769b41a337e7', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'General And Plastic Surgery', 'Vasoview Hemopro 2 Endoscopic Vessel Harvesting System', 'Performance', 'Other', 'Not Specified', 'Performance', 'Moderate', 0, 0, '', '75628');
INSERT INTO safety_incidents VALUES ('027654ed715228576a8be8e8e179373b11beb4cb', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'General Hospital And Personal Use', 'Howmedica Revision Instrument System (HRIS) Storage &amp; Sterilization Case and Tray', 'Sterility', 'Other', 'Eye Injury', 'Sterility', 'Moderate', 0, 0, '', '75629');
INSERT INTO safety_incidents VALUES ('f63303a8b75fbed6294ca3043f5ef9a221540869', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Medical Devices', 'Absorbable (dissolvable) threads used in cosmetic thread lift procedures', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not conduct a thread lift procedure on yourself.If your health care professional has recommended a thread lift procedure, consult with them about the risks and benefits of the device, and who should perform the procedure.Check that your clinic is using absorbable threads that have been authorized by Health Canada specifically for cosmetic use by searching Health Canada''s Medical Devices Active Licence Listing (MDALL) and requesting the instruction for use (IFU).Confirm that your thread lift p', '75631');
INSERT INTO safety_incidents VALUES ('71807393150cfca69b76bf7fab94bae2e88fe0ff', 'Health Canada', '2024-06-06', 2024, '2024-06', 'Canada', 'Canada', '', 'Drugs', 'Mint-Betahistine  8, 16 & 24mg', 'Product Quality', 'Chemical / Toxic Substance', 'Not Specified', 'Product quality', 'Serious', 0, 0, 'Return the affected products to your local pharmacy for a replacement, and for&nbsp;proper disposal. If you are unsure whether your product is affected, check with your pharmacy.Consult a health care professional if you have used the affected product and you have health concerns.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.Contact the companies if you have questions about their recall:Accel Pharma Inc., by contacting Betty Cory at Accel Qualit', '75634');
