INSERT INTO safety_incidents VALUES ('9b609bec5b49ed2edef07c8421fb4e1363e07e7d', 'Health Canada', '2024-05-31', 2024, '2024-05', 'Canada', 'Canada', '', 'Drugs', 'Counterfeit Viagra, 100 mg sildenafil tablets; Counterfeit Cialis, 20 mg tadalafil tablets', 'Unauthorized Product - Product Safety', 'Other', 'Not Specified', 'Unauthorized product - Product safety', 'Not Reported', 0, 0, 'Immediately stop using and&nbsp;safely dispose&nbsp;of this product. Consult your health care provider if you have taken this product and have health concerns. Only buy your prescription drugs from&nbsp;licensed pharmacies.  Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (D', '75600');
