INSERT INTO safety_incidents VALUES ('7bc956416c5b448f10d0964069089377a9e65b35', 'Health Canada', '2024-05-03', 2024, '2024-05', 'Canada', 'Canada', '', 'Drugs', 'REDDY-SAPROPTERIN 100mg powder for solution', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Serious', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '75409');
INSERT INTO safety_incidents VALUES ('6e41b67293cb8d4683d59e49a38af205855d0785', 'Health Canada', '2024-05-03', 2024, '2024-05', 'Canada', 'Canada', '', 'Household Items', 'Costway Portable Baby Bed Side Sleeper Infant Travel Crib with Carrying Bag', 'Injury', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Entrapment hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Costway for a refund.For more information, consumers can contact Costway by email at recall@costway.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer produc', '75455');
