INSERT INTO safety_incidents VALUES ('e98df948d600336023a56cac70bf176c465772a7', 'Health Canada', '2024-04-26', 2024, '2024-04', 'Canada', 'Canada', '', 'Drugs', 'Counterfeit Viagra, 100 mg sildenafil tablets', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Immediately stop using and safely dispose&nbsp;of this product. Consult your health care provider if you have taken this product and have health concerns. Only buy your prescription drugs from licensed pharmacies.Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You ', '75447');
