INSERT INTO safety_incidents VALUES ('2ba8ab0a5ce9d767d7a6628cf6eed6515c2dc1ea', 'Health Canada', '2024-04-25', 2024, '2024-04', 'Canada', 'Canada', '', 'Tools & Machinery', 'Oregon, PowerPro, Country Tuff, and SpeeCo branded log splitters', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'If consumers experience the wedge failing to retract, consumers should immediately stop using the recalled log splitter and cylinder kits and contact Oregon Tool for installation of a free replacement cylinder.  For more information, consumers can contact Oregon Tool by telephone at 833-948-2590, from 6 a.m. to 7 p.m. EST, Monday to Friday, by email at logsplitter@oregontool.com or online at https://www.oregontool.com/product-recalls/ or www.oregonproducts.com and click on Product Recalls for mo', '75363');
INSERT INTO safety_incidents VALUES ('978a8940969474c709a2a253717a040273180c9c', 'Health Canada', '2024-04-25', 2024, '2024-04', 'Canada', 'Canada', '', 'Specialized Products', '3M™ PELTOR™ X4 Series Earmuffs', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled earmuffs and contact 3M to receive free replacement earmuffs, including free shipping. For more information, consumers can contact 3M Technical Services Team by telephone toll-free at 1-800-267-4414 between 8:00 a.m. to 5:00 p.m. CT Monday to Thursday and 8:00 a.m. to 4:30 p.m. CT Friday, by email&nbsp;or visit the company’s website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and 3M Company. ', '75370');
INSERT INTO safety_incidents VALUES ('047af09dff71e3c0f99f27e91ea0401c232486ff', 'Health Canada', '2024-04-25', 2024, '2024-04', 'Canada', 'Canada', '', 'Household Items', 'Crate & Barrel Hampshire Cribs', 'Falls', 'Entrapment', 'Entrapment', 'Fall hazard - Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Crate &amp; Barrel to obtain a repair kit or to arrange for the company to pick up the crib for a refund. Crate &amp; Barrel will contact all known purchasers directly. For more information, consumers can contact Crate &amp; Barrel by telephone at 888-780-5873,&nbsp;from 8 a.m. to 7 p.m. CT, Monday through Friday,&nbsp; 8 a.m. to 6 p.m. CT, Saturday and Sunday, or visit the company website at https://www.crateandbarrel.ca/', '75402');
INSERT INTO safety_incidents VALUES ('a785b40447c9df1f6ca17daa3b6bdc8a5fc9a580', 'Health Canada', '2024-04-25', 2024, '2024-04', 'Canada', 'Canada', '', 'Household Items', 'Shandi 0-25Kg Big Space Electric Baby Crib Cradle Infant Rocker Auto Swing Bed Baby Cradle', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Entanglement hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Yi Xiang Shang E-commerce Co., Ltd. for a full refund.For more information, consumers can contact Yi Xiang Shang E-commerce Co., Ltd. by email at yxsun0309@163.com and return the product to: GCCA Return 200, c/o 5 Paget Rd, Brampton, Ontario, Canada, L6T 5S2.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like', '75435');
INSERT INTO safety_incidents VALUES ('fcc3459bd6beb379dcd9cd56088b345f7b611974', 'Health Canada', '2024-04-25', 2024, '2024-04', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Children’s Hooded Bathrobe', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bathrobe, keep it out of reach of children and destroy it.For more information, consumers can contact Temu by visiting the company’s website. Affected customers may also log in to their Temu account to identify detailed information of the recall by referring to the Your Recalls and Product Safety Alerts page.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in ', '75438');
