INSERT INTO safety_incidents VALUES ('c1ba890455348633fb2814ef7f00e584167bf415', 'Health Canada', '2024-04-24', 2024, '2024-04', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Shakeel Bhai Mehndi Waley Almas Henna Cones, Original Special Zeenat Henna Cones and Special Bridal Henna Cones', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of them in regular household garbage. Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer produc', '75275');
