INSERT INTO safety_incidents VALUES ('b2320f8cc0ea06cca40ad11b8be3e59cc3dff292', 'Health Canada', '2024-04-24', 2024, '2024-04', 'Canada', 'Canada', '', 'Cannabis', 'Full Sesh Purple Gelato Punch dried cannabis, Lot PG23102', 'Contamination', 'Other', 'Not Specified', 'Microbial contamination', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased, or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '75426');
