INSERT INTO safety_incidents VALUES ('5d24bce2a52a9e13d71293815c676794855062f5', 'Health Canada', '2024-04-23', 2024, '2024-04', 'Canada', 'Canada', '', 'Natural Health Products', 'Miracle Reds', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Verify if your product is affected.Stop using this product if you have an immune-compromised condition, such as AIDS or lymphoma (cancer), or if you''re undergoing long-term corticosteroid treatment. Stop taking this product if you are pregnant or breastfeeding and have not consulted a healthcare provider before using it.&nbsp;Do not use this product if you are taking health products that affect blood coagulation.&nbsp;Talk to a health care professional if you have questions or have health concer', '75428');
