INSERT INTO safety_incidents VALUES ('37ed0c531c5564c820290eba1c0adfd6361ef132', 'Health Canada', '2024-04-15', 2024, '2024-04', 'Canada', 'Canada', '', 'Clothing & Textiles', 'AGV Tourmodular DOT (E2206) Multi MPLK and Solid MPLK motorcycle helmets', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Customers should contact Dainese for a return kit free of charge.&nbsp; Dainese will repair the helmet and return to the consumer free of charge.&nbsp; In the meantime, if you have a recalled AGV Tourmodular DOT (E2206) Multi MPLK and Solid MPLK motorcycle helmet and observe that the red lever latch of the micrometric buckle does not automatically engage, you must manually close the red lever latch to ensure that the micrometric buckle fastens properly and securely before use.&nbsp; For more inf', '75392');
INSERT INTO safety_incidents VALUES ('0de36225125573a3e991600fe06da099b8e45775', 'Health Canada', '2024-04-12', 2024, '2024-04', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Turquaz 100% Turkish Cotton Hooded Terry Kid''s Bathrobes', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bathrobes and destroy them.For more information, consumers can contact RobeMart by telephone toll-free at 1-844-762-6278 between 9:00 a.m. and 4:00 p.m. PST, by email&nbsp;or visit the company’s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the', '75377');
INSERT INTO safety_incidents VALUES ('0b3030b02dbe833be07ed72e6d931f4279f23e92', 'Health Canada', '2024-04-12', 2024, '2024-04', 'Canada', 'Canada', '', 'Drugs', 'JAMP-Guanfacine XR 4 mg tablets', 'Contamination', 'Other', 'Not Specified', 'Contamination - Product safety', 'Not Reported', 0, 0, 'Check your or your child''s pill bottle to ensure that the green JAMP Guanfacine XR 4mg tablets do not have any brown or amber-coloured stains. If stains are identified, or if you are unsure, return it to your pharmacy for a replacement.Talk to a health care professional if you have questions or have health concerns.Contact JAMP Pharma Corporation by calling 450-449-4326 (option 3) or 1-866-399-9091 (option 3), or by email at custjamp@jamppharma.com if you have questions about this recall.Report ', '75391');
