INSERT INTO safety_incidents VALUES ('7ac535e33fcbd85c9fa9b1734dd5b13ad777e4ff', 'Health Canada', '2024-04-11', 2024, '2024-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'Delta Cycle Stem Raisers', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled stem raisers and bring the product to a local bike shop to ensure the correct torque is applied.For more information, consumers can contact Delta Cycle by telephone at 800-474-6615, Extension 2, from 9 a.m. to 5 p.m. EDT, Monday through Friday, by email at stemrecall@designbydelta.com or visit the company website&nbsp;and click on Stem Recall at the bottom of the page for the more information.Joint recall with Health Canada, the United States ', '75362');
INSERT INTO safety_incidents VALUES ('5b160e0091729c325386b245fceebfc10cbba882', 'Health Canada', '2024-04-11', 2024, '2024-04', 'Canada', 'Canada', '', 'Chemicals', 'Treepoxy brand epoxy hardeners', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products, keep them out of reach of children and contact Kingma Lumber Masters for an exchange.For more information, consumers can contact Kingma Lumber Masters by telephone at 780-238-2431, from 9 a.m&nbsp; to 5 p.m (MST), Monday to Friday,&nbsp; or by email at kingmalm2019@gmail.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada wou', '75375');
INSERT INTO safety_incidents VALUES ('1f65176d8c6d5dbfb85138c29db89bd67ddab2c9', 'Health Canada', '2024-04-11', 2024, '2024-04', 'Canada', 'Canada', '', 'Toys & Childcare', 'Kinderfeets Hanging Gym Products', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled hanging gym products and contact Kinderfeets LLC for a pre-paid return label to return the product to the importer.&nbsp; Once the product has been received by the importer, consumers can contact the original point of purchase for a full refund.For more information, consumers can contact Kinderfeets LLC by telephone at 1-866-627-9690 or by email at customerservice@kinderfeets.com.Please note that the Canada Consumer Product Safety Act prohibit', '75376');
