INSERT INTO safety_incidents VALUES ('2e4bc029d866aaf09d5a9060ee497fbfff67b011', 'Health Canada', '2024-04-09', 2024, '2024-04', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products labelled to contain prescription, controlled or other drug ingredients', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use these products. Consult a health care professional if you have used any of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies. Return the products to your local pharmacy for proper disposal.Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Hom', '75371');
