INSERT INTO safety_incidents VALUES ('b44626a75f37a67662f127752104b5824215ab56', 'Health Canada', '2024-04-04', 2024, '2024-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'Thule RideAlong Child Bike Seat', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Thule RideAlong and contact Thule Group to arrange for the return of the harness padding and register for a replacement harness padding.For more information, consumers can contact Thule Group by telephone at 1-888-816-0228, by email at thuleridealong.americas@thule.com or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Thule Group.Please note that the Canada Consumer', '75269');
