INSERT INTO safety_incidents VALUES ('e255a092c5136ceba38270cf21261608ad356dbd', 'Health Canada', '2024-04-02', 2024, '2024-04', 'Canada', 'Canada', '', 'Household Items', 'JURLEA Area Rugs', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Yalande-US for a full refund. Consumers will be asked to destroy the product by cutting it in half and to provide proof of destruction by sending a photo of the cut product to yalande_us2021@163.com to receive a full refund. Yalande-US is contacting all known consumers directly. For more information, consumers can contact Yalande-US by telephone at +8617806631084 from 2:00am to 11:00am (PDT), or by email at yalande_us2021@1', '75296');
