INSERT INTO safety_incidents VALUES ('8876e9206d1c384f701159b3d102a721669cc5e5', 'Health Canada', '2024-03-28', 2024, '2024-03', 'Canada', 'Canada', '', 'Household Items', 'VEVOR Snow Melting Mat', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Vevor Snow Melting Mat and dispose of the product according to municipal hazardous waste guidelines or contact the company to return the product to a designated location for a refund. For more information, consumers can contact Vevor by telephone at 855-385-1880, Monday to Friday, 8 a.m. to 5 p.m. PST, Saturday to Sunday, 8 a.m. to 3 p.m. PST, by email at support@vevor.ca or visit the company website.Please note that the Canada Consumer Produc', '75234');
