INSERT INTO safety_incidents VALUES ('35e5c1ccbef0cecc229dc4bd317308168479cbb1', 'Health Canada', '2024-03-28', 2024, '2024-03', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Henna cones', 'Chemical', 'Chemical / Toxic Substance', 'Burns', 'Chemical hazard - Product safety', 'Not Reported', 0, 0, 'Consumers should immediately stop using the henna cone products that have been recalled, as well as any henna cone products that cause irritation to the skin (i.e. burning sensation, redness, or blisters). Dispose of them in regular household garbage.To check for any possible skin irritation to a henna cone product, consumers can apply a small amount of the product to their forearm as a patch test.If skin irritation does occur, with a recalled product or from use of another henna cone product, w', '75305');
