INSERT INTO safety_incidents VALUES ('acc394b84e09649aad40a38b93a10cff5780442f', 'Health Canada', '2024-03-21', 2024, '2024-03', 'Canada', 'Canada', '', 'Household Items', 'Elin Dessert Plates sold by Anthropologie', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of them in regular household garbage. Customers who purchased the product in-store may choose to return the product to any Anthropologie store for a full refund. If the product was purchased online, customers may contact Anthropologie using the contact information below to receive a full refund.&nbsp; Anthropologie is contacting all online purchasers by email.For more information, consumers can contact Anthropologie at 800', '75272');
