INSERT INTO safety_incidents VALUES ('83b6e23785bdadd38d804033028a8e8e6616379d', 'Health Canada', '2024-03-13', 2024, '2024-03', 'Canada', 'Canada', '', 'Health Products', 'Unauthorized health products labelled to contain drugs', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use these products. Return the products to your local pharmacy for proper disposal.  Consult a health care professional if you have used any of these products and have health concerns.  Buy your prescription drugs only from licensed pharmacies.  Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) o', '74473');
