INSERT INTO safety_incidents VALUES ('936a78f668b8985ba6ef60a59243ef46204ba93d', 'Health Canada', '2024-02-22', 2024, '2024-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'MSR camping cooking pots', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled camping cooking pot and contact Cascade Designs for a free replacement pot handle/lifter. The replacement pot handle/lifter does not require tools to install.&nbsp; &nbsp;For more information, consumers can contact Cascade Designs Inc. &nbsp;by telephone at 800-531-9531, from 8 a.m. to 4 p.m. PT, Monday through Friday or visit the company website https://www.msrgear.com/pot-recall.html or &nbsp;www.msrgear.com and then click on the “Recall Hea', '75115');
INSERT INTO safety_incidents VALUES ('ef944c7f4eb08bdf63bdefce6f41cfaa920aeef5', 'Health Canada', '2024-02-22', 2024, '2024-02', 'Canada', 'Canada', '', 'Food & Food Contact', 'Vegetarian Beef Ball', 'Gluten - Wheat', 'Allergen', 'Not Specified', 'Gluten - Wheat', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionIf you have celiac disease or other gluten-related disorders, do not consume the recalled product&nbsp;as it&nbsp;may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more', '75116');
