INSERT INTO safety_incidents VALUES ('ad21cc282a1a72d86ad90b2f25e32d104d1920b6', 'Health Canada', '2024-02-21', 2024, '2024-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'FirstPower 4000mAh V6 Battery Replacement for Dyson V6 Series Vacuums', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard - Burn hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and safely dispose of the items in such a way that they cannot be used again. Contact your municipality for instructions on how to safely transport and dispose of lithium-ion batteries. Batteries are considered hazardous waste. Do not place them in household garbage. Consumers can contact Shenzhen Lepower International Electronics Co.,Ltd for a full refund or a new product for free.For more information, consumers can c', '74937');
INSERT INTO safety_incidents VALUES ('8d2abfebb1977e4606ba91223009709018e80883', 'Health Canada', '2024-02-21', 2024, '2024-02', 'Canada', 'Canada', '', 'Other', 'Hopia Cake', 'Egg', 'Allergen', 'Not Specified', 'Egg', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '75085');
