INSERT INTO safety_incidents VALUES ('344685af69bcdd98ddc6dc66ac9acc0a2910cba1', 'Health Canada', '2024-02-21', 2024, '2024-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'iTrust Heavy Duty Wall Charger Real 2.1 A', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose of the product in accordance with municipal electronic waste requirements.For more information, consumers can contact MSB Trading by telephone at 778-855-7860 from 10:00 am – 5:00 pm PST, or by email at&nbsp;&nbsp;msb.trading@yahoo.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to ', '75105');
