INSERT INTO safety_incidents VALUES ('4222b2cc80e171a21f340f4c1b4519168d5818a5', 'Health Canada', '2024-02-21', 2024, '2024-02', 'Canada', 'Canada', '', 'Household Items', 'Various Bico Estonia window coverings with ties', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and keep all cords away from children. For more information, consumers can contact the vendor by logging into their Etsy account and can also visit Help Centre for guidance. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product', '75107');
