INSERT INTO safety_incidents VALUES ('72f0cdbe9ad1ea436b14f4ae76c1396382f1b374', 'Health Canada', '2024-02-20', 2024, '2024-02', 'Canada', 'Canada', '', 'Fresh', 'Mexican Style Street Corn Chopped (Salad) Kit', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serio', '75109');
INSERT INTO safety_incidents VALUES ('c5bf61235a567783cb512a6522c499de16924b0d', 'Health Canada', '2024-02-20', 2024, '2024-02', 'Canada', 'Canada', '', 'Drugs', 'Certain lots of Audrina 28 birth control pills (listed below)', 'Labelling', 'Chemical / Toxic Substance', 'Not Specified', 'Labelling', 'Not Reported', 0, 0, 'Take your Audrina 28 pills as prescribed. If your day-of-the-week sticker is misprinted and lists "Tuesday" instead of "Thursday," you can:          Keep track of your daily pill intake independently or correct the error by writing the proper day on the sticker. Consider additional reminders to take your pill on schedule, such as a daily alarm;      Go to your pharmacy to request replacement day-of-the week stickers. Jamp Pharma Corp will begin distributing corrected stickers to Canadian pharmac', '75110');
INSERT INTO safety_incidents VALUES ('366e6030bda52265d6db39030a5b93a3d46cc4f1', 'Health Canada', '2024-02-20', 2024, '2024-02', 'Canada', 'Canada', '', 'Other', 'Unisex by Eros and Company', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact the company to obtain a new instruction manual. For more information, consumers can contact Ajpro Distribution by telephone at 450-681-0666, from 9am to 5pm, Monday to Friday, by email at service@ajpro.ca or visit the company''s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to', '75111');
INSERT INTO safety_incidents VALUES ('bbd9a72490ff02e27d56b15ef47c5c9a2fec44bc', 'Health Canada', '2024-02-20', 2024, '2024-02', 'Canada', 'Canada', '', 'Natural Health Products', 'Nutracelle Nutramin Vitamin for Kids', 'Dosage', 'Other', 'Not Specified', 'Dosage', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '75112');
INSERT INTO safety_incidents VALUES ('95602cd8691ea6d7fe0ba92373b146b62304bde1', 'Health Canada', '2024-02-20', 2024, '2024-02', 'Canada', 'Canada', '', 'Drugs', 'PDP-Desonide', 'Packaging', 'Other', 'Not Specified', 'Packaging', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '75113');
INSERT INTO safety_incidents VALUES ('77e88c432f5f8fa91b659824a10faafb19b290bc', 'Health Canada', '2024-02-19', 2024, '2024-02', 'Canada', 'Canada', '', 'Health Products', 'APO-MOMETASONE', 'Contamination', 'Microbiological Contamination', 'Not Specified', 'Contamination', 'Moderate', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for&nbsp;proper disposal.Seek medical attention if you or your child have used this product and are experiencing persistent or worsening symptoms, such as fevers, or facial pain or pressure. Consult a health care professional if you or your child have used this product and have health concerns.Contact Apotex Inc. via Sedgwick by calling 1-844-265-7389 if you have questions about this recall.Report any health product-related&nbsp;s', '75083');
INSERT INTO safety_incidents VALUES ('3f5d285e4e4d289ea7d327aa0996af4e4aef05f7', 'Health Canada', '2024-02-19', 2024, '2024-02', 'Canada', 'Canada', '', 'Drugs', 'APO-Mometasone nasal spray, 50 mcg/metered spray', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Not Reported', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for proper disposal.Seek medical attention if you or your child have used this product and are experiencing persistent or worsening symptoms, such as fevers, or facial pain or pressure. Consult a health care professional if you or your child have used this product and have health concerns.Contact Apotex Inc. Customer Service by calling 1-877-427-6839 if you have questions about this recall.Report any health product-related&nbsp;si', '75103');
