INSERT INTO safety_incidents VALUES ('b80fb4d918ab49874cb349d9e772a82a546d84f3', 'Health Canada', '2024-02-15', 2024, '2024-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Frigidaire-Branded Rear-Control Range', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Frigidaire rear-control range and contact Electrolux Group for a free repair/professional installation of a new control panel. &nbsp;Consumers should not use the range while awaiting the service call.&nbsp; Consumers should unplug the unit until repaired by an authorized servicer.To participate in the recall consumers can register online at&nbsp;www.rangeuirecall.ca or call 1-888-889-8933 from 8:30 a.m. to 8:00 p.m. ET, Monday through Friday (', '74981');
INSERT INTO safety_incidents VALUES ('efba796a4746561aa42447f8f2ef79f1aebb29b7', 'Health Canada', '2024-02-15', 2024, '2024-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'Bell Soquel Youth Helmets', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Bell Soquel Youth Helmets and contact Bell Sports for a refund.For more information, consumers can contact Bell Sports by telephone at (800) 456-2355 (option 3), Monday through Friday, from 8 a.m. and 5 p.m. CT, by email at consumersupport-bell@bellhelmets.com &nbsp;or visit the company website www.thebellgarage.com.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Bell Sports.Please note that ', '75007');
INSERT INTO safety_incidents VALUES ('1cafaed5e49d602d9e5fbdf87098071c6ef9d4c1', 'Health Canada', '2024-02-15', 2024, '2024-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Char-Broil Digital Electric Smokers', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Char-Broil Electric Smokers and contact Char-Broil for a repair kit. The repair kit consists of a Ground Fault Circuit Interrupter (“GFCI”) plug (also known as a “pigtail”), a clamshell enclosure to secure the GFCI pigtail and a cable clamp. Instructions for installing each of these repair kit items will also be provided.For more information, consumers can contact Char-Broil by telephone at 1-833-206-4647 from 9:00 a.m. to 7:00 p.m. ET, Monday', '75033');
INSERT INTO safety_incidents VALUES ('71195fa39fbd9e411c175e4d926420e18acac4b4', 'Health Canada', '2024-02-15', 2024, '2024-02', 'Canada', 'Canada', '', 'Cannabis', 'BonBon Turkish Delight - Lokum edible cannabis, Lots WCTD231127 and WCTD240108', 'Contamination', 'Other', 'Not Specified', 'Microbial contamination', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased, or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '75072');
