INSERT INTO safety_incidents VALUES ('f6820bb611e129a32671cfee85e0e4d5a327fbd3', 'Health Canada', '2024-02-14', 2024, '2024-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'USB Charger Adapter', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled USB Charger Adapter, dispose of the product in accordance with municipal electronic waste requirements and contact Temu for a refund.For more information, consumers can contact Temu by visiting the company "Support Centre" website https://www.temu.com/support-center.html. Affected customers may also log in to their Temu account to identify detailed information of the recall by referring to the “Your Recalls and Product Safety Alerts” page.Plea', '75048');
