INSERT INTO safety_incidents VALUES ('fc79117218c4ad9e70793d2d833cb4b4e4d6a37a', 'Health Canada', '2024-02-12', 2024, '2024-02', 'Canada', 'Canada', '', 'Specialized Products', 'Unregistered insecticides such as "Sniper 1000EC DDVP," "Lava 100% EC" and "NOPEST". These contain the insecticide dichlorvos at levels that pose a significant risk to human health.', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard - Unauthorized products - Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not purchase, import, sell or use these products.If you are in possession of one of these products, safely dispose of it in accordance with your provincial and/or municipal guidelines for the disposal of hazardous waste.Only purchase insecticides that have been registered by Health Canada with a PCPA registration number identified on the product label. This code has up to five digits, for example: Registration No. 12345 Pest Control Products Act. To know if a product is registered, visit the ', '75058');
