INSERT INTO safety_incidents VALUES ('b94fa8f376d5d610da29db4eba83f34d4a35312d', 'Health Canada', '2024-02-08', 2024, '2024-02', 'Canada', 'Canada', '', 'Tools & Machinery', 'Husqvarna petrol grass trimmer', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Husqvarna Petro Gas Trimmer and return for repair to a Husqvarna Certified Dealer.For more information, consumers can contact Husqvarna by telephone at 877-257-6921 from 8am to 7pm ET, Monday through Friday or online at www.husqvarna.com/ca-en/ or www.husqvarna.com/ca-fr/.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Husqvarna Professional Products Inc..Please note that the Canada Consumer ', '74966');
INSERT INTO safety_incidents VALUES ('cdd1a46117c29134cf4825884746b9a23f3650eb', 'Health Canada', '2024-02-08', 2024, '2024-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Ice Buckets in Certain Frigidaire Branded Side-by-Side Refrigerators', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Choking hazard - Laceration hazard', 'Not Reported', 0, 0, 'Immediately stop using the ice makers, empty and discard the ice and contact Electrolux to request a replacement ice bucket, free of charge.To participate in the recall consumers can register online at icebucketrecall.ca, or contact the company at icebucketrecall@electrolux.com, or call 1-888-377-7564 from 8:30 a.m. to 8:00 p.m. ET, Monday through Friday (except statutory holidays).Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Electrolux Home', '74967');
INSERT INTO safety_incidents VALUES ('ef557b1350c65e7b7503b176db4d89bbe5d30072', 'Health Canada', '2024-02-08', 2024, '2024-02', 'Canada', 'Canada', '', 'Household Items', 'Steamfast, Sharper Image and Vornado Brand Handheld Garment Steamers', 'Burns', 'Sharp Edges / Points', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Steamfast, Sharper Image and Vornado Brand Handheld Garment Steamers and contact Vornado for a refund.For more information, consumers can contact Vornado by telephone toll-free at 1-888-240-2768, from 8:00 a.m. to 5:00 p.m. ET, Monday through Friday or online at www.vornado.com/recalls/hhgs to start a recall submission. Consumers can also visit www.vornado.com, www.steamfast.com, or www.sihomecomfort.com and click on "Product Recalls" at the t', '75001');
INSERT INTO safety_incidents VALUES ('f9be37cb50e31e5657601bf537554a3d0ba0ecf1', 'Health Canada', '2024-02-08', 2024, '2024-02', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Lolanta Children’s Hooded Flannel Bathrobes', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bathrobes, destroy the garment by cutting them in half and email a photograph of the destroyed garment for a full refund.For more information, consumers can contact Lolanta by telephone at +86&nbsp;183 7913 2016, from 9:00 a.m. to 6:00 p.m. CST, by email or visit the company website.&nbsp;Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Lolanta.Please note that the Canada Consumer Product Safe', '75008');
