INSERT INTO safety_incidents VALUES ('3ae36ddf53d45c234cd125b3ee0e9b537134ddc0', 'Health Canada', '2024-02-01', 2024, '2024-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'NordicTrack iSelect Voice-controlled Adjustable Dumbbells with model number NTSAW23020', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled dumbbells and contact Member Care for refund or credit toward a new iFIT product or the iFIT subscription service.For more information, consumers can contact Member Care by telephone at 1-888-936-4266, from 7:30 am to 4:30 pm EST, Monday through Friday, or by email at customerservice@iconcanada.ca or servicealaclientele@iconcanada.ca.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and iFIT Inc.Pl', '74927');
