INSERT INTO safety_incidents VALUES ('d69d82f597df54ee7d1a81265f16be61929a0c2f', 'Health Canada', '2024-02-01', 2024, '2024-02', 'Canada', 'Canada', '', 'Household Items', 'BISSELL® Multi Reach® Hand and Floor Vacuum Cleaner, Models 1985, 1985C, 2151, 21518, and 2151C', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled vacuums and contact BISSELL for instructions on how to deplete the charge on the battery and receive a free replacement.For more information, consumers can contact BISSELL toll free 1-855-739-1702 from 9 a.m. to 7 p.m. ET Monday through Saturday, or go to Canada.BISSELL.com/recall for more information about the free replacement. Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and BISSELL Canada C', '74964');
INSERT INTO safety_incidents VALUES ('f04d3ebcb42682cfae83deb887a73b7c921457cd', 'Health Canada', '2024-02-01', 2024, '2024-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'SRAM 12-speed Shift Brake Levers', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled SRAM shift brake levers and inspect their levers for tightness. If the shift brake lever rotates or is loose, the consumer should contact an authorized SRAM dealer for a &nbsp;free brake installation inspection. If the brake installation is loose at the dealer inspection, the clamp bolt assembly will be tightened or replaced at no charge to the consumer. For more information, consumers can contact SRAM Service Canada ULC by telephone at 604-99', '74965');
INSERT INTO safety_incidents VALUES ('c38cd31aef2844ecc34594551128ccabd482c8f7', 'Health Canada', '2024-02-01', 2024, '2024-02', 'Canada', 'Canada', '', 'Toys & Childcare', 'Certain 2023 Versions of Slide & Seek Ball Run with Wooden Knobs sold as part of The Babbler Play Kit by Lovevery', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Slide &amp; Seek Ball Run and contact Lovevery, Inc. for instructions on how to receive a replacement Slide &amp; Seek Ball Run.For more information, consumers can contact Lovevery, Inc. by telephone toll-free at 888-520-0167 from 7 a.m. to 6 p.m. CT Monday through Friday, by email at ballrun@lovevery.com, or visit the company’s recall website for more information.Joint recall with Health Canada, the United States Consumer Product Safety Commi', '74968');
