INSERT INTO safety_incidents VALUES ('ec12c1003cc07a4abe70b76e346ec0b639d8a3a7', 'Health Canada', '2024-01-25', 2024, '2024-01', 'Canada', 'Canada', '', 'Household Items', 'Maverick Coastal 60-Inch Outdoor Ceiling Fan', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Visual Comfort &amp; Co. to obtain free replacement blades.For more information, consumers can contact Visual Comfort &amp; Co. by email at techlightingcs@visualcomfortco.com, by telephone at 888-475-1136, Monday through Friday, from 9 a.m. to 5 p.m. CT, or online at https://www.visualcomfort.com/recall/ or https://www.visualcomfort.com/ and click “Recall” at the bottom of the page for more information.Joint recall with Hea', '74781');
