INSERT INTO safety_incidents VALUES ('93913cc5282b1c5763e59bd8b4cdcfd0b8d70fca', 'Health Canada', '2024-01-25', 2024, '2024-01', 'Canada', 'Canada', '', 'Household Items', 'Various custom-made corded window coverings by Vénitiennes 83 Inc.', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact the manufacturer to have replacement parts installed.For more information, consumers may contact Vénitiennes 83 Inc. by telephone at 418-543-8383, Monday to Friday, from 8:30 am to 5 pm (ET), by email at mariechantale@venitiennes83.com, or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada wo', '74949');
INSERT INTO safety_incidents VALUES ('178d04fdc4c44319db1043e5305ef9051bf91820', 'Health Canada', '2024-01-24', 2024, '2024-01', 'Canada', 'Canada', '', 'Specialized Products', 'Natural gas and propane-fired direct vent free-standing fireplaces manufactured by CFM Inc. (Majestic Fireplace) that bear the trade names Insta-flame or Northern Flame (Models FSDV22, FSDV30, FSDV32, D222 and D232 Series).', 'Fire', 'Explosion', 'Not Specified', 'Fire hazard - Flammability hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using these fireplaces.Any affected fireplaces currently in use should have the fuel supply disconnected immediately. The manufacturer is no longer in business and there is no retro fit kit available. Contact a licensed gas technician for disconnection.Canadian retailers and distributors of these fireplaces should immediately cease sale.Manufacturers, importers, distributors or retailers that become aware of incidents, including recalls initiated for human healt', '25476');
INSERT INTO safety_incidents VALUES ('073c2395642716b0302a0fbb5f41d5f25a636c68', 'Health Canada', '2024-01-24', 2024, '2024-01', 'Canada', 'Canada', '', 'Chemicals', 'Sudbury Products - ALL-OFF™ Hull and Bottom Cleaner', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of them according to municipal hazardous waste guidelines.For more information, consumers can contact Sudbury Boat Care Products by telephone at 978-532-4019, from 8:00 am to 5:00 pm ET or email at csr@suburyboatcare.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any he', '74939');
INSERT INTO safety_incidents VALUES ('b02a605b39e44d367fb5c345d39cdd786d6442c0', 'Health Canada', '2024-01-24', 2024, '2024-01', 'Canada', 'Canada', '', 'Drugs', 'JAMP TELMISARTAN-HCT', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '74945');
