INSERT INTO safety_incidents VALUES ('2d84320d2908b38da8940847d0951b365a04d5c0', 'Health Canada', '2024-01-22', 2024, '2024-01', 'Canada', 'Canada', '', 'Household Items', 'All window coverings from the Vision collection, the Vienna collection as well as the Romain blinds made with the “P-clip”', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to the point of purchase for a new clip provided by the company.For more information, consumers can contact Carsan EVP by telephone at 1-800-661-8716 or 450-661-8716 from 9 a.m. to 5 p.m. or by email at orderdesk@carsan.ca or in-person visit at 1311 avenue Godin, Laval, QC, H7E 2T1. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in C', '74919');
