INSERT INTO safety_incidents VALUES ('a509f0537124d66cf48e1396b92b8afc5f8b1601', 'Health Canada', '2024-01-15', 2024, '2024-01', 'Canada', 'Canada', '', 'Drugs', 'PEDIATRIX', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '74912');
