INSERT INTO safety_incidents VALUES ('e654d01acb8df9fa5b73df6b82d706f56205be04', 'Health Canada', '2024-01-02', 2024, '2024-01', 'Canada', 'Canada', '', 'Household Items', 'Various Blinds from SBM Canada', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to the point of purchase for repairs.For more information, consumers can contact SBM Canada by telephone at 514-353-3339, Monday to Friday, from 9am to 4pm EST, by email at service@storesbm.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any', '74827');
INSERT INTO safety_incidents VALUES ('18d2a0f05c16431bc02d296642e7fbdc4f1b5166', 'Health Canada', '2024-01-02', 2024, '2024-01', 'Canada', 'Canada', '', 'Household Items', 'Zebra blinds and Roller shades with chain and chain guard', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact the company Juste des Stores/True Blinds for a cordless replacement system and additional instructions.For more information, consumers can contact Juste des Stores/True Blinds by telephone at 1-844-741-9835, Monday to Friday, from 8am to 4pm EST, by email at info@justedesstores.ca or info@trueblinds.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or eve', '74829');
