INSERT INTO safety_incidents VALUES ('5535c3d8f983909a170185ccf412ab5e8857cc80', 'Health Canada', '2023-12-29', 2023, '2023-12', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Klein Tools Portable Power Station and Blackfire Portable Power Station', 'Burns', 'Flammability / Overheating', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of lithium ion batteries according to local municipal transportation and waste requirements for lithium-ion batteries.Customers should contact Klein Tools by telephone toll-free at 1-800-553-4876 from 7:30 AM to 6:00 PM CST Monday through Friday, or by email at KTB1000PAC1000recall@kleintools.com with verification that the power station has been recycled, as well as the serial number of the battery and proof of purchase if', '74796');
INSERT INTO safety_incidents VALUES ('249cf2d37a858a3c50f1710f1e37e5f488d1447f', 'Health Canada', '2023-12-29', 2023, '2023-12', 'Canada', 'Canada', '', 'Household Items', 'Smartlux Manual Open Roller Shade (No-Guard Mechanism) Blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled roller shades and contact Les Entreprises Smartlux Inc. for a repair kit and instructions.For more information, consumers can contact Les Entreprises Smartlux Inc. by telephone at 1-877-825-6679 English/French (option 2), Monday to Friday, from 8:00 am to 4:00 pm EST, or by email at info@smartlux.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.He', '74818');
INSERT INTO safety_incidents VALUES ('f2b0bed15317cb813e3e352aebc84540014f0690', 'Health Canada', '2023-12-29', 2023, '2023-12', 'Canada', 'Canada', '', 'Toys & Childcare', 'Kluster magnetic game', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately stop using the recalled product and contact the company MJ Games for more information.For more information, consumers can contact MJ Games by email at&nbsp;mail@mjgames.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer product', '74819');
INSERT INTO safety_incidents VALUES ('ba85dee42b7ee8b2e5f6fc06f2460bafedaea95d', 'Health Canada', '2023-12-29', 2023, '2023-12', 'Canada', 'Canada', '', 'Chemicals', 'Fix A Leak leak sealer', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard - Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Fix A Leak and request a replacement.For more information, consumers can contact Marlig Industries Inc by telephone at 905-374-2560 from 9:00 am to 5:00 pm, Monday to Friday Eastern Time, by email at info@fixaleak.com&nbsp; or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to re', '74820');
INSERT INTO safety_incidents VALUES ('f81f71976b893f8ec58080e86bed8fe2c1c439cb', 'Health Canada', '2023-12-29', 2023, '2023-12', 'Canada', 'Canada', '', 'Household Items', 'Piccolo Bambino white contour baby changing pad', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and remove the zipper pull. This can be done by twisting the zipper pull with your fingers. Discard the zipper pull and any other metal piece that falls off.For more information, consumers can contact Abond Group by telephone at 514-353-9060, extension 285, from 8:30 am to 5 pm EST, or by email at quality@abondgroup.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or', '74821');
INSERT INTO safety_incidents VALUES ('a6509a0d6c6d1ce8da24565bd13e222939ed1421', 'Health Canada', '2023-12-29', 2023, '2023-12', 'Canada', 'Canada', '', 'Household Items', 'Various Home Decorators Collection and HDG corded window coverings', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact the manufacturer, Nien Made Enterprise Co. Ltd., for a retrofit kit and additional instructions.For more information, consumers can contact Nien Made Enterprise Co. Ltd. by telephone at the toll-free number 1-800-666-1779, Monday to Friday, from 9am to 7pm EST, or visit the Home Depot Canada’s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even ', '74822');
