INSERT INTO safety_incidents VALUES ('a9cf491289db851e71ac3a5aa8147929defe80e8', 'Health Canada', '2023-12-15', 2023, '2023-12', 'Canada', 'Canada', '', 'Household Items', 'FG Square Santa Sleigh', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to a London Drugs for a full refund. For more information, consumers can contact London Drugs by telephone at 1-888-991-2299 from 6am to 10pm Monday to Friday, 7am to 10pm Saturday, and 8am to 8pm Sundays &amp; Holidays or visit the company website. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to rem', '74742');
INSERT INTO safety_incidents VALUES ('0665589b3c6d1c4f852d07f264a09e78286692df', 'Health Canada', '2023-12-15', 2023, '2023-12', 'Canada', 'Canada', '', 'Fresh', 'Enoki Mushroom', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Listeria monocytogenes&nbsp;may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and', '74743');
INSERT INTO safety_incidents VALUES ('81226b6ad68f1ab898e9b69818a08a60efb2f29e', 'Health Canada', '2023-12-15', 2023, '2023-12', 'Canada', 'Canada', '', 'Drugs', 'Hadalabo Pearl Barley Facial Foam', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Moderate', 0, 0, 'Stop using these&nbsp;products. Consult your health care professional if you have used these products and have health concerns, and for advice on which health products are best for you and your family.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check if products have been authorized f', '74752');
