INSERT INTO safety_incidents VALUES ('2ba71c014db40cbf75a4d61511cc99e57ba35e4a', 'Health Canada', '2023-12-14', 2023, '2023-12', 'Canada', 'Canada', '', 'Household Items', 'Steamfast brand lightweight handheld Home and Away Travel Steam Iron models', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using&nbsp;the above&nbsp;Steamfast irons and&nbsp;contact Vornado for a refund.For more information, consumers can contact Vornado by telephone at 1-866-827-3362, or online&nbsp;at www.steamfast.com/recalls/travelirons&nbsp;to start a recall submission. Consumers can also visit www.vornado.com or www.steamfast.com, and click on “Product Recalls” at the top of the page for more information.Joint recall with Health Canada, the United States Consumer Product Safet', '73562');
