INSERT INTO safety_incidents VALUES ('0cc53f8c61b73a6aec33468a9c4e659b7f462d22', 'Health Canada', '2023-12-14', 2023, '2023-12', 'Canada', 'Canada', '', 'Drugs', 'JAMP Guanfacine XR 1 mg', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'Check your or your child''s pill bottle of JAMP Guanfacine XR 1 mg tablets to ensure it contains only 1 mg white, round tablets. If it contains any JAMP Guanfacine XR 4 mg green, oval tablets, or if you are unsure, return it to your pharmacy. Your pharmacist will check it and provide you with a replacement if needed.Contact a health care professional immediately if you or your child are experiencing signs and symptoms of overdose.Contact JAMP Pharma Corporation by calling toll-free at 1-866-399-9', '74729');
