INSERT INTO safety_incidents VALUES ('a5ae18dd60fab84ef2f08edc2396f8573114305a', 'Health Canada', '2023-12-04', 2023, '2023-12', 'Canada', 'Canada', '', 'Electrical & Electronics', 'GE Brand 30” Knob-Controlled Electric Radiant Cooktops', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should contact MC Commercial to arrange for free installation of a replacement burner knob assembly. When not in use, turn the unit off at the circuit breaker. Do not leave flammable materials or empty cookware on or near the cooktop. In the affected units, the burner can remain on following use even after being turned to the “off” position. In this case, the “On” indicator light will not be illuminated, but the “Hot Cooktop” light corresponding to the burner will remain illuminated un', '74684');
