INSERT INTO safety_incidents VALUES ('a6f344597b20f75dd4487d891799f0a532fa9438', 'Health Canada', '2023-11-29', 2023, '2023-11', 'Canada', 'Canada', '', 'Medical Devices', 'Unauthorized blood glucose (sugar)-reading smartwatches', 'Unauthorized Product - Inaccurate Test Or Measurement Results - Increased Risk Or New Adverse Events - Lack Of Efficacy', 'Other', 'Not Specified', 'Unauthorized product - Inaccurate test or measurement results - Increased risk or new adverse events - Lack of efficacy', 'Not Reported', 0, 0, 'Do not use blood glucose-reading smartwatches that are not authorized by Health Canada.  Consult a healthcare professional if you have used any of these products and have health concerns.Talk to your healthcare professional about which blood glucose monitoring system is right for you. You can search Health Canada authorized medical devices at Medical Devices Active Licence Listing (MDALL).Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '74673');
