INSERT INTO safety_incidents VALUES ('a25d93121bc2b568fc5b508cf524a24f6b6acf52', 'Health Canada', '2023-11-20', 2023, '2023-11', 'Canada', 'Canada', '', 'Other', 'Rojada Child Safety Seats', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have the affected products should immediately stop using them and safely dispose of them in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Product I', '74312');
