INSERT INTO safety_incidents VALUES ('28af94f41516edc044bf7ad8b147271fcc533e06', 'Health Canada', '2023-11-20', 2023, '2023-11', 'Canada', 'Canada', '', 'Chemicals', 'Polyester Hardener and Polyester Fiberglass Resin recalled due to improper labelling and packaging', 'Consumer Products', 'Other', 'Not Specified', 'Consumer products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products. The products can be returned to the place of purchase for a refund. Products can also be disposed of according to local municipal hazardous waste guidelines.For more information, consumers can contact Lloyds Laboratories Inc. by telephone at 705-876-9997 between 8:30 and 16:30 EST or by email at orderdesk@lloydslaboratories.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistribute', '74617');
