INSERT INTO safety_incidents VALUES ('1a794318f0d3a2493c676c39dc9bf1a1373a055f', 'Health Canada', '2023-11-17', 2023, '2023-11', 'Canada', 'Canada', '', 'Household Items', 'HT Blinds: White Horizontal Fauxwood 2” Blind Safecord', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled blind and contact HT Blinds for repair.For more information, consumers can contact HT BLinds by telephone at 604-593-5450, Monday to Friday 9 am – 5 pm, or by email at service@htblinds.caPlease note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this pro', '74592');
