INSERT INTO safety_incidents VALUES ('1cd2407bc6ab82f0cb81b0e3ac4a363390aaf64e', 'Health Canada', '2023-11-14', 2023, '2023-11', 'Canada', 'Canada', '', 'Natural Health Products', 'Herbaland brand gummy vitamins and supplements', 'Labelling - Product Safety', 'Other', 'Not Specified', 'Labelling - Product safety', 'Serious', 0, 0, 'Do not use these bulk products and keep them out of the reach of children. Follow municipal or regional guidelines on how to dispose of chemicals and other hazardous waste or return the product to your local pharmacy for&nbsp;proper disposalConsult a healthcare professional if you have used any of these products and have health concerns.Contact Herbaland Naturals Inc. by calling 1-877-464-8669 if you have questions about this recall.Report any health product-related&nbsp;side effects&nbsp;or&nbs', '74556');
