INSERT INTO safety_incidents VALUES ('6a703cea3cb5ad86b47f59a936e4832a1032e4fb', 'Health Canada', '2023-11-09', 2023, '2023-11', 'Canada', 'Canada', '', 'Radiopharmaceuticals', 'Sabril (vigabatrin) 500 mg sachets, DIN 02068036, lots 3209710A and 3207333A.  UPDATED September and November 2023 to add additional lots/products (see table).', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Not Reported', 0, 0, 'Do not stop taking your Sabril medication without consulting your physician.Monitor for any new and unexpected side effects. Seek immediate medical attention of you experience symptoms of a severe allergic reaction, such as difficulty breathing or swallowing or severe swelling of the lips, mouth or throat.Consult your health care professional if you or your child are taking Sabril and you have any concerns. Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Healt', '74153');
INSERT INTO safety_incidents VALUES ('012d7c96064fbfaf19bd9532e48631bb877c29cc', 'Health Canada', '2023-11-09', 2023, '2023-11', 'Canada', 'Canada', '', 'Other', 'DR Pro Tow-Behind Field and Brush Mowers', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled&nbsp;mowers and contact DR Power Equipment for a prorated refund or credit in the amount of the prorated refund toward a new DR Power product.&nbsp; The prorated refund or credit will be determined based on the age of the unit. DR Power will be contacting all known consumers directly.For more information, consumers can contact DR Power Equipment by telephone at 1-800-854-1565 from 8:30 a.m. to 5 p.m. ET Monday through Friday, by email at recal', '74534');
