INSERT INTO safety_incidents VALUES ('d6906b4be4c9247168cbc079af4ce9c8e2d0db9e', 'Health Canada', '2023-11-01', 2023, '2023-11', 'Canada', 'Canada', '', 'Meat And Poultry', 'Vienna Sausage', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Minor', 0, 0, '', '74493');
INSERT INTO safety_incidents VALUES ('12fdbe049f2c4ae0bba2997cd646d528279c2bf7', 'Health Canada', '2023-11-01', 2023, '2023-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Honda Outboard Engine', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Honda Outboard Engines and contact an authorized Honda Marine dealer to schedule an appointment for a free repair. Honda is contacting all known purchasers directly.For more information, consumers can contact Honda Canada Customer Relations by telephone at 1-888-946-6329 from 9 a.m. to 7:30 p.m. ET, Monday through Friday, or visit the company website. Please note that the Canada Consumer Product Safety Act prohibits recalled products from bein', '74498');
INSERT INTO safety_incidents VALUES ('cb8526f886b92dc98d0edf64b57a528ec5b8f9e2', 'Health Canada', '2023-11-01', 2023, '2023-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Battery Pack within certain Anker EverFrost Powered Coolers', 'Consumer Products', 'Flammability / Overheating', 'Not Specified', 'Consumer products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Anker for a free replacement battery pack.For more information consumers can contact Anker by telephone at 1-800-988-7973 Mon-Fri 9:00AM – 5:00PM (PT), by email at support@anker.com or Website Live Chat: Mondays to Fridays 10AM – 4PM (PST) at https://support.anker.com/s/contact-us.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.', '74499');
INSERT INTO safety_incidents VALUES ('a9c6566ce1f6d3adc5cf67273ad3ab7b3e8fc061', 'Health Canada', '2023-11-01', 2023, '2023-11', 'Canada', 'Canada', '', 'General And Plastic Surgery', 'Evis Exera III Video System - Gastrointestinal Videoscope', 'Sterility', 'Other', 'Not Specified', 'Sterility', 'Moderate', 0, 0, '', '74508');
INSERT INTO safety_incidents VALUES ('6b2a4fa26cadd5fff7f47a776c3cc42ec83fd5cf', 'Health Canada', '2023-11-01', 2023, '2023-11', 'Canada', 'Canada', '', 'Drugs', 'Phentolamine Mesylate', 'Establishment/Site Licensing', 'Other', 'Not Specified', 'Establishment/Site licensing', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '74509');
