INSERT INTO safety_incidents VALUES ('ad135cc41287050e05a246331c5dc72f2396018c', 'Health Canada', '2023-11-01', 2023, '2023-11', 'Canada', 'Canada', '', 'Biologic Or Vaccine', 'Cord blood currently banked at the Canadian Cord Blood bioRepository (CCBR), located in Edmonton, Alberta, that was collected, processed, tested, and/or stored anytime between March 1, 2014, and present.', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'If you want to use your stored cord blood, it should be tested prior to release by a qualified third party according to accredited standards outlined by the Canadian Standards Association for blood cells used for transplantation. This should include, at a minimum, testing for infectious disease agents and cell viability.If you have cord blood stored at CCBR or if you have a contract to store cord blood with CCBR, it is recommended you contact CCBR to understand your options.If you have concerns ', '74512');
