INSERT INTO safety_incidents VALUES ('72b210a11119bc427773c339ba12e0bb707567c3', 'Health Canada', '2023-10-31', 2023, '2023-10', 'Canada', 'Canada', '', 'Household Items', 'Kingdom of Comfort Linen Curtain Valance with Ties', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and keep all cords away from children. For more information, consumers can contact the vendor by logging into their Etsy account and can also visit Help Centre for guidance. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product', '74487');
