INSERT INTO safety_incidents VALUES ('cd4416f024429f264160b836f1786a63202c07a8', 'Health Canada', '2023-10-31', 2023, '2023-10', 'Canada', 'Canada', '', 'Medical Devices', 'Unauthorized health products, including drugs, natural health products and medical devices, sold online.', 'Product Safety - Unauthorized Product - Unauthorised Device', 'Other', 'Not Specified', 'Product safety - Unauthorized product - Unauthorised device', 'Not Reported', 0, 0, 'Read the information Health Canada has posted on the dangers of buying&nbsp;drugs,&nbsp;natural health products&nbsp;or&nbsp;medical devices over the Internet.Look for health products that have been authorized by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Medicine Number (DIN-HM).&nbsp;Consumers can also check whether products have been authorized for sale by searching Health Canada''s&nbsp;Drug Produ', '74503');
