INSERT INTO safety_incidents VALUES ('900000f04dca3cd578413fed4d1c9093488d1470', 'Health Canada', '2023-10-31', 2023, '2023-10', 'Canada', 'Canada', '', 'Fresh', 'White Sliced Mushrooms', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '74506');
