INSERT INTO safety_incidents VALUES ('f00d5e37166836f64cc5f6d6a254ebcead1f4e97', 'Health Canada', '2023-10-27', 2023, '2023-10', 'Canada', 'Canada', '', 'Clothing & Textiles', 'COWS Youth Terry Spots Hoody', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and remove the drawstrings or return the product for a refund or replacement. For more information, consumers can contact COWS Inc. by telephone at 1-800-565-2697 or by visiting the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to ', '74467');
INSERT INTO safety_incidents VALUES ('0bce4de9d46ffcbcef77fe7981ac6be638eb5864', 'Health Canada', '2023-10-27', 2023, '2023-10', 'Canada', 'Canada', '', 'Toys & Childcare', 'Borax packet included in all Slime Smoothies by Rahma', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled&nbsp;Borax powder and&nbsp;dispose of it according to municipal hazardous waste guidelines.For more information, consumers can contact Slime Smoothies by email at slimesmoothie.by.rahma@gmail.com or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety in', '74469');
INSERT INTO safety_incidents VALUES ('ea7d0afe2cf9eec058e0fcea105681238bcac76f', 'Health Canada', '2023-10-27', 2023, '2023-10', 'Canada', 'Canada', '', 'Chemicals', 'PURE RESIN Brand Epoxy Resin Kits', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact PURE RESIN to obtain a corrected label.For more information, consumers can contact Pure Resin by email at support@pureresin.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or co', '74471');
INSERT INTO safety_incidents VALUES ('108b45d7602e965505ad58bc7407caa2bc520975', 'Health Canada', '2023-10-27', 2023, '2023-10', 'Canada', 'Canada', '', 'Other', 'Topdeal Baby Feeding Nursing Pillow, Portable Breast Feeding Pillows, with two curved handles, for kids', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using&nbsp;the recalled nursing pillow and dispose of the product.For more information, consumers can contact Qian Sheng Zhuang by email at gzblh@outlook.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold, or even given away in Canada.Health Canada would like to remind consumers to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic ', '74472');
INSERT INTO safety_incidents VALUES ('e4255f6aaede3a71d4047d4b35d7313d60fe8593', 'Health Canada', '2023-10-27', 2023, '2023-10', 'Canada', 'Canada', '', 'Chemicals', 'Quicksilver Corrosion Guard and Quicksilver Light Gray Primer Spray Paint', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to an authorized Mercury&nbsp;or Land ‘N’ Sea&nbsp;dealer for a full refund.For more information, consumers can contact Mercury Marine Limited by telephone at 905-636-4700 between 9:00 a.m. and 5:00 p.m. EST or by email at cdn.mercurysales@mercmarine.com. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would li', '74477');
INSERT INTO safety_incidents VALUES ('839576ec44de100dcf09d618ca117c3b307c8f71', 'Health Canada', '2023-10-27', 2023, '2023-10', 'Canada', 'Canada', '', 'Toys & Childcare', 'Creativity for Kids DIY Glowing Squishy Slime and Magical Mixing', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Creativity for Kids DIY Glowing Squishy Slime and Magical Mixing and dispose of them according to municipal hazardous waste guidelines.For more information, consumers can contact Faber-Castell by telephone at 1-800-311-8684, Monday to Thursday, 9:00 a.m. – 4:00 p.m. and Friday 8:00 a.m. – Noon EST or by email&nbsp;at&nbsp;consumer@fabercastell.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being re', '74478');
INSERT INTO safety_incidents VALUES ('68997aecc81b3c73a9485f9f494180292f3f427a', 'Health Canada', '2023-10-26', 2023, '2023-10', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Insignia™ Multi-Function Pressure Cookers', 'Burns', 'Explosion', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the pressure cookers and&nbsp;contact Best Buy Canada for a free replacement of the inner pot and floating locking valve for signalling pressure.For more information, consumers can contact Best Buy Canada by telephone at 1-888-359-4485  from 7:30 a.m. to 5 p.m. CT Monday through Friday,&nbsp;or visit the company website https://www.recallrtr.com/pc.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Best Buy ', '74430');
