INSERT INTO safety_incidents VALUES ('3a0bb94248976d5554a145188a438d94aab29712', 'Health Canada', '2023-10-06', 2023, '2023-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'Honda Lawnmowers Model numbers HRN216 and HRX217K6', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact an authorized Honda Power Equipment dealer to schedule a camshaft replacement. Honda is contacting all known purchasers directly.For more information, consumers can contact American Honda Motor by telephone at&nbsp;1- 888-888-3139 from 9 a.m. to 7:30 p.m. ET, Monday through Friday&nbsp;or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, s', '74388');
