INSERT INTO safety_incidents VALUES ('7437662cf498e7794715248b19b75ea918999300', 'Health Canada', '2023-10-06', 2023, '2023-10', 'Canada', 'Canada', '', 'Cannabis', 'Port North Lemon Z Rosin - Strain Specific Full Spectrum Solventless Soft Chews, Lot 0Z-03-08-07', 'Contamination', 'Other', 'Not Specified', 'Microbial contamination', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased, or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '74390');
