INSERT INTO safety_incidents VALUES ('3f3d81a2abf22859a2bce7a97b508b3b262e20be', 'Health Canada', '2023-09-25', 2023, '2023-09', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Honda EU7000is Portable Generators', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the&nbsp;recalled Honda EU7000is Portable Generators and contact an authorized Honda Power Equipment dealer to schedule an appointment for a free repair. Honda is contacting all known purchasers directly.For more information, consumers can contact Honda Canada Customer Relations at 1-888-9HONDA9 (1-888-946-6329) from 9 a.m. to 7:30 p.m. ET, Monday through Friday, or visit the company website&nbsp;and click on “Recalls and Updates” at the bottom of the page', '74324');
