INSERT INTO safety_incidents VALUES ('e3a20846631f2d0a82144f5fdefeea6415b9db61', 'Health Canada', '2023-09-21', 2023, '2023-09', 'Canada', 'Canada', '', 'Other', 'DR Power Equipment Chipper Shredders', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled power chipper shredders and contact DR Power Equipment&nbsp;to receive a full refund or a free repair including shipping. For more information, consumers can contact DR Power Equipment by telephone at 800-550-4845 from 8:30 a.m. to 5:00 p.m. ET, Monday through Friday; by email at recall@drpower.com or online at www.drpower.com and click on product recalls page.Joint recall with Health Canada, the United States Consumer Product Safety Commissio', '74306');
