INSERT INTO safety_incidents VALUES ('214fe6117904dbfbc93711b3519f9b81901c4c03', 'Health Canada', '2023-09-21', 2023, '2023-09', 'Canada', 'Canada', '', 'Sports & Leisure', 'Pre-July 2019 Shimano 11-Speed Bonded Hollowtech II Road Cranksets', 'Crash Hazard', 'Other', 'Skin Irritation', 'Crash hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled cranksets and contact Shimano to schedule a free crankset inspection. Only consumers whose cranksets show signs of bonding separation or delamination during the inspection will be provided a free crankset and installation. For more information, consumers can contact Shimano by telephone at 844-776-0315 from 8am to 5pm Monday to Friday PST or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Co', '74311');
