INSERT INTO safety_incidents VALUES ('f5ece5702621568f92a4f40d5bbd277adee3a271', 'Health Canada', '2023-09-14', 2023, '2023-09', 'Canada', 'Canada', '', 'Toys & Childcare', 'Magnetic Dart Board', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled&nbsp;Magnetic Dart Board and return the product for a refund.For more information, consumers can contact The Granville Island Toy Company by telephone at 604-875-0065 seven days a week from 10 am to 6 pm PST or by email at toysupport@toycompany.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report', '74262');
INSERT INTO safety_incidents VALUES ('f396bac20376f19c1650e1651e773814ff776ba7', 'Health Canada', '2023-09-14', 2023, '2023-09', 'Canada', 'Canada', '', 'Other', 'Generac Portable Generators', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled generators and&nbsp;contact Generac for a free repair kit.For more information, consumers can contact Generac by telephone at 1-888-391-0503 from 8 am to 5 p.m. CT Monday through Friday or visit the company website at https://www.generac.com/about-us/product-recall-notifications/GP15000-GP17500-recall. Joint recall with Health Canada, the United States Consumer Product Safety Commission&nbsp;(US CPSC) and Generac.Please note that the Canada Co', '74269');
INSERT INTO safety_incidents VALUES ('996118690ab9c563579fcc90040a145c461f89d2', 'Health Canada', '2023-09-13', 2023, '2023-09', 'Canada', 'Canada', '', 'Furniture & Home', 'IKEA LETTAN Mirror', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled LETTAN mirrors.&nbsp;IKEA urges all customers who own an affected LETTAN mirror to stop using it, and to order replacement wall fittings free of charge. Consumers may also return the mirror to IKEA for refund.&nbsp; A receipt is not required.For more information, consumers can contact IKEA by telephone toll-free at 1-800-661-9807, Monday to Sunday from 9:00 a.m. to 9:00 p.m. EST, or visit the company''s website.Please note that the Canada Consu', '72565');
