INSERT INTO safety_incidents VALUES ('a0c652d41802ae07c1f2f46702dae8c9aa9fac1b', 'Health Canada', '2023-08-31', 2023, '2023-08', 'Canada', 'Canada', '', 'Household Items', 'Prime-Line Defender Security Glass Knobs', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled glass knobs and Prime-Line Products, LLC to receive a merchant gift card. For more information, consumers can contact Prime Line Products at 1-800-729-6123 from 8 a.m. to 7 p.m. ET Monday through Friday, by email at glassknobs@realtimeresults.net, online at https://www.recallrtr.com/glassknobs or at&nbsp;www.primeline.net and click on “Important Recall Information” at the top of the page for more information.Joint recall with Health Canada, th', '74227');
INSERT INTO safety_incidents VALUES ('ef4b6c6a18964b65050d6c474cacb543896b84cd', 'Health Canada', '2023-08-31', 2023, '2023-08', 'Canada', 'Canada', '', 'Specialized Products', 'Boon Flair & Flair Elite High Chair', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Boon Flair &amp; Flair Elite high chairs and immediately contact TOMY for a free repair kit. Consumers will receive a set of bolts and split and flat washers to repair the recalled highchair.For more information, consumers can contact TOMY International, Inc. by telephone at 866-725-4407 from 8 am to 4 pm CT, Monday through Friday, or visit the company website at&nbsp;https://recall.tomy.com or&nbsp;https://us.tomy.com&nbsp;and click on “Produ', '74228');
