INSERT INTO safety_incidents VALUES ('a7c1441ad582ea37202535de75e21c4b576ff60a', 'Health Canada', '2023-08-24', 2023, '2023-08', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Aiper Elite Pro GS100 robotic swimming pool vacuum cleaner', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Aiper Elite Pro and&nbsp;return the product to Aiper for a free replacement.For more information, consumers can contact Aiper by telephone at 1-(888)968-0666 daily from 9:00am to 9:00pm EST, by email at recall@aiper.com or visit the company website www.Aiper.com/elite-pro-recall.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Shenzhen Aiper Intelligent Co., Ltd.Please note that the Canada Con', '73992');
