INSERT INTO safety_incidents VALUES ('2e514026e3ba004ec1d82ecece2d6662aa80c239', 'Health Canada', '2023-08-14', 2023, '2023-08', 'Canada', 'Canada', '', 'Drugs', 'Apo-Acyclovir Tablets', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Serious', 0, 0, 'Continue taking your medication&nbsp;unless&nbsp;you have been advised to stop by your health care provider.&nbsp;You do not need to return your medication to your pharmacy.&nbsp;Not treating your condition may pose a greater health risk.Talk to your health care provider if you are taking a recalled product and are concerned about your health.If you have questions about the recall, contact Apotex Inc. at 1-888-628-0732 or by email at apotex4315@sedgwick.com.Report any health product-related&nbsp', '64118');
INSERT INTO safety_incidents VALUES ('389a6e566b9587d3da4424d3494ab950abb3ef01', 'Health Canada', '2023-08-14', 2023, '2023-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Big Game Hunters and Garden Games Junior Cricket sets', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Big Game Hunters and Garden Games Junior Cricket sets and complete an online form to request a replacement set. Online form can be found here: https://docs.google.com/forms/d/e/1FAIpQLSd4i6A_nvjnDzKiLnmV2zwwAAvzcEpO7kVKQng2Hcg9RdtB1Q/viewform?usp=sf_linkFor more information, consumers can contact DOM Enterprises &amp; Mfg. Ltd. by telephone at 1-877- 725-5056 from 8:30am – 4:30pm ET, Monday to Friday, or by email at support@domsports.com.Pleas', '74067');
INSERT INTO safety_incidents VALUES ('7fa1896ad7332c4aecb471752a133312761cc19d', 'Health Canada', '2023-08-14', 2023, '2023-08', 'Canada', 'Canada', '', 'Chemicals', 'All HOME FRAGRANCE reed diffusers', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Attitudes Import Inc. for a refund.For more information, consumers can contact Attitudes Import Inc. by telephone at 450-681-4147, Monday to Friday, 9am to 5pm EST or by email at joel@attitudesimport.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind consumers to report any health or safety in', '74086');
INSERT INTO safety_incidents VALUES ('640714e5b66557d3baee2abfed9df13642384611', 'Health Canada', '2023-08-14', 2023, '2023-08', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Philips Avent Digital Video Baby Monitor', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the Digital Video Baby Monitors, dispose of the affected product and register for a free replacement on the Philips Website which is available in English and French.Consumers may view the recall notice by Philips in English or French.For more information, consumers can contact Philips by telephone at 1-866-276-5311 from 9 a.m. to 9 p.m. ET Monday through Saturday and from 9 a.m. to 6 p.m. ET Sundays. Please note that the Canada Consumer Product Safety Act ', '74106');
