INSERT INTO safety_incidents VALUES ('fdf7d16d3e323855b9dcc3304aa6561759e331bc', 'Health Canada', '2023-08-11', 2023, '2023-08', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products labelled to contain a prescription drug', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use these products. Return the products to your local pharmacy for proper disposal.Consult a health care professional if you have used any of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies.Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Home', '74107');
