INSERT INTO safety_incidents VALUES ('1b3b8daaf6b57c1962a84d8d597d8186d04a85b4', 'Health Canada', '2023-07-27', 2023, '2023-07', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products labelled to contain a prescription drug', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use these products. Return the products to your local pharmacy for proper disposal.Consult a health care professional if you have used any of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies.Buy only authorized health products. Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Home', '74021');
