INSERT INTO safety_incidents VALUES ('bcbfe04980d55d16c2c428db0bf40fe7f8a09700', 'Health Canada', '2023-07-18', 2023, '2023-07', 'Canada', 'Canada', '', 'Nuts, Grains, And Seeds', 'Raw Macadamia Nuts', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Salmonella&nbsp;may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serio', '73971');
INSERT INTO safety_incidents VALUES ('ca17efaf3848385a72523c5f752e659dbd4135e2', 'Health Canada', '2023-07-18', 2023, '2023-07', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products labelled to contain prescription drugs', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use these products. Return products to your local pharmacy for proper disposal.Consult a health care professional if you have used any of these products and have health concerns.Only buy prescription drugs from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also che', '73972');
