INSERT INTO safety_incidents VALUES ('23950904d62b76be8870eedd4d5bd9e27ca164ad', 'Health Canada', '2023-07-13', 2023, '2023-07', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Cantu Shea Butter Oil Sheen Deep Conditioning Spray', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return the product to the place of purchase to receive a refund.For further information, consumers may directly contact the retailer/importer from whom they purchased the recalled product.Please note that, in addition to the requirements of the Cosmetic Regulations,&nbsp;the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Hea', '73920');
INSERT INTO safety_incidents VALUES ('c4e42afe4fcde1ec4fec911d526ed095426fd413', 'Health Canada', '2023-07-13', 2023, '2023-07', 'Canada', 'Canada', '', 'Chemicals', 'STA-BIL 360 Protection 236 mL (8 fl.oz)', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose of it according to local municipal hazardous waste guidelines. For more information, consumers can contact Amazon.ca at Canada: 1-877-586-3230International: 1-206-266-288For further information, customers can also visit Amazon.ca Product Safety and Recalls.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like t', '73931');
INSERT INTO safety_incidents VALUES ('84e0bcbffbb8a26e634749efa4a0031ba14b6315', 'Health Canada', '2023-07-13', 2023, '2023-07', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'SACHAJUAN Hairspray Light and Flexible', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it for a replacement, or dispose of it.For more information, consumers can contact SACHAJUAN by email at contactus@sachajuan.com or visit the company website www.sachajuan.com.Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Health Canada', '73934');
