INSERT INTO safety_incidents VALUES ('d32c185ee4d5825be120507ed7be7af14ad9a5d0', 'Health Canada', '2023-07-07', 2023, '2023-07', 'Canada', 'Canada', '', 'Drugs', 'Rhinaris Nasal Mist 30 mL (lot 230391A)', 'Product Safety', 'Chemical / Toxic Substance', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Do not use the affected product. Return it to your local pharmacy for proper disposal.Consult a health care professional if you have used this product and have health concerns.Contact Pendopharm Division of Pharmascience Inc. by calling 1-888-550-6060 or emailing medinfo@pendopharm.com if you have questions about this recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '73927');
