INSERT INTO safety_incidents VALUES ('eef3af96f1215883ae38c4965c573016fb0e18a8', 'Health Canada', '2023-07-06', 2023, '2023-07', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Fruit Jelly Snack, Mini Fruit Jelly', 'Other', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Other', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedThe above packages contain mini jelly cups, about the size of coffee creamers.&nbsp;Small jelly cups have previously been implicated in choking deaths of children.&nbsp;  Depending upon the size, shape and consistency mini-cup jelly products may become lodged in the throat and may be difficult to rem', '73782');
