INSERT INTO safety_incidents VALUES ('59075237b312f9d7d6520f2a5587a71804326d58', 'Health Canada', '2023-07-06', 2023, '2023-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'woom ORIGINAL Bikes (2018-2021 models. Sizes 1, 1+, 2, 3, 4, 5, 6.)', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and&nbsp;contact woom Bikes USA for a repair kit.For more information, consumers can contact woom Bikes USA by telephone at 1-855-966-6872 between 8 am to 5 pm CT, Monday through Friday, by email at productsafetyUS@woom.com or visit the company website. Consumers may also use the woom Online Stem Checker to check if their bike is affected.Joint recall with Health Canada, the United States Consumer Product Safety Commission&nbsp; and w', '73903');
