INSERT INTO safety_incidents VALUES ('feb8b2bb911d3792145ce5e605645c12979b835d', 'Health Canada', '2023-06-22', 2023, '2023-06', 'Canada', 'Canada', '', 'Drugs', 'JAMP Venlafaxine XR 37.5 mg capsules', 'Labelling', 'Other', 'Not Specified', 'Labelling', 'Serious', 0, 0, 'Check the capsules in your pharmacy bottle of JAMP Venlafaxine XR 37.5 mg capsules to make sure it contains 37.5 mg capsules (grey / pink in colour) and not 150 mg capsules (caramel in colour). If you are unsure, contact your pharmacist to check if your bottle contains the correct capsules.If you see incorrect capsules, stop taking the medication and contact your pharmacy immediately for a replacement product. Return the affected product to your pharmacy for&nbsp;proper disposal.Contact your hea', '73865');
