INSERT INTO safety_incidents VALUES ('bd63424fb1b3d00378b0472207b3354751b9743b', 'Health Canada', '2023-06-15', 2023, '2023-06', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'BKIND Brightening Face Serum', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the&nbsp;BKIND Brightening Face Serum,&nbsp;contact the company for a replacement or refund, and then dispose of it.For more information, consumers can contact BKIND Entreprise Inc. by email at hello@bkind.ca. Please note that, in addition to the requirements of the Cosmetic Regulation the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Health Canada', '73778');
INSERT INTO safety_incidents VALUES ('34b36383ded039ec8a057418279e13fd5d9efbf5', 'Health Canada', '2023-06-15', 2023, '2023-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Oceanic Excursion, Hera, and OceanPro QLR4 Weight Pockets', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact&nbsp;Huish Outdoors LLC for replacement QLR4 weight pockets. For more information, consumers can contact Huish Outdoors LLC by telephone at 1-833-493-1029 from 9:00am to 5:00pm MT or by email at service@huishoutdoors.com. Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Huish Outdoors LLC.Please note that the Canada Consumer Product Safety Act prohibits recalled products fr', '73804');
INSERT INTO safety_incidents VALUES ('60c0c9a681fc2ccc9c78e36de811620c3ab21d3e', 'Health Canada', '2023-06-15', 2023, '2023-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Revision 1 of the Promax Solve DSK 925 and Promax F1 DSK 927 Hydraulic Disc Brakes', 'Injury', 'Other', 'Eye Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact an authorized Trek retailer for an inspection and, if warranted, a repair free of charge to the consumer.To determine if a bicycle is affected, consumers can enter their bicycle’s serial number on Trek Bikes website.For more information, consumers can contact Trek Bicycle Canada by telephone toll-free at 1-800-373-4594, Monday through Friday from 8:00 a.m. to 6:00 p.m. CT, or visit their website.Joint recall with Health Can', '73805');
INSERT INTO safety_incidents VALUES ('723cc54eb1a340cc3564b86082cf62cfa98145e9', 'Health Canada', '2023-06-15', 2023, '2023-06', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', '10X Quick Dry Tinted Lace Spray', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and&nbsp;return the product to EBIN New York to receive a refund.For more information, consumers can contact EBIN NEW YORK by email at cs@ebinnewyork.com. Operating hours are between 9am to 6PM EST.Please note that, in addition to the requirements of the Cosmetic Regulation the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary conditions, to users in Canada.Heal', '73806');
