INSERT INTO safety_incidents VALUES ('25b59320a57947017ade5479ee94addd23e9d640', 'Health Canada', '2023-06-02', 2023, '2023-06', 'Canada', 'Canada', '', 'Fresh', 'Fresh cut cubed Butternut Squash', 'Listeria', 'Microbiological Contamination', 'Laceration / Cut', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '73758');
