INSERT INTO safety_incidents VALUES ('133db34ddc929b8abdd0fa0ebef8869e90e07fa3', 'Health Canada', '2023-06-01', 2023, '2023-06', 'Canada', 'Canada', '', 'Tools & Machinery', 'EGO Power+ Cordless Brushless Hedge Trimmers', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled hedge trimmer and contact Chervon North America for a free repair of the rear trigger switch.For more information, consumers can contact Chervon North America by telephone toll free at 1-800-492-0777 from 8:30 a.m. to 8:00 p.m. ET Monday to Friday, 10 a.m. to 6 p.m. ET Saturday and Sunday; by email at HT2410recall@na.chervongroup.com or online at www.egopowerplus.com/recalls or www.egopowerplus.com and click on “PRODUCT RECALLS” at the top of ', '73682');
