INSERT INTO safety_incidents VALUES ('1150bff02254806ccc6aafed250a732d8a91aa98', 'Health Canada', '2023-06-01', 2023, '2023-06', 'Canada', 'Canada', '', 'Natural Health Products', 'Nature’s Bounty Kids Multivitamin Gummies (Disney Princess; Disney/Pixar Cars; Marvel Avengers; Disney Frozen; Disney/Pixar Toy Story; Disney Encanto) (NPN 80117143)', 'Labelling', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Labelling', 'Not Reported', 0, 0, 'Do not give these products to children under the age of four. If you have purchased an affected product for a child under four years old, return the product to your local pharmacy for proper disposal. Contact Nestlé Health Science for a reimbursement or if you have any other questions about the recall by calling, toll-free, 1-800-387-4636, or by emailing&nbsp; consumer.care@ca.nestle.com.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '73741');
