INSERT INTO safety_incidents VALUES ('402c3b573c9572d82c10b404c1d79a070d581e60', 'Health Canada', '2023-05-25', 2023, '2023-05', 'Canada', 'Canada', '', 'Toys & Childcare', 'The Good and the Beautiful Math 1 and Math 3 Boxes with metallic whiteboards', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled whiteboards away from children, discard them and contact The Good and the Beautiful to receive a free non-metallic replacement. Consumers should visit www.goodandbeautiful.com/math-1-quality-reporting/ for the Math 1 Box and www.goodandbeautiful.com/math-3-quality-reporting/ for the Math 3 Box to complete a form with their contact information. The Good and the Beautiful is contacting known consumers directly.For more information, consumers can conta', '73701');
