INSERT INTO safety_incidents VALUES ('d1ef8913ca5712eb9733b30c9326af1762850b12', 'Health Canada', '2023-05-16', 2023, '2023-05', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized products labelled to contain mifepristone and misoprostol (commonly known as the “abortion pill”), and unauthorized emergency contraceptive labelled to contain levonorgestrel (commonly known as the “morning after pill”)', 'Product Safety - Unauthorized Product', 'Other', 'Not Specified', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not buy or use any unauthorized health products from “Dr. Pooja” websites. If you have taken unauthorized products labelled to contain mifepristone and misoprostol from these websites, seek immediate medical attention to receive a proper health assessment and medical care. If you have taken unauthorized products labelled to contain levonorgestrel, speak to your health care professional to receive a proper health assessment and medical care.Return unauthorized drugs to your local pharmacy for ', '73674');
