INSERT INTO safety_incidents VALUES ('db803fd0b212d138241a3a7ca8afaea78231fcbe', 'Health Canada', '2023-05-15', 2023, '2023-05', 'Canada', 'Canada', '', 'Consumer Products', 'SmartBase® Euro Slats Metal Platform Bed Frames – Twin Size', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled metal bed frames and contact Zinus to obtain a free repair kit consisting of reinforcing brackets to be installed on the corners of the base. An appropriate tool and hardware, and both printed and video instructions are available at&nbsp;www.zinus.ca/requestkit. For more information, consumers can contact Zinus by telephone at 800-613-1225 from 8:30 a.m. to 4:30 p.m. PT, Monday through Friday, by email at&nbsp;mesb@zinus.com or visit the compa', '73670');
