INSERT INTO safety_incidents VALUES ('941e87545c6eb44755e1744b06cf23ccb8d454e0', 'Health Canada', '2023-05-12', 2023, '2023-05', 'Canada', 'Canada', '', 'Sports & Leisure', 'Peloton Bike Model PL01 Seat Post', 'Injury', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled exercise bike and contact Peloton for a free repair. Peloton is offering consumers a free seat post that can be self-installed. Starting&nbsp;after May 16, 2023,&nbsp;Peloton can be reached toll-free at&nbsp;(833) 821-0099&nbsp;from 6 a.m. to 12 a.m. ET, 7 days a week or online&nbsp;at&nbsp;www.onepeloton.ca/replacement/checkout.&nbsp;Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, ', '73661');
