INSERT INTO safety_incidents VALUES ('8eeefa2e33e4bab3bc8ce37bd0d951e89262ef61', 'Health Canada', '2023-05-11', 2023, '2023-05', 'Canada', 'Canada', '', 'Other', 'LIVINGbasics®️  Indoor Safety Gate', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled safety gate, dispose of it in such a way that it cannot be used again and contact Shopper+ Inc. for a refund.For more information, consumers can contact Shopper+ Inc. by telephone 1-866-979-7463 between 9am and 5pm Eastern Time Monday to Friday or by email at support@shopperplus.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would', '73640');
