INSERT INTO safety_incidents VALUES ('82c16474ca7bbd5b230ef22c59eb0e264d645b4e', 'Health Canada', '2023-05-11', 2023, '2023-05', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Lithium-ion batteries used in e-mobility devices, such as e-scooters or e-bikes', 'Chemical', 'Electrical Fault', 'Burns', 'Burn hazard - Chemical hazard - Electrical hazard - Fire hazard - Flammability hazard - Injury hazard', 'Not Reported', 0, 0, 'If you currently own an e-mobility device, never attempt to modify, tamper with or build your own lithium-ion batteries.Always use the original lithium-ion batteries that came with your e-bike or e-scooter.Only replace batteries with original parts from the manufacturer.Check to see if your e-mobility device is compliant with the:ANSI/CAN/UL 2272 -- Standard for Electrical Systems for Personal E-Mobility Device; and,ANSI/CAN/UL 2849 -&nbsp;Standard for Safety for Electrical Systems for eBikes.St', '73653');
