INSERT INTO safety_incidents VALUES ('e783fc95aea495b0629e80e194594016fd3f8c1c', 'Health Canada', '2023-05-10', 2023, '2023-05', 'Canada', 'Canada', '', 'Drugs - Cannabis', 'Illegal edible cannabis products', 'Unauthorized Product - Unauthorized Products', 'Other', 'Poisoning / Ingestion', 'Unauthorized product - Unauthorized products', 'Not Reported', 0, 0, 'When purchasing cannabis, purchase only legal and regulated cannabis products in plain packaging with child-resistant features and only from provincially and territorially authorized retailers. Store all cannabis products securely and out of the reach and sight of children, teens, and pets.Who is affectedChildren and young persons are at risk of serious harm if they accidentally ingest cannabis.&nbsp;Signs that a child has ingested cannabis can include:chest painrapid heartbeatnauseavomitingpsyc', '63752');
