INSERT INTO safety_incidents VALUES ('00068f90bb5bfdbbeb7e02fe0cbb36975f7ab33e', 'Health Canada', '2023-04-20', 2023, '2023-04', 'Canada', 'Canada', '', 'Tools & Machinery', 'Stanley FATMAX and DEWALT Fiberglass Sledgehammers', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled sledgehammers&nbsp;and contact Stanley Black &amp; Decker for a refund. To obtain a refund, consumers should register on the firm’s recall website (found below), upload a photo of their hammer with "Recalled" written on the handle with permanent marker, and affirm the hammer will be disposed of. For more information, consumers can contact&nbsp;Stanley Black &amp; Decker&nbsp;by telephone&nbsp;at 1-855-418-3032 or online.Joint recall with Healt', '73305');
INSERT INTO safety_incidents VALUES ('2bc85a99223fad0a5dc79c5a145407610240c7bf', 'Health Canada', '2023-04-20', 2023, '2023-04', 'Canada', 'Canada', '', 'Toys & Childcare', 'Kid Casters Children’s Fishing Rod', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled fishing rods and contact Lil Anglers to arrange for return of the product and a refund or replacement.For more information, consumers can contact Lil Angers by telephone toll-free at 1-844-347-4543 from 8:00 a.m. to 4:30 p.m. CST Monday through Friday, by email,&nbsp;or visit the Kid Casters and Profishiency&nbsp;websites.Joint recall with Health Canada, the United States Consumer Product Safety Commission&nbsp;(US CPSC) and Lil Anglers LLC.Pl', '73534');
