INSERT INTO safety_incidents VALUES ('cdcb6d59b62cacd1cd7afe7a9edb1a49ac5698a3', 'Health Canada', '2023-04-18', 2023, '2023-04', 'Canada', 'Canada', '', 'Cannabis', 'Harts Charlottes Angel dried cannabis pre-rolls, Lot B22058PR', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should verify whether their product is affected. If you wish to return affected product, please contact the retail store where the product was purchased.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '73526');
