INSERT INTO safety_incidents VALUES ('3362b28c3b77f7142b4ff9194ead5a7a9f8f11f0', 'Health Canada', '2023-04-17', 2023, '2023-04', 'Canada', 'Canada', '', 'Other', 'BabyTeddy 7 in 1 Convertible Baby Crib Wooden Baby Cot', 'Chemical', 'Entrapment', 'Entrapment', 'Chemical hazard - Entrapment hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers who have this affected crib should immediately stop using it and safely dispose of the item in such a way that it cannot be used again. Consumers should find an alternative safe sleeping environment for their infant.Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or', '73504');
INSERT INTO safety_incidents VALUES ('969b8643a53baa70aa20e664c6d1b136e3f9d9aa', 'Health Canada', '2023-04-17', 2023, '2023-04', 'Canada', 'Canada', '', 'Drugs', 'Test kits designed to detect illegal drugs', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Use every precaution, even if you or your friends use fentanyl or xylazine test strips:Never consume alone.Consider consuming a smaller dose: start low and go slow.Don''t mix opioids with alcohol or other drugs.Go to a&nbsp;supervised consumption site&nbsp;if your community has one.Carrynaloxone, which can temporarily reverse an opioid overdose. Make sure that you, and the people with you, know how to administer it.Call 9-1-1 or your local emergency help line if you think someone is having a drug', '73521');
