INSERT INTO safety_incidents VALUES ('a6f56a6844e62b080da765778a67d12933b973d7', 'Health Canada', '2023-04-03', 2023, '2023-04', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health product labelled to contain a prescription drug', 'Product Safety', 'Other', 'Eye Injury', 'Product safety', 'Not Reported', 0, 0, 'Do not use this product. Return the product to your local pharmacy for proper disposal.Consult a health care professional if you have used this product and have health concerns.Buy your prescription drugs only from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check ', '72930');
INSERT INTO safety_incidents VALUES ('771333322f7c6123d53c506427935b6e659b177d', 'Health Canada', '2023-04-03', 2023, '2023-04', 'Canada', 'Canada', '', 'Jewellery', 'Great Pretenders Easter Bunny Necklace', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled jewellery away from children and return it to the place of purchase for a&nbsp;full refund.For more information, consumers can contact Creative Education of Canada Inc by telephone toll-free at 1-800-982-2642 or by email.&nbsp;&nbsp;&nbsp; Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or ', '73423');
INSERT INTO safety_incidents VALUES ('eddb949cd346aa4ac033f712f3ed7f037551bf9c', 'Health Canada', '2023-04-03', 2023, '2023-04', 'Canada', 'Canada', '', 'Household Items', 'Sunter Rechargeable LED Vanity Mirror', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately remove the lithium-ion battery from the affected product.&nbsp; Once the battery is removed, consumers may continue to use the mirror with the AC power adaptor and charging cable supplied at the time of purchase and contact Blackstone International Ltd. to obtain a free replacement battery.For more information, consumers can contact Blackstone International Ltd. by telephone toll-free at 1-800-485-4286, Monday to Friday from 8:00 a.m. to 7:00 p.m. (EST), by email&nbs', '73424');
INSERT INTO safety_incidents VALUES ('3fc32815db9a2b252ab4a66e624326351a1ae1e8', 'Health Canada', '2023-04-03', 2023, '2023-04', 'Canada', 'Canada', '', 'Toys & Childcare', 'MAG-N-5-SPHERE - set of gray color rare earth sphere magnets packaged in an industrial plastic bag.', 'Injury', 'Other', 'Poisoning / Ingestion', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled magnet set away from children and return them&nbsp;for refund.For more information, consumers can contact ABRA Electronics Corp. telephone at 1-800-361-5237 from 8:30am – 4:30pm EST, Monday through Friday, by email at sales@abra-electronics.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any healt', '73425');
