INSERT INTO safety_incidents VALUES ('708e067e6d621092182e4c6562bd1a4f336087d5', 'Health Canada', '2023-04-01', 2023, '2023-04', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', '60% Dark Chocolate with Hazelnuts', 'Milk', 'Allergen', 'Not Specified', 'Milk', 'Serious', 0, 0, 'Check to see if you have recalled products.Do not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reaction.Do not serve, use, sell or distribute recalled products.Recalled products should be thrown out or returned to the location where they were purchased.Learn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigat', '73106');
