INSERT INTO safety_incidents VALUES ('529666caf79b7fded25a2683635ed66eb7f0728c', 'Health Canada', '2023-03-31', 2023, '2023-03', 'Canada', 'Canada', '', 'Other', 'The Laundress fabric conditioners.', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled&nbsp;fabric conditioners and contact The Laundress for reimbursement.Consumers who have previously requested a refund for these products in response to The Laundress’ December 2022 recall and reimbursement program should not submit a new request. Consumers who purchased the recalled products on or after January 2021 can request a refund using either a photo of the lot code with their initials and the date written in marker or a receipt, or if ', '73415');
