INSERT INTO safety_incidents VALUES ('fb85d293191210fcc4e90ba26b133c805713680b', 'Health Canada', '2023-03-31', 2023, '2023-03', 'Canada', 'Canada', '', 'Household Items', 'YANRU Baby Walkers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have these baby walkers should immediately stop using them and safely dispose of the baby walkers in such a way that they cannot be used again. Removing wheels from a baby walker does not make it a stationary activity center. Baby walkers should be destroyed and thrown away.Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any hea', '73422');
