INSERT INTO safety_incidents VALUES ('3c8e4ca25368d6a8f23787a62d63718f9efcaf76', 'Health Canada', '2023-03-30', 2023, '2023-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Battery Packs within Higdon Outdoors XS Series Motion Waterfowl Decoys and XS Replacement Battery', 'Fire', 'Drowning Risk', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Higdon Outdoors LLC to coordinate the return of the affected battery packs for a replacement battery pack.For more information, consumers can contact Higdon Outdoors LLC by telephone at 1-800-962-0656 Monday through Friday from 9 a.m. to 5 p.m. ET, by email at recall@higdonoutdoors.com&nbsp;or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Higdon', '73401');
INSERT INTO safety_incidents VALUES ('b70180000803400a947bdc61932e102d3cbc3672', 'Health Canada', '2023-03-30', 2023, '2023-03', 'Canada', 'Canada', '', 'Condiments', 'Seasoned Hot Pepper Sauce', 'Clostridium Botulinum', 'Microbiological Contamination', 'Not Specified', 'Clostridium botulinum', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with&nbsp;Clostridium botulinum&nbsp;toxin may not look or smell spoiled but can still make you sick. Symptoms in adults can include facial paralysis or loss of facial expression, unreact', '73402');
INSERT INTO safety_incidents VALUES ('6dd1b08343fe2da185f20f6bcf82e1ee056aa2cb', 'Health Canada', '2023-03-30', 2023, '2023-03', 'Canada', 'Canada', '', 'Cannabis', 'Original Fraser Valley Weed Co. B.C. Sour Kush dried cannabis, lots 03984 and 03985', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should verify whether their product is affected. If you wish to return affected product, please contact the retail store where the product was purchased. For additional information about the recall, consumers can contact the Original Fraser Valley Weed Co. at hello@fraservalleyweedco.com or 1-888-207-4360.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the onl', '73406');
