INSERT INTO safety_incidents VALUES ('5b52ee7943f770ba64700fcc26fcd9c27a7ea233', 'Health Canada', '2023-03-29', 2023, '2023-03', 'Canada', 'Canada', '', 'Household Items', 'Various Change Table Accessories for Harmony Play & Go Playards', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately detach and discard the change table straps and stop using the instructions for the change table. Consumers should contact Harmony to obtain updated change table instructions. Once the updated change table instructions have been reviewed, consumers may continue to use Harmony Play &amp; Go Playard change table in accordance with the updated instructions.For updated instructions, additional information or to schedule a call with Harmony, consumers may contact Harmony J', '73397');
