INSERT INTO safety_incidents VALUES ('a304602e527b282b7c39236b45aed34717407b64', 'Health Canada', '2023-03-16', 2023, '2023-03', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products labelled to contain a prescription drug', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Do not use these products. Return the product to your local pharmacy for proper disposal.Consult a health care professional if you or your child have used either of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (', '73331');
