INSERT INTO safety_incidents VALUES ('d5a9b1e5d5a65f36d89843605bcaa52140888c1c', 'Health Canada', '2023-03-09', 2023, '2023-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Hopper® M20 Soft Backpack Cooler, Hopper® M30 Soft Cooler, SideKick Dry® Gear Case', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact YETI Canada to coordinate the return of the product for a suggested replacement product of equal or greater value or a gift card. For more information, consumers can contact YETI by telephone at 1-833-444-3151 Monday through Sunday from 7 a.m. to 7 p.m. CT; email at: productrecall@yeti.com or online at www.yeti.ca and click on “Product Recall” at the bottom of the page for more information.&nbsp; Joint recall with Health Ca', '73105');
