INSERT INTO safety_incidents VALUES ('e08cc78edee5461974d404bdb6d9ef975cfeb7ff', 'Health Canada', '2023-03-01', 2023, '2023-03', 'Canada', 'Canada', '', 'Other', 'Child Secure Seatbelt Vest and Toddler Child Car Booster Seat', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers who have these affected products should immediately stop using them and safely dispose of the items in such a way that they cannot be used again. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada would like to remind consumers to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Pr', '73021');
INSERT INTO safety_incidents VALUES ('cd9398323246d4fd87bfbac58c8bbb949f2ec388', 'Health Canada', '2023-03-01', 2023, '2023-03', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health product labelled to contain a prescription drug', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Do not use these products. Return the product to your local pharmacy for proper disposal.Consult a health care professional if you have used any of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can ', '73060');
