INSERT INTO safety_incidents VALUES ('c50d2b20a12706c49872863f5f80168a5cf3ca26', 'Health Canada', '2023-02-23', 2023, '2023-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Certain models of Cosori-branded Air Fryers', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and request a free replacement unit by registering online at www.recall.cosori.com or contacting the toll-free recall hotline at 1-888-216-5974 Monday – Friday, 8:00AM – 5:00PM ET. No receipt is needed to receive a replacement unit. Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC), PROFECO and Etekcity Corporation.Please note that the Canada Consumer Product Safety Act prohibits recalled p', '72618');
INSERT INTO safety_incidents VALUES ('9ccf8e2b30df7aeeac58ac35210a2c7d28450853', 'Health Canada', '2023-02-23', 2023, '2023-02', 'Canada', 'Canada', '', 'Specialized Products', 'Lancaster Table & Seating Brand High Chairs', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled high chairs and contact Clark Associates for a replacement high chair or store credit.For more information, consumers can contact Clark Associates by telephone at 1-800-285-8172 from 9 a.m. to 5 p.m. ET Monday through Friday, by email at highchairs@lancastertableandseating.com, or online.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Clark Core Services, LLC, d/b/a Clark Associates&nbsp; Ple', '72725');
INSERT INTO safety_incidents VALUES ('5cc4773f2db332c915954526b4a6f23d55fe6725', 'Health Canada', '2023-02-23', 2023, '2023-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'SCARPA F1 LT and F1 GT ski boots', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact SCARPA for instructions on replacing the screws.&nbsp; Consumers can either take the recalled ski boots to an authorized SCARPA dealer to have the screws replaced at no cost or request SCARPA to send the free screws for self-replacement.&nbsp;A video demonstrating the repair is available at https://us.scarpa.com/community/support/contact-scarpas-recall-team.For more information, consumers can contact SCARPA by telephone tol', '72727');
INSERT INTO safety_incidents VALUES ('a7f0fcb638d954d93c28d5deed2c9f2e95ba45d6', 'Health Canada', '2023-02-23', 2023, '2023-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'XDEEP NX700 scuba regulator', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled NX700 scuba regulators and return for a full refund.For more information, consumers can contact XDEEP by telephone at&nbsp;1&nbsp;201&nbsp;710 0042 (US regional distributor), +48 12 44 66 998 (EU manufacturer), by email at support@xdeep.eu or visit the company website. Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and XDEEP.Please note that the Canada Consumer Product Safety Act prohibits recal', '72901');
INSERT INTO safety_incidents VALUES ('3065a999bfab3b71f7cc92890def6c3e4d8356fd', 'Health Canada', '2023-02-23', 2023, '2023-02', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Anker 535 Power Bank (PowerCore 20k) A1366', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Anker 535 Power Bank and contact Anker customer support for a refund.For more information, consumers can visit the company website&nbsp;or contact Anker by telephone at 1 800-988-7973 Monday to Friday between 7 am and 5 pm PST, by email at support@anker.com or by live chat on the company website from Monday to Friday between 9 a.m. and 5 p.m. PT.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redi', '72904');
