INSERT INTO safety_incidents VALUES ('9e9735aa04b3a4d3ab0e6a166ad849b04857387a', 'Health Canada', '2023-02-17', 2023, '2023-02', 'Canada', 'Canada', '', 'Drugs', 'Kirkland Signature Extra Strength Acetaminophen Tablets 500 mg', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '72690');
INSERT INTO safety_incidents VALUES ('ae538f66b050734893175bb6ea5a1ba3c3cefe2b', 'Health Canada', '2023-02-17', 2023, '2023-02', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health product labelled to contain a prescription drug', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Do not use this product. Return the product to your local pharmacy for proper disposal.Consult a health care professional if you have used this product and have health concerns.Buy your prescription drugs only from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check ', '72816');
INSERT INTO safety_incidents VALUES ('aa5dc20e466c0ccba4bd6872ec239c59de8d34d5', 'Health Canada', '2023-02-17', 2023, '2023-02', 'Canada', 'Canada', '', 'Chemicals', 'Dr. Crafty branded epoxy kits – various sizes', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the epoxy kits and dispose of them according to local municipal hazardous waste requirements. Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada reminds Canadians to report any health or safety incidents related to the use of these products or any other consumer product or cosmetic by filling out the Consumer Product Incident Report Form. Related', '72817');
