INSERT INTO safety_incidents VALUES ('b52fe679b00fee16dc022b4eda761104f0e4b06c', 'Health Canada', '2023-02-10', 2023, '2023-02', 'Canada', 'Canada', '', 'Drugs - Natural Health Products', 'Various unauthorized health products promoted for sexual enhancement, weight loss, as a workout aid, as "poppers", or for lightening skin or treating skin conditions (such as eczema or psoriasis).', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Not Reported', 0, 0, 'Stop using the products listed in the table. Consult your health care professional if you have used these products and have health concerns, and for advice on which health products are best for you and your family.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check if products have been', '78101');
INSERT INTO safety_incidents VALUES ('8a4691b753a8b44bf5f7626c4b8dc52acb3684ba', 'Health Canada', '2023-02-09', 2023, '2023-02', 'Canada', 'Canada', '', 'Toys & Childcare', 'Raindrop Toy Component that is sold with the Skip Hop Silver Lining Activity Gym', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately remove the raindrops from the Raindrop Toy Component by cutting them off or destroying the Raindrop Toy Component.&nbsp; Consumers can submit a photograph of the modified or destroyed toy to Skip Hop through www.skiphoprecall.com for a $10 gift card.&nbsp; Consumers can contact Skip Hop toll free by calling 1-800-692-4674 from 9:00 a.m. to 5:30 p.m. ET Monday through Friday or online at www.skiphop.com and click on Product Recalls at the bottom of the page or visit w', '72564');
INSERT INTO safety_incidents VALUES ('9dea660b0553ab9e0b5d058fc5c427a8af3417c7', 'Health Canada', '2023-02-09', 2023, '2023-02', 'Canada', 'Canada', '', 'Sports & Leisure', 'Ovation Protégé Equestrian Helmet', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to the retailer they were purchased from or to any Ovation authorized dealer for a free replacement Ovation Deluxe Schooler helmet or contact English Riding Supply for a $60 (USD) refund.For more information, consumers can contact English Riding Supply by telephone at 1-866-569-1600 from 8:30 a.m. to 5:00 p.m. ET Monday through Friday, by email at helmets@englishridingsupply.com or visit the company website:&nbsp;www.e', '72642');
INSERT INTO safety_incidents VALUES ('949f03ac2741f473e6dd982763a4835a912a8837', 'Health Canada', '2023-02-09', 2023, '2023-02', 'Canada', 'Canada', '', 'Other', 'LiftMaster myQ 889LM and 041A7928-3 garage door control panels that are sold as an individual accessory and/or packed-in with wall-mount residential jackshaft openers', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'The impacted control panels can still be used so long as the operator uses the wireless keypad in accordance with the Owner’s Manual and does not press “ENTER” more than once on the keypad. Consumers should contact Chamberlain Group to receive a replacement control panel. Chamberlain Group will offer the repair as a kit with instructions that consumers can be completed by the consumer or a professional installer.For more information, consumers can contact The Chamberlain Group Canada Co. toll-fr', '72666');
