INSERT INTO safety_incidents VALUES ('4d3820cb592311f1ac310848784084e84dc91d09', 'Health Canada', '2023-02-08', 2023, '2023-02', 'Canada', 'Canada', '', 'Chemicals', 'Fabuloso Multi-Purpose Cleaner - Lavender Scent, 1.65L', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Fabuloso Multi-Purpose Cleaner - Lavender Scent, 1.65L. Consumers should take pictures of the UPC code/lot code in order to contact Colgate–Palmolive for a full refund of the purchase price (with receipt) or of the manufacturer’s recommended retail price (without receipt) or for a coupon for a free replacement bottle. After requesting a refund, consumers should dispose of the product safely according to local municipal waste requirements.For m', '72665');
INSERT INTO safety_incidents VALUES ('492de4b80fb23e0dac2903782b7f9bfbc2bb0403', 'Health Canada', '2023-02-08', 2023, '2023-02', 'Canada', 'Canada', '', 'Cannabis', 'Spinach GMO Cookies pre-rolled joints dried cannabis, Lots 008406 and 008397', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should verify whether their product is affected. If you wish to return affected product, please contact the retail store where the product was purchased.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '72671');
INSERT INTO safety_incidents VALUES ('e8046e985f4ef732865460879459d953c332b454', 'Health Canada', '2023-02-08', 2023, '2023-02', 'Canada', 'Canada', '', 'Household Items', 'Ove Decors Vanessa 42-inch Fire Table', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled fire table, make sure the gas tank is OFF, and contact Ove Decors for a free repair kit, including shipping. Consumers will receive a spring hook to keep the hose away from the heat shield and a warning label. For more information, consumers can contact Ove Decors by telephone at 1 (866) 839-2888 between Monday and Friday, 8am to 5pm EDT (UTC -4 hours), by email at customerservice@ovedecors.com or visit the company website.Please note that the', '72673');
INSERT INTO safety_incidents VALUES ('716208fa13aa9a361ed789a5b6fa6112fc3928d1', 'Health Canada', '2023-02-07', 2023, '2023-02', 'Canada', 'Canada', '', 'Drugs', 'Amitriptyline 10 mg tablets (Updated 2023-02-07 to add one recalled lot of APO-Amitriptyline)', 'Contamination', 'Other', 'Not Specified', 'Contamination - Product safety', 'Not Reported', 0, 0, 'Patients can continue to take their medication as prescribed by their health care provider as there is no immediate risk in continuing to take the recalled medication. Stopping amitriptyline may lead to mild withdrawal symptoms.Contact your health care provider if you have taken a recalled product and you have concerns about your health. Ask your pharmacist if you are unsure whether you are taking a recalled product.Contact the company if you have questions about the recall:Apotex Inc. via Sedgw', '62345');
