INSERT INTO safety_incidents VALUES ('11d059e273a6030435406686b5f71c636dbbd771', 'Health Canada', '2023-02-03', 2023, '2023-02', 'Canada', 'Canada', '', 'Food & Food Contact', 'Meatball products', 'Egg - Gluten - Milk - Wheat', 'Allergen', 'Not Specified', 'Egg - Gluten - Milk - Wheat', 'Serious', 0, 0, 'Check to see if you have recalled products Do not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reaction If you have celiac disease or other gluten-related disorders, do not consume the recalled products as they may cause a serious or life-threatening reaction Do not serve, use, sell or distribute recalled products Recalled products should be thrown out or returned to the location where they were purchasedLearn more: Learn more a', '72648');
INSERT INTO safety_incidents VALUES ('b59419c54c263db99fe8bc54598d898c717409c2', 'Health Canada', '2023-02-03', 2023, '2023-02', 'Canada', 'Canada', '', 'Medical Devices', 'Intraocular lenses when used to replace a patient’s natural lens of the eye are only licensed in Canada to treat cataracts. They are not licensed to replace lenses in patients without cataracts, and come with risks.', 'Product Safety', 'Other', 'Eye Injury', 'Product safety', 'Not Reported', 0, 0, '', '72649');
INSERT INTO safety_incidents VALUES ('91145debda94f8329cb157488dd1e134a8a20de2', 'Health Canada', '2023-02-02', 2023, '2023-02', 'Canada', 'Canada', '', 'Natural Health Products', 'Fiber Plus Powder', 'Contamination', 'Other', 'Not Specified', 'Contamination - Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '72647');
