INSERT INTO safety_incidents VALUES ('20170560c6d824507bfc89e70fc4455491d2d24e', 'Health Canada', '2023-02-01', 2023, '2023-02', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Helly Hansen sweaters and hoodies', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Helly Hansen sweaters and hoodies, and then contact the company for a credit note. For more information, consumers can contact Helly Hansen by telephone toll-free at 1-888-889-9096 from 7:00 a.m. to 4:30 p.m. PST Monday through Friday. Support is available in English and French. Consumers may also reach Helly Hansen by email at&nbsp;highpri.support.na@hellyhansen.com&nbsp;or visit the company website.Please note that the Canada Consumer Produc', '72628');
