INSERT INTO safety_incidents VALUES ('0d8ed7bf2b0b23be6df8850e4fb9f04909f263ef', 'Health Canada', '2023-01-31', 2023, '2023-01', 'Canada', 'Canada', '', 'Kitchenware And Tableware', 'Various Indigo-branded Ceramic Mugs, Mug Ornaments, and Houseware Products', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return the products to an Indigo store for a full refund.For more information, consumers may contact Indigo by telephone toll-free at 1-833-463-4461 from Monday to Friday between 8:00 am to 9pm Est., and Saturday to Sunday between 10 am to 6 pm&nbsp;EST by email at service@indigo.ca or visit the company website Indigo Online.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistribute', '72626');
INSERT INTO safety_incidents VALUES ('0dacc8141a031f44a6e708e520989af1ea3bc5a7', 'Health Canada', '2023-01-31', 2023, '2023-01', 'Canada', 'Canada', '', 'Cannabis', 'Spinach Feelz Tropical Diesel CBG (Chill Bliss) infused pre-rolls cannabis extract, Lot 008399', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'No action is required by consumers. If, however, you wish to return affected product, please contact the retail store where the product was purchased.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '72629');
