INSERT INTO safety_incidents VALUES ('e8ee269a1bcb5f729d24d6eeaeb62b40b0acf2a7', 'Health Canada', '2023-01-20', 2023, '2023-01', 'Canada', 'Canada', '', 'Drugs', 'Various unauthorized health products labelled to contain prescription drugs', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Do not use these products. Return the product to your local pharmacy for proper disposal.Consult a health care professional if you have used any of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can ', '72597');
