INSERT INTO safety_incidents VALUES ('a669e418340e369c6f9a5b0867b430028cd01957', 'Health Canada', '2023-01-12', 2023, '2023-01', 'Canada', 'Canada', '', 'Household Items', 'BISSELL® Cordless Multi-Surface Wet Dry Vacuum, Model 2551', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact BISSELL to obtain a free battery pack replacement. Consumers can&nbsp;schedule a free in-home repair visit from an authorized BISSELL service technician to replace the existing battery pack.For more information, consumers can contact BISSELL toll-free at 1-855-739-1702 from 9 a.m. to 7 p.m. ET Monday through Saturday, or by visiting the company website&nbsp;for more information about a free battery pack replacement.Joint re', '72560');
INSERT INTO safety_incidents VALUES ('012a89f344abdeb5906c04ddce55e930e7f26777', 'Health Canada', '2023-01-12', 2023, '2023-01', 'Canada', 'Canada', '', 'Household Items', 'Certain LG 86-inch Smart TVs and associated support stands', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and detach the TV from the support stand. Consumers should then place the television face down on a soft cloth or blanket in a safe location away from children. Contact LG Electronics for instructions on how to inspect the unit and to obtain replacement screws and stand parts, including help from a technician for a free repair. Consumers whose TVs are wall-mounted do not need to stop using them.For more information, consumers can conta', '72561');
INSERT INTO safety_incidents VALUES ('6c6a7ba58d07197c00023778dafe588151704e7c', 'Health Canada', '2023-01-12', 2023, '2023-01', 'Canada', 'Canada', '', 'Sports & Leisure', 'Salewa Alp Trainer 2 Mid GTX hiking boots', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled hiking boots and contact Salewa for instructions to obtain a replacement.For more information, consumers can contact Salewa toll-free by telephone at 1-844-412-7013 from 9:00 a.m. to 5:00 p.m. Monday to Friday CST, by email at AlpTrainer2@salewa.com or visit the company''s website&nbsp;and click on "Alp Trainer 2 Mid GTX Voluntary Recall".Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistribute', '72562');
INSERT INTO safety_incidents VALUES ('d6c6aa411b4cdc5ee64c1fd4c6513e96f3b7b5ef', 'Health Canada', '2023-01-12', 2023, '2023-01', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Giant Tiger brands sleepwear (monkey bars, Bella & Birdie, Mountain Ridge, Survival Gear), Men’s Sherpa Robes, Pajar Ski Pants and Men’s Ski Pants', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled sleepwear, robes and ski pants and return to Giant Tiger store for refund.For more information, consumers can contact Giant Tiger Customer Service via https://www.gianttiger.com/pages/contact-us.&nbsp;Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the u', '72563');
