INSERT INTO safety_incidents VALUES ('b2b37829c0b5d80dcec6714600c631ff21a93405', 'Health Canada', '2023-01-05', 2023, '2023-01', 'Canada', 'Canada', '', 'Sports & Leisure', 'Whiskey Parts Co. No.9 12F and No.9 24F carbon handlebars, Salsa Cowchipper and Salsa Cowbell carbon handlebars, and select Salsa Bicycles that came equipped with the Salsa Cowchipper or Salsa Cowbell carbon handlebars.', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact their local retailer for a free installation of a replacement carbon handlebar or an alternative aluminum handlebar. For more information, consumers can contact Quality Bicycle Products by telephone at 1-800-346-3340 from 9 a.m. to 6 p.m. CT, Monday through Friday, by email at recall@qbp.com&nbsp;or online at https://www.salsacycles.com/support/recalls/cowbell-cowchipper-carbon-handlebar-recall and https://whiskyparts.co/n', '72418');
INSERT INTO safety_incidents VALUES ('04fe96c8666c558c6255212109f499eeb3ade306', 'Health Canada', '2023-01-05', 2023, '2023-01', 'Canada', 'Canada', '', 'Other', 'Mombella Mini Mushroom Soothing Teether', 'Injury', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled pacifiers and dispose of the product.For more information, consumers can contact Leda Health by email at info@ledahealth.ca, Monday to Friday from 9 a.m. to 5 p.m. EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other c', '72527');
