INSERT INTO safety_incidents VALUES ('2900dac1b8f25772a384c8f2179c3c4fb1a80741', 'Health Canada', '2022-12-28', 2022, '2022-12', 'Canada', 'Canada', '', 'Sports & Leisure', 'KLIM Backcountry Probe A300', 'Injury', 'Mechanical Failure', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled probes. For more information, consumers can contact KLIM by email at orders@KLIM.com with subject line “A300 Probe Recall” for a full refund.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic', '72417');
