INSERT INTO safety_incidents VALUES ('55a6fd3b952dd70ce4959259e17de87e81f07d9a', 'Health Canada', '2022-12-22', 2022, '2022-12', 'Canada', 'Canada', '', 'Household Items', 'Various Bassinets and Change Tables for Harmony Play & Go Playards recalled due to potential suffocation and entrapment hazards', 'Entrapment Hazard - Physical Hazard', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Entrapment hazard - Physical hazard', 'Not Reported', 0, 0, 'Bassinet: Consumers should not use the bassinet of the Harmony Play &amp; Go Playard without the accompanying bassinet structural support bars in place. Consumers should contact Harmony to receive a free kit to eliminate the possibility of removing the bassinet structural support bars.Change Table: Consumers should immediately detach and discard the change table straps and stop using the instructions for the change table. Consumers should contact Harmony to obtain updated change table instructio', '72202');
INSERT INTO safety_incidents VALUES ('440ad026e488cf5a8c4cb521437f95b5e4baffcf', 'Health Canada', '2022-12-22', 2022, '2022-12', 'Canada', 'Canada', '', 'Sports & Leisure', 'BLU3 Nomad Battery-Powered Tankless Diving Systems', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Nomad battery-powered tankless diving systems and contact BLU3 to schedule a free repair at an approved service center.&nbsp; For more information, consumers can contact BLU3 Inc. by submitting the form online at www.diveblu3.com/recall or by telephone at 1-833-703-5796 from 9:00 a.m. to 5:00 p.m. ET Monday through Friday. Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and BLU3.Please note that ', '72370');
