INSERT INTO safety_incidents VALUES ('1bc56936bd7ef4a0b15b7fdc10da5c527c56d3ea', 'Health Canada', '2022-12-15', 2022, '2022-12', 'Canada', 'Canada', '', 'Specialized Products', 'Sundance® Spas and Jacuzzi® Hot Tubs', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should use an accurate external thermometer to confirm the water temperature prior to entering the hot tub until the hot tub is confirmed not to have the affected temperature sensor. For hot tubs with the affected temperature sensor, consumers should contact an authorized dealer to schedule a free repair to replace the sensor.For more information, consumers can contact Sundance Spas/Jacuzzi Hot Tubs toll-free at 1-800-549-1502 from 7 a.m to 4 p.m., PT, Monday through Friday, by email a', '72206');
