INSERT INTO safety_incidents VALUES ('1674c0a476e05b8cd37dd84e48c0916f15a91c51', 'Health Canada', '2022-12-08', 2022, '2022-12', 'Canada', 'Canada', '', 'Other', 'Scotch™ Thermal Laminator TL1302', 'Consumer Products', 'Flammability / Overheating', 'Not Specified', 'Consumer products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, unplug the device and contact 3M for reimbursement.&nbsp; Consumers should visit&nbsp;https://www.scotchbrand.com/3m/en_ca/scotch-brand-ca/tl1302-laminator-recall/&nbsp;and fill out the recall registration form.&nbsp; 3M will email the consumer directly and request the consumer send in one image that includes: (1) the cut cord from the impacted laminator; and (2) the laminator serial number found on the sticker on the bottom of the la', '72184');
