INSERT INTO safety_incidents VALUES ('072f11110ae7b38cfde012c06d61fb7499b68576', 'Health Canada', '2022-12-02', 2022, '2022-12', 'Canada', 'Canada', '', 'Other', 'Lamaze Chill Teether', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled teether and contact TOMY International, Inc. to initiate a replacement request. For more information, consumers can contact TOMY International, Inc. by telephone at 1-866-725-4407 from 8:00 a.m. and 4:00 p.m. CT Monday through Friday or visit the company website at http://recall.tomy.com. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada', '72306');
