INSERT INTO safety_incidents VALUES ('acb84b10d3530e5fa06e5356cd0e2889ac2ac0ff', 'Health Canada', '2022-12-01', 2022, '2022-12', 'Canada', 'Canada', '', 'Toys & Childcare', 'Discovery Cubes Animal Hide and Seek activity toy', 'Choking', 'Small Parts / Choking Hazard', 'Poisoning / Ingestion', 'Choking hazard - Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled toy, cut the toy in half with a pair of scissors, take a photo of it, and discard it in the household trash. Contact HABA&nbsp;to receive a $30 refund or gift card. Email a photo documenting that the toy has been destroyed, along with your contact information to recall@habausa.com to receive the refund.For more information, consumers can contact HABA USA by calling 1-888-430-0060 from 8:00 a.m. to 5:00 p.m. ET, Monday through Friday, by email ', '72237');
