INSERT INTO safety_incidents VALUES ('94b28aebc8cf677b2310c68886ace29b56effe2a', 'Health Canada', '2022-12-01', 2022, '2022-12', 'Canada', 'Canada', '', 'Household Items', 'H for Happy™ 50- Count LED Basic Christmas String Lights in White', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled decorative lighting strings and return it to any Bed Bath &amp; Beyond location for a refund.For more information, consumers can contact Bed Bath &amp; Beyond by telephone 800-462-3966 Monday- Sunday 7:00am-12am ET, by email at productrecalls@bedbath.com or visit the company website: www.bedbathandbeyond.com.&nbsp; Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given a', '72297');
INSERT INTO safety_incidents VALUES ('8421b5d8ac47ee98328f4c4083c59ef9bb9a726a', 'Health Canada', '2022-12-01', 2022, '2022-12', 'Canada', 'Canada', '', 'Household Items', 'Cuisinart Compact Blender & Juice Extractor Combo', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the blender part of the recalled product and contact Conair for a free replacement blade assembly. The consumer will receive instructions on how to install the replacement blade assembly after discarding the existing blade assembly and after verifying disposal of the existing blade assembly. The juice extractor is unaffected and may continue to be used.For more information, consumers can contact Conair Consumer Products ULC at 1-866-729-2389 Monday to Frid', '72298');
INSERT INTO safety_incidents VALUES ('10e2e2ef40e083e69db81e5b370ef582d6b893ac', 'Health Canada', '2022-12-01', 2022, '2022-12', 'Canada', 'Canada', '', 'Other', 'Draw-Tite 1 7/8” Chrome Hitch Ball', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Draw Tite 1 7/8” Chrome Hitch Ball that are incompatible with their vehicle and contact their Subaru dealership for a replacement.For more information, consumers can contact their local Subaru dealer or Subaru Canada Inc. toll free at 1-800-894-4212 from 8:30 am to 5:00pm ET Monday to Friday or online.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.', '72301');
INSERT INTO safety_incidents VALUES ('76356b69daac21d6c82693b42caabc4d0288af85', 'Health Canada', '2022-12-01', 2022, '2022-12', 'Canada', 'Canada', '', 'Chemicals', 'Certain lots of The Laundress brand laundry detergent, fabric conditioner and household cleaning products.', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact The Laundress for reimbursement.To learn more about how to request a refund or replacement, go to www.TheLaundressRecall.com. After requesting a refund, consumers should dispose of the product by closing the bottle tightly and placing it in household trash. Do not empty the product prior to disposal.&nbsp; For any further questions, call The Laundress at (800) 681-1915, Monday through Friday, 9 a.m. to 5 p.m. EST, or online', '72303');
INSERT INTO safety_incidents VALUES ('9f61433f752bab5e75710317d79b3ddba67f83d8', 'Health Canada', '2022-12-01', 2022, '2022-12', 'Canada', 'Canada', '', 'Chemicals', 'Anti-fog reactivator for swimming goggles by Nabaiji', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the anti-fog reactivator marker for swimming googles by Nabaiji and contact the nearest point of sale to obtain a refund.For more information, consumers can contact Decathlon Canada Inc. by telephone at 1-844-533-3322, Monday to Friday 10am to 6pm EST, by email at onlineservice@decathlon.ca&nbsp;or visit the company''s website (Décathlon - Product Recalls (decathlon.ca)).Please note that the Canada Consumer Product Safety Act prohibits recalled products fro', '72304');
