INSERT INTO safety_incidents VALUES ('7736cf603d478584f2bbcf6139bfc34b8f75b45b', 'Health Canada', '2022-11-23', 2022, '2022-11', 'Canada', 'Canada', '', 'Other', 'Nûby 3-Pack Ring Chill kool Soother Teether', 'Microbial Hazard', 'Radiation', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled teethers and contact Elfe Juvenile Products and register on their web page https://www.elfe.com/en/safety-advisories for a free replacement teether.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or c', '72223');
