INSERT INTO safety_incidents VALUES ('557ed3a41b1a69dc14d9d71b30e767b5e2b5ac32', 'Health Canada', '2022-11-15', 2022, '2022-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Swift Industries 9” Black Rubber Straps', 'Injury', 'Entrapment', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Swift straps, discard them and contact Swift Industries for a free replacement strap. For more information, consumers can contact Swift Industries at 1-206-397-8638 between 8:30am to 4:30pm PST Monday through Friday, by email at recall@builtbyswift.com or online at https://builtbyswift.com/voluntary-recall. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in C', '72185');
INSERT INTO safety_incidents VALUES ('b96738c11a20f10ab6242e4cd4fbdb3cb489e971', 'Health Canada', '2022-11-15', 2022, '2022-11', 'Canada', 'Canada', '', 'Biologic Or Vaccine', 'Allergenic Extract Non Pollens', 'Product Quality', 'Allergen', 'Allergic Reaction', 'Product quality', 'Serious', 0, 0, 'Verify if your product is affected.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '72196');
