INSERT INTO safety_incidents VALUES ('588436be7da8156a7ec68becd053501e8631609a', 'Health Canada', '2022-11-14', 2022, '2022-11', 'Canada', 'Canada', '', 'Household Items', 'Various Lauren Taylor and Studio 707 corded window coverings', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and keep all cords out of reach of children. Products can be returned to be exchanged for a cordless replacement.For more information, consumers can contact Literies Universelles PAGA Inc. by going to the https://www.marimac.com/ website and using the "contact us" link.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like', '72192');
INSERT INTO safety_incidents VALUES ('b827f647c75c10931c0eab47e4a76783d0b41d54', 'Health Canada', '2022-11-14', 2022, '2022-11', 'Canada', 'Canada', '', 'Chemicals', 'Primo Resin Deep Pour, Table Top & Bar and Arts & Crafts epoxy kit hardeners', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products, keep them out of reach of children and contact the company or safely dispose of them in accordance with local municipal hazardous waste requirements.For more information, consumers can contact Primo Resin by telephone at 1-800-385-7637, Monday to Friday from 9:00 am to 8:00 pm EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Cana', '72193');
INSERT INTO safety_incidents VALUES ('c812ad476e4dd49315c7bcc8e3b740b14be96aa6', 'Health Canada', '2022-11-10', 2022, '2022-11', 'Canada', 'Canada', '', 'Household Items', 'Generac and DR Brand 6500 Watt and 8000 Watt Portable Generators.', 'Physical Hazard', 'Entrapment', 'Entrapment', 'Physical hazard', 'Not Reported', 0, 0, 'Update: Consumers should immediately stop using the recalled portable generators, unless the locking pin has been properly inserted to secure the handle in place before and after moving the generator, and contact Generac for a free, updated repair kit.Customers who responded to the original recall will automatically be sent a new kit. Please allow four weeks from the release of this notice for the processing of orders before inquiring if you have not yet received your kit.For more information, c', '62590');
