INSERT INTO safety_incidents VALUES ('23ad3e6e0bec576f2d340de39cc0fafc2400a4b1', 'Health Canada', '2022-11-03', 2022, '2022-11', 'Canada', 'Canada', '', 'Chemicals', 'Got Launch Traction Liquid', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Got Launch Traction Liquid and contact Got Launch to arrange for a return.For more information, consumers can contact Got Launch by telephone at 613-848-5712, Monday to Friday 10am-6pm EST or by email at teambellevegas@yahoo.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety', '72151');
INSERT INTO safety_incidents VALUES ('cc9e84188bc586204206c060759195fe4f15bbb4', 'Health Canada', '2022-11-03', 2022, '2022-11', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Several versions of Clarks women’s shoes sold under the "Breeze" style name, as reflected below.', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Clarks on how to receive a refund of the purchase price. For more information, consumers can register for the recall online at http://tinyurl.com/ClarksRecall, &nbsp;or contact Clarks by telephone toll free at 1-800-480-5137 between 6:00 a.m. ET to 6:00 p.m. ET Monday to Saturday or by email at productrecall@customerreply.clarks.com.Joint recall with Health Canada, the United States Consumer Product Safety Commission&nbsp;(', '72152');
INSERT INTO safety_incidents VALUES ('1af8969a3a1930e8f5048b1b26a3af00e5baef43', 'Health Canada', '2022-11-03', 2022, '2022-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'MYX II Stationary Exercise Bikes', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled exercise bikes until the pedals are properly tightened per the instructions that Myx is providing consumers via email. Consumers should contact Myx to schedule a free, in-home repair if their bike’s pedals have previously detached and have not already been repaired by Myx.For more information, consumers can contact Myx by telephone toll-free at 1-855-898-1275, Monday through Friday from 6:00 a.m. to 4:00 p.m. PST,&nbsp;or visit the company web', '72153');
INSERT INTO safety_incidents VALUES ('ddf59f644c873dc1ec24cb59136d222f55a9fc1f', 'Health Canada', '2022-11-03', 2022, '2022-11', 'Canada', 'Canada', '', 'Health Products', '0.9% SODIUM CHLORIDE INJECTION & LACTATED RINGER''S INJECTION', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Serious', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '72165');
INSERT INTO safety_incidents VALUES ('cf99e4b64f92880a600e97768c4c79d2074878cd', 'Health Canada', '2022-11-03', 2022, '2022-11', 'Canada', 'Canada', '', 'Grain Products', 'Tiramisu Twist Cookie', 'Tree Nut', 'Allergen', 'Not Specified', 'Tree nut', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '72166');
