INSERT INTO safety_incidents VALUES ('fad2a75eb7e1e810f7c27520be8a3deb9f470656', 'Health Canada', '2022-11-02', 2022, '2022-11', 'Canada', 'Canada', '', 'Tools & Machinery', 'Electrimart Mini Feed Thru Cord Switch', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the affected electrical switch and verify that the product is installed correctly. Consumers with an affected unit should disconnect power to it and verify that the smooth wire conductor is installed in the switch’s base instead of the ribbed wire.&nbsp; For more information, consumers can contact Cathelle Inc. by telephone at 1-800-363-0691 from 8a.m. to 5p.m. (eastern time) or by email at info@cathelle.com.Please note that the Canada Consumer Product Saf', '72118');
INSERT INTO safety_incidents VALUES ('7eecefcc655303ee972ffb223dda42f502ab7a3d', 'Health Canada', '2022-11-02', 2022, '2022-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Thermomix TM6 Measuring Cup Instructions', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the Thermomix TM6 measuring cup instructions and contact Vorverk to obtain updated product instructions.&nbsp; Once the updated product instructions have been reviewed, consumers may continue to use the TM6 Measuring Cup in accordance with the updated instructions. Customers do not need to return the product.Customers were informed directly via email by Vorwerk. Vorwerk has initiated a Global Information Campaign to reduce risk of user error with respect t', '72121');
