INSERT INTO safety_incidents VALUES ('f6b607f46f55c6c50e9196ce7b4a2bdc3d6f5e34', 'Health Canada', '2022-11-02', 2022, '2022-11', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Tag brand hooded, padded jacket with Sherpa lining', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, keep it out of reach of children, and return it to an Aubainerie store for a refund.For more information, consumers can contact Aubainerie by telephone at 1-833-303-1244, 8:30 am to 4:30 pm Monday to Friday, or by email at service@aubainerie.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to ', '72143');
INSERT INTO safety_incidents VALUES ('ca1903443fa691f6f4a73a4083fe8f7d56ec63a1', 'Health Canada', '2022-11-02', 2022, '2022-11', 'Canada', 'Canada', '', 'Other', 'Footpads for Onewheel GT model self-balancing electric skateboard', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Affected consumers should stop using the recalled product and contact Future Motion to request, free of charge, the replacement footpads and instructions for installation.&nbsp; The replacement footpads and instructions will be mailed to consumers who can complete the repairs themselves.&nbsp; Where requested, consumers may also send their GT to Future Motion to complete the replacement, free of charge.&nbsp; Only consumers with boards containing the original footpad will be asked to participate', '72145');
INSERT INTO safety_incidents VALUES ('2bda6722d743c9adedefa94db7b59cfda4807429', 'Health Canada', '2022-11-02', 2022, '2022-11', 'Canada', 'Canada', '', 'Medical Devices', 'Unlicensed ozone saunas', 'Product Safety - Unauthorised Device', 'Other', 'Not Specified', 'Product safety - Unauthorised device', 'Not Reported', 0, 0, 'Do not buy an ozone sauna or use an ozone sauna, such as at a spa or wellness centre.Consult a health care professional if you have used an ozone sauna and you have concerns about your health.Check whether medical devices have been licensed for sale by searching Health Canada''s Medical Devices Active Licence Listing.Report any health product-related adverse reactions or complaints to Health Canada.Stay connected with Health Canada and receive the latest advisories and product recalls.', '72150');
