INSERT INTO safety_incidents VALUES ('dee491a1b466a1e49392ebb568b41c976cc9cf20', 'Health Canada', '2022-11-01', 2022, '2022-11', 'Canada', 'Canada', '', 'Drugs', 'Janus Kinase (JAK) inhibitors, including: Cibinqo, Inrebic, Jakavi, Olumiant, Rinvoq and Xeljanz/Xeljanz XR.', 'Labelling', 'Other', 'Not Specified', 'Labelling', 'Not Reported', 0, 0, 'Talk to your health care professional for more details about this new safety information.Talk to your health care professional about possible heart disease risk factors before starting a JAK inhibitor.Contact your health care professional immediately and stop taking your JAK inhibitor if you develop symptoms of a heart problem. Symptoms may include:new or worsening chest pain;shortness of breath;irregular heartbeats; orswelling of the legs.Talk to your health care professional if you have or hav', '72146');
