INSERT INTO safety_incidents VALUES ('1e7b6bac1d0fb71bdc96c33224f83d124b3f4c20', 'Health Canada', '2022-10-27', 2022, '2022-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'Horizon T101-05 Folding Treadmills', 'Injury', 'Instability / Fall Risk', 'Fall Injury', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should stop using the treadmills and contact Horizon Fitness to obtain updated software.Consumers can contact Horizon Fitness online by email at retailrecall@johnsonfit.com or www.horizonfitness.com and click on “Safety Notices.” Consumers can also contact Horizon by telephone at 1-888-223-1045 from 8 a.m. to 5 p.m. CT Monday through Friday.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Johnson Health Tech Trading, Inc.Please note th', '64539');
INSERT INTO safety_incidents VALUES ('99b2aed41576c3e46dac98ffc0e7fc3b579939de', 'Health Canada', '2022-10-27', 2022, '2022-10', 'Canada', 'Canada', '', 'Furniture & Home', 'Amazon Basics High Back Executive Desk Chairs', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Amazon for a refund. Affected products contain a horizontal piece of plastic on the bottom of the caster bracket. Consumers will be asked to identify whether their product is within the scope of the recall, and if so, consumers should stop use of the product immediately and upload a photograph of the chair leg base for a refund. Once consumers upload the photograph and certify their disposal of the affected product at https', '72056');
