INSERT INTO safety_incidents VALUES ('c87146e90262ce217e0ce02ce31ae98777f831f6', 'Health Canada', '2022-10-27', 2022, '2022-10', 'Canada', 'Canada', '', 'Electrical & Electronics', 'King Song KS-16S Electric Unicycle Battery', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled electric unicycle battery and contact Smart Wheel to&nbsp;schedule a battery diagnostic and&nbsp;obtain&nbsp;a&nbsp;user manual for the product. Consumers must follow instructions in the user manual related to proper use and&nbsp;safety of the product.For more information, consumers can contact Smart Wheel by telephone 1-888-407-4997, by email at support@smartwheel.ca or visit the company website.Please note that the Canada Consumer Product Sa', '72087');
INSERT INTO safety_incidents VALUES ('e595209685c5dabd19459acc8c2a2635e49883ad', 'Health Canada', '2022-10-27', 2022, '2022-10', 'Canada', 'Canada', '', 'Tools & Machinery', 'BoxHot Glow Sticks Battery', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the affected product and contact Motif Labs Ltd. to arrange a return.For more information, consumers can contact Motif Labs Ltd. by telephone 1-855-527-1048, from 8:00 a.m. to 5:00 p.m. ET Monday through Friday, by email or visit the company’s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any healt', '72088');
INSERT INTO safety_incidents VALUES ('ccaa703e39c8e382d10b6e929f4953014e24bfa1', 'Health Canada', '2022-10-27', 2022, '2022-10', 'Canada', 'Canada', '', 'Chemicals', 'Pine-Sol® Scented Multi-Surface Cleaner in Lavender Clean®, Lemon Fresh, and Mandarin Sunrise® Scents', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalls product, dispose of the product in its container with household trash or by pouring it down the toilet or drain, and contact The Clorox Company for a refund.&nbsp; Consumers should take a picture of the date code, dispose of the product in its container with household trash or by pouring it down the toilet or drain, and contact The Clorox Company toll-free at 855-378-4982, Monday to Friday between 9:00 AM and 5:00 PM EST, or online at pinesolre', '72089');
