INSERT INTO safety_incidents VALUES ('5254a08416071c22fc73ec1447cf6e14b8e351d2', 'Health Canada', '2022-10-20', 2022, '2022-10', 'Canada', 'Canada', '', 'Other', 'Mittal International Brand Chenille Weave Baby Blankets in ochre, blush, blue, natural, taupe, grey, and spa/mint colours', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Entrapment hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to any HomeSense, Winners or Marshalls location for a refund. For more information, consumers can contact TJX by telephone toll-free at 1-800-646-9466 between 9 am to 5 pm or by visiting the Winners,&nbsp;HomeSense&nbsp;or&nbsp;Marshalls&nbsp;websites.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and TJX.Please note that the Canada Consumer Product Safety Act prohibits ', '72029');
INSERT INTO safety_incidents VALUES ('240c3fc42f0cbddeb6679b531c239dca1192bd63', 'Health Canada', '2022-10-20', 2022, '2022-10', 'Canada', 'Canada', '', 'Chemicals', 'Meguiar’s Heavy Duty Headlight Restoration Kit, G2980C', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, keep them out of reach of children and contact the place of purchase to have their return processed.For more information, consumers can contact 3M Canada at 1-800-364-3577, Monday to Friday between 8:00 AM to 5:00 PM EST or visit www.meguiars.ca/3M/en_CA/meguiars-ca/products/consumer-product-recall/.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in ', '72052');
