INSERT INTO safety_incidents VALUES ('7e7cfaad1602344c71fd482ac6bae14803a0c031', 'Health Canada', '2022-10-19', 2022, '2022-10', 'Canada', 'Canada', '', 'Toys & Childcare', '300 piece Army Action Figure Set (the "Action Figure Set")', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled 300 piece Army Action Figure Set and dispose of the product.For more information, consumers can contact Juvo Plus, Inc. by email at figuresandnets@realtimeresults.netPlease note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other con', '72057');
