INSERT INTO safety_incidents VALUES ('36773efa577b9855bf32c64dc37ce3c2da883d91', 'Health Canada', '2022-10-18', 2022, '2022-10', 'Canada', 'Canada', '', 'Other', 'Unbranded Stroller and Travel systems', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled stroller and travel system and return it to Allure Hair Fashions for a refund.For more information, consumers can contact Allure Hair Fashions by telephone at (604) 463-3443 between 10 AM and 6 PM PST Monday through Friday, or Saturday and Sunday between 12 PM and 5 PM PST. The company may also be contacted by email at allurehairfashions@gmail.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being re', '72053');
