INSERT INTO safety_incidents VALUES ('ab13dfb545baf34a76200c467b0de305e8d9a0ec', 'Health Canada', '2022-10-06', 2022, '2022-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'Specialized-branded Sirrus, Sirrus X and Sirrus Sport bicycles with alloy cranks', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bicycles and return them to the nearest Authorized Specialized retailer. The retailer will re-install the cranks to factory specification at no cost. Specialized Bicycle Components is contacting all known purchasers directly.For more information, consumers may contact Specialized Bicycle Components Canada, Inc. at 1-800-465-8887 from 8:00 a.m. to 6:00 p.m. ET Monday through Friday or&nbsp;online.Joint recall with Health Canada, the United Stat', '61513');
INSERT INTO safety_incidents VALUES ('917078b1ea7fa06771b611269627f21847f85d27', 'Health Canada', '2022-10-06', 2022, '2022-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'Optimus Gemini 2-Burner Gas Stove', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Optimus Gemini gas stove and return the product to the original place of purchase for a full refund.For more information, consumers can contact Katadyn Canada by telephone 1-877-962-1919, Monday through Thursday, from 9&nbsp;am to 5&nbsp;pm ET or contact customer service or visit the company website www.katadyngroup.com/ca/en/recall.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Katadyn Cana', '64584');
