INSERT INTO safety_incidents VALUES ('9414e0c28db41d9eb5780b284978917ed38cc1c2', 'Health Canada', '2022-10-05', 2022, '2022-10', 'Canada', 'Canada', '', 'Sports & Leisure', 'Tethrd One Stick GEN 2 Climbing Sticks', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled climbing sticks and contact the manufacturer for instructions on returning the recalled products. The manufacturer will have the stick tested and if it is determined not to conform to manufacturer’s specifications, it will be replaced at no cost to the consumer.For more information, consumers can contact Tethrd LLC by telephone at 1-612-643-9331 from 9 a.m. to 3 p.m. CT Monday through Friday, by email at testing@tethrdnation.com or visit the c', '64596');
