INSERT INTO safety_incidents VALUES ('e055c37070ab705a5e6b1e08006bb19150ab5f1b', 'Health Canada', '2022-09-26', 2022, '2022-09', 'Canada', 'Canada', '', 'Medical Devices', 'Philips Respironics sleep therapy masks with magnets in the headgear clips or straps (Amara View; DreamWisp; DreamWear; Wisp and Wisp Youth; and Therapy Mask 3100 NC/SP)', 'New Safety Information', 'Entrapment', 'Not Specified', 'New safety information', 'Not Reported', 0, 0, 'STOP USING the affected mask if you or any of your household members, caregivers or bed partners have implanted metallic medical devices or objects that may be affected by magnets, including but not limited to:PacemakersImplantable cardioverter defibrillators (ICD)NeurostimulatorsMagnetic metallic implants/electrodes/valves placed in upper limbs, torso, or higher (neck and head)CSF (cerebral spinal fluid) shunts (e.g., VP [ventriculo peritoneal] shunt)Aneurysm clipsEmbolic coilsIntracranial aneu', '64582');
