INSERT INTO safety_incidents VALUES ('e83ae854d3453febe319e1b7f209651ef29e3884', 'Health Canada', '2022-09-21', 2022, '2022-09', 'Canada', 'Canada', '', 'Chemicals', 'Krystal Epoxy Resin Tabletop & Art Epoxy Kit (250 mL, 500 mL, 1 L, 1 gallon, 2 gallons)', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product, keep them out of reach of children and contact the company for a free repair kit, which includes a child resistant cap and updated labels.For more information, consumers can contact Krystal Resin by telephone at +1 (416) 838-4988 from 9:00 a.m. to 6:00 p.m. or by email at info@krystalresin.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada', '64564');
