INSERT INTO safety_incidents VALUES ('adc46fdd861dadbc039ed0fe3b2fa1fcffd4746a', 'Health Canada', '2022-09-16', 2022, '2022-09', 'Canada', 'Canada', '', 'Other', 'Veggie Cevapcici', 'Tree Nut', 'Allergen', 'Not Specified', 'Tree nut', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '64555');
INSERT INTO safety_incidents VALUES ('7fa7b74796909db652ba54648d2a7855d9edbeab', 'Health Canada', '2022-09-15', 2022, '2022-09', 'Canada', 'Canada', '', 'Sports & Leisure', 'Cervélo R5 and Caledonia-5 bicycles and ST31 LT replacement stems', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the Model Year 2022 Cervélo R5 and Caledonia-5 bicycles, and Cervélo bicycles with the affected ST31 LT replacement stems, and contact an authorized Cervélo dealer to arrange for a free repair to replace the faceplate.For more information, consumers can contact Cervélo Cycles Inc. toll-free at 1 833-416-8605 Monday through Friday from 10 a.m. to 5 p.m. PST, by email at&nbsp;ST31LTRecallSupport@cervelo.com, or online at https://www.cervelo.com/product-recal', '64551');
