INSERT INTO safety_incidents VALUES ('99bee103197f1e398aa145cf872fe77a06173bed', 'Health Canada', '2022-09-06', 2022, '2022-09', 'Canada', 'Canada', '', 'Household Items', 'IKEA TRIPPEVALS and HOPPVALS Cellular Blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled IKEA TRIPPEVALS and HOPPVALS cellular blinds if the product was purchased between May 1, 2021 and September 5, 2022 and contact IKEA for a refund. Proof of purchase (receipt) is not requred.For more information, consumers can contact IKEA Customer Support Centre&nbsp;by telephone at 1-800-661-9807 Monday to Sunday: 9am - 9pm (EST).Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold', '64538');
