INSERT INTO safety_incidents VALUES ('acc5fdc49eaec4e34597c21723d4dd2cb9b5a2a2', 'Health Canada', '2022-09-01', 2022, '2022-09', 'Canada', 'Canada', '', 'Other', 'UPPAbaby All-Terrain RIDGE Jogging Strollers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled strollers and go to www.uppababy.com/ridge/disc-brakes/ and click on “Submit Info” at the bottom of the page to receive free replacement disc brakes for both wheels.For more information, consumers can contact UPPAbaby by telephone at 844-823-3132 from 9 a.m. to 5 p.m. ET Monday through Friday, email support@uppababy.com or online at www.uppababy.com and click on “Click to read more” next to the recall announcement.Joint recall with Health Cana', '64522');
INSERT INTO safety_incidents VALUES ('4236b74eeb86c08288c0119c2cb263ffd8642788', 'Health Canada', '2022-09-01', 2022, '2022-09', 'Canada', 'Canada', '', 'Herbs And Spices', 'Keampferia Galanga Powder (sand ginger powder)', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Sign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation and recall processReport a food safety or labelling concern', '64531');
