INSERT INTO safety_incidents VALUES ('78ef1c4930ef0b983413e27a9ca6cb5b980f842a', 'Health Canada', '2022-08-29', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'JAMP ATORVASTATIN CALCIUM', 'Dosage - Labelling', 'Other', 'Not Specified', 'Dosage - Labelling', 'Serious', 0, 0, 'Check your bottle of Jamp-Atorvastatin Calcium, 10 mg tablets to make sure it contains 10 mg tablets and not 40 mg tablets. 10 mg atorvastatin calcium tablets are white to off-white, oval shaped, film-coated tablets, with "10" marked on one side and "AT" marked on the other. 40 mg atorvastatin calcium tablets are white to off-white, oval shaped, film-coated tablets, with "40" marked on one side and "AT" marked on the other.If you are unsure, contact your pharmacist to check if your bottle of Jam', '64512');
