INSERT INTO safety_incidents VALUES ('72fd0cf88d79aa43bec71f9d9c8903c928073a64', 'Health Canada', '2022-08-22', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'PMS-HYDROMORPHONE TAB 2 MG', 'Adverse Reaction - Dosage - Labelling - Packaging - Product Safety - Product Withdrawal', 'Chemical / Toxic Substance', 'Poisoning / Ingestion', 'Adverse reaction - Dosage - Labelling - Packaging - Product safety - Product withdrawal', 'Serious', 0, 0, 'Check your bottle of pms-Hydromorphone to ensure you have the correct tablets. The 2 mg hydromorphone tablets are round and orange with a "2" on one side of the tablet and "pms" on the other side. The 8 mg hydromorphone tablets are round and white with an "8" on one side of the tablet and "pms" on the other side.Stop using product from the affected lot and contact your pharmacy immediately for a replacement product.If you have accidentally taken the 8 mg hydromorphone tablet instead of the 2 mg ', '64487');
