INSERT INTO safety_incidents VALUES ('014f6d94bab5a906c34379c70ce335cf2187d531', 'Health Canada', '2022-08-20', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'pms-Hydromorphone, 2 mg tablets (DIN 00885436) marketed by Pharmascience Inc. Sold to pharmacies in bottles of 100 tablets for dispensing to consumers.', 'Adverse Reaction - Dosage - Labelling - Packaging - Product Safety - Product Withdrawal', 'Chemical / Toxic Substance', 'Poisoning / Ingestion', 'Adverse reaction - Dosage - Labelling - Packaging - Product safety - Product withdrawal', 'Not Reported', 0, 0, 'Check your bottle of pms-Hydromorphone to ensure you have the correct tablets. The 2 mg hydromorphone tablets are round and orange with a "2" on one side of the tablet and "pms" on the other side. The 8 mg hydromorphone tablets are round and white with an "8" on one side of the tablet and "pms" on the other side.Stop using product from the affected lot and contact your pharmacy immediately for a replacement product.If you have accidentally taken the 8 mg hydromorphone tablet instead of the 2 mg ', '64485');
INSERT INTO safety_incidents VALUES ('0f65d86e4974322c03cb5216a5da12f9e6f8949c', 'Health Canada', '2022-08-19', 2022, '2022-08', 'Canada', 'Canada', '', 'Grain Products', 'Pro-licious Protein Pancake & Waffle Mix', 'Milk', 'Allergen', 'Allergic Reaction', 'Milk', 'Moderate', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '64462');
INSERT INTO safety_incidents VALUES ('b99506325e0f2ed91b2758c94e768f9d24a903e1', 'Health Canada', '2022-08-19', 2022, '2022-08', 'Canada', 'Canada', '', 'Natural Health Products', 'Carnivor', 'Labelling - Product Quality', 'Other', 'Not Specified', 'Labelling - Product quality', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '64475');
