INSERT INTO safety_incidents VALUES ('3042d4e960381c3fdc4ad7eddd69275b3af35475', 'Health Canada', '2022-08-17', 2022, '2022-08', 'Canada', 'Canada', '', 'Cannabis', 'Ellevia THC Light 4:1 cannabis extract, Lot CO107461', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should verify whether their product is affected. If you wish to return affected product, please contact Shoppers Cannabis Care at 1-844-633-2627 or cannabis@shoppersdrugmart.ca.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '64464');
