INSERT INTO safety_incidents VALUES ('0cfa2f1464f41ef2afab2815e4fac90fc5102309', 'Health Canada', '2022-08-17', 2022, '2022-08', 'Canada', 'Canada', '', 'Cannabis', 'XMG Cola edible cannabis beverage, Lots 520413041, 520504051 and 520606051', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should verify whether their product is affected. If you wish to return affected product, please contact the retail store where the product was purchased.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '64474');
INSERT INTO safety_incidents VALUES ('68efc3dc37cba7690304e10cd5e62e410887511d', 'Health Canada', '2022-08-17', 2022, '2022-08', 'Canada', 'Canada', '', 'Household Items', 'Aspen Cordless Wood Blinds – Creation, Mirage PVC Mini Blinds with PVC Headrail– Creation, Tristan Faux Wood Blinds – Creation, Jean H. Henlé Blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and keep all of the cords away from children. The cord(s) should be cut and the product disposed of.For more information, consumers may contact Fabricville by email: andrem@fabricville.com or by telephone at 514-383-3949 extension 334 (Monday to Thursday 9:00 am– 5:00 pm and Friday 9:00 am – 1:00 pm).Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in', '64476');
INSERT INTO safety_incidents VALUES ('9595b1406082d34362a338a4691ca6a939db91d5', 'Health Canada', '2022-08-16', 2022, '2022-08', 'Canada', 'Canada', '', 'Household Items', 'Various Bouclair blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Bouclair stores for a store credit.For more information, consumers can contact Bouclair Canada by telephone at 1-800-268-2524, Monday to Friday from 8:30 am to 5:00 pm EST or by email at https://www.bouclair.com/en/contactus.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report an', '64466');
