INSERT INTO safety_incidents VALUES ('b49fbc671b59f9374b59f5646281ad83242cd3e2', 'Health Canada', '2022-08-15', 2022, '2022-08', 'Canada', 'Canada', '', 'Household Items', '4moms MamaRoo  Baby Swing (models 4M-005, 1026, and 1037) and RockaRoo Baby Rocker (model 4M-012)', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers with infants who can crawl should immediately stop using the recalled products and place them in an area where crawling infants cannot access. Consumers who have a recalled swing or rocker should register for the recall via 4moms recall registration website or by phone. 4moms will then send a strap fastener to consumers, with instructions for installation. Consumers who have infants who can crawl, stop using the products and place them in an area where children cannot access it until t', '64460');
