INSERT INTO safety_incidents VALUES ('02e0512efc00d50eff42a066c0fb3ded0de8825e', 'Health Canada', '2022-08-11', 2022, '2022-08', 'Canada', 'Canada', '', 'Processed', 'Pastrami, Turkey Breast - Tuscan Flavoured', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '64465');
INSERT INTO safety_incidents VALUES ('ac07f5939bf3bf8e3f3871ed275ca67c6659cde9', 'Health Canada', '2022-08-10', 2022, '2022-08', 'Canada', 'Canada', '', 'Household Items', 'ST. CHARLES Top-Down Bottom-Up Cordless Cellular Shade', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose of the product.For more information, consumers can contact All Strong Industry USA Inc. by telephone at 1-877-804-5504 Monday to Friday 8:30 am to 5:00 pm EST or by email at customerervice@lbg-sales.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety inci', '64435');
INSERT INTO safety_incidents VALUES ('aa05a6c76fd5b6c9a4a30d5de40e7292d6f416ed', 'Health Canada', '2022-08-10', 2022, '2022-08', 'Canada', 'Canada', '', 'Household Items', 'Safdie & Co. Home – Premium. Day & Night Zebra Roller Blind Dual Layer Shades', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Safdie &amp; Co. for a repair kit or refund. For more information, consumers can contact Safdie &amp; Co. by telephone at (514) 344-5579 from 8:30 a.m. to 4:30 p.m. PST, Monday through Friday or by email at sales_info@safdieco.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to repo', '64443');
INSERT INTO safety_incidents VALUES ('f24e51baeb8406f51ad210c9df5de1477b0ef913', 'Health Canada', '2022-08-10', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'Taro-Zoledronic Acid', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Serious', 0, 0, 'Check your product or contact your pharmacist to determine if it is affected. If you have a recalled product, do not use it and return it to your pharmacy for a replacement product and proper disposal.If you have used the recalled product and have health concerns, contact your healthcare provider. Go to the hospital immediately if you develop difficulty breathing, chest pain or confusion.Contact Taro Pharmaceuticals Inc. by calling toll free at 1-800-268-1975 if you have questions about this rec', '64452');
INSERT INTO safety_incidents VALUES ('027f6d238956aaa1ed86bdebf33eda045dc7fa6a', 'Health Canada', '2022-08-10', 2022, '2022-08', 'Canada', 'Canada', '', 'Chemicals', 'Magic Resin Table Top & Art Epoxy Resin Products', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products, keep them out of reach of children and contact the company to request a free child resistant cap, or safely dispose of them in accordance with local municipal hazardous waste requirements.For more information, consumers can contact Magic Resin by telephone at 1-819-962-2521 from 9:00 AM to 5:00 PM EST or by email.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even', '64461');
