INSERT INTO safety_incidents VALUES ('f481573ac208ef2be63ea649d082eecf951ca35c', 'Health Canada', '2022-08-09', 2022, '2022-08', 'Canada', 'Canada', '', 'Household Items', 'For Living 1” Light Filtering Cordless Blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard - Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to a local Canadian Tire location for exchange or refund. For more information, consumers can contact Canadian Tire by telephone toll-free at 1- 800-387-8803 Monday through Friday 8:00 a.m. to 9:00 p.m. EST, and on Saturday and Sunday from 9:00 a.m. to 5:00 p.m. EST. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Can', '64440');
INSERT INTO safety_incidents VALUES ('bedb29a0fa0d3560a4369a62e6540682cb6cc7f0', 'Health Canada', '2022-08-09', 2022, '2022-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Konges Sløjd Silicone Baby Mirror Toy Bear Activity Toy', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the toy away from children and contact Konges Sløjd for a full refund.For more information, consumers can contact Konges Sløjd by telephone at +45 70 60 51 01 from 3 a.m. to 9 a.m. ET Monday through Friday, by email,&nbsp;online at https://kongessloejd.com/pages/product-recall or https://kongessloejd.com/ and click on “product recall” at the bottom of the site for more informationJoint recall with Health Canada, the United States Consumer Product Safety Commissi', '64454');
