INSERT INTO safety_incidents VALUES ('6ce7c50ff93f67037deabdf12bc419a9e721fdcf', 'Health Canada', '2022-08-09', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'Taro-Zoledronic acid injection 5mg/100mL (DIN 02415100)', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Not Reported', 0, 0, 'Check your product or contact your pharmacist to determine if it is affected. If you have a recalled product, do not use it and return it to your pharmacy for a replacement product and proper disposal.If you have used the recalled product and have health concerns, contact your healthcare provider. Go to the hospital immediately if you develop difficulty breathing, chest pain or confusion.Contact Taro Pharmaceuticals Inc. by calling toll free at 1-800-268-1975 if you have questions about this rec', '64457');
