INSERT INTO safety_incidents VALUES ('861872de7f64e6fd153d79fe989cbeef106ccd52', 'Health Canada', '2022-08-08', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'JAMP-ATORVASTATIN', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Serious', 0, 0, 'Contact your pharmacy to confirm if you are taking medication from the affected lot. If you are, stop taking it and return it to your pharmacy for a replacement product and proper disposal.Contact Jamp Pharma Corporation by calling toll-free at 1-866-399-9091, extension 501, or by email at&nbsp;serviceclient@jamppharma.com, if you have questions about this recall.Report any health product&nbsp;adverse events&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '64451');
INSERT INTO safety_incidents VALUES ('8a1b6c349b67ae6f3c68931d2c477051be055395', 'Health Canada', '2022-08-06', 2022, '2022-08', 'Canada', 'Canada', '', 'Drugs', 'Jamp-Atorvastatin 40 mg tablets (lot MHC1403A, expiry 2023-09-30)', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Not Reported', 0, 0, 'Contact your pharmacy to confirm if you are taking medication from the affected lot. If you are, stop taking it and return it to your pharmacy for a replacement product and proper disposal.  Contact Jamp Pharma Corporation by calling toll-free at 1-866-399-9091, extension 501, or by email at serviceclient@jamppharma.com, if you have questions about this recall.  Report any health product adverse events or complaints to Health Canada.', '64446');
INSERT INTO safety_incidents VALUES ('3aad285717b9bd71427edb1689e428b0426e63af', 'Health Canada', '2022-08-05', 2022, '2022-08', 'Canada', 'Canada', '', 'Cannabis', 'VORTEX 10 SOUR THC JELLY DROPS 10 MG THC PER DROP edible cannabis, Lot FP-22MA-005, VORTEX 10 MIXED BERRY JELLY DROPS 10MG THC edible cannabis, Lot FP-22FE-011', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers that have purchased the affected product and wish to return it may visit the retail store where the product was purchased.&nbsp;Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.&nbsp;', '64384');
INSERT INTO safety_incidents VALUES ('1992a4059c2b70b6e11be476862b9601bb89d22b', 'Health Canada', '2022-08-05', 2022, '2022-08', 'Canada', 'Canada', '', 'Chemicals', 'Stone Coat Countertops Art Coat Resin Kit (1/2 gallon, 1 gallon, 2 gallon)', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and dispose of them according to their local municipal hazardous waste guidelines.For more information, consumers can contact Stone Coat Countertops Customer Service by telephone at (541) 450-1976 from 8:00 a.m. to 4:30 p.m. PST.&nbsp; Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any', '64437');
INSERT INTO safety_incidents VALUES ('402a3f9ba0c75dac57f3fbeaf5f1fc2dfe14ba55', 'Health Canada', '2022-08-05', 2022, '2022-08', 'Canada', 'Canada', '', 'Food & Food Contact', 'Primal Patties for Dogs – Beef Formula', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose of the product.For more information, consumers can contact Primal Pet Foods by telephone toll-free at 1-800-742-1312 Monday–Friday, from 6:00 a.m. through 4:00 p.m. PST, or by submitting an online request. Consumers can also read the company’s recall announcement on their website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.He', '64441');
INSERT INTO safety_incidents VALUES ('77c4757a77be530b6137859450631714341f9ff2', 'Health Canada', '2022-08-05', 2022, '2022-08', 'Canada', 'Canada', '', 'Health Products', 'Unauthorized health products, including prescription drugs', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Do not use these products. Return the product to your local pharmacy for proper disposal. Consult a health care professional if you have used any of these products and have health concerns.Buy your prescription drugs only from licensed pharmacies.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can', '64444');
