INSERT INTO safety_incidents VALUES ('bde81ef65c676b0ababe2c3ccadccd07d64d71d1', 'Health Canada', '2022-08-05', 2022, '2022-08', 'Canada', 'Canada', '', 'Medical Devices', 'Counterfeit BTNX Rapid Response COVID-19 antigen rapid test kits (25-pack)', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Canadians are advised not to use any of the components contained in these counterfeit kits regardless of how much they may resemble components found in other licensed COVID-19 test kits sold in Canada.Health Canada has no evidence to suggest that additional counterfeit kits have been distributed in Canada.If you suspect you have a counterfeit kit, do not use it and dispose of it in household garbage. Report suspected counterfeit medical devices to Health Canada. You can also report suspected cou', '78092');
