INSERT INTO safety_incidents VALUES ('807aab09ff063face4a0365418265c060e5e41ec', 'Health Canada', '2022-08-04', 2022, '2022-08', 'Canada', 'Canada', '', 'Tools & Machinery', 'DEWALT 12-inch Sliding Compound Miter Saws', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Stanley Black &amp; Decker Canada Corporation for a replacement rear guard assembly kit or go to a DEWALT Service Center for a free repair.For more information, consumers can contact Stanley Black &amp; Decker Canada by telephone at 1-800-990-6421 or online at&nbsp;https://www.dewalt.ca/miter-saw-recall.Joint recall with Health Canada, the United States Consumer Product Safety Commission (add CPSC’s web link) (US CPSC) and ', '64409');
