INSERT INTO safety_incidents VALUES ('6a33e27483b92b563c35bb30c632572acddf9d75', 'Health Canada', '2022-08-01', 2022, '2022-08', 'Canada', 'Canada', '', 'Chemicals', 'Cozy Flame CA Tabletop Fire Pits', 'Burns', 'Flammability / Overheating', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled tabletop fire pit and contact Cozy Flame CA for more information.For more information, consumers may contact Cozy Flame CA by telephone at 1-413-276-5756 Monday to Friday from 10:00 a.m. to 4:00 p.m. CT or by email at Cozyflameca@gmail.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any heal', '64416');
