INSERT INTO safety_incidents VALUES ('181efa81abbd37cc59104d46451c20d80331e53f', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Drugs', 'Apo-Acyclovir (acyclovir) 200 mg and 800 mg tablets (UPDATED 2022-07-28 to add additional recalled lots)', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Not Reported', 0, 0, 'Continue taking your medication unless you have been advised to stop by your health care provider. You do not need to return your medication to your pharmacy. Not treating your condition may pose a greater health risk. Talk to your health care provider if you are taking a recalled product and are concerned about your health. If you have questions about the recall, contact Apotex Inc. at 1-888-628-0732 or by email at apotex4315@sedgwick.com.Report any health product-related&nbsp;side effects&nbsp', '64122');
INSERT INTO safety_incidents VALUES ('bbc9cbbc8c8b245c5fca43bc6e3c23d20ee62275', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Toys & Childcare', 'Kidoozie Brand Play Tents', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Play Tents and contact Epoch Everlasting Play LLC for instructions on how to receive a refund or replacement. For more information, consumers can contact Epoch Everlasting Play LLC by telephone, Toll free at 1-800- 631-1272 Monday through Friday from 8 a.m. to 5 p.m. Pacific Time; email at: productsafety@epocheverlastingplay.com or online at epocheverlastingplay.com/recalls Joint recall with Health Canada, the United States Consumer Product Sa', '64231');
INSERT INTO safety_incidents VALUES ('8e75187f66173fe11a135dbf7322bb31bb184c99', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'PIEPS and Black Diamond Avalanche Transceivers and Beacons', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled transceiver or beacon, follow the directions on the Black Diamond website to perform a device check, and contact Black Diamond Equipment for a repair or replacement if the product is malfunctioning.For more information, consumers can contact Black Diamond Equipment toll-free at 866-306-0865 between 9 am and 4 pm MT Monday through Friday, or on the company website. &nbsp;Joint recall with Health Canada, the United States Consumer Product Safety', '64320');
INSERT INTO safety_incidents VALUES ('6e1a4e0fb30173c5d9e8e788aad0a01bcaa410e4', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Powercom/Milcom Underwater Wireless Diver Units', 'Fire', 'Drowning Risk', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Powercom/Milcom Underwater wireless diver units and contact Ocean Technology Systems (OTS) for a replacement battery.&nbsp; For more information, consumers can contact OTS by telephone toll-free at 1-800-550-1984 from 7:00 a.m. to 4:00 p.m. CT Monday through Friday. Consumers may also reach the OTS Sales Department by telephone at (714) 754-7848 Ext. 115 or by email, or the OTS Service Department by telephone at (714) 754-7848 Ext. 141 or by e', '64359');
INSERT INTO safety_incidents VALUES ('fd47f151e1003b6cc2f89140c95c378b46d5cbfb', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Chemicals', 'Aesop Post-Poo Drops and Various Aesop Oil Burner Blends', 'Aspiration Hazard', 'Other', 'Burns', 'Aspiration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Aesop Post-Poo drops and Aesop Oil Burner Blends and contact Aesop for instructions on how to safely dispose of the product and register to receive a full refund in the form of an Aesop digital gift card.For more information on the recall, consumers should visit http://aesop.com/ca/en/r/recall-2022 (English) or http://aesop.com/ca/fr/r/recall-2022 (French) or https://www.aesop.com/ca and click on “Product Recalls” or call +1 (855) 919-4773 fro', '64382');
INSERT INTO safety_incidents VALUES ('7dca486bfcd927c5f7e57e8ce35f0c806c234c6b', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Other', 'NUK First Choice 240 mL Glass Baby Bottles', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled glass baby bottle. Contact NUK for information on how to return the recalled bottle and receive a refund. Direct Care (Amazon seller) is contacting all purchasers directly. For more information, consumers may contact NUK toll-free at 888-685-1238 from 9 a.m. to 5 p.m. ET Monday through Friday, or visit the company''s website&nbsp;and click on RECALL at the top of the page for more information.Joint recall with Health Canada, the United States C', '64407');
INSERT INTO safety_incidents VALUES ('fcf7755b594d7e57fb5a7753863be5f8c0019177', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Evaporator Coil Drain Pans', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately use the model verification tool available at www.recallrtr.com/drainpan to determine if their system is within the recall range and, if so, contact Goodman for a free repair by a qualified technician.For more information, consumers may contact Goodman by telephone toll-free at 888-520-0579 from 7 a.m. to 6 p.m. CT Monday through Friday.&nbsp; Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Daikin Comfort Technologie', '64408');
INSERT INTO safety_incidents VALUES ('c2c7ab6071769d7d8a67278c27350231495b3a2f', 'Health Canada', '2022-07-28', 2022, '2022-07', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Certain dark chocolate bars', 'Milk', 'Allergen', 'Not Specified', 'Milk', 'Serious', 0, 0, 'Check to see if you have recalled productsDo not consume recalled products to which you are allergic or sensitive as they may cause a serious or life-threatening reactionDo not serve, use, sell or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation ', '64412');
