INSERT INTO safety_incidents VALUES ('9d094a7ea18560d3d02652b80b633db5ffb31718', 'Health Canada', '2022-07-27', 2022, '2022-07', 'Canada', 'Canada', '', 'Household Items', 'LIKCO Baby Walker Interactive Baby Walker with Music 4 Height Adjustable (Green) Anti-Rollover Child Walker for 6-24 month babies.', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the baby walker, destroy it so it cannot be used again&nbsp;and safely dispose of it according to their local municipal waste guidelines.Regularly check the&nbsp;Healthy Canadians Recalls and Safety Alerts database&nbsp;for dangerous products and take action to remove items of concern.Health Canada reminds&nbsp;Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by filling out the&', '64339');
INSERT INTO safety_incidents VALUES ('a76178e9708d5cde74714d26cbe74b39936764ff', 'Health Canada', '2022-07-27', 2022, '2022-07', 'Canada', 'Canada', '', 'Cannabis', 'NightNight Pomegranate Sunset CBN+CBD Shot edible cannabis, Lots 32004, 32003, 32002, 32001, 31005, 31004, 31003, 31002', 'Microbial Hazard', 'Microbiological Contamination', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using this product. Consumers can return the product to the retailer where the product was purchased or dispose of the product. Opened product should be disposed of safely and out of the reach of children and young persons.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '64410');
