INSERT INTO safety_incidents VALUES ('2f54ee745fec5d7ebb95823bc952831c032aeb64', 'Health Canada', '2022-07-20', 2022, '2022-07', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized health products, including drugs, natural health products and medical devices, sold online.', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Not Reported', 0, 0, 'If you are planning to buy health products online, read the information Health Canada has posted on the risks of buying&nbsp;drugs, natural health products&nbsp;or&nbsp;medical devices&nbsp;over the Internet.Look for health products that have been authorized by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Medicine Number (DIN-HM).&nbsp;Consumers can also check whether products have been authorized for ', '64380');
