INSERT INTO safety_incidents VALUES ('7d798a849027d64f286c0cdea1656e1d111e1523', 'Health Canada', '2022-07-15', 2022, '2022-07', 'Canada', 'Canada', '', 'Household Items', 'Fisher-Price Infant-to-Toddler and Newborn-to-Toddler Rockers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'If your baby falls asleep in this product, move them to a safe surface intended for sleeping, such as a crib, cradle, or bassinet.  Do not leave your baby unsupervised or unrestrained while in the rocker.  To view the United States Consumer Product Safety Commission (US CPSC)''s warning on the rockers, visit their recent publication.  Other similar products such as high chairs, baby swings, bouncers, strollers and car seats are made for babies, but also not for sleep. Sleeping in a sitting positi', '64368');
