INSERT INTO safety_incidents VALUES ('7242058f2b8e8ede1302461ed8dc77f80525044c', 'Health Canada', '2022-07-14', 2022, '2022-07', 'Canada', 'Canada', '', 'Sports & Leisure', 'Cabela’s Outfitter and Big Horn tents', 'Injury', 'Flammability / Overheating', 'Respiratory', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using a wood stove inside the tents and contact Westfield Outdoor for a free replacement stove jack ring. Consumers can remove the old stove jack ring from the tent and install the replacement ring by following the instructions provided with the replacement ring. Westfield Outdoor is contacting all known purchasers directly.For more information, consumers can contact Westfield Outdoor toll-free at 877-579-1550 from 7:30 a.m. to 4:30 p.m. ET Monday through Friday', '64333');
