INSERT INTO safety_incidents VALUES ('b9dc9da961dc268215076c5072994ccfd0f5c5b9', 'Health Canada', '2022-07-12', 2022, '2022-07', 'Canada', 'Canada', '', 'Household Items', 'Arlo Blinds Cordless Lift Bamboo Shade', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Top Blinds for a full refund. For more information, consumers may contact Top Blinds toll-free at 1-888-608-8468 from 9:00 a.m. to 5:00 p.m. ET Monday through Friday, or by&nbsp;email at: CanadaWFRecall@topblinds.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health ', '64340');
INSERT INTO safety_incidents VALUES ('aef238be06a1a241884e1c2f357abd7d2c5792cf', 'Health Canada', '2022-07-13', 2022, '2022-07', 'Canada', 'Canada', '', 'Furniture & Home', 'Cyme-Tech Low Profile Murphy Bed Part numbers S214, S215, S234 and S235.', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Low Profile Murphy Bed&nbsp;Part numbers S214, S215, S234 and S235 until visual inspection has been conducted to ensure proper installation. Please take contact with Cyme-Tech for details.For more information, consumers can contact Cyme-Tech at service@cymetech.ca or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Ca', '64341');
INSERT INTO safety_incidents VALUES ('83227cb02c538eded8da21cd54268721d32599c1', 'Health Canada', '2022-07-13', 2022, '2022-07', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Vichy LiftActiv Peptide-C Ampoules, 1.8ml', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products.For more information, consumers can contact Vichy Canada customer service by phone at 1-888-458-4249 (available Monday to Friday between 9am and 5pm ET) for product return and refund options, or visit the company website Vichy.ca.Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the sale of cosmetics that are either made with hazardous substances, or under unsanitary ', '64358');
INSERT INTO safety_incidents VALUES ('53d47030bc0f4fffa9596d8b60315d626bb0a856', 'Health Canada', '2022-07-13', 2022, '2022-07', 'Canada', 'Canada', '', 'Drugs', 'Oxygen USP 99.0%', 'Dosage', 'Other', 'Not Specified', 'Dosage', 'Minor', 0, 0, 'Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check if products have been authorized for sale by searching Health Canada’s&nbsp;Drug Product Database&nbsp;and&nbsp;Licensed Natural Health Product Database.Report any health product&nbsp;adverse events&nbsp;or&nbsp;complaints&nbsp;to Heal', '64361');
INSERT INTO safety_incidents VALUES ('cc9e5dfa4a4ec9d882ec148da02a8882ad6be48d', 'Health Canada', '2022-07-12', 2022, '2022-07', 'Canada', 'Canada', '', 'Fresh', 'Enoki Mushroom', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '64360');
