INSERT INTO safety_incidents VALUES ('11140825ba99bca72e5bc73c67983167a1b80146', 'Health Canada', '2022-07-07', 2022, '2022-07', 'Canada', 'Canada', '', 'Toys & Childcare', 'Scholastic Canada Ltd. The Shake Look Touch book', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the book and contact 1-800-268-3848 to begin the return process. Consumers will be provided a shipping label and asked to return the books to Scholastic Canada Ltd. Upon receipt of the returned Book, consumers will be issued a refund.For more information, consumers can contact Scholastic Canada Ltd. by telephone (at 1-800-268-3848) or visit the company website&nbsp;https://www.scholastic.ca/productsafetyrecall/shakelooktouch/Joint recall with Health Canada', '64230');
INSERT INTO safety_incidents VALUES ('254707dcd10cfd8b762f1b15c51f127f3d7ec094', 'Health Canada', '2022-07-07', 2022, '2022-07', 'Canada', 'Canada', '', 'Other', 'John Deere Lawn Tractors', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled lawn tractors and contact an authorized John Deere dealer for a free inspection and repair.For more information, consumers can contact Deere &amp; Company at (800) 537-8233 Monday through Friday from 7 a.m. to 7 p.m. and on Saturdays from 8 a.m. to 4:30 p.m. CST, or visit their web site at https://www.deere.ca/en/ orhttps://www.deere.ca/fr/.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and John', '64337');
INSERT INTO safety_incidents VALUES ('33c9ffe75b6247561051b075f01804239a28d026', 'Health Canada', '2022-07-05', 2022, '2022-07', 'Canada', 'Canada', '', 'Household Items', 'PADERNO 1.7 Qt Glass Square Baking Dish with Lid', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and visit their local Canadian Tire for an exchange or refund.For more information, consumers may contact Canadian Tire by telephone toll-free at 1-800-387-8803 Monday through Friday from 8:00 a.m. to 9:00 p.m. EST, and on Saturday and Sunday from 9:00 a.m. to 5:00 p.m. EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would ', '64322');
