INSERT INTO safety_incidents VALUES ('967a657a2bf449397d39405d276c10a358b5b156', 'Health Canada', '2022-07-01', 2022, '2022-07', 'Canada', 'Canada', '', 'Grain Products', 'Certain bakery products', 'Extraneous Material', 'Other', 'Not Specified', 'Extraneous Material', 'Moderate', 0, 0, 'Check to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Sign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation and recall processReport a food safety or labelling concern', '64326');
INSERT INTO safety_incidents VALUES ('c2a87d1c5e3558677bc80bbbfbd46cc9154c16ac', 'Health Canada', '2022-07-01', 2022, '2022-07', 'Canada', 'Canada', '', 'Fresh', 'King Oyster Mushroom', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stif', '64327');
INSERT INTO safety_incidents VALUES ('85020932ef8ee4fdf09da8187f7a9c140d6ca1df', 'Health Canada', '2022-06-30', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'LAARS Mini-Therm JX Gas-Fired Boilers', 'Poisoning Hazard', 'Flammability / Overheating', 'Poisoning / Ingestion', 'Poisoning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled boilers and contact LAARS® Heating Systems Company to arrange for the installation of a free repair kit.For more information, consumers can contact LAARS® Heating Systems Company by telephone at 1‑888-454-3223, Monday to Friday from 8:00 a.m. to 5:00 p.m. EDT, by email at warranty@laars.com, or visit the company website and click on “Recall Notice” for more information.Joint recall with Health Canada, the United States Consumer Product Safety ', '64299');
INSERT INTO safety_incidents VALUES ('6eaeba452d00d4b3a84e930ee86a12c56033061e', 'Health Canada', '2022-06-30', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'COVID-19 Preventive Prescription I & II', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Minor', 0, 0, 'Stop using these products and consult your healthcare professional if you have health concerns.&nbsp;Report&nbsp;the sale of these or any unauthorized health products to Health Canada.&nbsp;Report any health product&nbsp;adverse events&nbsp;to Health Canada.', '64323');
INSERT INTO safety_incidents VALUES ('e95467b59eadd99fff27e04ce4eb8173da246856', 'Health Canada', '2022-06-30', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'Succinyl Choline Injection USP', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Serious', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '64324');
