INSERT INTO safety_incidents VALUES ('39570a3fcadc83cd403dbb0a9e16a47fb5abb312', 'Health Canada', '2022-06-29', 2022, '2022-06', 'Canada', 'Canada', '', 'Toys & Childcare', 'Infant formulas for babies with food allergies and certain medical conditions', 'Supply - Other', 'Other', 'Allergic Reaction', 'Supply - Other', 'Not Reported', 0, 0, 'Speak to a health care professional, such as your doctor or pharmacist, to discuss your baby’s needs and possible alternative products and how to transition them into your infant’s diet.If you are combining bottle-feeding and breastfeeding, try to maintain your breastmilk supply and consult your health care professional if you need advice on an allergen free diet.Do not attempt to make homemade infant formula as it can put your baby’s health at risk. Commercial infant formula contains many impor', '64183');
