INSERT INTO safety_incidents VALUES ('b451352be845ff4fc6fc079a16a74cdda5ee62bb', 'Health Canada', '2022-06-24', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'Brite Blinds Brand 2” SafeCordTM Fauxwood blinds', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Brite Blinds brand 2” SafeCordTM Fauxwood blinds and contact the company to request free repair kits.For more information, consumers can contact Brite Blinds Ltd. by telephone at (604) 420-8820, Monday to Friday from 9:00am to 5:00pm PST, by email at support@briteblinds.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to r', '64307');
