INSERT INTO safety_incidents VALUES ('24fa56131d25e672f63973ba779a0a33eb0cf09f', 'Health Canada', '2022-06-24', 2022, '2022-06', 'Canada', 'Canada', '', 'Dairy', 'Gelato Artigianale al gusto di Raspberry Gelato', 'Norovirus', 'Other', 'Not Specified', 'Norovirus', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, contact your healthcare providerCheck to see if you have recalled productsDo not consume, serve, use, sell, or distribute recalled productsRecalled products should be thrown out or returned to the location where they were purchasedPeople with norovirus illness usually develop symptoms of gastroenteritis within&nbsp;24 to&nbsp;48 hours, but symptoms can start as early as&nbsp;12 hours after exposure. The illness often begins suddenly', '64310');
