INSERT INTO safety_incidents VALUES ('7cb58103d26f39db93956718e8ace27f311d97f7', 'Health Canada', '2022-06-23', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'SunVilla 10 foot Solar LED Market Umbrella', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled umbrella, and:• Remove the Solar Panel from the top of the umbrella• Store the panel out of the sun and away from combustible material • Do not charge the panel with the AC adapter Consumers may return the umbrella and solar panel puck to any Costco Warehouse for a full refund.&nbsp;Consumers that are unable to return the umbrella and puck to a Costco Warehouse can contact SunVilla.For more information, consumers can contact SunVilla by teleph', '64270');
INSERT INTO safety_incidents VALUES ('f3f0b7f5aa8367933d9a3cea1765b1d049d256a7', 'Health Canada', '2022-06-23', 2022, '2022-06', 'Canada', 'Canada', '', 'Clothing & Textiles', 'The Children’s Place Baby Boy Rompers', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled rompers away from children and contact The Children’s Place for instructions that describe how to return the product for a refund.For more information, consumers can contact The Children’s Place by telephone at 1‑877-827-7895, Monday to Friday from 9:00 a.m. to 5:00 p.m. EDT, or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and The Children’s Place.Please note that the Canad', '64279');
INSERT INTO safety_incidents VALUES ('4890355748d1be79731df75a3d6600d538a852ba', 'Health Canada', '2022-06-23', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'Coda Pendant by Tech Lighting, a brand of VC Brands', 'Injury', 'Other', 'Fracture / Blunt Trauma', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately prevent people from going under the recalled light fixtures and contact Tech Lighting to obtain a free repair kit.&nbsp; Consumers will need to schedule installation by a certified technician, and Tech Lighting will reimburse the consumer for the service. For more information, consumers can contact Tech Lighting toll-free at 888-475-1136 from 9 a.m. to 5 p.m. CT Monday through Friday, or by email at techlightingcs@visualcomfortco.com, or online and click on the recal', '64298');
