INSERT INTO safety_incidents VALUES ('db7f916091a9ae5e17f822a24f78d383bc4b0e78', 'Health Canada', '2022-06-21', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'Various unauthorized health products promoted for sexual enhancement', 'Undeclared Substance', 'Allergen', 'Not Specified', 'Undeclared substance', 'Serious', 0, 0, 'Stop using the products listed. Consult your health care professional if you have used these products and have health concerns, and for advice on which health products are best for you and your family.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check if products have been authorized f', '64296');
