INSERT INTO safety_incidents VALUES ('5eb233e0db2bccc4ea8e046ae052136aa811914e', 'Health Canada', '2022-06-19', 2022, '2022-06', 'Canada', 'Canada', '', 'Toys & Childcare', 'Certain powdered infant formula products', 'Salmonella - Other', 'Microbiological Contamination', 'Not Specified', 'Salmonella - Other', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled products in your home or establishmentDo not consume the recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Cronobacter sakazakii may not look or smell spoiled but can still make you sick. Although Cronobacter sakazakii is not commonly linked to human illness, in rare cases it can cause serious or fa', '64281');
INSERT INTO safety_incidents VALUES ('65809b863bf56ba5a237cea0caa74a710a61f05c', 'Health Canada', '2022-06-18', 2022, '2022-06', 'Canada', 'Canada', '', 'Oatmeal - Other', 'Certain smoothies and oats', 'Norovirus', 'Other', 'Not Specified', 'Norovirus', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have recalled productsDo not consume recalled productsRecalled products should be thrown out or returned to the location where they were purchasedPeople with norovirus illness usually develop symptoms of gastroenteritis within 24 to 48 hours, but symptoms can start as early as 12 hours after exposure. The illness often begins suddenly. Even after having the illness, you can still become re-infecte', '64280');
INSERT INTO safety_incidents VALUES ('1b5bbdc53bba83f6fe3d1c9c6e8a6d4d2ac7795e', 'Health Canada', '2022-06-17', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'Bugaboo Stardust Play Yard', 'Physical Hazard', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Physical hazard', 'Not Reported', 0, 0, 'Consumers should not use the bassinet inlay of the Bugaboo Stardust Play Yard without the accompanying mattress support board. Consumers should contact Bugaboo to receive a free kit to eliminate the possibility of removing the bassinet mattress support board.For more information, consumers can contact Bugaboo International BV by telephone at 1-800-460-2922, Monday to Friday from 7:00 a.m. to 4:00 p.m. Pacific Time, by email at service.us@bugaboo.com or visit the company website. French speaking ', '64254');
INSERT INTO safety_incidents VALUES ('314b2102d9f9c75e97d78dbdfa75ced8b11a2f57', 'Health Canada', '2022-06-17', 2022, '2022-06', 'Canada', 'Canada', '', 'Toys & Childcare', 'Wonder & Wise Baby Activity Push Walker', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled walkers away from children, stop using them until repaired and contact Asweets for instructions on getting free replacement rear wheels. Asweets is offering a free repair kit. For more information or to participate in the recall, consumers can contact Asweets by telephone &nbsp;at 833-422-2028 from 9:00 a.m. to 5:00 p.m. PT, Monday through Friday, by email at &nbsp;info@asweets.com, or visit the recall website at www.wonderandwise.com/recalls/activi', '64277');
INSERT INTO safety_incidents VALUES ('064213810471aabee46b561afe7794cb5bbae63e', 'Health Canada', '2022-06-17', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'The California Beach Co. Pop N’ Go Playpen', 'Fire', 'Entrapment', 'Entrapment', 'Entrapment hazard - Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the affected Pop N’ Go playpens and the included shade cover and safely dispose of them in accordance with local municipal waste requirements. Consumers can contact California Beach Company for a refund.For more information, consumers can contact California Beach Company by email at customerservice@thecaliforniabeachco.com or by telephone, toll-free, at 1-877-795-1772.Please note that the Canada Consumer Product Safety Act prohibits recalled products from ', '64278');
INSERT INTO safety_incidents VALUES ('b222c15f1bc7e90e4e2d4edb4dc88858bda7d59f', 'Health Canada', '2022-06-17', 2022, '2022-06', 'Canada', 'Canada', '', 'Other', 'Sesame Asian Style Dressing', 'Non Harmful (Quality Or Spoilage)', 'Other', 'Not Specified', 'Non harmful (quality or spoilage)', 'Minor', 0, 0, '', '64297');
INSERT INTO safety_incidents VALUES ('7b1810d4664b9f6800c3ed53adf298c453c37e48', 'Health Canada', '2022-06-16', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'Unauthorized skin cream, eye ointment and sexual enhancement products seized from three herbal medicine stores in Calgary, Alberta. [UPDATED June 16, 2022, to add products]', 'Product Safety - Unauthorized Product', 'Other', 'Eye Injury', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Do not use these products. Consult a health care professional if you have used any of these products and have health concerns.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check whether products have been authorized for sale by searching Health Canada''s&nbsp;Drug Product Database&nbsp;a', '64103');
INSERT INTO safety_incidents VALUES ('b5a0c97262ddb2ccb2810ccb55a4ea8adf3a4fcc', 'Health Canada', '2022-06-16', 2022, '2022-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Various Square D Plug on Neutral (PON) Loadcentres by Schneider Electric', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately contact Schneider Electric Canada to arrange for an inspection. For more information, consumers can contact Schneider Electric Canada by telephone at 1-888-778-2733, Monday through Sunday from 8:00 a.m. to 5:00 p.m. EST or visit the company website:&nbsp;http://se.com/us/qoloadcenter-safetynotice.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Schneider Electric Canada.Please note that the Canada Consumer Product Sa', '64216');
INSERT INTO safety_incidents VALUES ('2fc94f25c770b35ddbf653b36669379385cacc49', 'Health Canada', '2022-06-16', 2022, '2022-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'WarmWave and Hunter Oscillating Ceramic Tower Heaters', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and visit www.homeproductservice.com/recall to apply for full or partial product refund.For more information, consumers can contact Sienhua Group (North America) Inc. by email at 18inCeramicHeaterRecall@gmail.com.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Sienhua Group (North America) Inc.Please note that the Canada Consumer Product Safety Act prohibits recalled products from bei', '64269');
INSERT INTO safety_incidents VALUES ('e47d683b2ea369f1ed90fe6b50ac81f9e12394c2', 'Health Canada', '2022-06-16', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'Shop LC Personal Electric Space Heaters', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled electric space heaters and return the product to Shop LC. For more information, consumers can contact Shop LC toll-free at 877-899-0078 anytime, email at&nbsp;c​​​​​​​ustomerservice@shoplc.com&nbsp;or online at https://www.shoplc.com/productrecalls.html or www.shoplc.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to rem', '64272');
INSERT INTO safety_incidents VALUES ('3e893652cd4f635dafd8cad9633f37fc880ada3c', 'Health Canada', '2022-06-16', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'Nomad Hand Sanitizers', 'Undeclared Substance', 'Allergen', 'Not Specified', 'Undeclared substance', 'Moderate', 0, 0, 'Stop using the products identified in the table.Follow municipal or regional guidelines on how to dispose of chemicals and other hazardous waste; orReturn the product to your local pharmacy for proper disposalContact the company if you would like more information about the recallConsult your health care professional if you have used these products and have health concernsKeep all hand sanitizers out of the reach of children.Never eat or drink hand sanitizers, as swallowing even small amounts can', '64273');
INSERT INTO safety_incidents VALUES ('7b621b8e617dbed464fdbe510ff361cb58093ee6', 'Health Canada', '2022-06-16', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'Broadspectrum solar protection products', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Moderate', 0, 0, 'Stop using the recalled products. Consult a health care professional if you have used any of these products and have health concerns.Continue using other sunscreen as directed on the product label.Contact the company if you would like more details about the recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.Health Canada strongly encourages the use of&nbsp;sunscreens&nbsp;to protect against harmful UV radiation and provides&nbsp;general sun s', '64275');
INSERT INTO safety_incidents VALUES ('337ce780ddf06b66d970576d695b5b50dbd3fa21', 'Health Canada', '2022-06-15', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'ALLEN + ROTH Cellular Shades', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Cellular Shades and contact the company to request free replacement endcap kits.For more information, consumers can contact All Strong Industry Inc. by telephone at 1-877-804-5504, Monday to Friday from 8:30 am to 5:00 pm EST or by email at customerservice@lbgsales.com.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remin', '64271');
