INSERT INTO safety_incidents VALUES ('d1134f53059983b74d517820f64561cfcc79a200', 'Health Canada', '2022-06-10', 2022, '2022-06', 'Canada', 'Canada', '', 'Chemicals', 'Exothermic Designs Concrete Tabletop Fire Pits', 'Consumer Products', 'Flammability / Overheating', 'Not Specified', 'Consumer products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled fire pit and contact Exothermic Designs for more information. For more information, consumers may contact Exothermic Designs by telephone at 1-403-671-0867 Monday to Friday from 10:00 a.m. to 3:00 p.m. MT or by email at exothermicdesigns20@gmail.com to find out next steps.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to re', '64248');
