INSERT INTO safety_incidents VALUES ('120aec03e0835de2fcc1aa50f77ec1c4d662aa34', 'Health Canada', '2022-06-09', 2022, '2022-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Spirit Halloween 48” Black Light Fixture with Bulb', 'Fire', 'Flammability / Overheating', 'Burns', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Spirit Halloween 48” Black Light Fixture with Bulb and contact Spirit Halloween for a refund.Consumers should be prepared to send a photo of the model number located on the back of the light fixture to guest services to facilitate the full refund.&nbsp; For more information, consumers can contact Spirit Halloween toll free at 1-866-586-0155 from 9:00 am to 5:30 pm ET Monday to Friday or by&nbsp;email&nbsp;or&nbsp;online.Joint recall with Healt', '64119');
INSERT INTO safety_incidents VALUES ('290835daaca1050ce27e372b188e722fd86e9578', 'Health Canada', '2022-06-09', 2022, '2022-06', 'Canada', 'Canada', '', 'Toys & Childcare', 'Activity Loops', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Activity Loop.&nbsp; Consumers can return product to place of purchase, or contact Manhattan Toy, for a refund or credit.To arrange to return the product contact Manhattan Group LLC at 1-800-541-1345, Monday through Thursday between 8 AM and 4 PM (CST) and Friday between 8 AM and noon (CST).Joint recall with Health Canada, the United States Consumer Product Safety Commission &nbsp;(https://www.cpsc.gov/recalls/2022/the-manhattan-toy-company-re', '64193');
INSERT INTO safety_incidents VALUES ('887a049190fd678d59aa782549a71e1b514c7c00', 'Health Canada', '2022-06-09', 2022, '2022-06', 'Canada', 'Canada', '', 'Electrical & Electronics', '26.6 cubic-foot Hisense brand Bottom Freezer, French Door Refrigerators in Stainless Steel', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should contact Hisense Canada to schedule an appointment with a service technician to replace the refrigerator door hinges.For more information, consumers can contact Hisense Canada by telephone at 1-855-344-7367, Monday to Friday from 8:00 am to 8:00 pm ET, Saturday and Sunday from 9:00 am to 6:00 pm ET, or by email at canadasupport@hisense.com&nbsp;or visit the company website&nbsp;to schedule a service appointment.Joint recall with Health Canada, the United States Consumer Product S', '64218');
INSERT INTO safety_incidents VALUES ('f68c35b9378d057a69299cd0eb48ce49e61787c9', 'Health Canada', '2022-06-09', 2022, '2022-06', 'Canada', 'Canada', '', 'Vaping And Tobacco Products', 'Viceroy Smooth (Viceroy Velouté), Regular Size, 20 and 25 cigarettes', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact the distributor, Imperial Tobacco Canada Limited, to return the product for a replacement product.For more information, consumers can contact Imperial Tobacco Canada Limited in their official language of choice (French or English) by telephone 1-800-932-9326, Monday to Friday from 8 a.m. to 7 p.m. ET or visit the company website&nbsp;to file a complaint. Please note that the Canada Consumer Product Safety Act prohibits rec', '64249');
INSERT INTO safety_incidents VALUES ('90a42d21a3199f3b171cee72c15fcf8e8630b8c7', 'Health Canada', '2022-06-08', 2022, '2022-06', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Certain frozen bars', 'Milk - Sulphites - Tree Nut', 'Allergen', 'Not Specified', 'Milk - Sulphites - Tree nut', 'Serious', 0, 0, 'Check to see if you have the recalled products in your homeIf you have an allergy to hazelnut or milk or a sensitivity to sulphites, do not consume the recalled products as they may cause a serious or life-threatening reactionRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation', '64223');
