INSERT INTO safety_incidents VALUES ('e93a2821f86e3befbc11b8988f5960b2c6f99098', 'Health Canada', '2022-06-06', 2022, '2022-06', 'Canada', 'Canada', '', 'Furniture & Home', 'Lam Hiep Hanging Egg Chairs', 'Consumer Products', 'Instability / Fall Risk', 'Fall Injury', 'Consumer products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled hanging chair and return it to Winners, HomeSense or Marshalls for a refund.For more information, consumers can contact TJX Canada by telephone toll-free at 1-800-646-9466 between 9:00AM and 5:00PM EST Monday through Friday, or by visiting the Winners, HomeSense, or Marshalls websites. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada wo', '64227');
