INSERT INTO safety_incidents VALUES ('7d7637f43dbe7dc3d2e65190bb77fe19803538ee', 'Health Canada', '2022-06-03', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs - Natural Health Products', 'Various unauthorized health products promoted for sexual enhancement, weight loss, as a workout aid, as "poppers", or for lightening skin or treating skin conditions (such as eczema or psoriasis).', 'Unauthorized Product', 'Other', 'Not Specified', 'Unauthorized product', 'Not Reported', 0, 0, 'Stop using the products listed in the table. Consult your health care professional if you have used these products and have health concerns, and for advice on which health products are best for you and your family.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check if products have been', '78094');
INSERT INTO safety_incidents VALUES ('1ff87a3039ab7532d952998a1198a68702130471', 'Health Canada', '2022-06-02', 2022, '2022-06', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Leveret Cotton Terrycloth Hooded Bathrobes', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Cotton Terrycloth Hooded Bathrobes and destroy.&nbsp; Leveret will provide a full refund upon proof of destruction.For more information, consumers should contact Leveret by telephone at 844-338-3738, Monday through Friday between 8:00 a.m. and 5:00 p.m. ET, by e-mail: productrecall@leveret.com&nbsp;or on-line.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Leveret.Please note that the Canada ', '64038');
INSERT INTO safety_incidents VALUES ('ee4dd9d1e9dbbc430812dd6f4622f30acd0081a6', 'Health Canada', '2022-06-02', 2022, '2022-06', 'Canada', 'Canada', '', 'Household Items', 'Demdaco Microwavable Bowl Holders', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled bowl holders and contact their local Demdaco retailer to obtain a full refund. For more information, consumers can contact Demdaco by telephone at 1-888-336-3226 from 8:00 a.m. to 5:00 PM CST Monday to Friday. Press ''5'' when prompted to speak to a customer care representative.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and DemdacoPlease note that the Canada Consumer Product Safety Act prohibi', '64191');
INSERT INTO safety_incidents VALUES ('7a6b59a90ee570e86020273e73a45cf861b3599d', 'Health Canada', '2022-06-02', 2022, '2022-06', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Certain Frigidaire and Electrolux Side-by-Side and Four-door refrigerators', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately empty the ice bucket, stop using the ice makers on the recalled refrigerators and contact Electrolux to schedule a replacement of the ice maker with one that has a polypropylene ice level detector free of charge.To participate in the recall, consumers should visit https://www.icemakerrecall.ca. Consumers can also find this webpage on Frigidaire.ca or Electrolux.ca by clicking on “Recalls” at the bottom of the page. Alternatively, consumers can contact Electrolux toll', '64192');
INSERT INTO safety_incidents VALUES ('e772c0351f72cde14990ef6c08f53521d28b22b0', 'Health Canada', '2022-06-02', 2022, '2022-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Backcountry Access Tracker4 Avalanche Transceiver', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled transceiver and contact K2 Corporation of Canada  for a replacement product.For more information, consumers can contact K2 Corporation of Canada  by telephone at&nbsp;1-866-455-2748, by email or on the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission&nbsp;(US CPSC) and K2 Corporation of Canada.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redi', '64195');
INSERT INTO safety_incidents VALUES ('fdf2710182b0f29a4f293427064c79bbba6e89bd', 'Health Canada', '2022-06-02', 2022, '2022-06', 'Canada', 'Canada', '', 'Drugs', 'MONTELUKAST', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Moderate', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '64224');
