INSERT INTO safety_incidents VALUES ('4fe960c710b653ffc7bd3f46cf15cab9233c6396', 'Health Canada', '2022-05-05', 2022, '2022-05', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Various Infant Winter Water Factory products', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'Choking hazard - Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled garments, destroy the recalled garments by cutting them in half with scissors and upload a photo of the destroyed garments to the company’s website. &nbsp;When uploading the photo, consumers can decide whether to choose a full refund of the purchase price or a store credit with an additional 20% of the purchase price, or the full retail price, whichever is higher.For more information, consumers may contact Winter Water Factory by email&nbsp;or', '64125');
