INSERT INTO safety_incidents VALUES ('769529f8ee2292ed71171d637923954d6401a864', 'Health Canada', '2022-05-02', 2022, '2022-05', 'Canada', 'Canada', '', 'Natural Health Products', 'Bio-Calcium', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '64132');
INSERT INTO safety_incidents VALUES ('6d8c11bae2787b3d6b7b3b22d6e05c7db2871931', 'Health Canada', '2022-05-02', 2022, '2022-05', 'Canada', 'Canada', '', 'Nuts, Grains, And Seeds', 'Certain blue organic poppy seeds', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled product in your homeDo not consume the recalled productRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Salmonella may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serious and sometimes deadly infections. Heal', '64134');
INSERT INTO safety_incidents VALUES ('19e32905a549616e0192df698e5ea0f0a97c609e', 'Health Canada', '2022-04-29', 2022, '2022-04', 'Canada', 'Canada', '', 'Household Items', 'Household cleaning products, hand soaps and body soaps', 'Covid', 'Other', 'Not Specified', 'COVID', 'Not Reported', 0, 0, 'Continue to purchase household cleaning products, hand soaps and body soaps as you have been while practising physical distancing. This interim policy will help ensure that adequate supply continues to be available in Canada. The risk to Canadians of allowing non-compliant labels is low, as long as consumers use these products as directed.Wash your hands often with soap and water for at least 20 seconds, especially after using the washroom and when preparing food.Use an alcohol-based&nbsp;hand s', '63338');
