INSERT INTO safety_incidents VALUES ('83f4ab361ccf693a05d004414a50340b45285297', 'Health Canada', '2022-04-29', 2022, '2022-04', 'Canada', 'Canada', '', 'Household Items', 'AmazonBasics School Classroom Stack Chairs', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled chairs and contact Amazon for instructions on how to dispose of the chairs for a full refund. Amazon is contacting all known purchasers directly.For more information, consumers can contact Amazon toll-free at 877-882-0606 from 8 a.m. to 5 p.m. ET Monday through Friday or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Healt', '64121');
