INSERT INTO safety_incidents VALUES ('505e49275e13115b9ab4d8ed5dcc602ccc508b7b', 'Health Canada', '2022-04-28', 2022, '2022-04', 'Canada', 'Canada', '', 'Household Items', 'DR Power Brand & Generac Brand electric start pressure washers', 'Poisoning Hazard', 'Explosion', 'Poisoning / Ingestion', 'Poisoning hazard', 'Not Reported', 0, 0, 'Consumers should&nbsp;immediately stop using the recalled pressure washer unless they have removed the rechargeable battery, and contact Generac to arrange to have an authorized dealer replace the start/stop switch on the pressure washer free of charge. The pressure washer can continue to be used with the battery removed but using the pull-start option to start the unit. For more information, consumers can contact Generac by telephone 855-625-2933 or visit the company website www.generac.com/est', '64116');
