INSERT INTO safety_incidents VALUES ('e3eff3079bc97a23969a010ff9968c57b3766f85', 'Health Canada', '2022-04-22', 2022, '2022-04', 'Canada', 'Canada', '', 'Other', 'Baby Trend Activity Walkers', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled baby walkers and contact Triplenet Pricing Inc. for instructions on how to obtain a refund. For more information, consumers can contact Triplenet Pricing Inc. by telephone at 1-301-330-9594 &nbsp;from 9:00 a.m. to 5:00 p.m. ET Monday through Friday,&nbsp;or by email &nbsp;at customerservice@triplenetpricing.comPlease note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away i', '64101');
INSERT INTO safety_incidents VALUES ('c571b338e2f1320ecb5f4294d418087a8b503339', 'Health Canada', '2022-04-22', 2022, '2022-04', 'Canada', 'Canada', '', 'Electrical & Electronics', '12/2 NMD90 75M Romex SIMpull cable (yellow)', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately check the time stamp on the product to identify if the cable is included in the recall and immediately stop using the recalled product.Consumers with any questions can also call Southwire Canada''s toll-free support line at 1-833-408-0463, from Monday through Friday, 8 AM to 7 PM EST, for assistance in English or French.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health', '64102');
