INSERT INTO safety_incidents VALUES ('2428126b3a625ad2fc0d40b9126369f32df933b3', 'Health Canada', '2022-04-21', 2022, '2022-04', 'Canada', 'Canada', '', 'Drugs', 'Accupril (quinapril hydrochloride) and Accuretic (quinapril hydrochloride and hydrochlorothiazide)', 'Contamination', 'Explosion', 'Not Specified', 'Contamination', 'Not Reported', 0, 0, 'Continue taking your medication unless you have been advised to stop by your health care provider. Not treating your condition may pose a greater health risk.Contact your health care provider to discuss other treatment options. There is currently a reduced supply of combination quinapril hydrochloride and hydrochlorothiazide nationally; however, other drug products are available for treating high blood pressure.If you have questions about the recall, contact Pfizer Canada ULC at 1-800-463-6001 o', '63962');
INSERT INTO safety_incidents VALUES ('60f5c3bc9ee99a39ec7d651185486b0fbe26d91f', 'Health Canada', '2022-04-21', 2022, '2022-04', 'Canada', 'Canada', '', 'Kitchenware And Tableware', 'Norwex Ceramic Knives', 'Consumer Products', 'Sharp Edges / Points', 'Laceration / Cut', 'Consumer products', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled knives and contact Norwex for instructions describing the process to return the product for a product of equal or greater value.For more information, consumers can contact Norwex by telephone toll-free at 1-877-766-7939 or by email at&nbsp;cndnorwexservice@norwex.com.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Norwex Canada Inc.Please note that the Canada Consumer Product Safety Act prohi', '64085');
INSERT INTO safety_incidents VALUES ('834ef3663abcb335aae4131be240598d0506368a', 'Health Canada', '2022-04-21', 2022, '2022-04', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Insignia Air Fryers and Air Fryer Oven', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled air fryers and air fryer ovens and visit https://www.recallrtr.com/airfryer to register for the recall. If you need assistance or have questions on how to participate, please call Best Buy at 800-566-7498 from 7:30 a.m. to 5 p.m. CT Monday through Friday for instructions. &nbsp;The consumer will receive a refund in the form of a credit for use at Best Buy Canada. The consumer&nbsp;should&nbsp;not&nbsp;return the recalled air fryers and air fry', '64096');
