INSERT INTO safety_incidents VALUES ('23092f80768ee2ccb31602247f2128fe74fd225d', 'Health Canada', '2022-04-21', 2022, '2022-04', 'Canada', 'Canada', '', 'Natural Health Products', 'The Newfoundland Distillery Company - Fighting Spirit', 'Product Safety - Covid', 'Other', 'Not Specified', 'Product safety - COVID', 'Moderate', 0, 0, 'Stop using the products identified in the table.Follow municipal or regional guidelines on how to dispose of chemicals and other hazardous waste; orReturn the product to your local pharmacy for proper disposalContact the company if you would like more information about the recallConsult your health care professional if you have used these products and have health concernsKeep all hand sanitizers out of the reach of children.Never eat or drink hand sanitizers, as swallowing even small amounts can', '64099');
