INSERT INTO safety_incidents VALUES ('0430b90b1c311a08631caf5634723cdb192106d1', 'Health Canada', '2022-04-14', 2022, '2022-04', 'Canada', 'Canada', '', 'Electrical & Electronics', '36” wide GE-brand Free-Standing French Door Refrigerators in Fingerprint Resistant Stainless Steel', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should contact MC Commercial Inc. for a free inspection and repair. Once inspected or repaired, the product can continue to be used, sold or redistributed.For more information, consumers may contact MC Commercial Inc. online, or by phone at 1-833-607-3322 between 8 a.m. and 5 p.m. ET Monday through Friday for an inspection.Joint recall with Health Canada, the United States Consumer Product Safety Commission and&nbsp;MC Commercial Inc.Please note that the Canada Consumer Product Safety ', '63961');
INSERT INTO safety_incidents VALUES ('4ab5d6cf5605c43e04302534bb395d672a97d2b2', 'Health Canada', '2022-04-14', 2022, '2022-04', 'Canada', 'Canada', '', 'Sports & Leisure', 'Shell Diving Drysuit Inflation Valve with International Nipple', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using drysuits with the recalled inflation valve and contact Ocean Equipment to return the affected valve for a free valve part replacement.For more information, consumers can contact Ocean Equipment by telephone at 1-800-657-7736 from 9 a.m. to 4 p.m. PT (Monday through Friday), by email or visit the company’s recall notice on their website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and SI TECH AB.Please note', '64051');
INSERT INTO safety_incidents VALUES ('ec312ffa89554f5cd95e9b98927653cc42b61d26', 'Health Canada', '2022-04-14', 2022, '2022-04', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Crafter’s Square Mini Hot Glue Gun', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Crafter’s Square Mini Hot Glue Gun and return the affected product to any Dollar Tree store location for a full refund.For more information, consumers  may contact Dollar Tree by telephone at 800-876-8697 from 9 a.m. to 5 p.m. ET Monday through Friday, by email at recalls@dollartree.com or visit the company website at https://www.dollartree.com/product-recalls or at www.dollartree.com and click on “Recall Information” at the bottom of the page', '64079');
