INSERT INTO safety_incidents VALUES ('225bcd7496c8497e939de5c87bcd32533d2c86e6', 'Health Canada', '2022-04-08', 2022, '2022-04', 'Canada', 'Canada', '', 'Cannabis', 'Emblem CBD 100 Cannabis Extract, Lot 3848-2', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'No action is required. If, however, you wish to return affected product, please contact Emblem Cannabis Corporation at hi@emblemcannabis.com or 1-844-546-3633.&nbsp;Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.&nbsp;', '64056');
INSERT INTO safety_incidents VALUES ('3a28a8bef5e4386ed71236b0516d2f472938a0e2', 'Health Canada', '2022-04-08', 2022, '2022-04', 'Canada', 'Canada', '', 'Other', 'Interactive Baby Walker with Music 4 Height Adjustable (Green) Anti-Rollover Child Walker and Adjustable Baby Walker with Easy Clean Tray, Universal Wheeled Walker (Black)', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Dimaobaihuo by email at dimaobaihuo@hotmail.com or by telephone at&nbsp;+8613834531327 for instructions for a refund.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by', '64060');
INSERT INTO safety_incidents VALUES ('154801078ecc53099755a5637e8c07b444eaa39c', 'Health Canada', '2022-04-08', 2022, '2022-04', 'Canada', 'Canada', '', 'Herbs And Spices', '"Mix Voor Nasi & Bami Goreng"', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled product in your homeDo not consume the recalled productRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Salmonella may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serious and sometimes deadly infections. Heal', '64062');
INSERT INTO safety_incidents VALUES ('c644accfa552b70feb204fd10af78a57cb6cf446', 'Health Canada', '2022-04-07', 2022, '2022-04', 'Canada', 'Canada', '', 'Household Items', 'Stokke® Clikk™ High Chair in White', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'Fall hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled high chair and visit Stokke LLC’s website to determine whether their Clikk™  high chair in white is affected by the recall. Consumers who own affected products will be asked to register for the recall online. The Firm will arrange for delivery of a replacement chair and the pickup of the recalled chair. For more information, consumers can contact Stokke LLC by telephone at 1-877-978-6553 from 9 a.m. to 8 p.m. ET, Monday through Friday, by emai', '64032');
INSERT INTO safety_incidents VALUES ('0419bcb7ba1fa4fd94f3ed6e6ea0bed53ba24fb9', 'Health Canada', '2022-04-07', 2022, '2022-04', 'Canada', 'Canada', '', 'Furniture & Home', 'Bestar Wall Beds', 'Injury', 'Entrapment', 'Entrapment', 'Entrapment hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled wall beds and contact Bestar to determine whether they require a repair via reinstallation. Consumers who are uncertain whether their wall bed needs to be reinstalled are entitled to a free inspection.&nbsp; If the bed requires reinstallation, consumers are advised to use a professional installer. Bestar will reimburse consumers for the reinstallation cost and expects that cost to range from CAD $216 - $263 for Above Top Shelf wall beds or CAD', '64034');
INSERT INTO safety_incidents VALUES ('ed824d128906d82c79f542fed3351afe5a0b1ed3', 'Health Canada', '2022-04-07', 2022, '2022-04', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Celebright Lighting System', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately unplug the product and contact Celebright Inc. to have the product retrofitted.&nbsp; The unit should remain unplugged, until the system is retrofitted with the certified components.For more information, consumers can contact Celebright Inc. by telephone at 613-800-9006, Monday to Friday from 8:30 a.m. to 4:00 p.m. ET or by email at hello@celebright.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold o', '64052');
INSERT INTO safety_incidents VALUES ('41756117ef327cdd1af53bbb8ac2a4f065a443b0', 'Health Canada', '2022-04-06', 2022, '2022-04', 'Canada', 'Canada', '', 'Clothing & Textiles', 'AOSKERA Children’s Nightgowns', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and dispose.For more information, consumers can contact Amazon through the&nbsp;company''s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by filling out the Consumer Produc', '64050');
INSERT INTO safety_incidents VALUES ('e85b04bee3b92d384eea77e3bb9e99bd4bbbfe0e', 'Health Canada', '2022-04-06', 2022, '2022-04', 'Canada', 'Canada', '', 'Veterinary Drugs', 'ORBAX', 'Labelling', 'Other', 'Not Specified', 'Labelling', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '64053');
INSERT INTO safety_incidents VALUES ('f28a1c368c096f0565744788144f5aca7d7c55ac', 'Health Canada', '2022-04-06', 2022, '2022-04', 'Canada', 'Canada', '', 'Medical Devices', 'Breast implants', 'New Safety Information', 'Other', 'Not Specified', 'New safety information', 'Not Reported', 0, 0, 'If you have an Allergan Biocell breast implant or another type of breast implant:Removing your breast implants is not recommended if you do not have any signs or symptoms suggesting BIA-ALCL. Discuss the risks and benefits of removal with your healthcare professional, keeping in mind that:BIA-ALCL is usually slow-growing and, when diagnosed at early stages, is highly treatableThere are risks associated with surgery to remove or replace breast implantsRemoval of the breast implants may not elimin', '64057');
INSERT INTO safety_incidents VALUES ('6e2f9ef2428dc0c53860ba1739564df1897d72c3', 'Health Canada', '2022-04-06', 2022, '2022-04', 'Canada', 'Canada', '', 'Candy, Confectionary, Snacks And Sweeteners', 'Certain chocolate products', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled products in your homeDo not consume the recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Salmonella may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serious and sometimes deadly infections. He', '64058');
