INSERT INTO safety_incidents VALUES ('54b343294499f25fb2a996b2312534617abc54ea', 'Health Canada', '2022-04-05', 2022, '2022-04', 'Canada', 'Canada', '', 'Consumer Products', 'Vertbaudet Hearts children’s bathrobe, light pink with white hearts.', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Immediately stop using this children’s bathrobe and dispose of the product.General children’s sleepwear safety tips:Dress children in actual sleepwear when putting them to bed.Make sure any belts, ties or sashes on children''s robes are stitched firmly to the centre back of these products.Check for loose buttons or other small parts that could become a choking hazard.Check sleepers and blankets regularly for loose threads, and fix them immediately.', '64049');
