INSERT INTO safety_incidents VALUES ('7361412d4967ba79a2ba41e390a92feeafbb7c51', 'Health Canada', '2022-03-25', 2022, '2022-03', 'Canada', 'Canada', '', 'Tools & Machinery', 'Yardworks 15-Amp Electric Corded Snowblower, 22-in', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Electrical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and return them to any Canadian Tire Store for a full refund.For more information, consumers may contact the Canadian Tire Call Centre by telephone at 1-800-387-8803.&nbsp; The call centre is open Monday to Friday from 8:00 a.m. to 9:00 p.m. EST and on Saturday and Sunday from 9:00 a.m. to 5:00 p.m. EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away', '64018');
INSERT INTO safety_incidents VALUES ('ded06afb333d1ed60870f5dea0f03bc664dc6920', 'Health Canada', '2022-03-25', 2022, '2022-03', 'Canada', 'Canada', '', 'Household Items', 'Prepworks by Progressive Nut Chopper recalled due to potential injury hazard', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled nut chopper and contact the place of purchase for instructions on how to return the product for a full refund.For more information, only consumers who purchased the nut chopper at Lee Valley Tools from December 2018 to October 2019 with proof of purchase can contact them by telephone toll-free at 1-800-267-8761, Monday to Friday from 9:00 a.m. to 5:30 p.m. EST and Saturdays from 9:00 a.m. to 5:00 pm EST, or by email. Do not contact Lee Valley ', '64019');
INSERT INTO safety_incidents VALUES ('da19d117382a85cf9b98150d445c5c6f22b5ec8c', 'Health Canada', '2022-03-25', 2022, '2022-03', 'Canada', 'Canada', '', 'Food & Food Contact', 'Various baked goods', 'Salmonella', 'Microbiological Contamination', 'Not Specified', 'Salmonella', 'Moderate', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled products in your homeDo not consume the recalled productsRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with Salmonella may not look or smell spoiled but can still make you sick. Young children, pregnant women, the elderly and people with weakened immune systems may contract serious and sometimes deadly infections. He', '64022');
INSERT INTO safety_incidents VALUES ('0841523af8f49242ba33a957392ae7234bf85d73', 'Health Canada', '2022-03-24', 2022, '2022-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Dimensions Bluetooth Speaker Helmets', 'Impact Hazard', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled helmets and contact Sakar International, Inc. for a free replacement helmet.For more information, consumers can contact Sakar International, Inc. by telephone anytime at 800-592-9541, by email at support@sakar.com, or visit the company website or www.vivitar.com and click on "Recalls" at the bottom of the page.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC)&nbsp;https://www.cpsc.gov/Recalls/2022/', '63963');
INSERT INTO safety_incidents VALUES ('2c7819fab1d09af2ff0dd743c98370a3e583be8a', 'Health Canada', '2022-03-24', 2022, '2022-03', 'Canada', 'Canada', '', 'Radiopharmaceuticals', 'NETSPOT', 'Product Quality', 'Other', 'Not Specified', 'Product quality', 'Minor', 0, 0, 'Verify if your product is affected.Consult your healthcare provider prior to discontinuing use of the affected product(s), or for any health concerns.Contact the recalling firm if you have any questions about the recall.Report any health product&nbsp;related&nbsp;side effects&nbsp;to Health Canada.Report any other health product safety&nbsp;complaints&nbsp;to&nbsp;Health Canada.', '64016');
