INSERT INTO safety_incidents VALUES ('53f86e54412fd0bd7f4cdd936f265adf8d729fc6', 'Health Canada', '2022-03-22', 2022, '2022-03', 'Canada', 'Canada', '', 'Other', 'Vegetarian Mushroom Jerky (Hot)', 'Milk', 'Allergen', 'Not Specified', 'Milk', 'Serious', 0, 0, 'Check to see if you have the recalled product in your homeIf you have an allergy to milk, do not consume the recalled product as it may cause a serious or life-threatening reactionRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safety investigation and recall processReport a food safety or lab', '64015');
