INSERT INTO safety_incidents VALUES ('34ed81ea31fd4245a955601f8a0b92e1e006f2c5', 'Health Canada', '2022-03-16', 2022, '2022-03', 'Canada', 'Canada', '', 'Toys & Childcare', 'B. toys Wooden Activity Toddler Walker - Walk ''n'' Learn', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled toy and use pliers or an adjustable wrench to check the tightness of the bolts and nuts securing the wheels. If needed, consumers can request a repair kit from Battat at no extra costs, which will include the tools and hardware needed to complete the repair.For more information, consumers may contact Maison Battat Inc. at 1-844-963-2479 between 9:00 a.m. and 4:30 p.m. ET Monday through Friday, by email at recalls@battatco.com or by visiting th', '63897');
