INSERT INTO safety_incidents VALUES ('bc8644a05aa1e9a57d9d9d6626d7fe35abf0119d', 'Health Canada', '2022-03-12', 2022, '2022-03', 'Canada', 'Canada', '', 'Other', 'Classic Hash Brown Patties, Potato Patties', 'Gluten - Wheat', 'Allergen', 'Not Specified', 'Gluten - Wheat', 'Serious', 0, 0, 'Check to see if you have the recalled products in your homeIf you have an allergy to wheat or have celiac disease or other gluten-related disorders, do not consume the recalled products as they may cause a serious or life-threatening reactionRecalled products should be thrown out or returned to the location where they were purchasedLearn more:Learn more about common food allergiesSign up for recall notifications by email and follow us on social mediaView our detailed explanation of the food safe', '63979');
INSERT INTO safety_incidents VALUES ('84ba38e8b7f302fa86a552879b36716e5df01602', 'Health Canada', '2022-03-11', 2022, '2022-03', 'Canada', 'Canada', '', 'Health Products', 'Over-the-counter and prescription ranitidine drugs (LATEST UPDATE: March 11, 2022 – Pharmascience Inc. recall)', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'Talk to your doctor or pharmacist at your earliest convenience about alternative, non-ranitidine treatment options appropriate for your health circumstances. There are many prescription and over-the-counter drug alternatives in Canada that are authorized for the same or similar uses as ranitidine.Individuals taking a prescription ranitidine drug, including a recalled product,&nbsp;should not stop&nbsp;taking it unless they have spoken to their health care provider and obtained alternative treatm', '59609');
