INSERT INTO safety_incidents VALUES ('ee412294b38ed387a768c10aab6d0723a128090b', 'Health Canada', '2022-03-09', 2022, '2022-03', 'Canada', 'Canada', '', 'Toys & Childcare', 'Crate and Kids Be the Band Music set', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Crate and Barrel for further steps.For more information, consumers can contact Crate and Barrel by telephone at 1-800-967-6696, by text at 312-779-1979 from 8 a.m. to 7 p.m. CT Monday to Friday, or 8 a.m.to 6 p.m. CT Saturday and Sunday; or online at www.crateandbarrel.com and click on “Recalls” located at the bottom of the page for more information.Joint recall with Health Canada, the United States Consumer Product Safety ', '63953');
INSERT INTO safety_incidents VALUES ('a95134c086ec7d6e736a5b5cd268b9c0632c92dd', 'Health Canada', '2022-03-09', 2022, '2022-03', 'Canada', 'Canada', '', 'Chemicals', 'Giant Value Drain Opener - 900mL', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and return it to any Giant Tiger store to obtain a refund or safely dispose of the product in accordance with local municipal hazardous waste requirements.For more information, consumers can contact Giant Tiger Stores Ltd. by telephone at 1-833-848-4437 (Toll Free) Monday to Friday, 9 a.m. to 9 p.m. EST; Saturday and Sunday, 9 a.m. to 6 p.m. EST or visit the company website https://www.gianttiger.com/contact-us. Service is available in', '63970');
