INSERT INTO safety_incidents VALUES ('edd6b2a1d5dd34c3f2335f93107564647fef00da', 'Health Canada', '2022-03-04', 2022, '2022-03', 'Canada', 'Canada', '', 'Cosmetics & Personal Care', 'Bioderma Sensibio H2O Micellar water makeup remover 850 ml', 'Microbial Hazard', 'Drowning Risk', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products.To determine whether they are in possession of an affected product and to find out how they can get a refund and dispose of the product, consumers can visit the website https://www.bioderma.ca/en/product-withdrawal-recall-info&nbsp;or call 1-514-270-3763 option 1, Monday to Friday, 9:00 a.m. to 5:00 p.m. EST. &nbsp;Please note that, in addition to the requirements of the Cosmetic Regulations, the Food and Drugs Act (FDA) prohibits the', '63952');
INSERT INTO safety_incidents VALUES ('8680267030c32aa96049c17b1dc7983f7228f277', 'Health Canada', '2022-03-04', 2022, '2022-03', 'Canada', 'Canada', '', 'Cannabis', 'Truro CBD 3:2 510 Vape Cartridge cannabis extract, Lot TC052101', 'Labelling And Packaging', 'Other', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'No action is required by consumers. If, however, you wish to return affected product, please contact the retail store where the product was purchased.Health Canada would like to remind Canadians to report any health or safety complaints related to the use of this cannabis product or any other cannabis product by filling out the online complaint form.', '63957');
INSERT INTO safety_incidents VALUES ('f88132c039aa51ea0d5dd3b53b019a1c19eaf3a9', 'Health Canada', '2022-03-04', 2022, '2022-03', 'Canada', 'Canada', '', 'Drugs', 'Accuretic (quinapril hydrochloride and hydrochlorothiazide)', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Serious', 0, 0, 'Continue taking your medication&nbsp;unless&nbsp;you have been advised to stop by your health care provider. Not treating your condition may pose a greater health risk.Contact your health care provider to discuss other treatment options. There is currently a reduced supply of combination quinapril hydrochloride and hydrochlorothiazide nationally; however, other drug products are available for treating high blood pressure.If you have questions about the recall, contact Pfizer Canada ULC at 1-800-', '63960');
