INSERT INTO safety_incidents VALUES ('9175e44b586a44beaccad8279d1eaf39fde16171', 'Health Canada', '2022-03-02', 2022, '2022-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Petzl PIRANA descenders', 'Drowning', 'Drowning Risk', 'Drowning', 'Drowning hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled descenders and contact Petzl America, Inc. for a refund.For more information, consumers can contact Petzl America, Inc. by telephone at 800-932-2978 from Monday to Friday between 8:00 a.m. to 4:00 p.m. MST, by email at returns@petzl.com, or visit the company website.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Petzl America, Inc.Please note that the Canada Consumer Product Safety Act prohi', '63934');
INSERT INTO safety_incidents VALUES ('0b14093ccab50675947201b1f392e9022d6a7a19', 'Health Canada', '2022-03-02', 2022, '2022-03', 'Canada', 'Canada', '', 'Sports & Leisure', 'Ionic smartwatch', 'Burns', 'Other', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Ionic smartwatch and contact Fitbit LLC for a refund.For more information, consumers can contact Fitbit LLC by telephone at 1-888-925-1764 (toll free) or 213-328-5250 (toll) or online at www.help.fitbit.com/ionic,&nbsp;or www.fitbit.com&nbsp;and click on “Product Help” at the bottom of the page for more information or www.fitbitionic.expertinquiry.com.Joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPS', '63951');
