INSERT INTO safety_incidents VALUES ('7b2e4cf0b4b349ef96d549c95f2175f0856e8f7f', 'Health Canada', '2022-03-02', 2022, '2022-03', 'Canada', 'Canada', '', 'Household Items', 'Savaria and Garaventa branded Residential Elevators with exterior swing-style landing (hoistway) doors', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately block children''s access to the residential elevators. If the hazard exists, Savaria / Garaventa will send consumers space guards at no cost to the consumer. Support with measurement and installation is available from the company upon request. For more information, consumers can contact Savaria by telephone toll-free at 1-855-983-5520 from 8:00 a.m. to 5:00 p.m. ET, Monday through Friday, or visit the company’s recall information website&nbsp;for instructions and vide', '63958');
INSERT INTO safety_incidents VALUES ('9514df155673fd55ec6d37a65dfbc18e7ad38116', 'Health Canada', '2022-03-02', 2022, '2022-03', 'Canada', 'Canada', '', 'Drugs', 'Inderal-LA (propranolol hydrochloride) extended release capsules, in 60 mg, 80 mg, 120 mg and 160 mg strengths', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Serious', 0, 0, 'Contact your health care provider to discuss other treatment options, as there are no other companies marketing extended release propranolol in Canada.Continue taking your medication&nbsp;unless&nbsp;you have been advised to stop by your health care provider. Not treating your condition poses a greater health risk.Contact Pfizer Canada ULC at 1-800-463-6001 or&nbsp;www.pfizermedinfo.ca&nbsp;for medical inquiries and at 1-800-387-4974 for general inquiries if you have questions about the recall.R', '63959');
INSERT INTO safety_incidents VALUES ('9a18564119dc9b06165e7d8896ab539de3e440d9', 'Health Canada', '2022-03-01', 2022, '2022-03', 'Canada', 'Canada', '', 'Drugs', 'Inderal-LA (propranolol hydrochloride) extended release capsules, in 60 mg, 80 mg, 120 mg and 160 mg strengths', 'Contamination', 'Other', 'Not Specified', 'Contamination', 'Not Reported', 0, 0, 'Contact your health care provider to discuss other treatment options, as there are no other companies marketing extended release propranolol in Canada.Continue taking your medication unless you have been advised to stop by your health care provider. Not treating your condition poses a greater health risk.Contact Pfizer Canada ULC at 1-800-463-6001 or www.pfizermedinfo.ca for medical inquiries and at 1-800-387-4974 for general inquiries if you have questions about the recall.Report any health pro', '63956');
