INSERT INTO safety_incidents VALUES ('be11641fef9fe05443083accbcb47367cecf7fdb', 'Health Canada', '2022-02-24', 2022, '2022-02', 'Canada', 'Canada', '', 'General Hospital And Personal Use', 'COVID-19 rapid antigen test kits', 'New Safety Information - Increased Risk Or New Adverse Events - Covid', 'Chemical / Toxic Substance', 'Not Specified', 'New safety information - Increased risk or new adverse events - COVID', 'Not Reported', 0, 0, 'Keep rapid antigen test kits and solutions out of the reach of children and pets.Do not swallow the solutions, and avoid eye and skin contact.Wash hands thoroughly after use. If spillage occurs, rinse well with water. Follow all instructions for proper disposal. Report any health product-related side effects or complaints to Health Canada.Contact your local Poison Information Centre in cases of accidental ingestion of chemicals or direct skin exposure.', '63947');
INSERT INTO safety_incidents VALUES ('3efca40952256297324c326512eee002b6224045', 'Health Canada', '2022-02-23', 2022, '2022-02', 'Canada', 'Canada', '', 'Consumer Products', 'Bebe au Lait Wooden Teether Rings', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the teether. Consumers are directed to cut the string of the teether and take a photograph of it before discarding it in the trash. Consumers can submit the online form together with the photograph to obtain a refund or credit. Consumers should contact the Company by emailing: recall@bebeaulait.com or online at www.bebeaulait.com and click on “Safety Recalls” at the bottom of the page.&nbsp; Consumers may view the release by the US CPSC on the Commission’s', '63697');
