INSERT INTO safety_incidents VALUES ('20c09e07b8c9339da1401a489786e4dd4e630ec8', 'Health Canada', '2022-02-17', 2022, '2022-02', 'Canada', 'Canada', '', 'Toys & Childcare', 'Lovevery Drinking Cup with handle in “The Inspector” Play Kits', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled drinking cups away from children, stop using them, and contact Lovevery for a free replacement cup. Consumers will receive a free replacement cup after registering on the firm’s website, uploading a photo of their defaced cup with “X Recalled X” written inside of the cup with a permanent marker and affirming to the firm that the cup will be recycled according to local guidelines, or disposed of in the trash.For more information, consumers can contac', '63931');
