INSERT INTO safety_incidents VALUES ('dac87dda1a3f1ff5636a13681198ad33c229fa98', 'Health Canada', '2022-02-16', 2022, '2022-02', 'Canada', 'Canada', '', 'Household Items', 'Anecdote Autumn Glass Double Wick Candles; Sold exclusively at Anthropologie', 'Fire', 'Sharp Edges / Points', 'Laceration / Cut', 'Fire hazard - Laceration hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the candle and return it to an Anthropologie store. If the candle cannot be returned in store, consumers should visit www.anthropologie.com/recall for instructions on how to cut the candle wicks, provide verification of this to Anthropologie, and receive a full refund.For more information, consumers can contact Anthropologie by telephone at 1 (844) 387-3164 or by email at recall@urbn.com.Joint recall with Health Canada, the United States Consumer Product S', '63915');
