INSERT INTO safety_incidents VALUES ('de53bc86ceccb93f36b4dc4edf93d9c7e14d2783', 'Health Canada', '2022-02-03', 2022, '2022-02', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Joe Boxer Children’s Fleece Robe recalled due to Flammability Hazard', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the Children’s Fleece Robe and discard, or return to Joe Boxer for a full refund.For more information, consumers can contact Joe Boxer by telephone at 1-800 268-7939 Monday to Friday from 9:00 am to 5:00 pm EST, or by email at recall@caulfeild.com. Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health o', '63885');
INSERT INTO safety_incidents VALUES ('e943907d2e9a7055412ea6a557c36b2d83a592f9', 'Health Canada', '2022-02-03', 2022, '2022-02', 'Canada', 'Canada', '', 'Household Items', 'Harbor Breeze Belleisle Bay 52-inch Ceiling Fan', 'Injury', 'Other', 'Fracture / Blunt Trauma', 'Impact hazard - Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled fans and contact Hong Kong China Electric Appliance Manufacture Company (HKC) for instruction on how to receive a replacement. For more information, consumers may contact Hong Kong China Electric Appliance Manufacture Company (HKC) by telephone at 1-888-232-9895 between 8 a.m. and 8 p.m. EST Monday through Friday or by email at ceilingfanrecall@sedgwick.com or visit the company’s website at www.ceilingfanrecall.expertinquiry.com. Please note t', '63886');
