INSERT INTO safety_incidents VALUES ('d7a044d009ac5518745f6d6b0159c1f5f7d953b5', 'Health Canada', '2022-02-02', 2022, '2022-02', 'Canada', 'Canada', '', 'Chemicals', 'Hestia Canada Table Top Fire Pit Bowl', 'Burns', 'Flammability / Overheating', 'Burns', 'Burn hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by filling out the Consumer Product Incident Report Form.This recall is also posted on the OECD Global Portal on Product Recalls web', '63872');
