INSERT INTO safety_incidents VALUES ('fc870cdcec10c2cf8fec69e8dec1135e338c9748', 'Health Canada', '2022-02-01', 2022, '2022-02', 'Canada', 'Canada', '', 'Natural Health Products', 'Unauthorized Ayurvedic medicinal products sold by Kerela Ayurvedic & Natural Herbal Consultation in Toronto, ON. Health Canada received a report of heavy metal poisoning following use of products obtained from this clinic.', 'Product Safety - Unauthorized Product', 'Chemical / Toxic Substance', 'Poisoning / Ingestion', 'Product safety - Unauthorized product', 'Not Reported', 0, 0, 'Stop using Ayurvedic medicinal products sold by this clinic. Consult a health care professional if you have used any of these products and have health concerns.Read product labels to verify that health products have been authorized for sale by Health Canada. Authorized health products have an eight-digit Drug Identification Number (DIN), Natural Product Number (NPN) or Homeopathic Drug Number (DIN-HM). You can also check whether products have been authorized for sale by searching Health Canada''s', '63636');
