INSERT INTO safety_incidents VALUES ('5294058eaf4292ede0dd1b2c44abbd101cd1105a', 'Health Canada', '2022-01-28', 2022, '2022-01', 'Canada', 'Canada', '', 'Sports & Leisure', 'Matrix T1xe (TM522), Matrix T3x (TM509), and T3x (TM523) Treadmills', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should stop using and unplug the units and contact Johnson Health Tech North America to schedule a service technician to visit the consumer’s home to install a power cord keeper on the treadmill.Consumers can contact the company by telephone at 1-866-218-3674 from 8 a.m. to 5 p.m. CT Monday through Friday. This is a joint recall with Health Canada, the United States Consumer Product Safety Commission (US CPSC) and Johnson Health Tech North America.&nbsp;Consumers may view the release b', '63800');
INSERT INTO safety_incidents VALUES ('97adaa44cb9fc6919249969a4ab9847ea4889a13', 'Health Canada', '2022-01-28', 2022, '2022-01', 'Canada', 'Canada', '', 'Other', 'Original Kimchi', 'E. Coli O157:H7', 'Microbiological Contamination', 'Not Specified', 'E. Coli O157:H7', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled product in your homeDo not consume the recalled productRecalled products should be thrown out or returned to the location where they were purchasedFood contaminated with E. coli O157:H7 may not look or smell spoiled but can still make you sick. Symptoms can include nausea, vomiting, mild to severe abdominal cramps and watery to bloody diarrhea. In severe cases of illness, some pe', '63869');
INSERT INTO safety_incidents VALUES ('96035536a297c8ce56af7aaca56da22a15d65199', 'Health Canada', '2022-01-27', 2022, '2022-01', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Mastercraft 5 Gallon Air Compressor and MotoMaster 5 Gallon Twin-Stack Air Compressor', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the compressors and return them to the place of purchase for a full refund.For more information, consumers may contact the Canadian Tire Call Centre by telephone at 1-800-387-8803.&nbsp; The call centre is open Monday to Friday from 8:00 a.m. to 9:00 p.m. EST and on Saturday and Sunday from 9:00 a.m. to 5:00 p.m. EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Cana', '61894');
INSERT INTO safety_incidents VALUES ('82cc81435382e954936498b63448df26b8861af4', 'Health Canada', '2022-01-27', 2022, '2022-01', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Hoppetta 2-Way Gauze Sleep Bag', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Flammability hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled 2-Way Gauze Sleep Bag and discard, or return to Baby Square for a refund.For more information, consumers can contact Baby Square by email at info@babysquare.ca or visit the company website at www.babysquare.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related', '63865');
