INSERT INTO safety_incidents VALUES ('498f7e0827754b31dcf642336380c5759017fc6f', 'Health Canada', '2022-01-26', 2022, '2022-01', 'Canada', 'Canada', '', 'Drugs', 'APO-AMITRIPTYLINE 10mg', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Serious', 0, 0, 'Patients can continue to take their medication as prescribed by their health care provider as there is no immediate risk in continuing to take the recalled medication. Stopping amitriptyline may lead to mild withdrawal symptoms.Contact your health care provider if you have taken a recalled product and you have concerns about your health. Ask your pharmacist if you are unsure whether you are taking a recalled product.Contact the company if you have questions about the recall:Apotex Inc. via Sedgw', '63849');
