INSERT INTO safety_incidents VALUES ('b0a83f19867a9bdb314044fb76029e52946237cb', 'Health Canada', '2022-01-21', 2022, '2022-01', 'Canada', 'Canada', '', 'Other', 'Dyna-One Energy Absorber Lanyard', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Dyna-One Energy Absorber Lanyard and contact the manufacturer for a replacement product.For more information, consumers can contact PIP Canada by telephone at 1-877-446-3278 from 8am to 6pm EST Monday to Friday, by email at orders@pipcanada.ca or visit the company website&nbsp;www.pipcanada.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health C', '63841');
