INSERT INTO safety_incidents VALUES ('b2775362f7592fabb66303f49b1a57cfed152736', 'Health Canada', '2022-01-21', 2022, '2022-01', 'Canada', 'Canada', '', 'Non-Alcoholic', 'Immunity Super Functional Smoothie', 'Chemical', 'Chemical / Toxic Substance', 'Poisoning / Ingestion', 'Chemical', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctorCheck to see if you have the recalled product in your homeDo not consume the recalled productRecalled products should be thrown out or returned to the location where they were purchasedRaw elderberries naturally contain cyanogenic glycosides, which can release cyanide after being eaten. The human body can eliminate small amounts of cyanide, but larger amounts can result in cyanide poisoning, which could lead to death', '63851');
