INSERT INTO safety_incidents VALUES ('4502ac32d6f0df26c3eafce431e37b66ced034dc', 'Health Canada', '2022-01-19', 2022, '2022-01', 'Canada', 'Canada', '', 'Consumer Products', 'KidORCA Hard Shell Rain Jacket', 'Entanglement Hazard', 'Other', 'Not Specified', 'Entanglement hazard', 'Not Reported', 0, 0, 'Consumers should immediately remove the drawstrings and toggles from the bottom of the jacket, by cutting both sides of the cords, to eliminate the hazard. &nbsp;For more information, consumers can contact kidORCA by email or visit the company website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use', '63833');
