INSERT INTO safety_incidents VALUES ('0935368dd8cf68d8b4fccf02cdb88e3d00952cb9', 'Health Canada', '2022-01-19', 2022, '2022-01', 'Canada', 'Canada', '', 'Hobby And Craft Items', 'Lichtenberg generators', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'Electrical hazard - Unauthorized products', 'Not Reported', 0, 0, 'Do not attempt to build, purchase or use a Lichtenberg generator for any purpose.Discontinue the use of any homemade Lichtenberg generators immediately. Safely deactivate and disassemble the devices and dispose of the electrical components according to local/municipal guidelines.Discontinue the use of any complete Lichtenberg generators that may have been purchased and report the sellers to Health Canada.Use consumer electrical products as they are intended and only use those that bear a recogni', '63838');
