INSERT INTO safety_incidents VALUES ('42dd753737d4dbac2d7e6f62f971967360c73169', 'Health Canada', '2021-12-20', 2021, '2021-12', 'Canada', 'Canada', '', 'Medical Devices', 'All health products manufactured by Eco-Med Pharmaceuticals Inc. This includes ultrasound gels, transmission and massage lotions as well as hand sanitizers and first aid antiseptics.', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Not Reported', 0, 0, 'If you have purchased any health product(s) listed above, stop using them and discard them appropriately:Follow municipal or regional guidelines on how to dispose of chemicals and other hazardous waste; orReturn the product to your local pharmacy for proper disposal.If you have undergone procedures where the gel was applied to or introduced into the body, and you are feeling unwell (e.g., having a fever and/or feeling tired) following an ultrasound, seek immediate medical attention.Since Eco-Med', '62791');
