INSERT INTO safety_incidents VALUES ('fe91f0dac31cceea902c2a32845bc938966e607c', 'Health Canada', '2021-12-09', 2021, '2021-12', 'Canada', 'Canada', '', 'Sports & Leisure', 'Husqvarna® branded Automower 435X AWD and Automower 535 AWD robotic lawnmowers', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled product and contact Husqvarna to obtain information on product repair.For automowers with greater than 1,200 charging cycles, consumers should contact Husqvarna to make arrangements for a free battery replacement.For all other automowers, Husqvarna will provide two software updates through the Automower® Connect App, which, upon acceptance of the updates, will automatically be installed free of charge and eliminate the risk of battery degradat', '63684');
