INSERT INTO safety_incidents VALUES ('79ed08c96178983daa9d9e4a329ccb1c0f76d188', 'Health Canada', '2021-11-15', 2021, '2021-11', 'Canada', 'Canada', '', 'Drugs', 'Verkazia', 'Product Safety', 'Other', 'Eye Injury', 'Product safety', 'Moderate', 0, 0, 'If you see particulate matter (e.g. crystal-like particles) in the vials or if your eye symptoms worsen, stop using the product and consult your pharmacist to obtain a replacement as soon as possible.Consult a health care professional if you have taken a recalled product and have health concerns.Contact McKesson Specialized Distribution by calling&nbsp;1-877-827-1306&nbsp;or emailing&nbsp;msd.support@mckesson.ca&nbsp;if you have questions about the recall.Report any health product-related&nbsp;s', '63594');
INSERT INTO safety_incidents VALUES ('aa2e95b3c0bd43791ce2be45482926a2af8389c1', 'Health Canada', '2021-11-15', 2021, '2021-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Button batteries', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'It is important to act quickly if someone has swallowed a button battery as it can cause life-threatening internal burns in as little as two hours. Even used or expired batteries can cause life-threatening injuries.Someone who has swallowed a button battery may not show any symptoms or they may show non-specific symptoms such as vomiting, abdominal or chest pain, fever, difficulty breathing and swallowing or loss of appetite. If you think that a child or adult has swallowed a button battery, get', '78093');
