INSERT INTO safety_incidents VALUES ('dc9cb9d515848fd6c1bcd00a107624d6f2ed6bd3', 'Health Canada', '2021-11-12', 2021, '2021-11', 'Canada', 'Canada', '', 'Clothing & Textiles', 'Hanna Andersson Baby Long Sleeved Wiggle Set (Style 66938) and Baby Ruffle Romper (Style 66919)', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Choking hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled wiggle set and/or romper and return the product back to Hanna Anderson LLC to receive a refund.For more information consumers can contact Hanna Andersson by telephone toll-free at 1-800-222-0544, by email. Monday to Friday from 6:00am to 8:00pm PST or by visiting the company''s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada wou', '63568');
INSERT INTO safety_incidents VALUES ('c175bd4f4e6caa0c994276efcce264ab9da3033b', 'Health Canada', '2021-11-12', 2021, '2021-11', 'Canada', 'Canada', '', 'Health Products', 'Verkazia (cyclosporine) eye drops (DIN 02484137, lot 1N81H)', 'Product Safety', 'Other', 'Eye Injury', 'Product safety', 'Not Reported', 0, 0, 'If you see particulate matter (e.g. crystal-like particles) in the vials or if your eye symptoms worsen, stop using the product and consult your pharmacist to obtain a replacement as soon as possible. Consult a health care professional if you have taken a recalled product and have health concerns. Contact McKesson Specialized Distribution by calling 1-877-827-1306 or emailing msd.support@mckesson.ca if you have questions about the recall.Report any health product-related&nbsp;side effects&nbsp;o', '63584');
