INSERT INTO safety_incidents VALUES ('ff51a00b8aea5ef9d6ff900b1a62638425af15d5', 'Health Canada', '2021-11-09', 2021, '2021-11', 'Canada', 'Canada', '', 'Biologic Or Vaccine', 'Janssen and Vaxzevria (AstraZeneca) COVID-19 vaccines', 'Product Safety - Covid', 'Other', 'Not Specified', 'Product safety - COVID', 'Not Reported', 0, 0, 'If you have received the Janssen or Vaxzevria COVID-19 vaccine:Seek prompt medical attention immediately if you have any of the following symptoms after vaccination:unexplained bleedingunexplained bruisingsmall purplish spots beyond the site of vaccination &nbsp;shortness of breathchest painleg pain and/or swellingpersistent abdominal painTalk to your healthcare professional if you have any questions about the Janssen or Vaxzevria COVID-19 vaccines.Report any adverse events&nbsp;after immunizati', '78102');
