INSERT INTO safety_incidents VALUES ('17e999bb752f7832bb9b35cf8897a2b222f2d542', 'Health Canada', '2021-11-04', 2021, '2021-11', 'Canada', 'Canada', '', 'Household Items', 'Space-saving, Foldable and Comfortable 6-wheel Baby Walker', 'Injury', 'Other', 'Not Specified', 'Injury hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and contact Shandong Chengyan Culture Development at service@gteun.com for a full refund.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by filling out the Consumer Product Incide', '63539');
INSERT INTO safety_incidents VALUES ('4fd860307dbce5691c26ebb4a538ab77dcb3c897', 'Health Canada', '2021-11-04', 2021, '2021-11', 'Canada', 'Canada', '', 'Toys & Childcare', 'Turbo Racer and Cloud Racer Playsets with Wooden Roof', 'Entrapment Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled playsets. Backyard Play Systems will send affected consumers a free repair kit which includes replacement wood parts, hardware and instructions.For more information, consumers may contact Backyard Play Systems toll-free at 1-866-890-2211, between 8:00 AM and 5:00 PM ET, Monday through Friday, by email&nbsp;(customerservice@backyard-play.com)&nbsp;or&nbsp;visit the&nbsp;company''s website.Consumers may view the release by the US CPSC on the Comm', '63540');
INSERT INTO safety_incidents VALUES ('53309f1d83923c76b596104ee2cfd241af2c3f97', 'Health Canada', '2021-11-04', 2021, '2021-11', 'Canada', 'Canada', '', 'Sports & Leisure', 'Coleman Classic 2 Burner Naphtha Stove', 'Labelling And Packaging', 'Other', 'Burns', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should contact Coleman for updated product warning labels and a new childproof cap for the stove. Consumers should continue to follow the product safety manual that instructs consumers to never leave stove unattended when hot or in use and keep and store out of reach out children.For more information, consumers may contact Newell Brands Canada ULC (Coleman Division) at https://recall.colemancanada.ca/en&nbsp;or by phone at 1-800-387-6161, Monday to Friday, from 9:00 a.m. to 6:00 p.m. E', '63541');
