INSERT INTO safety_incidents VALUES ('1369d6fac87ad69d3ba43096b49de6b38e49cdae', 'Health Canada', '2021-11-03', 2021, '2021-11', 'Canada', 'Canada', '', 'Electrical & Electronics', 'Elektron BP-1  Power Handles', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled Elektron&nbsp;BP-1 Power Handles&nbsp; and contact Elektron to arrange free return shipping and a full refund.For more information, consumers may contact Elektron toll-free at 888-312-2709 from 10:00am to 4:00pm PST Monday through Friday, email at support@elektron.se, or online at https://bp1-support.elektron.se&nbsp; Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even give', '63528');
INSERT INTO safety_incidents VALUES ('ddbdc0fb27ee0010b9d1ffa40881a0eead999355', 'Health Canada', '2021-11-03', 2021, '2021-11', 'Canada', 'Canada', '', 'Fresh', 'Enoki Mushroom', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctor.Check to see if you have the recalled product in your home. Recalled products should be thrown out or returned to the store where they were purchased.Food contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stiffness. Pregnant women, the elderly and people with weakened immu', '63542');
INSERT INTO safety_incidents VALUES ('bb97625573c8cb00ab899b5ad9996e232f164149', 'Health Canada', '2021-11-03', 2021, '2021-11', 'Canada', 'Canada', '', 'Natural Health Products', 'TUMS Extra Strength', 'Product Safety', 'Other', 'Not Specified', 'Product safety', 'Moderate', 0, 0, 'Stop using the recalled product. Talk to your healthcare provider if you have taken a recalled product and have health concerns.Contact GSK Consumer Healthcare’s recall partner, Sedgwick, by calling 1-866-469-6524 or emailing gskcanada3969@sedgwick.com if you have questions about the recall.Report any health product-related&nbsp;side effects&nbsp;or&nbsp;complaints&nbsp;to Health Canada.', '63546');
