INSERT INTO safety_incidents VALUES ('72cf8fac6614005085b088d804757c940c66a44c', 'Health Canada', '2021-09-24', 2021, '2021-09', 'Canada', 'Canada', '', 'Other', 'Organic Tofu - Fine Herbs', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctor.Check to see if you have the recalled product in your home. Recalled products should be thrown out or returned to the store where they were purchased.Food contaminated with Listeria monocytogenes may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stiffness. Pregnant women, the elderly and people with weakened immu', '62986');
