INSERT INTO safety_incidents VALUES ('0e16270a7f0e48f8f674df7d12e61e0943897c03', 'Health Canada', '2021-09-22', 2021, '2021-09', 'Canada', 'Canada', '', 'Chemicals', 'Various JHY Design Tabletop Firepots', 'Labelling And Packaging', 'Flammability / Overheating', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled products and may contact Ningbo New Image Gifts by email at sales2@newimagegifts.com or by telephone at 86+15827758723 between 9pm to 12pm EST.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmet', '62845');
INSERT INTO safety_incidents VALUES ('e913c7737b519800c62cd7fd49e6e2529a26f348', 'Health Canada', '2021-09-22', 2021, '2021-09', 'Canada', 'Canada', '', 'Toys & Childcare', 'NicoSee Wonder Hematite Rattlesnake Eggs, SpaceCare Hematite Magnetic Stone set, and Ruptop Magnetic Pen High-quality Innovative Gel Pen Finger Play Toy', 'Physical Hazard', 'Other', 'Not Specified', 'Physical hazard', 'Not Reported', 0, 0, 'Immediately stop using these magnet sets, check that all pieces are accounted for and contact your municipality for instructions on how to dispose of the products.Keep small magnet sets out of the reach of children.Do not allow children to play with small toys or other small items that contain powerful magnets.Check your children’s toys for wear and tear. Throw away any toys with magnets that have come loose.Teach children of all ages that magnets and items containing magnets should never be pla', '62846');
