INSERT INTO safety_incidents VALUES ('234bc96d631d04d9ec8fa69857eb7bd3169dfa7f', 'Health Canada', '2021-08-12', 2021, '2021-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Nico SeeWonder Magnetic Rattle Snake Eggs.', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled magnets away from children and return to Ami Ventures Inc. for a refund.For more information, consumers may contact Ami Ventures Inc. by telephone at 1-281-738-1101, from 9:00 a.m. to 8:00 p.m. (CDT), or by email at&nbsp;walmart.gm.ca@supportingbuyers.com.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadian', '62760');
