INSERT INTO safety_incidents VALUES ('d5766932d4ef4d58cfeebe06a11b1919be0b5dfd', 'Health Canada', '2021-08-06', 2021, '2021-08', 'Canada', 'Canada', '', 'Toys & Childcare', 'Magnet Game Set assorted-12 pieces', 'Ingestion Hazard', 'Other', 'Poisoning / Ingestion', 'Ingestion hazard', 'Not Reported', 0, 0, 'Consumers should immediately take the recalled toy magnet set away from children and return to the place of purchase for a full refund.For more information, consumers may contact Sayal Electronics by telephone at 416-494-8999, 08:00 am to 06:00 pm EST from Monday to Friday and 09:00 am to 06:00 pm EST on Saturday by&nbsp;email&nbsp;or visit the&nbsp;firm''s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away', '62747');
