INSERT INTO safety_incidents VALUES ('469062d12e831426d9b2bdcb5845b0c985443987', 'Health Canada', '2021-08-05', 2021, '2021-08', 'Canada', 'Canada', '', 'Chemicals', 'Model 520 Firepots by Combi Inc', 'Labelling And Packaging', 'Flammability / Overheating', 'Not Specified', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the product and may contact Combi Inc. by telephone at 1-800-363-6443 or by e-mail at the following address:&nbsp;info@realflame.caPlease note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other consumer product or cosmetic by filling o', '62750');
INSERT INTO safety_incidents VALUES ('6f975eb81d895f0d2e0dd7ce50a8461655fa6ef6', 'Health Canada', '2021-08-04', 2021, '2021-08', 'Canada', 'Canada', '', 'Household Items', 'nan', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Fire hazard', 'Not Reported', 0, 0, '', '62522');
INSERT INTO safety_incidents VALUES ('25d13c05d7d121b852087084c4e1d249e3897185', 'Health Canada', '2021-08-04', 2021, '2021-08', 'Canada', 'Canada', '', 'Dairy', 'Repackaged Cahill''s brand Original Irish Porter Cheese', 'Listeria', 'Microbiological Contamination', 'Not Specified', 'Listeria', 'Serious', 0, 0, 'If you think you became sick from consuming a recalled product, call your doctor.Check to see if you have the recalled products in your home. Recalled products should be thrown out or returned to the store where they were purchased.Food contaminated with&nbsp;Listeria monocytogenes&nbsp;may not look or smell spoiled but can still make you sick. Symptoms can include vomiting, nausea, persistent fever, muscle aches, severe headache and neck stiffness. Pregnant women, the elderly and people with we', '62955');
