INSERT INTO safety_incidents VALUES ('df44fccfc1c0e10105cc4319089d8cc09d20938b', 'Health Canada', '2021-07-27', 2021, '2021-07', 'Canada', 'Canada', '', 'Electrical & Electronics', 'All removable foam facial interfaces for the Oculus Quest 2 Virtual Reality headset.', 'Chemical', 'Chemical / Toxic Substance', 'Skin Irritation', 'Chemical hazard', 'Not Reported', 0, 0, 'Consumers who experience a skin irritation or reaction should immediately stop using the affected product, and all consumers should contact Facebook Technologies to receive a free silicone cover. Facebook Technologies is contacting all Quest 2 users directly as well.For more information, consumers can contact Facebook Technologies online at&nbsp;https://www.oculus.com/quest-2/removable-facial-interface-alert&nbsp;or by telephone toll-free at 1-877-960-0889 24 hours per day, seven days per week.C', '62625');
