INSERT INTO safety_incidents VALUES ('f88694afb363f862d0959bb226568c87526f68d5', 'Health Canada', '2021-06-16', 2021, '2021-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Grill-It-Kit (12" Disposable Mini-Quick Grill)', 'Labelling And Packaging', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the product and return the product to the place of purchase for refund.For more information, consumers may contact Home Hardware Stores Ltd. By telephone at 519-664-2252 (ext. 6609) between 8:30am and 4:30pm EST, Monday to Friday or via email at&nbsp;contactus@homehardware.ca.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Cana', '62523');
INSERT INTO safety_incidents VALUES ('7a8175775de8c589e2ae983c07d545f7290d26fe', 'Health Canada', '2021-06-16', 2021, '2021-06', 'Canada', 'Canada', '', 'Sports & Leisure', 'Jealous Devil Lump 20lbs Charcoal, Jealous Devil Maxxx 10# Pillow Briquettes, Jealous Devil XL Lump 35lbs Charcoal, Jealous Devil CHUNX 10lbs Lump Charcoal, Jealous Devil CHUNX 20lbs lump charcoal and Jealous Devil MAX Pillow Briquette 10# Box', 'Labelling And Packaging', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Labelling and packaging', 'Not Reported', 0, 0, 'Consumers should immediately stop using the product and contact Jealous Devil by e-mail at&nbsp;info@jealousdevil.com&nbsp;to receive corrective Bilingual labels.For more information, consumers may contact the firm by telephone at +1 661-532-8767 from 9:00 am to 5:00 pm (EST), or by email:&nbsp;info@jealousdevil.com.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to ', '62524');
