INSERT INTO safety_incidents VALUES ('48414a2f89e0f8a074636d2159ee7e6a6f610fcd', 'Health Canada', '2021-06-14', 2021, '2021-06', 'Canada', 'Canada', '', 'Biologic Or Vaccine', 'Moderna COVID-19 Vaccine', 'Labelling - New Safety Information - Packaging - Supply - Covid', 'Other', 'Not Specified', 'Labelling - New safety information - Packaging - Supply - COVID', 'Not Reported', 0, 0, 'AudienceHealthcare professionals including infectious disease physicians, pharmacists, family physicians, public health officials, nurses and nurse practitioners, and healthcare professionals at identified points of use.&nbsp;Innomar Strategies Inc. (the Canadian importer and distributor) is distributing COVID-19 Vaccine Moderna doses directly to vaccination locations where administration of the vaccine will occur, as outlined by provincial and territorial governments and public health authoriti', '62511');
