INSERT INTO safety_incidents VALUES ('86559a7b32fcbff60c16c6797b9fd56bf9d91266', 'Health Canada', '2021-04-19', 2021, '2021-04', 'Canada', 'Canada', '', 'Household Items', 'Clipper Multi-purpose Shiny Colour and Classic Colours Lighters', 'Fire', 'Flammability / Overheating', 'Burns', 'Burn hazard - Fire hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the lighters and return to the place of purchase for a refund.For more information, consumers can contact HBI Canada at 1-866-420-4372, Monday to Friday, 8:00 to 16:00 PST.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety incidents related to the use of this product or any other ', '62343');
