INSERT INTO safety_incidents VALUES ('00e456a1e4cafb52f6bd467e0946650e3ee772b9', 'Health Canada', '2018-07-19', 2018, '2018-07', 'Canada', 'Canada', '', 'Household Items - Other', 'K9 Natural Frozen Chicken Feast 11lb bags with the batch number of #150517 and an expiration date of 15NOV2018.', 'Microbial Hazard', 'Other', 'Not Specified', 'Microbial hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using any of the pet food products affected by this recall and contact K9 Natural Ltd.For more information, consumers may contact K9 Natural Ltd at 1-888-345-4680, Monday through Friday between 8 AM&nbsp;and 5 PM PST or by&nbsp;email.Please note that the&nbsp;Canada Consumer Product Safety Act&nbsp;prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians to report any health or safety in', '58171');
