INSERT INTO safety_incidents VALUES ('f838c76190aabdb7d002bfc0101f933e51b09806', 'Health Canada', '2017-11-21', 2017, '2017-11', 'Canada', 'Canada', '', 'Furniture & Home', 'IKEA children’s chests of drawers taller than 60 cm (23 ½ inches) and IKEA adult chests of drawers taller than 75 cm (29 ½ inches).', 'Entrapment Hazard - Tip-Over Hazard', 'Entrapment', 'Entrapment', 'Entrapment hazard - Tip-over hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using all affected chests of drawers that are not securely anchored to the wall, and move them to an area that children cannot access.Consumers have two options to remedy the tip-over hazard of the chest of drawers.&nbsp; Consumers may obtain a free anchoring repair kit to secure the chest of drawers to the wall OR may contact IKEA for a refund, as stated in this notice:Consumers should visit IKEA Canada retail locations for a free wall anchoring kit to use with', '57778');
