INSERT INTO safety_incidents VALUES ('019c560f0437d4e3fee27509a0c173a677233273', 'Health Canada', '2016-11-04', 2016, '2016-11', 'Canada', 'Canada', '', 'Furniture & Home', 'IKEA children''s chests of drawers taller than 60 cm (23 ½ inches) and IKEA adult chests of drawers taller than 75 cm (29 ½ inches).', 'Tip-Over Hazard', 'Instability / Fall Risk', 'Fall Injury', 'Tip-over hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using all affected chests of drawers that are not securely anchored to the wall, and move them to an area that children can not access.Consumers have two options to remedy the tip-over hazard of the chest of drawers.&nbsp; Consumers may obtain a free anchoring repair kit to secure the chest of drawers to the wall OR may contact IKEA for a refund:Consumers should visit IKEA Canada retail locations for a free wall anchoring kit to use with the affected chests of d', '78088');
