INSERT INTO safety_incidents VALUES ('b5a455d7947880f885fca6718a3fa0a28890660c', 'Health Canada', '2014-04-29', 2014, '2014-04', 'Canada', 'Canada', '', 'Household Items', 'Children’s wall-mounted lamps', 'Choking', 'Small Parts / Choking Hazard', 'Choking / Suffocation', 'Strangulation hazard', 'Not Reported', 0, 0, 'Consumers should immediately stop using the recalled wall lamps and return them to an IKEA store for a product exchange or refund.For additional information, contact IKEA toll-free at 1-800-661-9807 anytime, or visit the firm''s website.Consumers may view the release by the US CPSC on the Commission''s website.Please note that the Canada Consumer Product Safety Act prohibits recalled products from being redistributed, sold or even given away in Canada.Health Canada would like to remind Canadians t', '51142');
