INSERT INTO safety_incidents VALUES ('2495958f662447d0672c2d338ba7cc50716c34b2', 'FDA', '2024-01-01', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'EnChroma Safety Glasses with Rx Indoor Universal Lenses:  Martinez Cx1 Indoor Rx, SKU: Cx.PC.IN.MTZ.BK.Rx;  Summit Indoor Rx, Cx.PC.IN.SUM.BK.Rx;  Martinez Black Cx Rx, Cx-3.PC.PT.MTZ.BK.Rx', 'Injury', 'Other', 'Eye Injury', 'Safety glasses with Rx indoor universal lenses fail to meet high impact safety specifications, which may not provide adequate protection against impact, posing a risk of eye injury.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0488-2025');
INSERT INTO safety_incidents VALUES ('67b5eba10998769a930bae95c9695b1b1b9e4561', 'FDA', '', 0, nan, 'USA', 'United States', 'New Zealand', 'Medical Devices', 'Otological Ventilation Tube - T-Tube 9mm - Silicone; Product Code: NZ3309;', 'Lack Of 510(K) Clearance.', 'Other', 'Not Specified', 'Lack of 510(k) clearance.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0966-2025');
INSERT INTO safety_incidents VALUES ('1e004501fddeaf43f89dd3c85845cb01da7bfc55', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Convenience Kits    1. 25GA Convenience Kit - FNX  VS0644.25-FNX    2. 25GA Convenience Kit - FXX  VS0644.25-FXX    3.25GA Convenience Kit - XES  VS0644.25-XES', 'Contamination', 'Chemical / Toxic Substance', 'Not Specified', 'There may be voids located in the seal of Tyvek pouches associated with identified catalog numbers and lots. A compromised sterile barrier has potential of bioburden contamination which could lead to infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1249-2026');
INSERT INTO safety_incidents VALUES ('6c272962c3f5e714d0b7cacc4729a1e217f2a76d', 'FDA', '', 0, nan, 'USA', 'United States', 'Denmark', 'Medical Devices', 'ABL800 FLEX  Model Numbers 393-800 and 393-801    The ABL800 FLEX analyzers are intended for:   " In Vitro testing of samples of whole blood for the parameters pH, pO2, pCO2, cK+, cNa+, cCa2+, cCl , cGlu, cLac, cCrea, ctBil, and co-oximetry parameters (ctHb, sO2, and the hemoglobin fractions FO2Hb, ', 'Issue With Analyzer When The Ph Of The Calibration Solution Decreases During The In-Use Period Potentially Because Of Bacterial Growth In The Calibration Solution Bottles.  This May Result In A Probability Of Reporting Biased Out-Of-Specification Ph Results On Blood Samples.', 'Microbiological Contamination', 'Not Specified', 'Issue with analyzer when the pH of the calibration solution decreases during the in-use period potentially because of bacterial growth in the calibration solution bottles.  This may result in a probability of reporting biased out-of-specification pH results on blood samples.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2426-2024');
INSERT INTO safety_incidents VALUES ('0a97af751ab2eeb5549fdd416a00030660342da4', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Universa Firm Ureteral Stent, Global Product No. G49864  G49865  G49866  G49867  G49868  G49869  G49870  G49874  G49875  G49877  G49879  G49881  G49882  G49887  G49888', 'The Wire Guide May Be Incorrectly Loaded Into The Wire Guide Holder, Leading To The Stiff Tip Of The Wire Guide Being Introduced Into The Patient Instead Of The Flexible Tip.', 'Chemical / Toxic Substance', 'Not Specified', 'The wire guide may be incorrectly loaded into the wire guide holder, leading to the stiff tip of the wire guide being introduced into the patient instead of the flexible tip.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0977-2020');
INSERT INTO safety_incidents VALUES ('1a995e69d2bdac207094884bbde68b1a5aefea7f', 'FDA', '', 0, nan, 'USA', 'United States', 'Japan', 'Medical Devices', 'Model No. CYF-V2, VISERA Cysto-Nephro Videoscope', 'Olympus Has Updated The Instructions For Use: Reusable Cleaning Brushes Have Been Removed From The Manual Cleaning. Single Use Brushes Remain Compatible.', 'Other', 'Not Specified', 'Olympus has updated the instructions for use: Reusable cleaning brushes have been removed from the manual cleaning. Single use brushes remain compatible.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0691-2024');
INSERT INTO safety_incidents VALUES ('18b9f67f2983629d56a62113e467f5160630126d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Centricity PACS Software Version 7.0 SP0.0.4.7', 'The Event Notification Manager (Enm) Functionality For Certain Products Does Not Process Notifications For Study Modifications Performed On Post Verified Exams.', 'Other', 'Not Specified', 'The Event Notification Manager (ENM) functionality for certain products does not process notifications for study modifications performed on post verified exams.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1466-2022');
INSERT INTO safety_incidents VALUES ('07841761a16d6868e84c097acc3335e44d5c1efc', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'THORACIC ROBOTS, DYNJ908777B', 'Kits Contain Recalled Olympus Biopsy Valves. Olympus Is Investigating An Increase In Complaints Associated With Rubber Fragment Detachment In The Slit Of Single Use Biopsy Valves. Potential Consequences Associated With Detachment Of Fragments From Valve Include Foreign Body In Patient''S Tracheobronchial Tree, Which May Require Intervention For Removal. Other Potential Consequences Include Inflammatory Response, Hypoxia, And Prolongation Of Procedure.', 'Mechanical Failure', 'Not Specified', 'Kits contain recalled Olympus biopsy valves. Olympus is investigating an increase in complaints associated with rubber fragment detachment in the slit of single use biopsy valves. Potential consequences associated with detachment of fragments from valve include foreign body in patient''s tracheobronchial tree, which may require intervention for removal. Other potential consequences include inflammatory response, hypoxia, and prolongation of procedure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1707-2026');
INSERT INTO safety_incidents VALUES ('524039c6da33ab50f92b205a6e867552ef79c2d1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', '20/30 Priority Pack Accessory Kit w/Copilot, REF: 1003327, used for cardiovascular procedures.', 'Inflation Device Used During Cardiovascular Procedures May Leak In The Indeflator At The Hose Rotating Luer Or At The Gauge, Which Could Lead To Air Embolism.', 'Chemical / Toxic Substance', 'Not Specified', 'Inflation Device used during cardiovascular procedures may leak in the indeflator at the hose rotating luer or at the gauge, which could lead to air embolism.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0732-2025');
INSERT INTO safety_incidents VALUES ('ad82e32985444ed96c3fd3ab027acc558c34fea7', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Solero Generator US PG, Item No. H78712740000US0, Catalog No. 12740000US', 'Specific Serial Numbers Of The Solero Mta Generator Require Servicing To Upgrade The Software To Help Reduce The Incidence Of Error 0001, Which Can Occur During System Start-Up.', 'Other', 'Not Specified', 'Specific serial numbers of the Solero MTA Generator require servicing to upgrade the software to help reduce the incidence of Error 0001, which can occur during system start-up.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2437-2021');
INSERT INTO safety_incidents VALUES ('2bd1834802afee1072a87f055af0b37904ce8fb8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Precision Delivery Set with Filter, REF: PD06F; and Precision Delivery Set with Trifurcated Luer, REF: PDT05CV2', 'Delivery Sets May Have Tubing That Could Become Detached That Could Result In Patient Infection.', 'Mechanical Failure', 'Not Specified', 'Delivery Sets may have tubing that could become detached that could result in patient infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1100-2023');
INSERT INTO safety_incidents VALUES ('56e2007ac0067e0a4e9100d933d6c16d2e8dcda1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Philips Trilogy 100 Ventilator, Model Numbers 1054260, 1054096, U1054260, U1054260B, 1054260B, CA1054096B, BT1054260, 1054096B, R1054260, RSL1054260, CA1054096, R1054260B, R1054655TPV, AU1054096, AU1054096B, 1054096B, 1054097, BR1054096, LA1054096, CN1054096, KO1054096, KR1054096, R1054655TP, R10546', 'The Replacement Silicone Sound Abatement Foam Installed Into Some Trilogy 100 And Trilogy 200 Devices May Separate From The Plastic Backing To Which It Is Attached. If This Were To Happen, The Foam Could Potentially Block Air Inlet, Which Could Result In A Reduction In Delivered Therapy Volume Or Pressure And Could Cause The Device To Alarm.', 'Explosion', 'Not Specified', 'The replacement silicone sound abatement foam installed into some Trilogy 100 and Trilogy 200 devices may separate from the plastic backing to which it is attached. If this were to happen, the foam could potentially block air inlet, which could result in a reduction in delivered therapy volume or pressure and could cause the device to alarm.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0882-2023');
INSERT INTO safety_incidents VALUES ('12275266bb7bce6637662fdd91d576ed3a36aab3', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', '126" (320 cm) 16.4 ml, 15 Drop Primary Set w/2 MicroClave Clear, Remv 2 Gang 4-Way NanoClave Stopcock, Rotating Luer, 1 Ext; 1 unit per pouch, 50 multivac pouches per case. UDI:(01)10887709070902(17)250201(30)50(10)4724881.     The Intravascular Administration Set is a single use, sterile, non-pyrog', 'Identification Of A  Potential  Manufacturing Defect On The Internal Surface Of The Nanoclave Within Specific Lots Of Nanoclave Sets, Which May Inhibit A Proper Seal With The Nanoclave Spike.', 'Mechanical Failure', 'Not Specified', 'Identification of a  potential  manufacturing defect on the internal surface of the NanoClave within specific lots of NanoClave sets, which may inhibit a proper seal with the NanoClave spike.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0218-2021');
INSERT INTO safety_incidents VALUES ('5a17805395921a112687ad198ba4696e710c9a26', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Olympus Bronchovideoscope, Models BF-3C40 & BF-N20.', 'Complaint Of Endoscope Model Becoming Lodged In The Endotracheal Tube Connector Due To Diameter Being Too Large.', 'Other', 'Not Specified', 'Complaint of endoscope model becoming lodged in the endotracheal tube connector due to diameter being too large.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2502-2023');
INSERT INTO safety_incidents VALUES ('61e21801153135940f9e8a40256db72b1b8bf028', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'a. Rapid Test Kit Coag-Sense Professional Blood Coagulation Test Prothrombin Time Test (PT/INR) Whole Blood Sample 50 Tests-IVD.  Part No. 0356-50.      b.  Coagulation Control Kit Coag-Sense PT / INR Test (Prothrombin Time Test) Low Level / High Level 10 Strips Part No. 03P69-10.', 'Facility Temperature Excursions (From June 2021-August 2021) Prior To Delivery; Exposure To Higher Temperatures May Have Impacted Product Effectiveness. All Lots Received Between 06/01/21-9/30/21.', 'Other', 'Fracture / Blunt Trauma', 'Facility Temperature excursions (from June 2021-August 2021) prior to delivery; exposure to higher temperatures may have impacted product effectiveness. All lots received between 06/01/21-9/30/21.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1583-2022');
INSERT INTO safety_incidents VALUES ('aa08a2806e9eb864282d1d5d42647b68a562a0ff', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Excelsior Medical, 0.9% Sodium Chloride Injection, USP - 10 mL Fill, Item Number EMZ111240.  Prefilled saline flush syringes', 'Medline Has Identified A Limited Quantity Of Saline Iv Flush Syringes That May Not Meet The Required Concentration Of Sodium Chloride.', 'Other', 'Not Specified', 'Medline has identified a limited quantity of saline IV flush syringes that may not meet the required concentration of sodium chloride.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0234-2026');
INSERT INTO safety_incidents VALUES ('c36fc6138b3ee0730c57a4c5ec2d708010c3a649', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE STERILE IRIS SCISSORS CVD/STD, REF DYNJ04049', 'Falls', 'Sharp Edges / Points', 'Fall Injury', '4.5" Iris Scissors, Sterile, Curved (DYNJ04049) are being recalled due to the potential of the tip protector to fall off. The sharp tip of the scissors could compromise the sterile barrier system by puncturing large and/or small holes that may not be visible to the user.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2595-2023');
INSERT INTO safety_incidents VALUES ('4ede8e41404af4b520f3617c993f0052707bc722', 'FDA', '2025-01-01', 2025, '2025-01', 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE convenience kits labeled as:    1) ACH PLASTICS BREAST-LF, REF CDS983639K;   2) BREAST ABD, REF CDS984267J;   3) PLASTIC PACK, REF DYNJ00264M;   4) BREAST ABDOMINOPLASTY MZ PK-LF, REF DYNJ0428947L;   5) BREAST ABDOMINOPLASTY MB PK-LF, REF DYNJ0428947M;   6) AUGMENTATION #87-RF, REF DYNJ27319', 'Medline Industries, Lp Is Issuing A Recall For Specific Item(S) And Lot(S) Of Medline Kits Containing Safeair Smoke Evacuation Pencils. Stryker Instruments Has Expanded The Scope Of Their Recall Of Safeair Smoke Evacuation Pencils Previously Initiated In October 2024, Adding An Additional 47 Lots To The Scope Of The Recall. The Initial Recall Was Due To The Potential For Product To Activate Without Manual Input When Plugged Into A Power Source Or Remain Active After Buttons Are Released.', 'Flammability / Overheating', 'Not Specified', 'Medline Industries, LP is issuing a recall for specific item(s) and lot(s) of Medline Kits containing SafeAir Smoke Evacuation Pencils. Stryker Instruments has expanded the scope of their recall of SafeAir Smoke Evacuation Pencils previously initiated in October 2024, adding an additional 47 lots to the scope of the recall. The initial recall was due to the potential for product to activate without manual input when plugged into a power source or remain active after buttons are released.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0519-2026');
INSERT INTO safety_incidents VALUES ('a1e2c4dd62d5ef1d83d3f76c0baffdb0587cb413', 'FDA', '2020-01-02', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Olympus Ultrasound Endoscope, Model number: GF-UCT140P-AL5 - Product Usage: used with other supporting equipment for endoscopic real-time ultrasound imaging and endoscopic surgery within the gastrointestinal tract.', 'A New Inspection Step Was Added To The Cleaning And Disinfection Section Of The Instructions For Use (Ifu) For This Device In Order To Reduce The Risk Of Causing Patient Infections.', 'Other', 'Not Specified', 'A new inspection step was added to the cleaning and disinfection section of the Instructions For Use (IFU) for this device in order to reduce the risk of causing patient infections.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0498-2021');
INSERT INTO safety_incidents VALUES ('7754058f8b4b699f5b1e86c881242f83b041ca12', 'FDA', '2023-01-01', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Grafton DBM (Flex), Model Numbers: T42100, Demineralized Bone Matrix', 'Specific Serial Numbers Of Graftontm Dbm Product Due To The Potential That A Step During The Inspection Of The Outer Tyvek Pouch May Not Have Been Performed According To Requirements. Based On This, Batches May Have Been Released With Potential Non-Conformances In The Outer Tyvek Pouch.', 'Other', 'Not Specified', 'Specific serial numbers of GraftonTM DBM product due to the potential that a step during the inspection of the outer Tyvek pouch may not have been performed according to requirements. Based on this, batches may have been released with potential non-conformances in the outer Tyvek pouch.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0162-2024');
INSERT INTO safety_incidents VALUES ('a9d0be47e9c03f25e602a9fdda9079c97040d4f8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ICD-DR DDBB2D1 EVERA XT IS1/DF1 INTL, Model Number DDBB2D1;  Implantable Cardioverter Defibrillators', 'There Is A Rare Potential For Reduced- Or No-Energy Output During High Voltage (Hv) Therapy (Typically 0-12J) In Implantable Cardioverter Defibrillators (Icds) And Cardiac Resynchronization Therapy Defibrillators (Crt-Ds) Manufactured With A Specific (Glassed) Feedthrough, Including Currently Available Icds And Crt-Ds.', 'Electrical Fault', 'Not Specified', 'There is a rare potential for reduced- or no-energy output during high voltage (HV) therapy (typically 0-12J) in implantable cardioverter defibrillators (ICDs) and cardiac resynchronization therapy defibrillators (CRT-Ds) manufactured with a specific (glassed) feedthrough, including currently available ICDs and CRT-Ds.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1707-2023');
INSERT INTO safety_incidents VALUES ('eff38bcc01a45c4cf8d185bc485f24d71d0769e0', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'REF 5065, Kendall, Impad Rigid Sole Foot Cover, Regular Pair ,<12", Rx Only Non-Sterile', 'Through Complaint Surveillance, It Was Identified That Reprocessed Deep Vein Thrombosis (Dvt) Compression Sleeves May Be  Mislabeled And/Or Mispackaged.', 'Other', 'Not Specified', 'Through complaint surveillance, it was identified that reprocessed Deep vein thrombosis (DVT) Compression Sleeves may be  mislabeled and/or mispackaged.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1612-2023');
INSERT INTO safety_incidents VALUES ('c4753dbdcc902441303f0b0bb0cbcc569bda6054', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Slick Set Cuffed Endotracheal Tube and Stylet Set, oral/nasal, REF 170085', 'Reports Of Disconnection Of The 15Mm Connector From The Endotracheal Tube (Et Tube) For The Affected Products.', 'Other', 'Not Specified', 'Reports of disconnection of the 15mm connector from the endotracheal tube (ET tube) for the affected products.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1834-2023');
INSERT INTO safety_incidents VALUES ('9c24aaa91bb7825216362bd0a9bde28ffe041ede', 'FDA', '2025-01-02', 2025, '2025-01', 'USA', 'United States', 'United States', 'Medical Devices', 'BD Pyxis MedStation ES, REF: 323,    BD Pyxis MedStation ES 7 Drawer Auxiliary, REF: 324,   BD Pyxis MedStation ES Tower, REF: 352,   BD Pyxis Pro 7-Drawer Auxiliary, REF: 1149-00,   BD Pyxis Pro 7- Drawer Auxiliary with Secure Tower, REF: 1152-00,   BD Pyxis Pro MedStation Main, REF: 1155-00,    BD', 'Automated Dispensing Cabinets (Adc) Received A Half Height Cubie Drawer Firmware Update, Which Caused A Cubie Insert Event Which Prompts Software To Generate A Duplicate Address, Which Causes An Error And The Drawer To Fail, Which May Lead To Inability Or Delay In Accessing Stored Items, Delay In The Replenishment Of Adcs Or Patient Specific Medications Stored Outside Of Adcs.', 'Chemical / Toxic Substance', 'Not Specified', 'Automated Dispensing Cabinets (ADC) received a Half Height CUBIE drawer firmware update, which caused a Cubie Insert event which prompts software to generate a duplicate address, which causes an error and the drawer to fail, which may lead to inability or delay in accessing stored items, delay in the replenishment of ADCs or patient specific medications stored outside of ADCs.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0962-2026');
INSERT INTO safety_incidents VALUES ('6609210ce03f91b244164019878cd9ead4279b9a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', '3COR DISTRACTION SCREW, 12 MM, STERILE, 5/BOX - Product Usage: intended to be used for distraction in the anterior approach to the cervical spine.', 'Lack Of Pouch Seal.  Product Is Labelled As Sterile.', 'Other', 'Not Specified', 'Lack of pouch seal.  Product is labelled as sterile.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2524-2020');
INSERT INTO safety_incidents VALUES ('a6e4066cd3d993ff4d5f0ac485926a0fadfbd7a8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Integris Allura 9, system codes 722018  722021', 'A Capacitor Inside The Converter Of The Velara X-Ray Generator May Fail After A Large Number Of Surges In A Short Period Of Time. When This Occurs, No Image Acquisition Is Possible.', 'Other', 'Not Specified', 'A capacitor inside the converter of the Velara X-ray generator may fail after a large number of surges in a short period of time. When this occurs, no image acquisition is possible.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1488-2020');
INSERT INTO safety_incidents VALUES ('08b983aabc694c76a56f31426b903eed73080096', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD Connecta Stopcock Without Extension Tube  Catalog No. 394601 (OUS)', 'Contamination', 'Other', 'Not Specified', 'May have the potential for leakage at the housing component of the stopcock, may result in delay or interruption in treatment, exposure to infusate and biohazardous material, under dosing/under infusion, contamination and/or air ingress.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1433-2022');
