INSERT INTO safety_incidents VALUES ('116c4e9898e0f4064fd3c5f50393c31958593788', 'FDA', '2023-01-01', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'EVIS EXERA III BRONCHOVIDEOSCOPE OLYMPUS Model Number BF-P190', 'There Is A Risk Of Endobronchial Combustion If High-Frequency Cauterization Is Performed While Supplying Oxygen [And/Or] The Electrode Section Of The Electrosurgical Accessory Is Too Close To The Distal End Of The Endoscope.', 'Flammability / Overheating', 'Not Specified', 'There is a risk of endobronchial combustion if high-frequency cauterization is performed while supplying oxygen [and/or] the electrode section of the electrosurgical accessory is too close to the distal end of the endoscope.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0194-2024');
INSERT INTO safety_incidents VALUES ('f4d0352387fa98423e55d78fee657ee1cf42b0ae', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'PROPONENT DR Pacemaker, SL (Model Number L201), (VDD) SL (Model Number L209), SL MRI (Model Number L211), EL (Model Number L221), and EL MRI (Model Number L231).', 'A Subset Of Devices From The Accolade Family Of Pacemakers And Crt-Ps, Built Before September 2018, Have An Increased Potential To Initiate Safety Mode During Telemetry Or Other Normal, Higher-Power Operations Due To Latent High Battery Impedance.', 'Other', 'Not Specified', 'A subset of devices from the ACCOLADE Family of Pacemakers and CRT-Ps, built before September 2018, have an increased potential to initiate Safety Mode during telemetry or other normal, higher-power operations due to latent high battery impedance.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0823-2025');
INSERT INTO safety_incidents VALUES ('fc0fd97d336b2c2d50ff8e55063358f2a9b1f809', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Zimmer Periarticular Locking Plate (ZPLP) Distal Lateral Femoral Plate 6 holes 159 mm Length-Indicated for temporary internal fixation and stabilization of osteotomies and fractures, including comminuted fractures, supracondylar fractures, intra-articular and extra-articular condylar fractures, frac', 'Thread Form Issue Of The Locking Holes In That The Locking Screws Would Not Properly Mate With The Plate. The Improperly Mated Screw May Not Be Readily Recognizable By The User Since The Screw May Not Correctly Lock.', 'Mechanical Failure', 'Fracture / Blunt Trauma', 'Thread form issue of the locking holes in that the locking screws would not properly mate with the plate. The improperly mated screw may not be readily recognizable by the user since the screw may not correctly lock.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2254-2023');
