INSERT INTO safety_incidents VALUES ('5a9c6b1852021dd334139bf7d10663a6461d822a', 'FDA', '', 0, nan, 'USA', 'United States', 'Belgium', 'Medical Devices', 'IDM-MICRO-R. Electrical wheelchair component.', 'Devices With Firmware Versions 2.3 And Lower May Experience Timing Variations Between Software Tasks, Which Could Result In Skipping The Necessary Neutral Check And The Wheelchair Producing Unintended Movement Upon Power-Up When The Joystick Is Out Of Neutral.', 'Electrical Fault', 'Not Specified', 'Devices with firmware versions 2.3 and lower may experience timing variations between software tasks, which could result in skipping the necessary neutral check and the wheelchair producing unintended movement upon power-up when the joystick is out of neutral.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2456-2025');
INSERT INTO safety_incidents VALUES ('232ef7c9e0031faa482df3cf51159efc31e4803e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Centurion manual surgical kits labeled as:   a) STERILE 4-1/2" S/S SCISSOR (SS5031), Product Code 65145;   b) STERILE S/B SCISSOR 4-1/2" (I142), Product Code 65940;   c) STERILE S/B SCISSOR 5-1/2" (I140), Product Code 65945;   d) STERILE CURV IRIS SCISSOR (IC164), Product Code 66150;   e) STERILE ST', 'Product May Have A Weak Seal Which May Result In A Breach Of Sterility Of The Contents If The Seal Fails. The Weak Seal May Not Be Detectable By All Users.', 'Other', 'Not Specified', 'Product may have a weak seal which may result in a breach of sterility of the contents if the seal fails. The weak seal may not be detectable by all users.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1444-2024');
