INSERT INTO safety_incidents VALUES ('52e51a1315204b1ad7e08e7034c24c9b3fe70ec4', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline Neuro Sponges, various dimensions, labeled as:    1. Neuro Sponges,  Eponges neuro,  Neuroesponjas,  size 0.25" X 0.25", XR, 10/PK, Medline SKU NEUROSPNG02;   2. Neuro Sponges,  Eponges neuro,  Neuroesponjas,  size 0.5" X 0.5", XR, 10/PK, Medline SKU NEUROSPNG05;   3. Neuro Sponges,  Eponges', 'During An Internal Review, Medline Identified Higher-Than-Expected Endotoxin Levels On A Representative Medline Neuro Sponge Product, Indicating That In-Market Product May Be Out-Of-Specification For Endotoxin.', 'Other', 'Not Specified', 'During an internal review, Medline identified higher-than-expected endotoxin levels on a representative Medline neuro sponge product, indicating that in-market product may be out-of-specification for endotoxin.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2008-2026');
INSERT INTO safety_incidents VALUES ('db4465f8a3487eb1fdab085285c088e8f9a94466', 'FDA', '', 0, nan, 'USA', 'United States', 'France', 'Medical Devices', 'Remisol Advance running on hardware with Windows XP, Windows 7, Windows Server 2003 and Windows Server 2008 operating systems', 'A Patch Was Released For A Critical Remote Code Execution Vulnerability In Remote Desktop Services. This Vulnerability Can Be Exploited Remotely Without Authentication On Certain Operating Systems. An Attacker Who Successfully Exploited This Vulnerability Could Execute Arbitrary Code On The Target System; Then Install Programs; View, Change, Or Delete Data; Or Create New Accounts With Full User Rights. If The Vulnerability Could Be Exploited Locally, It Would Lock Down The Computer.', 'Other', 'Laceration / Cut', 'A patch was released for a critical remote code execution vulnerability in remote desktop services. This vulnerability can be exploited remotely without authentication on certain operating systems. An attacker who successfully exploited this vulnerability could execute arbitrary code on the target system; then install programs; view, change, or delete data; or create new accounts with full user rights. If the vulnerability could be exploited locally, it would lock down the computer.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1430-2020');
INSERT INTO safety_incidents VALUES ('b69de13ce46d4a0e1c8df3c8901d14f4e5ad0b76', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Biofinity XR Toric 6-pack- Soft (hydrophilic) Contact Lens (extended wear)', 'Manufactured With Misaligned Axis Resulting In  Lenses With The Incorrect Power, Users May Experience Poor Visual Acuity', 'Other', 'Not Specified', 'Manufactured with misaligned axis resulting in  lenses with the incorrect power, users may experience poor visual acuity', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1197-2023');
