INSERT INTO safety_incidents VALUES ('06251af75317ff7100d89993b8b399377e13917c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Accolade pacemaker, Models:  a) L300   b) L301  c) L310  d) L311  e) L321  f) L331', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'Latent release of small amounts of hydrogen within the pacemaker may cause a low voltage capacitor to become electrically compromised over time resulting in accelerated battery depletion of the battery and associated progression of displayed battery depletion indicators.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2000-2021');
INSERT INTO safety_incidents VALUES ('37a907dae913f4bbd67ea238c526e4c43d698f7f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Boston Scientific NephroMax Kit, Material Numbers (UPN):    1.	M0062101180;    2.	M0062101600.     (Urology)', 'The Encore 26 Inflation Device Is Used With Balloon Dilation Catheters To Create And Monitor Pressure In The Balloon And To Deflate The Balloon. An Internal Investigation Determined That During Use, Foreign Material Particles Could Migrate From Affected Encore 26 Inflation Devices Into A Balloon Dilatation Catheter.', 'Explosion', 'Not Specified', 'The Encore 26 Inflation Device is used with balloon dilation catheters to create and monitor pressure in the balloon and to deflate the balloon. An internal investigation determined that during use, foreign material particles could migrate from affected Encore 26 Inflation Devices into a balloon dilatation catheter.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2535-2025');
