INSERT INTO safety_incidents VALUES ('0a91b9b7dc882dd31481342dadc766ef935a7184', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Ingenia 1.5T with Evolution Upgrade 1.5T - Magnetic Resonance (MR) systems are Medical Electrical Systems indicated for use as a diagnostic device  REF: 782116', 'Burns', 'Electrical Fault', 'Burns', 'Philips Ingenia Evolution systems with software R5.7.1 may not provide warning for low ventilation setting which may lead to increase in body temperature or burning sensation', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1829-2024');
INSERT INTO safety_incidents VALUES ('8f73ad2ebc642040852f756c5f39ccda4ca34407', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Tubing with male luer lock adapter (Component)   a. 76 cm, REF 601280   b. 122 cm, REF 607281.  component of extravascular  blood-pressure Transducer.', 'Specific Lots Of Medex High Pressure Adaptors, Rotators, Manifolds, Stopcocks And Tubing And Medex Logical Kits May Have Been Manufactured With Insufficient Or Incomplete Welds. These Are Components For Various Cardiac Kits Including Pressure Monitoring Devices And Interventional Imaging Devices.', 'Explosion', 'Not Specified', 'Specific lots of Medex High Pressure Adaptors, Rotators, Manifolds, Stopcocks and Tubing and Medex LogiCal Kits may have been manufactured with insufficient or incomplete welds. These are components for various cardiac kits including pressure monitoring devices and interventional imaging devices.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1480-2021');
INSERT INTO safety_incidents VALUES ('1d29503cdbb339a9b956f8010965c3b315863864', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Procedure pack:  Presource PBDS Cat. PLMHCSBHF, Hermann Hospital MHHS, Kit, C Section B MHHS, Sterile.', 'Packs Contain Recalled Components (Equipment Drapes, Table Cover, And Surgical Room Turnover (Srt) Kits).', 'Other', 'Not Specified', 'Packs contain recalled components (equipment drapes, table cover, and surgical room turnover (SRT) kits).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0090-2024');
