INSERT INTO safety_incidents VALUES ('4ca2136f3546878de4566929d4fdb3298a9f92c1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline custom medical procedure kits labeled as:    1) ENSEMBLE RACHIS-LF, REF DYNJ47568B;   2) UROLOGY ROBOTIC, REF DYNJ55555D;   3) KIT,SPINE LH, REF DYNJ906448A.', 'Contamination', 'Other', 'Not Specified', 'Custom convenience kits are being recall because the contain non-sterile Codman Surgical Patties & Surgical Strips, which have the potential for endotoxin contamination.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0792-2025');
INSERT INTO safety_incidents VALUES ('734ab5a5680c22cb9a981d4c3fabff733daf875c', 'FDA', '2023-01-02', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Ivenix Infusion System (IIS), Large Volume Pump LVP-0004', 'The Device May Experience Mechanical Interference On The Fluid Valve Pins, Which Will Trigger A Pump Problem Alarm. The Issue May Lead To Delay Or Interruption Of Therapy. Depending On The Therapy And Duration Of Delay/Interruption, The Issue May Lead To Serious Harm Or Death.', 'Chemical / Toxic Substance', 'Not Specified', 'The device may experience mechanical interference on the Fluid Valve pins, which will trigger a Pump Problem alarm. The issue may lead to delay or interruption of therapy. Depending on the therapy and duration of delay/interruption, the issue may lead to serious harm or death.', 'Fatal', 0, 0, 'Voluntary: Firm initiated', 'Z-0549-2024');
INSERT INTO safety_incidents VALUES ('71dd2a7af8d0a01b46df7f6443a6f74bffea9045', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Palindrome Precision RT Chronic Catheter Kit Symmetrical Tip, Reverse-Tunneled 15 Fr/Ch (5.0 mm) x 33 cm, Item Code 8888541033P', 'This Voluntary Withdrawal Is Being Conducted To Implement Point-Of-Use Labeling On Each Device And Enhancements To The Instructions For Use (Ifu).', 'Other', 'Not Specified', 'This voluntary withdrawal is being conducted to implement point-of-use labeling on each device and enhancements to the Instructions for Use (IFU).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2373-2021');
INSERT INTO safety_incidents VALUES ('b467b702437f1f0d89ca055da38c60bcb3ae67c8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'nanoDot D2DNS, Model Numbers:    a) 18100-000;   b) 18100-1MO;   c) 18100-2MO;   d) 18100-KIT; radiation monitoring dosimeter used with the microSTAR readers', 'Radiation', 'Radiation', 'Radiation Exposure', 'LANDAUER received reports indicating that some nanoDots may potentially be outside of the specified range of +/-5.5% accuracy. Investigation of nanoDots indicated the presence of a potential non-conformance in the Optical Stimulated Luminescence (OSL) material that is beamed after exposure and emits fluorescence proportional to radiation exposure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2562-2023');
INSERT INTO safety_incidents VALUES ('9f4519cad8de605c2f634fecaae682a9221b44de', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE TRAY TRACH BASIC SOLUTION, REF DYND40511', 'Medline Industries, Lp Is Recalling Certain Kits And Trays That Were Manufactured Using Specific Lots Of Nurse Assist (As Components):  0.9% Sodium Chloride Irrigation Usp, Sterile Water For Irrigation Usp And Saline Flush Syringe. Nurse Assist Issued A Recall Due To The Potential Lack Of Sterility, Which Could Result In The Solution Being Non Sterile.', 'Drowning Risk', 'Not Specified', 'Medline Industries, LP is recalling certain kits and trays that were manufactured using specific lots of Nurse Assist (as components):  0.9% Sodium Chloride Irrigation USP, Sterile Water for Irrigation USP and Saline Flush Syringe. Nurse Assist issued a recall due to the potential lack of sterility, which could result in the solution being non sterile.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1090-2024');
