INSERT INTO safety_incidents VALUES ('695357e0b7a5ddf143667ad29b9ac0a65c29bb0b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ICD DDPA2D1G COBALT XT DR MRI DF1 GOLD, Model Number DDPA2D1G;  Implantable Cardioverter Defibrillators', 'There Is A Rare Potential For Reduced- Or No-Energy Output During High Voltage (Hv) Therapy (Typically 0-12J) In Implantable Cardioverter Defibrillators (Icds) And Cardiac Resynchronization Therapy Defibrillators (Crt-Ds) Manufactured With A Specific (Glassed) Feedthrough, Including Currently Available Icds And Crt-Ds.', 'Electrical Fault', 'Not Specified', 'There is a rare potential for reduced- or no-energy output during high voltage (HV) therapy (typically 0-12J) in implantable cardioverter defibrillators (ICDs) and cardiac resynchronization therapy defibrillators (CRT-Ds) manufactured with a specific (glassed) feedthrough, including currently available ICDs and CRT-Ds.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1722-2023');
