INSERT INTO safety_incidents VALUES ('b5407e27b49f813d543215be6b3a0a225fa954c2', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'OUTLOOK PUMP SET 3 CARESITE LADS 133 IN.-Used with an electrically-powered infusion pump for intravenous (IV) administration of medication    Model/ Catalog Number: 490564', 'Potential For The Backcheck Valve To Malfunction, Resulting In Backflow Of Medication From Secondary (Piggyback) Iv Containers Into Primary Iv Containers And The Inability To Prime, Resulting In Patient Injuries Of Adverse Drug Reaction And/Or Product  Malfunction With Loss Of Medication/Blood.', 'Mechanical Failure', 'Not Specified', 'Potential for the backcheck valve to malfunction, resulting in backflow of medication from secondary (piggyback) IV containers into primary IV containers and the inability to prime, resulting in patient injuries of adverse drug reaction and/or product  malfunction with loss of medication/blood.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2404-2024');
INSERT INTO safety_incidents VALUES ('b279533b7b577f9372c9273366558162cfcd3d2c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'UIBC (Unsaturated Iron Binding Capacity), REF: OSR61205,', 'Beckman Coulter Identified That The Unsaturated Iron Binding Capacity (Uibc) Assay Is Not Meeting Their Labeled Hemoglobin Interference Claims Of No Significant Interference (I.E., Less Than 10%) Up To 200 Mg/Dl Hemoglobin As Indicated In Their Instructions For Use. Initial Internal Testing Confirmed That Samples With Low Uibc Levels Failed The Claimed Hemolysis Interference Specifications With Reported Biases Up To -43.6 % Uibc When Hemolyzed Serum Samples Contained 200 Mg/Dl Hemoglobin.', 'Other', 'Not Specified', 'Beckman Coulter identified that the Unsaturated Iron Binding Capacity (UIBC) assay is not meeting their labeled hemoglobin interference claims of no significant interference (i.e., less than 10%) up to 200 mg/dL hemoglobin as indicated in their instructions for use. Initial internal testing confirmed that samples with low UIBC levels failed the claimed hemolysis interference specifications with reported biases up to -43.6 % UIBC when hemolyzed serum samples contained 200 mg/dL hemoglobin.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2264-2025');
INSERT INTO safety_incidents VALUES ('9cfbec0a079ca02a3cd77d84f3e28206e1a48fe8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Datascope Intra-Aortic Ballon Catheters (IABs)-Linear 7.5Fr 34cc IAB Kit P/N: 0684-00-0479-01, 0684-00-0479-01C, 0684-00-0479-01U, 0684-00-0479-02, 0684-00-0479-02U, 0684-00-0479-07, 0684-00-0479-08, 0684-00-0479-10 - Product Usage: Indications For  Use: Acute Coronary Syndrome Cardiac and Non-Cardi', 'Contamination', 'Other', 'Laceration / Cut', 'Potential Endotoxin Contamination', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2839-2020');
