INSERT INTO safety_incidents VALUES ('42e966cd4247a0460678b940c9cac03cb98ac88c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Fixed Core Wire Guide (Safe-T-J Curved), Guidewire  Reference Part Number/GPN:  TSCF-25-180-3	G01602  TSCF-35-180-3	G00902  TSCF-21-260-3	G00455  THSCF-25-260-3	G02384  TSCF-25-145-3	G00466  THSCF-35-80-3	G04069  THSCF-35-180-15	G01151  TSCF-21-50-3	G00456  THSCF-35-145-3	G00412  TSCF-35-145-15	G005', 'Cook Medical Identified That Devices From The Affected Device Lots May Have A Complete Breach Of The Chevron Seal Of The Packaging. Therefore, The Sterility Of Affected Devices May Be Compromised.', 'Other', 'Not Specified', 'Cook Medical identified that devices from the affected device lots may have a complete breach of the chevron seal of the packaging. Therefore, the sterility of affected devices may be compromised.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1833-2022');
INSERT INTO safety_incidents VALUES ('78236f9fc7c70c1516af0ac439c85e827bc840ed', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'See RES for complete list. Medline Convenience Kits: 1) PLASTIC BIN W/MISC KITS, Model Number: ACC010499; 2) BREAST-HERNIA-PORT CDS-LF, Model Number: CDS984853J; 3) KIT UROLOGY URETHROPLASTY, Model Number: DYKMBNDL117C; 4) KIT PLASTIC INSERT TISSUE EXPA, Model Number: DYKMBNDL158; 5) KIT PLASTIC ABD', 'Medline Has Identified Issues Related To Calibration Of The Equipment Used To Sterilize And Package The Devices. All Products Were Exposed To The Validated Sterilization And Packaging Cycles; However, The Identified Calibration Issues Have The Potential To Impact The Sterility Assurance Level (Sal) Of The Recalled Products.', 'Other', 'Fracture / Blunt Trauma', 'Medline has identified issues related to calibration of the equipment used to sterilize and package the devices. All products were exposed to the validated sterilization and packaging cycles; however, the identified calibration issues have the potential to impact the sterility assurance level (SAL) of the Recalled Products.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2099-2026');
