INSERT INTO safety_incidents VALUES ('fd5f421e91c703bf62c74b5c3b7847abaff47dec', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Abbott Cholestech LDX Battery Kit, Model: 3LP656194-PCM-LD, PN: 55170', 'Burns', 'Electrical Fault', 'Laceration / Cut', 'There is a potential that the Cholestech LDX battery (an external battery pack available as an optional accessory to the Cholestech LDX Analyzer) may swell which could cause minor burns, cuts or abrasions, or low current electrical shock to the user.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1702-2024');
