INSERT INTO safety_incidents VALUES ('c842249c54b282eefdace5437a25d4fcf91c8038', 'FDA', '', 0, nan, 'USA', 'United States', 'Israel', 'Medical Devices', 'Elscint SPX6; dual-head nuclear medicine gamma camera designed specifically for cardiac imaging', 'Injury', 'Chemical / Toxic Substance', 'Fall Injury', 'GE HealthCare has become aware that certain Nuclear Medicine systems that are past the End of Guaranteed Service could have been transported or relocated without adequate detector support. This could result in excessive stress being applied to the detector mounting mechanisms, compromising their integrity. If this occurs, it can potentially result in a detector fall and lead to life-threatening bodily injury.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0293-2026');
