INSERT INTO safety_incidents VALUES ('5fe2de37c18b3b0c4ceb6f914a901a76683fe7a7', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BVI CustomEyes Procedure Packs containing Sol-M Luer Lock and Luer Slip 1ml syringes, Part Number: 58001944;', 'Due To A Voluntary Recall Of Low Dead Space Syringes, And Luer Slip Tip Syringes Manufactured By Sol-Millennium Medical (Sol-M), Inc. These Syringes  Manufactured By Sol-M Are Present In Some Of Bvi Customeyes Procedure Packs.', 'Other', 'Eye Injury', 'Due to a voluntary recall of low dead space syringes, and luer slip tip syringes manufactured by Sol-Millennium Medical (Sol-M), Inc. These syringes  manufactured by Sol-M are present in some of BVI CustomEyes Procedure Packs.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2928-2024');
