INSERT INTO safety_incidents VALUES ('17fe0bde59b7f31bc555757758d69a7da46a6494', 'FDA', '2020-01-02', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Cardioblate CryoFlex, Surgical Ablation Probe, Model Number 60SF7, PROBE 60SF7 CRYOFLEX 7CM 26L - is a single use, disposable cryoprobe that is designed for use with the CryoFlex Surgical Ablation System. The probe has an integrated thermocouple for monitoring temperature at its ablation segment.', 'There Is A Potential Defect In The Seals Of The Sterile Barrier Pouch Used To Package The Cryoflex Disposables Devices', 'Mechanical Failure', 'Not Specified', 'There is a potential defect in the seals of the sterile barrier pouch used to package the CryoFlex disposables devices', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0495-2021');
INSERT INTO safety_incidents VALUES ('63805fb0da3fc2717ce6d478d024b9c03cff11bd', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Model Number L211 PROPONENT DR SL MRI Pacemaker', 'Software To Enhance Safety Architecture Is Available And Designed To Prevent Initiation Of Safety Mode In An Ambulatory Setting Due To A High Battery Impedance State   For The Accolade Family Of Devices Which Includes Accolade, Proponent, Essentio, And Altrua 2 Dual Chamber (Dr) Standard Life (Sl) And Dr Extended Life (El) Pacemakers; And Visionist And Valitude Cardiac Resynchronization Therapy Pacemakers (Crt-Ps).', 'Other', 'Eye Injury', 'Software to enhance Safety Architecture is available and designed to prevent initiation of Safety Mode in an ambulatory setting due to a high battery impedance state   for the ACCOLADE family of devices which includes ACCOLADE, PROPONENT, ESSENTIO, and ALTRUA 2 dual chamber (DR) standard life (SL) and DR extended life (EL) pacemakers; and VISIONIST and VALITUDE cardiac resynchronization therapy pacemakers (CRT-Ps).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0089-2026');
