INSERT INTO safety_incidents VALUES ('633ccb271bcbf0507750f23731e57066f66d9339', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Sterile Custom Packs to  be used in surgical procedures.', 'The Surgical Gowns Were Manufactured In A Facility That Is Not Registered By The Fda.', 'Other', 'Not Specified', 'The surgical gowns were manufactured in a facility that is not registered by the FDA.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2176-2020');
INSERT INTO safety_incidents VALUES ('e8a4994659babce8e1bf748afdb057cecb30c52e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'AccuVu Angiographic Catheter, Straight Flush, Non-Braided, With 10 R/O Markers;  ACCU-VU STR FL 4F X 100CM 035 NB 6SH 10 R/O 6@1CM 4@5CM;  Catalog No.: 13709604;  Product/UPN No.: H787137096045 (Box), H787137096040 (Pouch);  Box Quantity: 5 pouches;', 'The Affected Devices Contain A Manufacturing Defect Which May Prevent The Appropriately Sized Guidewire From Passing Through The Inner Diameter (Id) Of The Catheter Hub.', 'Mechanical Failure', 'Not Specified', 'The affected devices contain a manufacturing defect which may prevent the appropriately sized guidewire from passing through the inner diameter (ID) of the catheter hub.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1873-2026');
INSERT INTO safety_incidents VALUES ('124bc8e4fbde4f4de40dd050ec187529f52b01c9', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Smart Stapes Protheses Piston  0.6mm X 4.25 mm- Partial Ossicular Replacement    Catalog Number: 70143662', 'Mislabeled Outer Carton: Packaged With The Outer Carton Label Stating The Contents Were The 70143662 Smart Piston But The Inside Package Contents Was The 70142158 Stapes Piston; See Image Below', 'Other', 'Not Specified', 'Mislabeled outer carton: packaged with the outer carton label stating the contents were the 70143662 Smart Piston but the inside package contents was the 70142158 Stapes Piston; see image below', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2814-2020');
