INSERT INTO safety_incidents VALUES ('c406ba7467861e26bcb88dde5baec092b32c7ee8', 'FDA', '2020-01-01', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'ZCA All Poly Acetabular Cup Longevity Crosslinked Polyethylene, I.D. 26 mm, 10 degree inclined face, O.D. Cup with Spacers, 51 mm    Number: 00-8065-648-26', 'Sterilant (Hydrogen Peroxide) Used In Acetabular Cup Hip Prosthesis Component Was Not Evaluated To Confirm The Biocompatibility Of The Residual Sterilant.  Cannot Rule Out The Potential For Adverse Tissue Reactions.', 'Other', 'Not Specified', 'Sterilant (hydrogen peroxide) used in acetabular cup hip prosthesis component was not evaluated to confirm the biocompatibility of the residual sterilant.  Cannot rule out the potential for adverse tissue reactions.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0368-2021');
