INSERT INTO safety_incidents VALUES ('b42ef2f2ffee7b3deed05f0be9ef926dffea30b0', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'McCormick Medical Distribution PORT TRAY, 25 trays per case.  Distributed by McCormick Medical Distribution.', 'Potential For The Outer Bag Having Pinhole Leaks Near The Seal, Which May Result In A Breach In The Sterility Of The Kit.', 'Other', 'Not Specified', 'Potential for the outer bag having pinhole leaks near the seal, which may result in a breach in the sterility of the kit.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0943-2023');
INSERT INTO safety_incidents VALUES ('8cd9e3b73bb08443b4430baed2b45d0766607ef9', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Convenience kits containing Tego Connectors    Medline DIALYSIS DRSNG CHNG  SKU DYNDC3167', 'Affected Lots May Exhibit Issues With The Silicone Seal On Tego Connectors Included In Kits. Issues Include Silicone Seal Doming And Silicone Seal Tearing. These Issues May Result In An Occluded Fluid Path Identified By The Inability Of The User To Inject Or Withdraw Blood Product With A Syringe. Damaged Seals May Also Result In Delay In Therapy Or Fluid Leakage, Interruption In Therapy, Exposure To Biological Contaminants Or Air Infused Into The Body.', 'Other', 'Not Specified', 'Affected lots may exhibit issues with the silicone seal on Tego Connectors included in kits. Issues include silicone seal doming and silicone seal tearing. These issues may result in an occluded fluid path identified by the inability of the user to inject or withdraw blood product with a syringe. Damaged seals may also result in delay in therapy or fluid leakage, interruption in therapy, exposure to biological contaminants or air infused into the body.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1468-2026');
