INSERT INTO safety_incidents VALUES ('6bec8d091925d390e03315b90e056ef26d1f91fe', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Philips Respironics V60 Ventilator Part Number 1053615 - Product Usage: intended to be used only with various combinations of Respironics-recommended patient circuits, interfaces (masks), humidifiers, and other accessories.', 'Ventilator May Experience Potential Issues With The Backup Battery Failures: 1) If The Battery Is Allowed To Over Discharge, Or 2) If The Ventilator Is Stored For An Extended Period Of Time Without Being Plugged Into Ac Power.', 'Other', 'Not Specified', 'Ventilator may experience potential issues with the backup battery failures: 1) if the battery is allowed to over discharge, or 2) if the ventilator is stored for an extended period of time without being plugged into AC power.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0887-2021');
