INSERT INTO safety_incidents VALUES ('a463bfb50fdd14e7cfc3e4e7f8b1bf8fb65f4c68', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline medical procedure convenience kits labeled as:  KIT ROBOTICS UROLOGY PROSTATE, REF DYKMBNDL116G', 'Medline Kits Containing Stryker''S Strykeflow 2 Suction Irrigators Due To A Change In Design In 2024, Irrigation Solution Is Able To Travel To The Handpiece And Battery Pack During Use Of The Strykeflow 2 Suction Irrigator. This Design Change Has Caused Some Devices To Leak And/Or Emit Vaporized Saline (Which Can Resemble Smoke) During Use.', 'Flammability / Overheating', 'Not Specified', 'Medline kits containing Stryker''s Strykeflow 2 Suction Irrigators due to a change in design in 2024, irrigation solution is able to travel to the handpiece and battery pack during use of the Strykeflow 2 Suction Irrigator. This design change has caused some devices to leak and/or emit vaporized saline (which can resemble smoke) during use.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1090-2026');
INSERT INTO safety_incidents VALUES ('55f93b7d1db59d7b38623ea4fc7ee136e383dcc5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Philips Respironics Trilogy Evo Universal, Software Version 1.05.15.00. Continuous home-use ventilator device.', 'Using Non-Pneumatic Nebulizers With Trilogy Evo Platform Ventilators May Result In A Discrepancy Between The Set Tidal Volume And The Tidal Volume Received By The Patient.', 'Other', 'Not Specified', 'Using non-pneumatic nebulizers with Trilogy Evo Platform ventilators may result in a discrepancy between the set tidal volume and the tidal volume received by the patient.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1617-2026');
INSERT INTO safety_incidents VALUES ('9db6eab7d3ff8c0c2213da133ec76497e2808900', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'PTS Diagnostics CardioChek Plus Professional Analyzer, New analyzer, boxed, with carrying case, Reference Numbers 2700', 'One Brand Of Batteries Have A Small Dimensional Difference In The Negative Button Terminal, Which, When The Batteries Are Inserted Incorrectly, Can Create The Possibility For The Battery Terminals To Make Reverse Contact.  This Reverse Contact Can Cause A Potential For Overheating.', 'Flammability / Overheating', 'Not Specified', 'One brand of batteries have a small dimensional difference in the negative button terminal, which, when the batteries are inserted incorrectly, can create the possibility for the battery terminals to make reverse contact.  This reverse contact can cause a potential for overheating.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0832-2020');
