INSERT INTO safety_incidents VALUES ('ff88364e3dd0fa9b635c05524dec38b2afd094be', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'AquaC UNO H [120V, 60Hz, 1700VA,   Fresenius US-Version: 24-0970-1  Vivonic Part Number: G02000966-US', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Internal ethernet cable may be misaligned, the cable jacket (insulation) could become compromised due to high temperature and result in the internal ethernet cable conducting electrical current to the ethernet port on the outside of the device), potentially harming service technicians and/or other authorized operators.  If the ethernet port on the device is touched or manipulated, there is a risk of electrical shock', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1463-2022');
