INSERT INTO safety_incidents VALUES ('165aa2db3a790f32355335e66ee78fdedcc28438', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CADD-Solis VIP ambulatory Infusion Pumps, Model 2120 (INSERT INTO safety_incidents VALUES ('901f274ba1bbe971c38470a04613d895178e4899', 'FDA', '', 0, nan, 'USA', 'United States', 'Israel', 'Medical Devices', 'Microstream Instructions for Use and Part Number used with - Product Description, REF:     FilterLine Sets & VitaLine Sets Adult/Pediatric, MQ04616 -     MICROSTREAM FilterLine H Set Long Adult-Pediatric CO2 Sampling Line and Airway Adapter for Humid Environments, 007737;    MICROSTREAM FilterLine S', 'Neonatal-Infant And Adult-Pediatric Co2 Sampling Line/Airway Adapter/Co2 Oral-Nasal Filter Line/Intubated Filter (Co2) Line Device Users May Experience Difficulty/Inability To Disconnect Adapter From Endotracheal Tube For Procedures (E.G. Suctioning), May Cause Treatment Delay And/Or Unintended Extubation, Which Could Lead To Respiratory Failure, Hypoxia, Aspiration, And/Or Low Oxygen Saturation.', 'Chemical / Toxic Substance', 'Respiratory', 'Neonatal-Infant and Adult-Pediatric CO2 Sampling Line/Airway Adapter/CO2 Oral-Nasal Filter Line/Intubated Filter (CO2) Line device users may experience difficulty/inability to disconnect adapter from endotracheal tube for procedures (e.g. suctioning), may cause treatment delay and/or unintended extubation, which could lead to respiratory failure, hypoxia, aspiration, and/or low oxygen saturation.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1377-2025');
