INSERT INTO safety_incidents VALUES ('a1c89ddd193f32b7a565a752a130cf196cdb12df', 'FDA', '2023-01-02', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'QUANTUM TTC BILIARY BALLOON DILATOR, REF  QBD-6X3, Order Number G22655; used to dilate strictures of the biliary tree', 'Injury', 'Mechanical Failure', 'Fracture / Blunt Trauma', 'Nonconforming devices while manufactured correctly, do not comply to their design requirements.  Potential harms associated with balloon detachment are endoscopic retrieval of an impacted or non-impacted object, bleeding caused by the retrieval device, or the incident can occur without injury and the object is left to pass naturally.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0460-2024');
INSERT INTO safety_incidents VALUES ('db4febf794a6d00a7d28f686f1f37e23aa36517a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD Pyxis" MedBank" Mini and BD Pyxis" MedBank" Tower, BD Pyxis" MedFlex, BD Pyxis" MedBank" MedPass are automated dispensing cabinets (ADC) intended to securely store and dispense medications to a qualified and authorized user in a clinical settings.', 'Due To A Software Bug, Automated Dispensing Cabinet Is Unable To Calculate Countback Discrepancies During The Issue Process, Which Causes Incorrect Transaction Quantity To Be Recorded. This Bug Can Also Result In The Cubie Opening More Times Than Needed For The Transaction To Be Completed, Which May Result In A Patient Receiving More Than The Intended Dose Of Medication.', 'Other', 'Not Specified', 'Due to a software bug, automated dispensing cabinet is unable to calculate countback discrepancies during the issue process, which causes incorrect transaction quantity to be recorded. This bug can also result in the CUBIE opening more times than needed for the transaction to be completed, which may result in a patient receiving more than the intended dose of medication.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1545-2025');
INSERT INTO safety_incidents VALUES ('4da3b7d20720b0a18b2a303a4b8cdfd91add44bc', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Philips Respironics Trilogy EV300, Software Version 1.05.15.00. Continuous home-use ventilator device.', 'Using Non-Pneumatic Nebulizers With Trilogy Evo Platform Ventilators May Result In A Discrepancy Between The Set Tidal Volume And The Tidal Volume Received By The Patient.', 'Other', 'Not Specified', 'Using non-pneumatic nebulizers with Trilogy Evo Platform ventilators may result in a discrepancy between the set tidal volume and the tidal volume received by the patient.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1616-2026');
INSERT INTO safety_incidents VALUES ('6a99545d8153f96e97a2fa97588326031ad1c67c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ADVIA 2120i (RoHS) Dual Aspirate Autosampler (SMN 11219530) - OUS, automated hematology analyzer     Software Versions 6.10 and 6.11', 'Potential Sample Identification (Sid) Mismatch With14-Character Barcodes', 'Other', 'Not Specified', 'Potential Sample Identification (SID) Mismatch with14-Character Barcodes', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1405-2021');
INSERT INTO safety_incidents VALUES ('c922fa4929ec4a0f0250622113b3ae0c6eb46fa0', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline Kits, trays, and packs labeled as follows:    a) ER LACERATION TRAY - SNAG FREE, REF SUT12825;   b) LACERATION TRAY, REF SUT21580;   c) LACERATION TRAY, REF DYNDL1484B;', 'Medline Industries, Lp Is Recalling Certain Kits And Trays That Were Manufactured Using Specific Lots Of Nurse Assist (As Components):  0.9% Sodium Chloride Irrigation Usp, Sterile Water For Irrigation Usp And Saline Flush Syringe. Nurse Assist Issued A Recall Due To The Potential Lack Of Sterility, Which Could Result In The Solution Being Non Sterile.', 'Sharp Edges / Points', 'Laceration / Cut', 'Medline Industries, LP is recalling certain kits and trays that were manufactured using specific lots of Nurse Assist (as components):  0.9% Sodium Chloride Irrigation USP, Sterile Water for Irrigation USP and Saline Flush Syringe. Nurse Assist issued a recall due to the potential lack of sterility, which could result in the solution being non sterile.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1118-2024');
INSERT INTO safety_incidents VALUES ('954fa7ac35edf11b1ccec99c60d2c1833b4d0998', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'EZDilate Wire Guided Balloon 6-7-8. indicated for endoscopic  dilation of strictures in the alimentary tract in adults and adolescents (>12 years)  Model: BD-410X-0855', 'Product Balloon Issues: Inflating, Deflating And/Or Retrieving The Devices; Reports Of Bursting And Leaking And Events Involving Foreign Body In Patient And Prolonged Procedure.', 'Explosion', 'Not Specified', 'Product balloon issues: inflating, deflating and/or retrieving the devices; reports of bursting and leaking and events involving foreign body in patient and prolonged procedure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0939-2024');
INSERT INTO safety_incidents VALUES ('45c435e50af705ddb2465dfc3e2fbcda1a3f956a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BIOTROL PURIT Clean-It General Purpose Ultrasonic Cleaner, REF PC016, net contents 16 fl. oz., makes 16 gallons of solution.', 'Contamination', 'Microbiological Contamination', 'Not Specified', 'The bulk product used in the recalling firm''s repackaged finished product was recalled due to bacterial contamination.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0008-2025');
INSERT INTO safety_incidents VALUES ('69ffe6e38b6f01a8cf69cb7cdce6d2ddebac3e2b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Polaris Ultra Ureteral Stent Set 6FX24CM with .035 Sensor     UPN: M006192132080', 'An Increase In The Rate Of Complaints For Difficulty Or Inability To Track Over The Guidewire, May Result In A  Procedural Delay Due To The Need To Exchange The Affected Device', 'Other', 'Not Specified', 'An increase in the rate of complaints for difficulty or inability to track over the guidewire, may result in a  procedural delay due to the need to exchange the affected device', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1740-2020');
INSERT INTO safety_incidents VALUES ('cfe7c5cce51a233dd72c7a99021f0eea8d52f1f6', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Flexible Intubation Fiberscope, Part: 11301BN1, with Instruction Manual: Z18441US - Product Usage: are intended to be used for examination and visualization of a patient s upper airway and for aiding placement of an endotracheal tube.', 'Updated Sterilization Instructions Are Being Provided To Ensure 1) A Specific Sterilization Tray Is Not Used, And 2) Ethylene Oxide Sterilization Is Never Used On Certain Reusable Flexible Intubation Endoscopes With Total Lumen Lengths Greater Than 850Mm. Incompletely Sterilized Endoscopes Might Introduce Infectious Agents Into Patient Airways, Resulting In Infection.', 'Other', 'Not Specified', 'Updated sterilization instructions are being provided to ensure 1) a specific sterilization tray is not used, and 2) ethylene oxide sterilization is never used on certain reusable flexible intubation endoscopes with total lumen lengths greater than 850mm. Incompletely sterilized endoscopes might introduce infectious agents into patient airways, resulting in infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2892-2020');
INSERT INTO safety_incidents VALUES ('cc5f14e939fa93398d74f83ecd61463b9d00da0e', 'FDA', '', 0, nan, 'USA', 'United States', 'Germany', 'Medical Devices', 'TOMTEC-ARENA TTA2;software version no. 2.20 and lower; Picture archiving and communications system.    Software Versions and applicable UDI:    TTA 1.2  release prior to UDI requirement  TTA2.00.01  release prior to UDI requirement  TTA2.11.01  release prior to UDI requirement  TTA2.11.02  release p', 'The Firm Discovered A Software Issue Associated With The Image-Com Module/Clinical Application Package (Cap) Interface For 3D Application In The Arena Software, Where Measurements From One Study Might Be Stored To Another Study.', 'Other', 'Not Specified', 'The firm discovered a software issue associated with the Image-Com module/clinical application package (CAP) interface for 3D application in the ARENA software, where measurements from one study might be stored to another study.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2496-2020');
INSERT INTO safety_incidents VALUES ('7c94981a18df6f8a97ea768e0ba1a0fefcb702f5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Wolf Pak Premium Dressing Change Kit with GuardVA and Statlok Cs/30  Ref: DC5090LF', 'Kits Mislabeled As Latex-Free, The Packaging For Component 94-7002 Non-Adherent Dressing Contains Natural Rubber Latex. Potential Risk To To Those With Latex Allergy', 'Allergen', 'Allergic Reaction', 'Kits mislabeled as latex-free, the packaging for component 94-7002 Non-Adherent Dressing contains natural rubber latex. Potential risk to to those with latex allergy', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1551-2022');
INSERT INTO safety_incidents VALUES ('4c36b7e0d8bd74229ea306148b3894f46327cb6a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'C6-2 Transducer Probe', 'To Provide Clarification And Labelling To Define The Useful Life Of Ultrasound Transducers In The Field.', 'Other', 'Not Specified', 'To provide clarification and labelling to define the useful life of ultrasound transducers in the field.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2355-2025');
INSERT INTO safety_incidents VALUES ('6e09100d2e1a4c54941235e9a31a2eb7d0b9f0a3', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Sterile Procedural Trays, labeled as the following:  a.	EAR CDS-LF b.	SINUS CDS-1 c.	ZALE FESS CDS d.	ZALE OTOLOGY CDS e.	ZALE HEAD & NECK CDS f.	CUH PARA/THYROIDECTOMY CDS g.	CAM ENDOSCOPIC SINUS/SEPTO CDS h.	HEAD AND NECK CDS i.	HEAD AND NECK CDS-LF j.	NASAL k.	ENT SET UP CDS l.	MINOR ENT SINUS PA', 'Sterile Blades Within Sterile Kits Have The Potential For The Blade To Puncture The Outer Foil Layer Of The Sterile Packaging.', 'Sharp Edges / Points', 'Not Specified', 'Sterile blades within sterile kits have the potential for the blade to puncture the outer foil layer of the sterile packaging.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1072-2023');
INSERT INTO safety_incidents VALUES ('b252f8513132e449d1d56761aead67d909a00d48', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Norton Arm Kit, Product Code 711400, (previous product code 031001), Sample Kit S711400', 'Affected Products Were Manufactured With Materials Found To Have A Bioburden Level Exceeding The Limit At Which The Product''S Sterilization Process Was Validated. As A Result, The Firm Cannot Provide Full Assurance That The Affected Products Were Effectively Sterilized, And The Product May Compromise A Sterile Field And Increase The Risk Of A Surgical Site Infection.', 'Other', 'Not Specified', 'Affected products were manufactured with materials found to have a bioburden level exceeding the limit at which the product''s sterilization process was validated. As a result, the firm cannot provide full assurance that the affected products were effectively sterilized, and the product may compromise a sterile field and increase the risk of a surgical site infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2390-2021');
INSERT INTO safety_incidents VALUES ('ee36ed96b32c2237eaace363a936c11c4ca389fa', 'FDA', '2020-01-01', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'ZCA All Poly Acetabular Cup Longevity Crosslinked Polyethylene, I.D. 32 mm, Snap-In O.D. Cup with Spacers, 55 mm    Number: 00-8065-952-32', 'Sterilant (Hydrogen Peroxide) Used In Acetabular Cup Hip Prosthesis Component Was Not Evaluated To Confirm The Biocompatibility Of The Residual Sterilant.  Cannot Rule Out The Potential For Adverse Tissue Reactions.', 'Other', 'Not Specified', 'Sterilant (hydrogen peroxide) used in acetabular cup hip prosthesis component was not evaluated to confirm the biocompatibility of the residual sterilant.  Cannot rule out the potential for adverse tissue reactions.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0394-2021');
INSERT INTO safety_incidents VALUES ('4ada5a87758fe06e8607cccb0811e02732da5967', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'OSTEOVATIONEX 5CC, INJECT FORMULA.  Product Number: 390-0005, UDI: 813845020023 - Product Usage: Callos is indicated to fill bony voids or gaps of the skeletal system (i.e. extremities, spine, pelvis). These defects may be surgically created osseous defects or osseous defects created from traumatic ', 'Bone Void Filler Kits May Not Maintain Its Setting Characteristics For The Labeled Shelf-Life Duration. Use May Increase The Required Surgical And Anesthesia Time For The Patient Or Possible Longer-Term Health Consequences Could Include Incomplete Bone Formation Or Lack Of Bone Formation, Delayed Union, Or Nonunion.', 'Mechanical Failure', 'Not Specified', 'Bone void filler kits may not maintain its setting characteristics for the labeled shelf-life duration. Use may increase the required surgical and anesthesia time for the patient or possible longer-term health consequences could include incomplete bone formation or lack of bone formation, delayed union, or nonunion.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2622-2020');
INSERT INTO safety_incidents VALUES ('d9fc4e95ef307be42dbfdc6557d5f4296b3d47a3', 'FDA', '2025-01-02', 2025, '2025-01', 'USA', 'United States', 'United States', 'Medical Devices', 'BIOSURE HA SCREW, 6MM x 20 MM. Threaded metallic bone fixation fastener.', 'Removal Of Affected Lot Of Screws Due To Labeling Error.', 'Other', 'Not Specified', 'Removal of affected lot of screws due to labeling error.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0957-2026');
INSERT INTO safety_incidents VALUES ('e2741e775a1ecf0688ef7c646389d2890357fc5e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Infa-Therm Transport Mattress, Reference Number 989805616831 1015', 'Falls', 'Instability / Fall Risk', 'Fall Injury', 'After the device was cleared by the FDA, Philips made changes to the labeling that do not fall within the existing FDA clearance. These devices with the modified labeling cannot be distributed or sold without new 510(k) clearance.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0505-2022');
INSERT INTO safety_incidents VALUES ('fc13fdf8b11e1b068269a7a7df652d20cc39865d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Tec 850 SEV Anesthesia Vaporizer, Reference Number 1177-9850-SEV', 'Due To A Manufacturing Issue, Certain Tec 6 Plus And Tec 800 Series Vaporizers Can Deliver Less Anesthetic Agent Than The Vaporizer Dial Setting.', 'Other', 'Not Specified', 'Due to a manufacturing issue, certain Tec 6 Plus and Tec 800 series vaporizers can deliver less anesthetic agent than the vaporizer dial setting.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0818-2025');
INSERT INTO safety_incidents VALUES ('7fba9f980a00af859c7002c8b7d1d371f8337084', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ImpellaCP SmartAssistSetAPAC, Delo1895; Product Code: 1000302;', 'A Potential Device Interaction Between The Shockwave Coronary Ivl Catheter And Left-Sided Impella Pumps During Coronary Interventions. Currently There Is No Abiomed Labeling (Ifu Etc.) Content Related To This Potential Interaction, So Abiomed Will Update The Ifu To Include Information On This Potential Device Interaction.', 'Other', 'Electric Shock', 'A potential device interaction between the Shockwave Coronary IVL Catheter and left-sided Impella Pumps during coronary interventions. Currently there is no Abiomed labeling (IFU etc.) content related to this potential interaction, so Abiomed will update the IFU to include information on this potential device interaction.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2967-2024');
INSERT INTO safety_incidents VALUES ('e3d303acb851b52125dbff9907e7a42a9d986231', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'K2M, ALEUTIAN Interbody Spacer Systems, EN AN Lordotic Spreader, Stainless Steel, Non-Sterile, Qty 1, Catalog # 5203-90109, UDI # 10888857108226, Size 24x6mm, 6  Product Usage: Used to simulate the height of the cage and expand the spine disc space to determine the optimal implant size base on patie', 'The Aleutian Anatomically Narrow Lordotic Spreader Was Manufactured As Two Pieces Welded Together Which Has Been Associated With The Spreader Tip Breaking Off During The Procedure.', 'Other', 'Not Specified', 'The Aleutian Anatomically Narrow Lordotic Spreader was manufactured as two pieces welded together which has been associated with the spreader tip breaking off during the procedure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2009-2020');
INSERT INTO safety_incidents VALUES ('b7cffcab682cc02e230d20063062820048fcf954', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Trilogy EVO Ventilator, France - Model Number: FR2110X14B    Trilogy Evo is intended for pediatric through adult patients weighing at least 2.5 kg. The ventilator can measure, display, record, and alarm SpO2, FiO2, CO2, and Pulse Rate data when integrated with the appropriate accessories.', 'Software Defect In The Trilogy Evo And Trilogy Evo Universal Ventilator, Versions Sw 1.00.05, Sw 1.01.09.00, Sw 1.01.10.00, And Sw 1.01.11.00, Causing Inoperative And Loss Of All Power Alarms. This Defect Causes An Incorrect Or Unexpected Result Failing Requirements Tsrs1298 And Prd439.', 'Mechanical Failure', 'Not Specified', 'Software defect in the Trilogy EVO and Trilogy EVO Universal Ventilator, versions SW 1.00.05, SW 1.01.09.00, SW 1.01.10.00, and SW 1.01.11.00, causing inoperative and loss of all power alarms. This defect causes an incorrect or unexpected result failing requirements TSRS1298 and PRD439.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0949-2020');
INSERT INTO safety_incidents VALUES ('e70768a0cd694d8c0bd9b6978bf57f43ec11484f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'COBALT DR MRI SureScan, Model Number DDPB3D1, Implantable Cardioverter Defibrillator', 'Potential For Manufacturing Defect. Weld Crack Led To Devices Failing At The Leak Check Step In Manufacturing.', 'Mechanical Failure', 'Not Specified', 'Potential for manufacturing defect. Weld crack led to devices failing at the leak check step in manufacturing.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2206-2024');
INSERT INTO safety_incidents VALUES ('c12de453d310eb657f3d5a05ab89f933d3eb5460', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BVI CustomEyes Procedure Packs containing Sol-M Luer Lock and Luer Slip 1ml syringes, Part Number: 58001624;', 'Due To A Voluntary Recall Of Low Dead Space Syringes, And Luer Slip Tip Syringes Manufactured By Sol-Millennium Medical (Sol-M), Inc. These Syringes  Manufactured By Sol-M Are Present In Some Of Bvi Customeyes Procedure Packs.', 'Other', 'Eye Injury', 'Due to a voluntary recall of low dead space syringes, and luer slip tip syringes manufactured by Sol-Millennium Medical (Sol-M), Inc. These syringes  manufactured by Sol-M are present in some of BVI CustomEyes Procedure Packs.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2892-2024');
INSERT INTO safety_incidents VALUES ('140c76b72aaa98a9fa9ad8dce2b09d6d708b05e1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Professional Urine Drug Control, Item code 88010 - Product Usage: The Alere Professional Cup Urine Drug Controls are compatible with all quantitative and qualitative drug detection procedures which are sufficiently sensitive to detect the control constituents.', 'Three Products Requiring Refrigerated Storage Conditions Were Incorrectly Stored Outside Of Approved Temperature Ranges. Using These Temperature Abused Products May Result In Misdiagnosis Of The Patient.', 'Other', 'Not Specified', 'Three products requiring refrigerated storage conditions were incorrectly stored outside of approved temperature ranges. Using these temperature abused products may result in misdiagnosis of the patient.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2050-2020');
INSERT INTO safety_incidents VALUES ('4a1b6702501c37dea3ae1b8c1c5187c8853a599e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Intera 1.5T Achieva Nova. Model (REF) Numbers 781172.', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'The Quadrature Body Coil (QBC) seal adhesive may fail, creating sharp edges that may come in contact with patients. If the QBC seal becomes loose during the scanning process, the risk to the patient may include skin abrasions, bruises, lacerations, hair loss/entanglement, and tissue injury.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0952-2024');
INSERT INTO safety_incidents VALUES ('76d2a91d6742f0a58e62e15961f014064e5ef015', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Dispensing Pins for Air Inlet Filter, Product Catalog No. 412005, DP2500  Dispensing Pin W/Valve.  A valve for aspiration or injection of medication or enteral feeding solution from inverted multi-dose vials.', 'Contamination', 'Chemical / Toxic Substance', 'Not Specified', 'This lot may have an elevated risk of leakage from the Air-Inlet Filter of the device. Leakage of the Air-Inlet Filter may increase the risk of decreasing the dose of medication delivered to the patient, cause delays in treatment due to the need to replace the device or may cause contamination of the fluid path that can lead to bloodstream infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0727-2022');
INSERT INTO safety_incidents VALUES ('e02c04fb76893619b1845e9017568a639f7720cd', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Baxter DISCPAC Syringe Tip Caps, Self-Righting, Luer Slip, Dark Blue: a) 25 pack REF H938693025, b) 100 pack REF H938673100', 'There Is A Potential Of The Packaging Not Maintaining A Sterile Barrier For The Tip Caps.', 'Other', 'Not Specified', 'There is a potential of the packaging not maintaining a sterile barrier for the tip caps.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1578-2022');
INSERT INTO safety_incidents VALUES ('cff24280b267356783cfbc572ecd1e448f082290', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Flexible DCI Intubation Fiberscope, Part: 11302BDD2, with Instruction Manual: Z18445US - Product Usage: are intended to be used for examination and visualization of a patient s upper airway and for aiding placement of an endotracheal tube.', 'Updated Sterilization Instructions Are Being Provided To Ensure 1) A Specific Sterilization Tray Is Not Used, And 2) Ethylene Oxide Sterilization Is Never Used On Certain Reusable Flexible Intubation Endoscopes With Total Lumen Lengths Greater Than 850Mm. Incompletely Sterilized Endoscopes Might Introduce Infectious Agents Into Patient Airways, Resulting In Infection.', 'Other', 'Not Specified', 'Updated sterilization instructions are being provided to ensure 1) a specific sterilization tray is not used, and 2) ethylene oxide sterilization is never used on certain reusable flexible intubation endoscopes with total lumen lengths greater than 850mm. Incompletely sterilized endoscopes might introduce infectious agents into patient airways, resulting in infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2895-2020');
INSERT INTO safety_incidents VALUES ('69f0c9c9f9b395c3fc8cc66a60360320656317b1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LVIS Intraluminal Support Device, REF/Outside Diameter(OD)xTotal Length(TL)xWorking Length(WL): 214022-CAS/4.0 mm x 22 mm x 18 mm, 214518-CAS/4.5 mm x 18 mm x 14 mm, 213517-CAS/3.5 mm x 17 mm x 13 mm', 'Injury', 'Chemical / Toxic Substance', 'Laceration / Cut', 'Stent-assisted coiling device may due to commingling during manufacturing have dimensional nonconformance and/or incorrect device configuration. If device is oversized may lead to increased vessel wall stress, neointimal hyperplasia, vessel injury/rupture; if undersized may lead to incomplete expansion/malposition, acute stent thrombosis, distal embolization, ischemic neurological events', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2200-2026');
INSERT INTO safety_incidents VALUES ('46651af20473d5722e6e0cbc8c0f5d00e7a1cc53', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'HAND PACK-Procedure Kit     Catalog Number: WEHD16B', 'Ethylene Oxide/Ethylene Chlorohydrin (Eo/Ech) Residuals For The Cast Padding Component Exceeded The Residual Limits For Permanent Exposure Devices As Indicated By Ansi/Aami/Iso 10993-7/(R)2012.', 'Other', 'Not Specified', 'Ethylene Oxide/Ethylene Chlorohydrin (EO/ECH) residuals for the cast padding component exceeded the residual limits for permanent exposure devices as indicated by ANSI/AAMI/ISO 10993-7/(R)2012.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2310-2024');
INSERT INTO safety_incidents VALUES ('89ac916346054616ed2a4ae3f9126d16712d5797', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CRT-D DTBA1Q1 VIVA QUAD XT IS4/DF1 US, Model Number DTBA1Q1;  Implantable Cardioverter Defibrillators', 'There Is A Rare Potential For Reduced- Or No-Energy Output During High Voltage (Hv) Therapy (Typically 0-12J) In Implantable Cardioverter Defibrillators (Icds) And Cardiac Resynchronization Therapy Defibrillators (Crt-Ds) Manufactured With A Specific (Glassed) Feedthrough, Including Currently Available Icds And Crt-Ds.', 'Electrical Fault', 'Not Specified', 'There is a rare potential for reduced- or no-energy output during high voltage (HV) therapy (typically 0-12J) in implantable cardioverter defibrillators (ICDs) and cardiac resynchronization therapy defibrillators (CRT-Ds) manufactured with a specific (glassed) feedthrough, including currently available ICDs and CRT-Ds.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1732-2023');
INSERT INTO safety_incidents VALUES ('a18b7f1d20328cce59c3bd5c99fdea69a7ffd5c5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD MaxGuard Drop Administration set with 3 Needleless Y-Sites Removable 3-port Manifold and removable 4-way stopcock, REF: MX4436', 'Administration Set, And Extension Set Product Labels List Expiration Year 2027 But The Labels Should List Expiration Year 2025. If Expired Product Is Used, The Integrity Of The Product May Be Compromised, And May Result In Potential Leaks And Risk Of Infection To The Patient And Healthcare Worker.', 'Other', 'Not Specified', 'Administration set, and extension set product labels list expiration year 2027 but the labels should list expiration year 2025. If expired product is used, the integrity of the product may be compromised, and may result in potential leaks and risk of infection to the patient and healthcare worker.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1756-2022');
INSERT INTO safety_incidents VALUES ('e2fe6a529e55397f7582662c1f8ccfdb89de835f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Sensor Nitinol Wire with Hydrophilic Tip .0383CM FLEX ANG/150CM    UPN:  M0066703101 box 5   UPN:  M0066703100 single unit', 'An Increase In The Rate Of Complaints For Difficulty Or Inability To Track Over The Guidewire, May Result In A  Procedural Delay Due To The Need To Exchange The Affected Device', 'Other', 'Not Specified', 'An increase in the rate of complaints for difficulty or inability to track over the guidewire, may result in a  procedural delay due to the need to exchange the affected device', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1732-2020');
INSERT INTO safety_incidents VALUES ('a0b5f36f2d94c5042b0a4d28a44b2271365ed802', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LSL Healthcare Wound Closure Tray, Model/Catalog Number: 7554', 'Medical Procedure Kits Were Distributed Containing Webcol Large Alcohol Prep Pads Which Were Subsequently Recalled For Non-Sterility.', 'Other', 'Laceration / Cut', 'Medical procedure kits were distributed containing Webcol Large Alcohol Prep Pads which were subsequently recalled for non-sterility.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1933-2026');
INSERT INTO safety_incidents VALUES ('41d6638496d09116f5f3e35d535638599464732d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'HCT 12 CC SYRINGE KIT, 20/TRAY,5 TRAYS/BAG, 5 BAGS /CASE HCT.  Distributed by Health Care Technology.', 'Potential For The Outer Bag Having Pinhole Leaks Near The Seal, Which May Result In A Breach In The Sterility Of The Kit.', 'Other', 'Not Specified', 'Potential for the outer bag having pinhole leaks near the seal, which may result in a breach in the sterility of the kit.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0938-2023');
INSERT INTO safety_incidents VALUES ('aff2a4e350a9b40f018e4dc665a6d2d5414238ea', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'HAMILTON C3 Ventilator REF  160005    Is intended to provide positive pressure ventilatory support to adults and pediatrics, and optionally infants and neonates', 'Due To A Software Anomaly After Approximately 91 Days Of Cumulative Use, The Ventilator May Stop And Enter The Ambient Mode Without Prior Notice.', 'Explosion', 'Not Specified', 'Due to a software anomaly after approximately 91 days of cumulative use, the ventilator may stop and enter the ambient mode without prior notice.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2142-2023');
INSERT INTO safety_incidents VALUES ('a00ff7d328e190b83ab136e27fb2ce982d05f680', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'MEVATRON M2/Primus Mid-Energy Model #01940035, MEVATRON PRIMART #05500371, MEVATRON KD-2 #08515520, MEVATRON KD2 #01940753, MEVATRON M-2 6740 #09401506, MEVATRON MD-2 #09401654, MEVATRON MDX-2 #09401746 with Digital LINAC Systems Control Console Software Versions 6, 7, 9, 13', 'Radiation', 'Radiation', 'Radiation Exposure', 'Potential safety issue with the dose monitoring system safety interlocks which could result in a 10-20% overdose of radiation therapy.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1678-2020');
INSERT INTO safety_incidents VALUES ('014f10c9f600eb3b5d74314dd1de0b57e90901c5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'JUNCTIONAL EMERGENCY TREATMENT TOOL (JETT), REF: 30-0088, a component inside kits:     KIT, TCCC Training- Complete (Modules 1-3), REF: 85-0550;  KIT, TCCC MODULE ONE - SKILLS, REF: 85-0519;  KIT, MULTI MISSION EXPEDITIONARY RESPONSE - MMERK, REF: 85-2420;  KIT, TCCC SKILLS/IFAK COMBO, REF: 85-0740,', 'Device Used For Unilateral Or Bilateral Occlusion Of Blood Flow To The Lower Limbs Has A Potential Manufacturing Defect That May Compromise The Structural Integrity Of The Device And Device Performance During Use.', 'Mechanical Failure', 'Not Specified', 'Device used for unilateral or bilateral occlusion of blood flow to the lower limbs has a potential manufacturing defect that may compromise the structural integrity of the device and device performance during use.', 'Fatal', 0, 0, 'Voluntary: Firm initiated', 'Z-2637-2025');
INSERT INTO safety_incidents VALUES ('fc2bc63f1cdfdd0013f1c859da63f6bf5fa1fcaf', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LINK SLED Knee System  POREX ENDO MODEL SLED TIBIAL COMP 11 MM X 55 MM	  Item Number: 15-2230/11', 'Low Risk', 'Chemical / Toxic Substance', 'Eye Injury', 'Additional Label Warnings: Amendment / reinforcement of the Surgical Technique and future product training on the updated technique, due to early aseptic loosening or increased wear of the implant caused by suboptimal positioning of the implant or inadequate cementing technique leading to an unsatisfactory surgical result, and in the worst case, intervention or revision earlier than expected', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1550-2023');
INSERT INTO safety_incidents VALUES ('822a06bee1d15fa1a68038c7cf4095d39bd23746', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Continuous CT Fluoroscopy DVI Ceiling Mount   CCT Arm DVI Option - Monitor     728332 - IQon Spectral CT    : IQon Spectral CT', 'Injury', 'Mechanical Failure', 'Fall Injury', 'Significant wear of the Monitor Bracket Assembly shaft  goes unrecognized could potentially lead to the Monitor Bracket Assembly detaching from the Suspension Arm and result in potential hazard for the monitor to fall while remaining attached to the  cables resulting in patient, operator, bystander, or service person  to serious injury.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1985-2021');
INSERT INTO safety_incidents VALUES ('b3cc0d48551560dd68ef0dba32f530ac04e8de7c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Nerveana x5 RLN Monitoring Kit with Cobra 1-Ch EMG ET Tube, 8.0 mm, REF NVTKIT-C8-5, Rx Only, Sterile  UDIB006NVTKITC852/$$7062118C - Product Usage: For continuous EMG monitoring and status assessment of the nerves supplying the laryngeal musculature as well as providing an open airway for patient v', 'The Electrode Insulating Material On The Cobra Emg Et Tube Used For Continuous Emg Monitoring May Soften Over Time So That It May Be More Susceptible To Damage By Scratching Or Bending, Which Could Stop Or Inhibit The Emg Signal Transmission Of The Electrodes To The Monitor And Render The Device Not Usable.', 'Other', 'Not Specified', 'The electrode insulating material on the Cobra EMG ET tube used for continuous EMG monitoring may soften over time so that it may be more susceptible to damage by scratching or bending, which could stop or inhibit the EMG signal transmission of the electrodes to the monitor and render the device not usable.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2902-2020');
INSERT INTO safety_incidents VALUES ('1a5d34cdfbeadc027ca3afb98468d35ce0fea5d8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'A.L.P.S. mvX--MEDIAL TIBIA PLATE 12H RT-Medial Tibia Plate, 12-Hole, Right  Intended for Fixation of fractures of the distal tibia  Model/Catalog Number: 770715122', 'Complaints Of The Locking Screw Passing Through The Locking Hole Intra-Operatively During Use Of The A.L.P.S. Mvx Medial Tibia Plates And Anatomic Lateral Fibula. R Surgical Delays Have Been Reported With The Use Of The Devices', 'Mechanical Failure', 'Fracture / Blunt Trauma', 'Complaints of the locking screw passing through the locking hole intra-operatively during use of the A.L.P.S. mvX Medial Tibia plates and Anatomic Lateral Fibula. r surgical delays have been reported with the use of the devices', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1224-2025');
INSERT INTO safety_incidents VALUES ('8671409fac2ac20f95c2cf3817242dab1e211dd2', 'FDA', '', 0, nan, 'USA', 'United States', 'Japan', 'Medical Devices', 'SD-230U-20 ELECTROSURGICAL SNARE, model no. SD-230U-20 - Product Usage: Used with endoscopes to electrosurgically resect tissue within the digestive tract.', 'Inspection Confirmed A Small Percentage Of Sterile Packages With Inadequate Package Seal (Partial Heat Seal). Patients May Develop Infections If Non-Sterile Equipment Is Used.', 'Other', 'Not Specified', 'Inspection confirmed a small percentage of sterile packages with inadequate package seal (partial heat seal). Patients may develop infections if non-sterile equipment is used.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0987-2021');
