INSERT INTO safety_incidents VALUES ('c29cd8909d79b49faf5cb03461c1b65b8fa59dfe', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline procedural kits labeled as:    1) ARTHROGRAM TRAY, Pack Number MNS11965A;   2) ARTHROGRAPH TRAY, Pack Number MNS12670A;   3) CIRCUMCISION TRAY, Pack Number CIT6860A;   4) CIRCUMCISION TRAY, Pack Number CIT6715;   5) CIRCUMCISION TRAY, Pack Number DYNDA2271;   6) CIRCUMCISION TRAY, Pack Numbe', 'Medical Convenience Kits Contain Plastic Syringes Affected By The Fda Safety Alert Issued On March 19, 2024. Leaks, Breakage, And/ Other Quality Issues Have Been Identified That May Pose A Risk To Patient Health.', 'Mechanical Failure', 'Not Specified', 'Medical convenience kits contain plastic syringes affected by the FDA Safety Alert issued on March 19, 2024. Leaks, breakage, and/ other quality issues have been identified that may pose a risk to patient health.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2752-2024');
INSERT INTO safety_incidents VALUES ('efeab862f98c249965f538e565623cfb5f496251', 'FDA', '', 0, nan, 'USA', 'United States', 'China', 'Medical Devices', 'Brand Name: Wolf Medical  Product Name: 12 mL (cc) Luer Lock STERILE LATEX FREE NON PYROGENIC  Model/Catalog Number: SYR12L  Product Description: NON-Sterile syringes without needles for single use  Component: No', 'Piston Syringes Sizes And Configurations Are Out Of The Range Of Devices Cleared Under The Firm''S 510(K).', 'Other', 'Not Specified', 'Piston syringes sizes and configurations are out of the range of devices cleared under the firm''s 510(k).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2104-2024');
INSERT INTO safety_incidents VALUES ('738da9b6a5496bf561363ed76d9e047048a652fe', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', '8mm HTR Sterile Hammer Toe Reaming Kit, Material: Stainless Steel,  Sterile: R, PX only, UDI: (01)00812926022345(17)231225  (10)TSL007202', 'The Firm Has Identified That Parts From The Kit, Lot: Tsl007202, Have The Potential To Contain The Incorrect Contents Of The 8Mm Htr Sterile Hammer Toe Reaming Kit. The Kit Should Contain (2) Reamers Total, (1) Concave Reamer And (1) Convex Reamer; There Is The Potential That Kits From The Identified Lot May Have (2) Of The Same Reamer Type As Opposed To One (1) Of Each Type.', 'Other', 'Not Specified', 'The firm has identified that parts from the kit, lot: TSL007202, have the potential to contain the incorrect contents of the 8mm HTR Sterile Hammer Toe Reaming Kit. The kit should contain (2) reamers total, (1) Concave Reamer and (1) Convex Reamer; there is the potential that kits from the identified lot may have (2) of the same reamer type as opposed to one (1) of each type.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1635-2020');
