INSERT INTO safety_incidents VALUES ('434c4ffb3f2f914793cbc9bbd0cc6062f85ee718', 'FDA', '2025-01-01', 2025, '2025-01', 'USA', 'United States', 'Germany', 'Medical Devices', 'Radiography 7300 C;  Model Number: 712037;', 'Philips Has Identified That Some Ceiling Suspension Telescopic Carriages Manufactured From July 2024  Through June 2025 May Be Difficult To Move Vertically (I.E. Additional Force/Physical Exertion Required  For Manual Movement) Due To Potential Manufacturing Issues.', 'Other', 'Not Specified', 'Philips has identified that some ceiling suspension telescopic carriages manufactured from July 2024  through June 2025 may be difficult to move vertically (i.e. additional force/physical exertion required  for manual movement) due to potential manufacturing issues.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0466-2026');
