INSERT INTO safety_incidents VALUES ('5d97c77f12ab87467c55cadcdd95bc561241014d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Turbett Surgical Container, TS1000: Indicated for enclosing other medical devices that are to be sterilized by a healthcare provider', 'Pod May Have Weld Failures Breaching The Sterile Barrier And Result In The Use Of Unsterile Instruments Leading To Infection Or Other Major Injuries.', 'Chemical / Toxic Substance', 'Not Specified', 'Pod may have weld failures breaching the sterile barrier and result in the use of unsterile instruments leading to infection or other major injuries.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1038-2023');
INSERT INTO safety_incidents VALUES ('5162e29568111b71b0090a08cc9f01b30668c409', 'FDA', '', 0, nan, 'USA', 'United States', 'China', 'Medical Devices', 'GE Healthcare CARESTATION 620 A2, Model/REF Number 1012-9620-002. Anesthesia system.', 'Certain Carestation 620/650/650C And 750/750C Anesthesia Delivery Systems Will Not Provide Effective Ventilation In Volume Control Ventilation (Vcv) Mode. In These Systems, Effective Ventilation Can Be Achieved In Pressure Control Ventilation (Pcv) Or Pressure Control Ventilation Volume Guarantee (Pcv-Vg) Modes Or With Manual Ventilation.', 'Explosion', 'Not Specified', 'Certain Carestation 620/650/650c and 750/750c Anesthesia Delivery Systems will not provide effective ventilation in Volume Control Ventilation (VCV) mode. In these systems, effective ventilation can be achieved in Pressure Control Ventilation (PCV) or Pressure Control Ventilation Volume Guarantee (PCV-VG) modes or with Manual ventilation.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1625-2025');
INSERT INTO safety_incidents VALUES ('b9512118e4b45c55a5f45ba313d543be55334c1e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LifeSPARC Pump (part number 5800-0000) contained within TandemLife LifeSPARC Priming Tray part number: 5800-1000.     Note: The 5800-1000 model number is an individually packaged component contained within the Kit numbers:   5830-2916  LS TANDEMLIFE KIT   DL29  5840-2417  LS TANDEMLIFE KIT - V24, A1', 'Epoxy Used During Manufacturing Of The Lifesparc  Pump May Have Uncured Epoxy. If Undetectable Curing May Result In Added Risk Of Early Pump Failure,', 'Other', 'Not Specified', 'Epoxy used during manufacturing of the LifeSPARC  Pump may have uncured epoxy. if undetectable curing may result in added risk of early pump failure,', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2465-2023');
INSERT INTO safety_incidents VALUES ('fcee4c1e283581411e9ad2a820ab2dac93889d25', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LINK SLED Knee System:  ALL POLY TIBIAL COMPONENT 11MM X 50MM	  	  Item Number: 15-2028/07', 'Low Risk', 'Chemical / Toxic Substance', 'Eye Injury', 'Additional Label Warnings: Amendment / reinforcement of the Surgical Technique and future product training on the updated technique, due to early aseptic loosening or increased wear of the implant caused by suboptimal positioning of the implant or inadequate cementing technique leading to an unsatisfactory surgical result, and in the worst case, intervention or revision earlier than expected', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1517-2023');
