INSERT INTO safety_incidents VALUES ('4ee049f92a5730e68826e99eaaec759bcd9f08ff', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medtronic CareLink SmartSync Patient Connector, Model Number 24967 with the following software components:    1.	Cobalt Crome application, Software Model Number D00U005;    2.	Claria Amplia Compia application, Software Model Number D00U009;    3.	Evera MRI application, Software Model Number D00U010;', 'In Prior Smartsync Application Versions, The Abort Button Stopped The Test That Was Selected. During An Induction Test, There Was A Limited Window Of Time For The User To Abort A Therapy, Thereby Limiting The User''S Ability To Cancel A High Voltage Therapy Delivery.', 'Electrical Fault', 'Not Specified', 'In prior SmartSync application versions, the Abort button stopped the test that was selected. During an induction test, there was a limited window of time for the user to abort a therapy, thereby limiting the user''s ability to cancel a high voltage therapy delivery.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2168-2025');
INSERT INTO safety_incidents VALUES ('1e2dfce4853d30891fcd138b8ed1dd5eac4256dd', 'FDA', '2024-01-02', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE medical convenience kits labeled as:    1) ACETABULAR PACK-LF, REF DYNJ0572894I;   2) LOCAL BASIC, REF DYNJ34418L;   3) LOCAL BASIC, REF DYNJ34418M;   4) MINI LOCAL, REF DYNJ900287D', 'Medline Is Recalling Medical Convenience Manufactured Using Certain Lots Of Safeair Smoke Evacuation Pencil Which Were Subsequently Recalled By Stryker.', 'Flammability / Overheating', 'Not Specified', 'Medline is recalling medical convenience manufactured using certain lots of SafeAir Smoke Evacuation Pencil which were subsequently recalled by Stryker.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0623-2025');
