INSERT INTO safety_incidents VALUES ('ccd95d121f235dbe2c02b20f90afba57df34c76c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'DR. THAMES - LAP CHOLE, REF: K0880, UDI:  (01)30607915139620', 'There May Be A Slightly Protruding Rivet On The Distal End Of The Laparoscopic Grasper Which Has The Potential For Tissue To Catch On It During Use And Lead To Tissue Damage.', 'Chemical / Toxic Substance', 'Not Specified', 'There may be a slightly protruding rivet on the distal end of the laparoscopic grasper which has the potential for tissue to catch on it during use and lead to tissue damage.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2160-2020');
INSERT INTO safety_incidents VALUES ('3d9c95f4f0fa866374971762ee3bb730843952b5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Heartware HVAD Pump Implant Kit, Product (REF) Number 1103', 'The Outflow Graft May Be Subject To Tears And The Strain Relief Screw May Break During The Pre-Implant Pump Assembly And Attachment To The Hvad Pump.', 'Other', 'Not Specified', 'The Outflow Graft may be subject to tears and the Strain Relief screw may break during the pre-implant pump assembly and attachment to the HVAD Pump.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2055-2020');
INSERT INTO safety_incidents VALUES ('d5d90e4bf174f3b4174aa7f59ec6dade3c050c3c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Artis zee/ zeego & Artis Q/ Q.zen  Artis Pheno', 'When The User Changes Frame Rates From Lower Frequency (E.G. 10 F/S) To Higher Frequency (E.G. 30 F/S) During Continuous Release Of Fluoro "Fluoro Override", The Measured Air Kerma Rate Can Exceed The Regulatory Limits.', 'Other', 'Not Specified', 'When the user changes frame rates from lower frequency (e.g. 10 f/s) to higher frequency (e.g. 30 f/s) during continuous release of Fluoro "Fluoro Override", the measured Air Kerma Rate can exceed the regulatory limits.', 'Serious', 0, 0, 'FDA Mandated', 'Z-0656-2021');
