INSERT INTO safety_incidents VALUES ('4ef9c2339ad32a9271b6f8d8636e04a9e3d21963', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LAP CHOLE PACK. Medical convenience kit.', 'Clearify Visualization System Was Inadvertently Resterilized In Kits, Causing Discoloration.', 'Other', 'Not Specified', 'CLEARIFY VISUALIZATION SYSTEM was inadvertently resterilized in kits, causing discoloration.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2253-2025');
INSERT INTO safety_incidents VALUES ('fb2fa75245e8adfe3a4eaff93524e9bade2af68f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD BBL Sensi Disc Azithromycin -15 ¿g, Catalog Number 231682¿used for semi-quantitative in vitro susceptibility testing.', 'There Is A Possibility Of Reproducibility, Accuracy, And/Or Qc Failures In Antibiotic Susceptibility Testing (Ast) For H. Influenzae. This May Cause Product Discard, Delayed Results, Or Additional Adverse Diagnostic Outcomes, Such As A Delay In Diagnosis, The Selection Of Inappropriate Antibiotics, Or Extended Duration Of Antibiotic Exposure And The Treatment Process.', 'Other', 'Not Specified', 'There is a possibility of reproducibility, accuracy, and/or QC failures in antibiotic susceptibility testing (AST) for H. influenzae. This may cause product discard, delayed results, or additional adverse diagnostic outcomes, such as a delay in diagnosis, the selection of inappropriate antibiotics, or extended duration of antibiotic exposure and the treatment process.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1015-2024');
INSERT INTO safety_incidents VALUES ('2129940f33bf68d0d4d79775f159ff21a8db534b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'SmartPath to dStream for 3.0T.   Product Code (REF): 782145.   MR systems with SW version R11.1 and R12.1.', 'The Potential For Stiffness Value Errors When Viewing Exported Mr Elastography (Mre) Stiffness Maps To Viewer Picture Archiving And Communication System (Pacs).', 'Other', 'Not Specified', 'The potential for stiffness value errors when viewing exported MR Elastography (MRE) stiffness maps to viewer Picture Archiving and Communication System (PACS).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1215-2026');
INSERT INTO safety_incidents VALUES ('a5bdaeafd70ba26edee687fefe228aa415512270', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'C8-4v Transducer Probe', 'To Provide Clarification And Labelling To Define The Useful Life Of Ultrasound Transducers In The Field.', 'Other', 'Not Specified', 'To provide clarification and labelling to define the useful life of ultrasound transducers in the field.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2358-2025');
INSERT INTO safety_incidents VALUES ('086bb934f654992c0ae9c09fb26322af92813fee', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'iDesign, Model - G300: System AWS (International), System AWS (China), Advanced WaveScan Studio (United States); iDesign Refractive Studio Aberrometer (International) and (United States), Model: G301', 'Aberrometer And Precision Laser Systems Are Affected By A Remote Code Execution Vulnerability Existing When The Microsoft Windows Print Spooler Service Is Enabled, And Improperly Performs Privileged File Operations. This Could Be Exploited To Run Arbitrary Code With System Privileges, Allowing For Program Installation; View/Change/Deleting Data; Or Creation Of New Accounts With Full User Rights.', 'Other', 'Radiation Exposure', 'Aberrometer and precision laser systems are affected by a remote code execution vulnerability existing when the Microsoft Windows Print Spooler service is enabled, and improperly performs privileged file operations. This could be exploited to run arbitrary code with SYSTEM privileges, allowing for program installation; view/change/deleting data; or creation of new accounts with full user rights.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0443-2022');
INSERT INTO safety_incidents VALUES ('9d9c981fcd6c877831662c6fa530b8a2450e7850', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Halyard CARDIAC CATH TRAY SHANDS JAX kit. Model Number: SHND401-04, SHND401-05.', 'Potential Risk For Medline Syringe Rotating Adaptor Unwinding During Use, Which May Result In A Loose Connection And/Or Full Disconnection Between The Syringe And Manifold.', 'Other', 'Not Specified', 'Potential risk for Medline syringe rotating adaptor unwinding during use, which may result in a loose connection and/or full disconnection between the syringe and manifold.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1972-2026');
INSERT INTO safety_incidents VALUES ('b0f74e0b2dc05190976af948152a39c1f3a1a9e3', 'FDA', '2020-01-02', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Geistlich Bio-Oss Pen 1-2mm 0.5g - Product Usage: natural bone mineral for filling of bone defects in maxillofacial surgery, implantology, and periodontology. Product Number: 20126', 'Difficult To Expel Geistlich Bio-Oss Granules From The Pen, Resistance Could Suddenly Drop, And The Granules May Be Expelled All At Once, Causing Surrounding Tissue, Particularly In Use For The Sinus Lift Indication And While Unlikely, Could Pose A Risk For Patient Harm, Including Irritation Of The Oral Mucosa Or Even A Perforation Of The Schneiderian Membrane', 'Mechanical Failure', 'Skin Irritation', 'Difficult to expel Geistlich Bio-Oss granules from the pen, resistance could suddenly drop, and the granules may be expelled all at once, causing surrounding tissue, particularly in use for the sinus lift indication and while unlikely, could pose a risk for patient harm, including irritation of the oral mucosa or even a perforation of the Schneiderian membrane', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0492-2021');
INSERT INTO safety_incidents VALUES ('90a79d6f200e64864d7eea9918f9f0b3d1418be7', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Zoll, REF 8700-0657-40 (IC-3893AE), ICY Intravascular Heat Intravascular Heat Exchange Catheter Kit, with central venous infusion capabilities (3 lumens), Heparin, Sterile EO, Rx Only, UDI:  (01)00849111075107', 'Labeling Update Concerning Potential Leaks From  The Catheter Or The Start-Up Kit (Suk) Tubing', 'Other', 'Not Specified', 'Labeling update concerning potential leaks from  the catheter or the start-up kit (SUK) tubing', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0057-2022');
INSERT INTO safety_incidents VALUES ('e7a15747d2d490adc9ff54dbc3c842b4e856eb6c', 'FDA', '2020-01-02', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Olympus Ultrasound Endoscope, Model number: GF-UC160P-OL5 - Product Usage: used for diagnostic ultrasound imaging or fluid flow analysis of the human body.', 'A New Inspection Step Was Added To The Cleaning And Disinfection Section Of The Instructions For Use (Ifu) For This Device In Order To Reduce The Risk Of Causing Patient Infections.', 'Other', 'Not Specified', 'A new inspection step was added to the cleaning and disinfection section of the Instructions For Use (IFU) for this device in order to reduce the risk of causing patient infections.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0505-2021');
INSERT INTO safety_incidents VALUES ('ceeed0f4c44a66242138f044a428d5333abda72e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD Phoenix PMIC/ID-108: IVD  is intended for the in vitro rapid identification (ID) of gram-positive bacteria from pure culture belonging to the genera Staphylococcus, Enterococcus, and other gram-positive cocci and gram-positive bacilli    Catalog Number: 448608', 'Bd Phoenix Sulfamethoxazole-Trimethoprim (Sxt) Resistance, False Resistant Sxt Result With S. Aureus Could Lead To A Potential Loss Of Access To A Preferred Antibiotic Regimen And Potential Reduction In Effectiveness Of Treatment Of The Infection', 'Microbiological Contamination', 'Not Specified', 'BD Phoenix Sulfamethoxazole-trimethoprim (SXT) Resistance, false resistant SXT result with S. aureus could lead to a potential loss of access to a preferred antibiotic regimen and potential reduction in effectiveness of treatment of the infection', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0762-2021');
INSERT INTO safety_incidents VALUES ('8d9479ed3cb4c7692aee7ae011b1f15fa18a8018', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Dover 100% Silicone Silver-Hydrogel Coated Foley Catheter with Temperature Sensor  16FR 5CCCC2W, Product Code: 50516ICT - Product Usage: for Drainage of the Urinary bladder and simultaneous monitoring of temperature. Prescription use only.', 'Temperature Sensing Catheters Failed To Meet The  Established Calibrated Temperature Sensing Tolerance Of +/- 0.2¿C. Failure To Correctly Measure Patient  Body Temperatures Could Lead To An Incorrect Diagnosis And Insufficient Treatment', 'Chemical / Toxic Substance', 'Not Specified', 'Temperature sensing catheters failed to meet the  established calibrated temperature sensing tolerance of +/- 0.2¿C. Failure to correctly measure patient  body temperatures could lead to an incorrect diagnosis and insufficient treatment', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1985-2020');
INSERT INTO safety_incidents VALUES ('9f755a63c418dc74f46f666b6e779ab7178c1997', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'TECNIS Toric 1-Piece IOL, Model Number: ZCT150 +23.5D SE 1.50D CYL - Product Usage: intended to be placed in the capsular bag.', 'Due To The Release Of Nonconforming Intraocular Lenses (Iols).', 'Other', 'Not Specified', 'Due to the release of nonconforming Intraocular Lenses (IOLs).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1163-2021');
INSERT INTO safety_incidents VALUES ('a9c94ade167cd8ea14d0cbd64011bccdb58f63fe', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'SEKISUI DIAGNOSTICS LLC SERUM HCG OSOMGENZME CONTROL SET.', 'Transit Delays Of Certain Cold Chain Products Due To Severe Thunderstorms Which May Caused The Products To Be Stored Outside The Recommended Labeled Storage Conditions. This Failure Could Increase The Probability Of An Incorrect Test Result Or A Delayed Test Result.', 'Other', 'Not Specified', 'transit delays of certain cold chain products due to severe thunderstorms which may caused the products to be stored outside the recommended labeled storage conditions. This failure could increase the probability of an incorrect test result or a delayed test result.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1854-2025');
INSERT INTO safety_incidents VALUES ('b4df72ced86b69fc61ee6014fc09a3712969808e', 'FDA', '', 0, nan, 'USA', 'United States', 'Netherlands', 'Medical Devices', 'Zenition 50, Model #718096', 'Firm Discovered That The Wireless Foot Switch Can Suddenly Stop Responding Due To A Firmware Issue. If The Wireless Foot Switch Fails, There Could Be A Delay Or Interruption Of Procedure If The Hand Switch Is Not Used Or If The Wired Foot Switch Is Not Connected To The System.', 'Other', 'Not Specified', 'Firm discovered that the wireless foot switch can suddenly stop responding due to a firmware issue. If the wireless foot switch fails, there could be a delay or interruption of procedure if the hand switch is not used or if the wired foot switch is not connected to the system.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0647-2022');
INSERT INTO safety_incidents VALUES ('fdb6f8b817df71155f1057c5be625bcb93285673', 'FDA', '', 0, nan, 'USA', 'United States', 'Italy', 'Medical Devices', 'Quanta System Sterile Optical Laser Fiber, reusable', 'Product Sterility Is Potentially Compromised.', 'Other', 'Radiation Exposure', 'Product sterility is potentially compromised.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1844-2021');
INSERT INTO safety_incidents VALUES ('55bf7b9d98a2fc1384b19c4c35aaa88b6f3465a3', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'OttLite Rechargeable UVC Disinfecting Wand', 'Radiation', 'Radiation', 'Radiation Exposure', 'Product allows for the emission of ultraviolet (UV) electronic product radiation in excess of exposure limits recommended by the International Commission on Non-ionizing Radiation Protection (ICNIRP).  The emissions are hazardous to users and others in the vicinity.', 'Serious', 0, 0, 'FDA Mandated', 'Z-1473-2023');
INSERT INTO safety_incidents VALUES ('7db3072a18914e0fab91e66e0d1ee391dc9f5aaa', 'FDA', '2022-01-02', 2022, '2022-01', 'USA', 'United States', 'Switzerland', 'Medical Devices', 'VADER Pedicle System Torque Wrench, Hudson Coupling, 12 Nm, REF 42-702', 'During Internal Testing (At Manufacturer Site) Of Two Torque Wrench Devices, It Was Detected That The Torque Limiting Function Was Out Of Specification. The Specified Torque Limiting Value Is 12 Nm. The Measuring Results For Both Instruments Were 4 Nm.', 'Other', 'Not Specified', 'During internal testing (at manufacturer site) of two torque wrench devices, it was detected that the torque limiting function was out of specification. The specified torque limiting value is 12 Nm. The measuring results for both instruments were 4 Nm.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0728-2023');
INSERT INTO safety_incidents VALUES ('1fee9b0b3f662b6875fc023c1afe26c4ae3c5c0e', 'FDA', '2020-01-01', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Covidien MONOJECT Standard Hypodermic Needle, Polypropylene Hub 22 G x 3/4". Intended use to facilitate activities such as: withdrawal of medication from a container, aspiration of fluid from a patient, injection of medication into a patient, and transfer fluids    Item Code: 8881250248', 'Falls', 'Sharp Edges / Points', 'Fall Injury', 'Potential for the needle to detach from the cartridge after the bottom of the cartridge is twisted and removed. If the needle is not securely seated, the needle can fall out of the sheath and cause the unused needle to project out of the cartridge, and  result in a needle stick/puncture from the clean/unused needle', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0424-2021');
INSERT INTO safety_incidents VALUES ('02db75ff38cd82e33603a4245d3c2583280d54c7', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Vital MIS Spinal Fixation system implants CANN BL POLY EXT 8.5X55MM, Item Number 811M8555 - Product Usage: are non-cervical spinal fixation devices intended for posterior pedicle screw fixation, posterior hook fixation, or anterolateral fixation. Pedicle screw fixation is indicated for skeletally ma', 'There Are Reports Of Inadequate Locking Of The Extended Tab Screws.  Complaints Were Reported Where The Closure Top Backed Out Of The Screw Post-Operatively.', 'Other', 'Not Specified', 'There are reports of inadequate locking of the extended tab screws.  Complaints were reported where the closure top backed out of the screw post-operatively.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2231-2020');
INSERT INTO safety_incidents VALUES ('54c171555c9f50ca2bd223135eae1cd7c9909ba2', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Olympus Single use Biopsy Valve. Model/Catalog Number: MAJ-210. 20 units per box.    The MAJ-210 has been designed to be attached to the instrument channel port of compatible endoscopes to prevent reflux of body fluids.', 'Potential For Rubber Fragment Detachment During Use.', 'Mechanical Failure', 'Not Specified', 'Potential for rubber fragment detachment during use.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1488-2026');
INSERT INTO safety_incidents VALUES ('c2e564a44446a431ff17d1bb2fcbdaa04daa3df3', 'FDA', '', 0, nan, 'USA', 'United States', 'China', 'Medical Devices', 'Brand Name: MEDLINE  Product Name: SYR 60ML L/S  Model/Catalog Number: 83079  Product Description: NON-Sterile syringes without needles for single use  Component: No', 'Piston Syringes Sizes And Configurations Are Out Of The Range Of Devices Cleared Under The Firm''S 510(K).', 'Other', 'Not Specified', 'Piston syringes sizes and configurations are out of the range of devices cleared under the firm''s 510(k).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2044-2024');
INSERT INTO safety_incidents VALUES ('2a0cd189489b053ff149fa216d8cf3030ef14aaf', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'REF: 381923    BD Insyte Autoguard Winged Shielded IV Catheter, 22 GA x 1.00 in (0.9 x 25 mm) 35 mL/min, STERILEEO, RxOnly', 'Due To Customer Complaints, There Is The Possibility That Catheter Needle May Be Slow To Retract Or Fail To Retract.', 'Other', 'Not Specified', 'Due to customer complaints, there is the possibility that catheter needle may be slow to retract or fail to retract.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2006-2025');
INSERT INTO safety_incidents VALUES ('f24ca52a816b116ed822dba08e048c241190ec6f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LVP software of the Ivenix Infusion System (IIS), LVP-SW-0004', 'Retroactively Reported Correction From 2022: A Software Defect May Cause An Incorrect (Fail-Stop) Alarm When An Administration Set Is Loaded With An Upstream Occlusion Present, Resulting In A Non-Recoverable (Fail-Stop) Pump Problem Alarm. This May Lead To Delay Of Therapy, And Patient May Experience From No To Minimal To Serious Harm.    This Issue Was Resolved In All Fielded Product In Software Version 5.2.1, Which Was Installed In September 2022.', 'Mechanical Failure', 'Not Specified', 'Retroactively reported correction from 2022: A software defect may cause an incorrect (Fail-Stop) Alarm when an administration set is loaded with an upstream occlusion present, resulting in a non-recoverable (Fail-Stop) Pump Problem alarm. This may lead to delay of therapy, and patient may experience from no to minimal to serious harm.    This issue was resolved in all fielded product in software version 5.2.1, which was installed in September 2022.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1282-2024');
INSERT INTO safety_incidents VALUES ('54c9b13f5c60a0349d51dafd1e1c2414aead437e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Baxter Operating  Table TruSystem 7000 (dV) V, Product code REF 1841083', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'The firm received customer reports stating that the batteries and their connectors experienced electrical short-circuits and/or emitted smoke.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0216-2025');
INSERT INTO safety_incidents VALUES ('cd2bcdfea3b5fa9f74efbec989fb1db83679aab8', 'FDA', '2024-01-01', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'SURG PAT XRAY 1/2X2  Model/Catalog Number: 801406.  The surgical patties and surgical strips are indicated for the use in protection of tissue, including brain and other tissues of the central nervous system, during surgery.', 'Identified Higher-Than-Expected Levels Of Endotoxin Within The Raw Material Used To Produce Codman Surgical Patties And Strips That May Have Resulted In Out-Of-Specification Levels Of Endotoxin In Finished Goods', 'Other', 'Not Specified', 'Identified higher-than-expected levels of endotoxin within the raw material used to produce Codman Surgical Patties and Strips that may have resulted in out-of-specification levels of endotoxin in finished goods', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0244-2025');
INSERT INTO safety_incidents VALUES ('a3c131e79feedb8e042f4c7014fb2e3aab87a78f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'GEM Premier 5000 PAK, Part No. 00055360004.', 'Confirmed Customer Complaints Indicating That Gem Paks (Cartridges) For The Gem Premier 5000 May Experience An Increased Incidence Of  Process Control Solution Not Detected  (Pcsnd) Errors During Warm-Up, Including Consecutive Occurrences, Resulting In Gem Pak Ejection And Requiring Insertion Of A New Gem Pak. Iqm2 Is An Active Quality Process Control Program Designed To Provide Continuous Monitoring Of The Entire Testing Process. Thus, If A Gem Pak Completes Autopak Validation Following Warm-Up, It May Remain In Use.    Consecutive Gem Pak Ejections During Warm-Up May Prolong Turnaround Times, Potentially Delaying Results. In Such Cases, Patient Management May Require Reassessment Once Results Are Available. While Many Gem Paks Continue To Perform As Intended, Consecutive Ejections May Increase The Likelihood Of Operational Disruption, Highlighting The Importance Of Advance Planning Where Feasible To Help Minimize Impact.', 'Other', 'Fracture / Blunt Trauma', 'Confirmed customer complaints indicating that GEM PAKs (cartridges) for the GEM Premier 5000 may experience an increased incidence of  Process Control Solution Not Detected  (PCSND) errors during warm-up, including consecutive occurrences, resulting in GEM PAK ejection and requiring insertion of a new GEM PAK. iQM2 is an active quality process control program designed to provide continuous monitoring of the entire testing process. Thus, if a GEM PAK completes AutoPAK Validation following warm-up', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1524-2026');
INSERT INTO safety_incidents VALUES ('05c4c0a113a3ebb1952030050ebe81cee5c4ebfe', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ev3 Pipeline Flex Embolization Device.  For neurological endovascular use.', 'Embolization Device Delivery System May Fracture At The Distal Section During Device Implantation. A Weakened Bond May Result In Unintended Separation, Where The Distal Portion Of The Device Delivery System Remains In The Patient. If A Pipeline Flex Embolization Device Has Already Been Implanted Successfully, There Is No Increased Risk To Patients Due To This Issue.', 'Mechanical Failure', 'Fracture / Blunt Trauma', 'Embolization device delivery system may fracture at the distal section during device implantation. A weakened bond may result in unintended separation, where the distal portion of the device delivery system remains in the patient. If a Pipeline Flex embolization device has already been implanted successfully, there is no increased risk to patients due to this issue.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1527-2020');
INSERT INTO safety_incidents VALUES ('6f8e9012c3732fde0a619bc11d75c95c09b0db09', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ACUSON AcuNav Volume Intracardiac Echocardiography Catheter 12.5F', 'Due To Adverse Events Received By The Firm For Left Atrial Perforations And Atrioventricular Node Block.', 'Other', 'Not Specified', 'Due to adverse events received by the firm for left atrial perforations and Atrioventricular Node block.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0090-2021');
INSERT INTO safety_incidents VALUES ('98f26b33ab906847eb37a8fe7e89f5aaed0c3e1e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Olympus EVIS EXERA III BRONCHOVIDEOSCOPE BF TYPE, Model Numbers BF-H190, BF-Q190, BF-XT190, BF-1TH190', 'There Have Been Complaints Of Endobronchial Combustion During Therapeutic Laser Procedures With The Bronchoscope.', 'Flammability / Overheating', 'Radiation Exposure', 'There have been complaints of endobronchial combustion during therapeutic laser procedures with the bronchoscope.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2017-2023');
INSERT INTO safety_incidents VALUES ('5dc04c81487e010b66e261dbabe9ba04c693fefc', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CARESCAPE Respiratory Module E-sCAiOV', 'Displayed End Tidal Oxygen (Eto2) And Fraction Of Inspired Oxygen (Fio2) Values May Be Incorrect Which Could Cause Up To 50% Measurement Error In The Eto2/Fio2 Values.', 'Other', 'Respiratory', 'Displayed End Tidal Oxygen (EtO2) and Fraction of Inspired Oxygen (FiO2) values may be incorrect which could cause up to 50% measurement error in the EtO2/FiO2 values.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0757-2020');
INSERT INTO safety_incidents VALUES ('07ba859d54a9c7cbc40573ac998c3014524de413', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'COOK MEDICAL Arterial Pressure Monitoring Tray, Reference Part Number APMY-2.5-15-0-2.5	, Order Number G58412; Reference Part Number APMY-4.0-21J-1-12, Order Number G58419', 'Products From The Affected Device Lots Were Labeled With Expiration Dates That Exceed The True Shelf Life.', 'Explosion', 'Not Specified', 'Products from the affected device lots were labeled with expiration dates that exceed the true shelf life.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1778-2026');
