INSERT INTO safety_incidents VALUES ('bd3713a6c7473165e80c401835141518113c2deb', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'SHARP MEDICAL PRODUCTS, LLC Reactor and Sleeve REF 100-36-01 Size: Adult', 'Non-Conformity (Holes/Punctures Or Deep Creases) In The Sterile Barrier.', 'Sharp Edges / Points', 'Not Specified', 'Non-conformity (holes/punctures or deep creases) in the sterile barrier.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1366-2021');
INSERT INTO safety_incidents VALUES ('a8c4143e373f834292a2806a821419430070bc10', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LinearTM 3-4 50 cm 8 Contact Lead Kit, part number M365SC2352500.   Leads function as a component of Boston Scientific''s Spinal Cord Stimulation (SCS) systems by delivering electrical stimulation to the nerve structures in the dorsal aspect of the spinal cord, resulting in an inhibition of pain sens', 'The Firm Is Initiating A Voluntary Removal Of Certain Spinal Cord Stimulation Leads, Lead Extensions, Adapters, And Deep Brain Stimulation Lead Extensions Due To The "Use By Date" Displayed On The Label Which Is Later Than The Correct "Use By Date".  No Adverse Health Consequence Is Expected To Occur From This Issue.', 'Electrical Fault', 'Laceration / Cut', 'The firm is initiating a voluntary removal of certain spinal cord stimulation leads, lead extensions, adapters, and deep brain stimulation lead extensions due to the "use by date" displayed on the label which is later than the correct "use by date".  No adverse health consequence is expected to occur from this issue.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2121-2020');
INSERT INTO safety_incidents VALUES ('5fcfa2dc869a1fd87d96e50e93e9770411da8312', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Baxter MiniCap Extended Life PD Transfer Set with Twist Clamp - Extra Short, 5C4483', 'Cleaning Products, Containing, But Not Limited To, Hydrogen Peroxide, Bleach, Alcohol, Or Antiseptic Agents And Solvent, Such As Those Containing Acetone, Toluene, Xylene, Or Cyclohexanone May Cause Damage, Such As Leaking Or Cracking, To The Minicap Extended Life Pd Transfer Sets.', 'Other', 'Not Specified', 'Cleaning products, containing, but not limited to, hydrogen peroxide, bleach, alcohol, or antiseptic agents and solvent, such as those containing acetone, toluene, xylene, or cyclohexanone may cause damage, such as leaking or cracking, to the MiniCap Extended Life PD transfer sets.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0572-2022');
INSERT INTO safety_incidents VALUES ('5655948087a10b31a98991d2e0f582a022ccce7f', 'FDA', '', 0, nan, 'USA', 'United States', 'China', 'Medical Devices', 'GE Healthcare LOGIQ F R3 Ultrasound System, Model/Catalog Number 5943263, diagnostic ultrasound system', 'Ge Healthcare Has Become Aware That The Estimated Fetal Weight (Efw) Measurement Data Feature On The Versana Premier R3 And Logiq F R3 Series Ultrasound Systems Can Display Previous Obstetric Patient Data In The  Whizz Report. This Could Potentially Lead To An Incorrect Clinical Decision Due To Inaccuracy In The Fetal Size And Growth Calculation.', 'Chemical / Toxic Substance', 'Not Specified', 'GE HealthCare has become aware that the Estimated Fetal Weight (EFW) measurement data feature on the Versana Premier R3 and LOGIQ F R3 series ultrasound systems can display previous obstetric patient data in the  Whizz report. This could potentially lead to an incorrect clinical decision due to inaccuracy in the fetal size and growth calculation.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2029-2025');
INSERT INTO safety_incidents VALUES ('0d5e1281e7405bc0a35f4d66eaba985039da19de', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Stryker Neurovascular, Trevo Trak 21 Microcatheter, REF 90338, 0.021in X162cm', 'The Microcatheter Ifu Contains An Intended Use That Has Not Been Evaluated By The Fda.', 'Other', 'Not Specified', 'The microcatheter IFU contains an intended use that has not been evaluated by the FDA.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1085-2024');
INSERT INTO safety_incidents VALUES ('b2134f66d80fa14635eaf6b095f1cc00ff12d519', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'PTFE Wire Guide, Guidewire, Global Product Number 638813  635413-10', 'The Wire Guide May Be Incorrectly Loaded Into The Wire Guide Holder, Leading To The Stiff Tip Of The Wire Guide Being Introduced Into The Patient Instead Of The Flexible Tip.', 'Chemical / Toxic Substance', 'Not Specified', 'The wire guide may be incorrectly loaded into the wire guide holder, leading to the stiff tip of the wire guide being introduced into the patient instead of the flexible tip.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0962-2020');
