INSERT INTO safety_incidents VALUES ('55478b2c874a56e6ec1ce22a0cc77c08c2a97ca1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ALPHAMAXX Mobile Operating Table, Model Number/Part Number: 113322B4', 'The Recall Is Prompted By A Defective Charger Unit (0970.2873) For Models 1133.22B4, 1133.22B5, And 1133.22F5 Of The Alphamaxx Mobile Operating Table. This Issue Poses A Risk Of Inadequate Charging And Operational Failure.', 'Mechanical Failure', 'Not Specified', 'The recall is prompted by a defective charger unit (0970.2873) for models 1133.22B4, 1133.22B5, and 1133.22F5 of the ALPHAMAXX mobile operating table. This issue poses a risk of inadequate charging and operational failure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2271-2024');
