INSERT INTO safety_incidents VALUES ('0362ad8769e81c1a7c19d9eb8ef5c9e8c1328b15', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Dual Flat Panel Monitor (DFPM) accessories for HarmonyAIR E-Series Surgical Lighting Systems', 'The Dfpm Yoke Assembly ("Yoke Assembly") May Detach From The Spring Arm. Should The Yoke Assembly Detach From The Spring Arm, The Yoke Assembly Would Not Be Expected To Fully Detach But Rather Hang From The Wiring Within The Yoke Assembly.', 'Electrical Fault', 'Not Specified', 'The DFPM yoke assembly ("yoke assembly") may detach from the spring arm. Should the yoke assembly detach from the spring arm, the yoke assembly would not be expected to fully detach but rather hang from the wiring within the yoke assembly.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2178-2025');
