INSERT INTO safety_incidents VALUES ('2ccd670782374b1875ad771a1cfece4ee606724b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'nanoDot A - item 1 of 3 for 03500-000, Model Number 03501-000; radiation monitoring dosimeter used with the microSTAR readers', 'Radiation', 'Radiation', 'Radiation Exposure', 'LANDAUER received reports indicating that some nanoDots may potentially be outside of the specified range of +/-5.5% accuracy. Investigation of nanoDots indicated the presence of a potential non-conformance in the Optical Stimulated Luminescence (OSL) material that is beamed after exposure and emits fluorescence proportional to radiation exposure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2554-2023');
