INSERT INTO safety_incidents VALUES ('4f429a32e83cf7ba74dcecad42aeb1327586732e', 'FDA', '', 0, nan, 'USA', 'United States', 'Sweden', 'Medical Devices', 'RayStation/RayPlan 8B Service Pack 2, Build Number 8.1.2.5, stand-alone software treatment planning system', 'There Is A Potential For Erroneous Propagation Of The Current Tabletop Positions When Applying Pitch Or Roll Correction. Even Though Pitch And Roll Correction Is Never Propagated, Non-Zero Pitch Or Roll Causes The Lateral, Longitudinal And Vertical Values Propagated To Be Incorrect.', 'Other', 'Not Specified', 'There is a potential for erroneous propagation of the current tabletop positions when applying pitch or roll correction. Even though pitch and roll correction is never propagated, non-zero pitch or roll causes the lateral, longitudinal and vertical values propagated to be incorrect.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1466-2020');
