INSERT INTO safety_incidents VALUES ('c37e5f549524375c5271d45cf785e849f1482aec', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CRTD DTMC1D1 COMPIA MRI US DF1, Model Number DTMC1D1;  Implantable Cardioverter Defibrillators', 'There Is A Rare Potential For Reduced- Or No-Energy Output During High Voltage (Hv) Therapy (Typically 0-12J) In Implantable Cardioverter Defibrillators (Icds) And Cardiac Resynchronization Therapy Defibrillators (Crt-Ds) Manufactured With A Specific (Glassed) Feedthrough, Including Currently Available Icds And Crt-Ds.', 'Electrical Fault', 'Not Specified', 'There is a rare potential for reduced- or no-energy output during high voltage (HV) therapy (typically 0-12J) in implantable cardioverter defibrillators (ICDs) and cardiac resynchronization therapy defibrillators (CRT-Ds) manufactured with a specific (glassed) feedthrough, including currently available ICDs and CRT-Ds.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1769-2023');
