INSERT INTO safety_incidents VALUES ('acb4c3fe9ca3af11d875fff94dbdd02bfd8ce478', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Sterile Disposable Connectors ASY RDC Y 1/2X3/8X3/8 STR 24 REF/ GTIN for Insert Label:050529000/ 00803622123351', 'The Firm Has Identified Through Internal Tests That The Sterile Barrier Of Certain Sterile Standalone Connectors May Present A Breach. The Issue Potentially Affects Component Assembled With A Specific Packaging And Is Associated To A Specific Production Period.', 'Other', 'Not Specified', 'The firm has identified through internal tests that the sterile barrier of certain Sterile Standalone Connectors may present a breach. The issue potentially affects component assembled with a specific packaging and is associated to a specific production period.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2456-2020');
INSERT INTO safety_incidents VALUES ('637dcdf440568bd3423c1dd7dd18f183cb74f4fd', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Hookup  Model/Catalog Number: 2-8-540CAS    Product Description: Hookups provide the interface between an Advantage Plus" Automated Endoscope Reprocessor and Advantage Plus" Pass-Thru Automated Endoscope Reprocessor ( AER ) and endoscopes, which allow perfusion of liquids dispensed by the AER to con', 'Contamination', 'Other', 'Not Specified', 'IFU for hookup were incorrectly reflected within hookup IFUs and online reference system, Hookup Lookup (HULU). Use of an incorrect hookup connection and/or parameter set may prevent an endoscope from being properly disinfected, which may present a risk of patient contamination or infection', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2538-2024');
