INSERT INTO safety_incidents VALUES ('006a86e65fbb378c551323cef7fcce162a001242', 'FDA', '', 0, nan, 'USA', 'United States', 'Ireland', 'Medical Devices', 'Multichem P, Part Code 08P90-10', 'Technopath Manufacturing Ltd. Has Identified An Issue With The Glass Vial Commodity Used To Fill The Multichem S Plus Level 1, Multichem S Plus Level 2, Multichem S Plus Level 3, Multichem Ia Plus And Multichem P Controls. Some Customers Have Experienced Broken Vials When Receiving Or Thawing Technopath Multichem Ia Plus And Multichem S Plus Controls. Breakages Have Been Observed Upon Delivery, While Thawing Or While Opening The Vial. The Breakages Can Result In The Bottom Of The Vial Breaking Off, Breakage In The Neck Thread Area Or Cracking On The Sides Of The Vial. This May Expose The User To Biohazardous Material If Cut And May Cause A Delay In Patient Results.', 'Mechanical Failure', 'Fracture / Blunt Trauma', 'Technopath Manufacturing Ltd. has identified an issue with the glass vial commodity used to fill the Multichem S Plus Level 1, Multichem S Plus Level 2, Multichem S Plus Level 3, Multichem IA Plus and Multichem P Controls. Some customers have experienced broken vials when receiving or thawing Technopath Multichem IA Plus and Multichem S Plus Controls. Breakages have been observed upon delivery, while thawing or while opening the vial. The breakages can result in the bottom of the vial breaking o', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0106-2024');
INSERT INTO safety_incidents VALUES ('bb623b319609c0c5c1d28b5e9ab1e2a5bc22043b', 'FDA', '', 0, nan, 'USA', 'United States', 'China', 'Medical Devices', 'GE Healthcare CARESTATION 650C A1, Model/REF Number 1012-9655-000. Anesthesia system.', 'Certain Carestation 620/650/650C And 750/750C Anesthesia Delivery Systems Will Not Provide Effective Ventilation In Volume Control Ventilation (Vcv) Mode. In These Systems, Effective Ventilation Can Be Achieved In Pressure Control Ventilation (Pcv) Or Pressure Control Ventilation Volume Guarantee (Pcv-Vg) Modes Or With Manual Ventilation.', 'Explosion', 'Not Specified', 'Certain Carestation 620/650/650c and 750/750c Anesthesia Delivery Systems will not provide effective ventilation in Volume Control Ventilation (VCV) mode. In these systems, effective ventilation can be achieved in Pressure Control Ventilation (PCV) or Pressure Control Ventilation Volume Guarantee (PCV-VG) modes or with Manual ventilation.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1632-2025');
INSERT INTO safety_incidents VALUES ('62264ebbd7a933c2d0165c09c23378fa597babb8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'NovaGuide 2 Traditional Ultrasound , REF: NSC-TCDNG2', 'Electric Shock', 'Mechanical Failure', 'Electric Shock', 'Due to inadvertently disconnecting grounding cable of ultrasound system could result in electrical shock, electrical interference and/or equipment malfunction.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2217-2024');
