INSERT INTO safety_incidents VALUES ('e8be4a38611e1c5815ec6730a222c851c8109917', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline Convenience kits labeled as:    1) KIT MANIFOLD CSTM-NORTHRIDGE, Pack Number 129736 ;   2) KIT LEFT HEART-VA MED, Pack Number 132701;   3) KIT MANIFOLD CSTM-RENAISSANC, Pack Number 134085 ;   4) KIT LEFT HEART- LEXINGTON , Pack Number 142643 ;   5) KIT ANGIO CSTM-SETON, Pack Number 143267;  ', 'Medical Convenience Kits Contain Plastic Syringes Affected By The Fda Safety Alert Issued On March 19, 2024. Leaks, Breakage, And/ Other Quality Issues Have Been Identified That May Pose A Risk To Patient Health.', 'Mechanical Failure', 'Not Specified', 'Medical convenience kits contain plastic syringes affected by the FDA Safety Alert issued on March 19, 2024. Leaks, breakage, and/ other quality issues have been identified that may pose a risk to patient health.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2990-2024');
