INSERT INTO safety_incidents VALUES ('d373d50d3e0502a59606e547903e3f8013322e6e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Isopure Sodium Bicarbonate Mixing and Distribution System (IsoMix PRO)', 'Electric Shock', 'Electrical Fault', 'Not Specified', 'Isopure received a report of a hazardous incident involving a device which had experienced an electrical short that resulted in a thermal event, damaging some of the device components. The firm is alerting customers to electrical safety measures that can be taken to prevent such events from occurring.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1360-2022');
