INSERT INTO safety_incidents VALUES ('5c58d5ac0e6716594c1049e43a08cbecfce3f12f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Colonoscope, Model Number CF-Q180AL.', 'Specific Repaired Colonovideoscopes Were Assembled Without An Adhesive Which Protects Them From Certain Physical Conditions Such As High Levels Of Vibration, Fluctuation In Temperature Or Severe Shock Loads.', 'Other', 'Electric Shock', 'Specific repaired colonovideoscopes were assembled without an adhesive which protects them from certain physical conditions such as high levels of vibration, fluctuation in temperature or severe shock loads.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1208-2024');
INSERT INTO safety_incidents VALUES ('bdd7817801efdf8c3d3d5cec228298e28fd74036', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Olympus Single Use Biopsy Valve. Model/Catalog Number: MAJ-1218. 20 units per box.    The MAJ-1218 has been designed to be attached to the instrument channel port of compatible endoscopes to prevent leakage of body fluids.', 'Potential For Rubber Fragment Detachment During Use.', 'Mechanical Failure', 'Not Specified', 'Potential for rubber fragment detachment during use.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1489-2026');
INSERT INTO safety_incidents VALUES ('304872c7ec384d7e31f1fae7c43b9412a61111a2', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Centurion Hemostat kits labeled as:   a) STERILE CURV KELLY HEMOSTAT, Product Code 65340;   b) STERILE CURV MOSQUITO HEMOSTAT (MHS103), Product Code 66145;   c) STERILE STRT KELLY HEMOSTAT (SK8039), Product Code 66170;   d) STERILE CURV KELLY HEMOSTAT (CK8040), Product Code 66175;   e) STERILE CURV ', 'Product May Have A Weak Seal Which May Result In A Breach Of Sterility Of The Contents If The Seal Fails. The Weak Seal May Not Be Detectable By All Users.', 'Other', 'Not Specified', 'Product may have a weak seal which may result in a breach of sterility of the contents if the seal fails. The weak seal may not be detectable by all users.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1438-2024');
INSERT INTO safety_incidents VALUES ('d8cfd2bb3f42713c6e4d10638943a0093fb0d653', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'remel BLOOD AGAR EMB AGAR BIPLATE, REF R02041, QTY 100, for invitro diagnostic use', 'Contamination', 'Microbiological Contamination', 'Not Specified', 'Product may contain surface and subsurface contamination of Listeria monocytogenes which is typically visible immediately upon removal from the packaging, appearing on the blood side of the biplate.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1201-2025');
INSERT INTO safety_incidents VALUES ('219b1d239a6b56e1ffe7c67bfe65cd137a06fa8d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Cardiosave Hybrid Intra-Aortic Balloon Pumps (IABP), Part Numbers 0998-00-0800-31, 0998-UC-0800-31, 0998-00-0800-32, 0998-00-0800-33, 0998-UC-0800-33, 0998-00-0800-34, 0998-00-0800-35, 0998-00-0800-45, 0998-00-0800-52, 0998-UC-0800-52, 0998-00-0800-53, 0998-UC-0800-53, 0998-00-0800-55, 0998-UC-0800-', 'Users Were Reporting Instances Of "Gas Loss In Iab Circuit" And "Gas Gain In Iab Circuit" Alarms While Providing Therapy. An Internal Investigation Of The Complaints Determined That There Is A Potential Trigger For These Alarms That Was Not Listed In The Ifu: Patient Movement (Coughing, General Movement, And Swallowing).  Blood In The Circuit, Kins And Abrasions Of The Tubing/Catheter And Certain Patient Conditions Could Also Trigger These Alarms.  The Hhe Also Identified Hardware Issues Related To These Alarms.', 'Other', 'Laceration / Cut', 'Users were reporting instances of "Gas Loss in IAB Circuit" and "Gas Gain in IAB Circuit" alarms while providing therapy. An internal investigation of the complaints determined that there is a potential trigger for these alarms that was not listed in the IFU: Patient Movement (coughing, general movement, and swallowing).  Blood in the circuit, kins and abrasions of the tubing/catheter and certain patient conditions could also trigger these alarms.  The HHE also identified hardware issues related', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2435-2023');
INSERT INTO safety_incidents VALUES ('addfed1d1a3f60f6c4de8dd9008f2409389c2f8b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'AW-M0001 SONARMED MONITOR. Used in conjunction with SonarMed Acoustic Sensors for airway monitoring.', 'Software Anomaly Resulted In Failure To Detect A Partial Obstruction In 2.5 Mm Sensors And Up To 3Mm Distal To The Sensor.', 'Other', 'Not Specified', 'Software anomaly resulted in failure to detect a partial obstruction in 2.5 mm sensors and up to 3mm distal to the sensor.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1535-2024');
