INSERT INTO safety_incidents VALUES ('aa8fda6463cac516c7ed087c04e18e2c4c3bda4d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CareLink SmartSync Device Manager (24970A).  used to interrogate cardiac implantable electronic devices (CIED).', 'There Is A Smartsync Software Issue That Results In An Overestimation In The Displayed Longevity Of These Devices During An Approximate 6-Month Window Of Time Before The Device Triggers Its Recommended Replacement Time (Rrt).', 'Other', 'Not Specified', 'There is a SmartSync software issue that results in an overestimation in the displayed longevity of these devices during an approximate 6-month window of time before the device triggers its Recommended Replacement Time (RRT).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1522-2021');
