INSERT INTO safety_incidents VALUES ('dec7245bdd44938415844e0eaa720fb6e6e0083a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'STEALTH SPRING CLIP 6mm latis (3/4 Force). REF/UDI::A1603/(01)00607915110581 - Product Usage: The device is indicated for surgical clamping during cardiovascular, peripheral vascular, and general surgery.', 'Failure Of Cardiovascular Clips To Provide Sufficient Occlusion Of The Vessel.', 'Other', 'Not Specified', 'Failure of cardiovascular clips to provide sufficient occlusion of the vessel.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2036-2020');
INSERT INTO safety_incidents VALUES ('2e0c9576ee1e97e9f2cecd3a2fa3ba6d93e34766', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ORTHOLOC 3DSi CLAW II 4 HOLE Plate, Size 25MM, REF 40241425, Bone fixation device', 'Stryker Has Identified An Issue That Impacts Two Specific Lots Of Claw" Ii Plates. The Plates Within These Two Lots Were Found To Have Been Comingled, Resulting In The Incorrect Product In Packages. Packaging For 402S0425 Incorrectly Contained 40241425, And Vice Versa.', 'Other', 'Fracture / Blunt Trauma', 'Stryker has identified an issue that impacts two specific lots of CLAW" II plates. The plates within these two lots were found to have been comingled, resulting in the incorrect product in packages. Packaging for 402S0425 incorrectly contained 40241425, and vice versa.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1170-2023');
INSERT INTO safety_incidents VALUES ('9880b8dd9c8e24782b3a189e7a98120d8b406cea', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'JUDKINS PACK', 'Component Part Number: 19537Lbl (Lbl, Sheet Of 39, Assorted, Stdsz, Multi W/Blk Ink, Waterproof) Is Being Reported As Intermittently Mixed With An Incorrect Medication Label Sheet Throughout The Specific Presource¿ Kit Sanhdjtvcf Judkins Pack Lot # 525067.', 'Drowning Risk', 'Not Specified', 'Component Part Number: 19537LBL (LBL, SHEET OF 39, ASSORTED, STDSZ, MULTI W/BLK INK, WATERPROOF) is being reported as intermittently mixed with an incorrect medication label sheet throughout the specific Presource¿ kit SANHDJTVCF Judkins Pack lot # 525067.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1256-2021');
INSERT INTO safety_incidents VALUES ('734199bb7216181fbe57f536246c370f7bc3d348', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'AGILE ESO OTW PC 23MM X 6.2CM IN 18.5 FR-  Agile Esophageal Partially Covered (PC) and Fully Covered (FC)  OTW Stent System is intended for maintaining esophageal luminal patency in esophageal strictures caused by intrinsic and/or extrinsic  malignant tumors, and occlusion of concurrent esophageal f', 'Wallflextm Esophageal Stent System And Agiletm Esophageal Over The Wire (Otw) Stent System Due To The Potential For Delivery Catheter Tip Detachment.', 'Mechanical Failure', 'Not Specified', 'WallFlexTM Esophageal Stent System and AgileTM Esophageal Over the Wire (OTW) Stent System due to the potential for delivery catheter tip detachment.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-3287-2024');
