INSERT INTO safety_incidents VALUES ('b3e802c5eb2dfd8322392f6f645f3c8f2be46c40', 'FDA', '2025-01-02', 2025, '2025-01', 'USA', 'United States', 'United States', 'Medical Devices', 'AMSCO 7052HP Washer/Disinfector  Model/Catalog Number: 7052HP     Product Description: The AMSCO 7052HP Washer/Disinfector is intended for use in the cleaning and intermediate-level disinfection of soiled reusable simple hard-surfaced rigid surgical instruments (such as forceps and clamps), utensils', 'Electric Shock', 'Electrical Fault', 'Electric Shock', 'Wire connected to the electrical box may shift out of its intended position, which may result in electrical arcing. Electrical arcing remains internal within the unit (no risk of shock to users).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0909-2026');
INSERT INTO safety_incidents VALUES ('150a1d8d40c5cc01ade79b1404e2e17a857ecb6d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Biodesign Inguinal Hernia Graft C-IHM-10X15 - To reinforce soft tissues in the inguinal floor to repair inguinal hernias.   Order Number (GPN): G46603', 'Products Expire Prior To The Expiration Date Printed On The Product Labeling', 'Other', 'Not Specified', 'Products expire prior to the expiration date printed on the product labeling', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-3261-2024');
INSERT INTO safety_incidents VALUES ('f441aad49ca13299386f07b44d65e40a3bddabc5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD Pyxis MedBank MedPass Software, REF: 139088-01', 'After Dispensing A Timed Dose Medication For A Patient, The Automated Dispensing Cabinet Software May Continue To Show The Already Dispensed Medication Dose Is Still Available For Dispense, Which Could Lead To Duplicate Medication Administration.', 'Chemical / Toxic Substance', 'Not Specified', 'After dispensing a timed dose medication for a patient, the automated dispensing cabinet software may continue to show the already dispensed medication dose is still available for dispense, which could lead to duplicate medication administration.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2646-2023');
INSERT INTO safety_incidents VALUES ('7a0ec0aac8e9ec966d6c744afe522d544f90db49', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'SIGNA Architect, with affected software versions:  DV26.0 to DV26.3, DV27.0 to DV27.3, DV28.0 to DV28.5, DV29.0, DV29.1, DV29.2, MR30.0, MR30.1; Nuclear Magnetic Resonance  Imaging System', 'Ge Healthcare Has Become Aware That For Certain Mr Systems, The System Predicted B1+Rms Value Can Exceed The B1+Rms User Prescribed Limit When Scanning In Low Sar Mode And The Following Two Conditions Are Met:  1. 2D Fse T2 Flair Or T2 Flair Propeller Imaging Sequence Is Selected,   And  2. The Optimized T2 Flair Sequence Option Is Turned Off Or Not Included In The Mr Configuration.  If This Occurs, It Can Result In Overheating Of An Mr Conditional Implant.', 'Flammability / Overheating', 'Not Specified', 'GE HealthCare has become aware that for certain MR systems, the system predicted B1+RMS value can exceed the B1+RMS user prescribed limit when scanning in Low SAR Mode and the following two conditions are met:  1. 2D FSE T2 FLAIR OR T2 FLAIR Propeller imaging sequence is selected,   AND  2. the Optimized T2 FLAIR sequence option is turned off OR not included in the MR configuration.  If this occurs, it can result in overheating of an MR conditional implant.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2459-2024');
INSERT INTO safety_incidents VALUES ('da26d72792fef873d0871bb55c7e6a6ec847e476', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CRTD DTMB1D4 AMPLIA MRI US DF4, Model Number DTMB1D4;  Implantable Cardioverter Defibrillators', 'There Is A Rare Potential For Reduced- Or No-Energy Output During High Voltage (Hv) Therapy (Typically 0-12J) In Implantable Cardioverter Defibrillators (Icds) And Cardiac Resynchronization Therapy Defibrillators (Crt-Ds) Manufactured With A Specific (Glassed) Feedthrough, Including Currently Available Icds And Crt-Ds.', 'Electrical Fault', 'Not Specified', 'There is a rare potential for reduced- or no-energy output during high voltage (HV) therapy (typically 0-12J) in implantable cardioverter defibrillators (ICDs) and cardiac resynchronization therapy defibrillators (CRT-Ds) manufactured with a specific (glassed) feedthrough, including currently available ICDs and CRT-Ds.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1762-2023');
INSERT INTO safety_incidents VALUES ('c19611fc2771936bb35f3a424d9545fcc96adac5', 'FDA', '2023-01-02', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Stay Safe Cap', 'Low Risk', 'Other', 'Not Specified', 'Updating the labeling to include additional warnings and contraindications for potential side effects.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0507-2024');
