INSERT INTO safety_incidents VALUES ('ecef8e52bb649cf28fee56e0ceb3fdf06fe7997a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Exactech Connexion GXL acetabular polyethylene liners used in the following systems: Catalog numbers 132-40-XX, Novation GXL Liner, Lipped Ant, 40mm; Novation GXL Liner, Lipped, 40mm.  Orthopedic hip implant component.', 'Risk Of Edge-Loading And Premature Prosthesis Wear Is Possible In A Specific Subset Of Patients With Certain Implant Configurations And Surgical Implant Positioning.', 'Other', 'Not Specified', 'Risk of edge-loading and premature prosthesis wear is possible in a specific subset of patients with certain implant configurations and surgical implant positioning.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2123-2021');
INSERT INTO safety_incidents VALUES ('7812f719ef5f6d780a8ea666e70f49a21fe1ce69', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Atellica IM 1300 Analyzer - automated, immunoassay analyzer designed to perform in vitro diagnostic tests on clinical specimens.  Siemens Material Number (SMN):	11066001', 'Lots Incompatible With Test Definition (Tdef) Version 1.4,  Potentially Lead To The Generation Of Erroneous Total T3 Results', 'Chemical / Toxic Substance', 'Not Specified', 'Lots incompatible with Test Definition (TDef) Version 1.4,  potentially lead to the generation of erroneous total T3 results', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1252-2022');
INSERT INTO safety_incidents VALUES ('f4f5c58f7fb98b06f32f90d5b75414dacb53ff70', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'The Vantage Total Ankle Tibial Insert, Fixed Bearing, Size 4, Right 10mm.', 'The Vantage Total Ankle Tibial Insert, Fixed Bearing, Size 4, Right 10Mm,  Were Found To Have A Labeling Error. Exactech Is Recalling The Vantage Total Ankle Tibial Insert, Fixed Bearing, Size 4, Right 10Mm Because They Were Found To Have A Labeling Error.  The Upper Right Corner Of The Label Incorrectly Identifies The Implant Size As 3 When The Implant Size Is 4.', 'Other', 'Not Specified', 'The Vantage Total Ankle Tibial Insert, Fixed Bearing, Size 4, Right 10mm,  were found to have a labeling error. Exactech is recalling the Vantage Total Ankle Tibial Insert, Fixed Bearing, Size 4, Right 10mm because they were found to have a labeling error.  The upper right corner of the label incorrectly identifies the implant size as 3 when the implant size is 4.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2926-2020');
INSERT INTO safety_incidents VALUES ('4e5829c913e7808f320f07dbc11ac7dcd3e33267', 'FDA', '2023-01-01', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Robotics Pack SAH, REF SAR530M', 'During An Internal Investigation, Acs Identified That The Components, I.V. Cath (Part Number 4252535-02) And   Adhesive Dermabond (Part Number Dhvm12) Were Inadvertently Subjected To The Acs Sterilization Process And Exposed To Eo And Higher Temperatures Than Approved By The Component Manufacturer. As A Result, The Components May (1) Have A Loss/Lack Of Functionality, (2) Loss Of Drug Efficacy, If Applicable, And (3) Have Higher Than Specified Eo Residuals.', 'Other', 'Not Specified', 'During an internal investigation, ACS identified that the components, I.V. Cath (part number 4252535-02) and   Adhesive Dermabond (part number DHVM12) were inadvertently subjected to the ACS sterilization process and exposed to EO and higher temperatures than approved by the component manufacturer. As a result, the components may (1) have a loss/lack of functionality, (2) loss of drug efficacy, if applicable, and (3) have higher than specified EO residuals.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0174-2024');
INSERT INTO safety_incidents VALUES ('204e9a73705cf4986fb10a73b35dbca62009c478', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Attune Revision Limb Preservation System (LPS) Tibial Insert XXSM 18MM, Part Number 151760118', 'Radiation', 'Radiation', 'Radiation Exposure', 'The subject product lots are being recalled because they received a higher than specified irradiation dose. This exceeds the validated range for exposure to gamma radiation of these devices and may result in changes to the implant material properties.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1263-2023');
INSERT INTO safety_incidents VALUES ('cd7b9e5b827ecd94aedaa147978a53bff1b02a95', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Artis Q ceiling, Model Number 10848281', 'If The Coolant Level In The Cooling Circuit Drops Below A Certain Level, This May Result In A Situation In Which The X-Ray Tube Is No Longer Sufficiently Cooled And The System Will Display The Message "Tube Hot, Have A Break". Several Minutes Later The System Will Block X-Ray To Prevent Further Damage And Display The Message "No Xray: Tube Too Hot".', 'Other', 'Not Specified', 'If the coolant level in the cooling circuit drops below a certain level, this may result in a situation in which the X-ray tube is no longer sufficiently cooled and the system will display the message "TUBE HOT, have a break". Several minutes later the system will block X-ray to prevent further damage and display the message "NO XRAY: TUBE TOO HOT".', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0975-2022');
INSERT INTO safety_incidents VALUES ('da021c9927a28a83173b01eb115e9bfe6ea23bbd', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Stryker ACM (Advanced Cement Mixing) System: ACM Kit w/ Femoral Breakaway Nozzle-Allows the user to mix bone cement witha constant high vacuum through the process Catalog Number: 0306-563-000', 'Falls', 'Chemical / Toxic Substance', 'Fall Injury', 'Potential for the Break-Away Femoral Nozzle  the applicator tip connecting the cement cartridge, to disassemble or break off during use, can lead to the potential for loss of function of the ACM system and bio-incompatibility due to components falling into surgical site', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2598-2023');
