INSERT INTO safety_incidents VALUES ('a06c0d06e5defa8f711eeabfffa0b1e4adb42fad', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LINK SLED Knee System  POREX ENDO SLED KNEE FEM COMP, MEDIUM SMALL	    Item Number:  15-2220/46', 'Low Risk', 'Chemical / Toxic Substance', 'Eye Injury', 'Additional Label Warnings: Amendment / reinforcement of the Surgical Technique and future product training on the updated technique, due to early aseptic loosening or increased wear of the implant caused by suboptimal positioning of the implant or inadequate cementing technique leading to an unsatisfactory surgical result, and in the worst case, intervention or revision earlier than expected', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1540-2023');
