INSERT INTO safety_incidents VALUES ('10658e46b57d9806d71af1980d7e5a6de44a5fa5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Gentuity HF-OCT Imaging System Model G10-01;  Software version 23.2.13;', 'The Potential For Repeated Frames During Hf-Oct Pullback When Using The Gentuity Hf-Oct Console (Software Version 21.11 To 23.3.13) With The Vis-Rx And Vis-Rx Prime Catheters. This Correction Is Intended To Ensure That Users Are Fully Informed Of How To Recognize, Avoid, And Mitigate This Condition To Maintain Accurate Longitudinal (Length) Measurements During Oct Imaging.', 'Other', 'Not Specified', 'The potential for repeated frames during HF-OCT pullback when using the Gentuity HF-OCT Console (software version 21.11 to 23.3.13) with the Vis-Rx and Vis-Rx Prime catheters. This correction is intended to ensure that users are fully informed of how to recognize, avoid, and mitigate this condition to maintain accurate longitudinal (length) measurements during OCT imaging.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1823-2026');
INSERT INTO safety_incidents VALUES ('cd6843f7aa7fbc31d9eefdae97c6368febd4e27c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD Alaris System PC Unit Model 8100 (Pump Module) and Pump Module Door Assembly Replacement Kits (P/N 49000239, 49000346, 49000438, 49000439) infusion pump.', 'Injury', 'Other', 'Not Specified', 'Pump Module keypad may exhibit keys that are unresponsive or stuck as a result of fluid ingress potentially resulting in a delay to the start of infusion or interruption of infusion. Delays in an infusion or interruption can cause serious injury or death in high-risk patient populations.', 'Fatal', 0, 0, 'Voluntary: Firm initiated', 'Z-2939-2020');
