INSERT INTO safety_incidents VALUES ('ddf06e1cd00e3cee16b94be70104a72b636ac3cf', 'FDA', '2024-01-01', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Abbott Alinity m HPV AMP Kit, used with the Alinity m System, product codes:  a) REF 09N15-095; b) REF 09N15-090; c) REF 09N15-091', 'Abbott Has Identified An Increase Of Incidences Regarding Error Code (Ec) 9198 (Positive Control Is Non-Reactive) While Using The Alinity M Hr Hpv Amp Kit And Alinity M Sti Amp Kit. Certain Invalidated Positive Assay Controls Can Be Traced To Iron Leaching Into The Alinity M Lysis Solution From The Lysis Transfer Pump In The Alinity M System.', 'Other', 'Not Specified', 'Abbott has identified an increase of incidences regarding Error Code (EC) 9198 (Positive control is non-reactive) while using the Alinity m HR HPV AMP Kit and Alinity m STI AMP Kit. Certain invalidated positive assay controls can be traced to iron leaching into the Alinity m Lysis Solution from the lysis transfer pump in the Alinity m System.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0233-2025');
