INSERT INTO safety_incidents VALUES ('10b859f4a9a65b0e4a4eaa646ff4e3671d4e4f34', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BVI CustomEyes Procedure Packs containing Sol-M Luer Lock and Luer Slip 1ml syringes, Part Number: 58000192;', 'Due To A Voluntary Recall Of Low Dead Space Syringes, And Luer Slip Tip Syringes Manufactured By Sol-Millennium Medical (Sol-M), Inc. These Syringes  Manufactured By Sol-M Are Present In Some Of Bvi Customeyes Procedure Packs.', 'Other', 'Eye Injury', 'Due to a voluntary recall of low dead space syringes, and luer slip tip syringes manufactured by Sol-Millennium Medical (Sol-M), Inc. These syringes  manufactured by Sol-M are present in some of BVI CustomEyes Procedure Packs.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2800-2024');
