INSERT INTO safety_incidents VALUES ('1328dd87d219fb4733541328dbb11faebf1147c8', 'FDA', '', 0, nan, 'USA', 'United States', 'Ireland', 'Medical Devices', 'Evidence MultiSTAT with software v 3.7-Analyzer intended for the qualitative determination  of parent drug molecule and metabolites of drugs in human urine  Catalog Number: EV4115', 'Foam Gasket On The Evidence Multistat Chip Heater Assembly May Not Perform As Expected. Foam That Is Not Functioning As Expected May Cause Light To Leak Into The Charged Coupled Device (Ccd) Camera During Imaging. This Will Affect The Testing And May Delay In Reporting Results.', 'Other', 'Not Specified', 'Foam gasket on the Evidence MultiSTAT chip heater assembly may not perform as expected. Foam that is not functioning as expected may cause light to leak into the Charged Coupled Device (CCD) Camera during imaging. This will affect the testing and may delay in reporting results.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1786-2024');
