INSERT INTO safety_incidents VALUES ('dda58f730c9f476fb67563cdcb43abca332dcd51', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Maquet/Getinge Rotaflow System Console US (115 V / 60 Hz) - Product Usage: Instructions for Use - Centrifugal Pump System is a device that uses a method other than revolving rollers to pump the blood through an extracorporeal circuit Material Number: 701043292', 'Instruction For Use (Ifu) References Incorrect Serial Number Of 90437000. It Should State  This Document Applies To Rotaflow Consoles As Of Serial Number 94175452 Affected By The Implementation Of The New Iec Standard 60601 1 2, 4Th Edition', 'Other', 'Not Specified', 'Instruction For Use (IFU) references incorrect serial number of 90437000. It should state  This document applies to ROTAFLOW Consoles as of serial number 94175452 affected by the implementation of the new IEC standard 60601 1 2, 4th edition', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2957-2020');
