INSERT INTO safety_incidents VALUES ('359f8bc5c33a8a42e43d68eac6fe36d150cec07c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Tearaway Introducer Kit, REF: KIT-010-12, KIT-010-17, KIT-900-16', 'Sheath Introducer Assemblies Could Potentially, Due To Improper Storage Conditions, Have A Luer Connection Portion Of The Dilator Hub That Cracks Or Dislodges During Use, Which Renders The Dilator Component Unusable, And Can Require The Use Of A Replacement Device.', 'Other', 'Not Specified', 'Sheath introducer assemblies could potentially, due to improper storage conditions, have a luer connection portion of the dilator hub that cracks or dislodges during use, which renders the dilator component unusable, and can require the use of a replacement device.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1968-2023');
INSERT INTO safety_incidents VALUES ('a43058bd414d9c85e25637fbae10d7814fbf9d6d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Gastroscope Family # 1-Gastroscopes without a Water Jet Channel Models: EG-2790i, EG-1690K, EG-2490K, EG-2790K, EG27-i10; Gastroscope Family # 2- Gastroscopes with a Water Jet Channel Models: EG-2990i, EG-2990K, EG-3490K, EG29-i10; Gastroscope Family # 3-Gastroscopes with Two Instrument Channels and', 'Updated Reprocessing Instruction For Use (Rifu): Impacted Pentax Medical Video Upper Gi Scopes (Eg) And Video Colonoscopes (Ec) Families', 'Drowning Risk', 'Fracture / Blunt Trauma', 'Updated Reprocessing Instruction For Use (rIFU): Impacted PENTAX Medical Video Upper GI Scopes (EG) and Video Colonoscopes (EC) families', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2449-2021');
