INSERT INTO safety_incidents VALUES ('c914994a7e379db33bf07808467032b78ef40554', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Drill Tapered RP 4.3x11.5 mm Single-Pat - Product Usage: The Guided Drills (Twist (Step) Drills, Guided Tapered Drills) are used for preparing osteotomies for the specific related implants.', 'Due To A Problem In The Packaging Sealing Process At The Supplier Of The Affected Devices, It Cannot Be Guaranteed That The Sterilized Medical Devices In The Scope Of This Recall Remain Sterile During Their Shelf-Life.', 'Other', 'Not Specified', 'Due to a problem in the packaging sealing process at the supplier of the affected devices, it cannot be guaranteed that the sterilized medical devices in the scope of this recall remain sterile during their shelf-life.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1309-2020');
