INSERT INTO safety_incidents VALUES ('b18b3a78d94dc8a15cd914f18b1ae11767aaa044', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Hand Pack, AKHD97C; Medical convenience kit', 'Acs Identified That Due To An Inoperable Chart Recorder, Humidity Readings Were Out-Of-Specification In One Of The Controlled Environment Areas. As A Result, Acs Is Unable To Confirm Product Sterilization Assurance Requirements Were Met.', 'Other', 'Not Specified', 'ACS identified that due to an inoperable chart recorder, humidity readings were out-of-specification in one of the controlled environment areas. As a result, ACS is unable to confirm product sterilization assurance requirements were met.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-3237-2024');
INSERT INTO safety_incidents VALUES ('1bcd02cda33de57ee2e71558eeb41dead046ef17', 'FDA', '2024-01-01', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Brand Name: Olympus  Product Name: Cystoscope Outer Sheath  Model/Catalog Number: WA22810A  Software Version: N/A  Product Description: Outer sheaths can be combined with rigid Telescopes.  Component: N/A', 'Olympus Is Removing The Statement Of Compatibility With A Greenlight Laser For Bph Therapy From The Instruction For Use (Ifu) Due To The Potential For A Damaged Tip During Use Of A Laser Probe.', 'Other', 'Radiation Exposure', 'Olympus is removing the statement of compatibility with a GreenLight Laser for BPH therapy from the Instruction for Use (IFU) due to the potential for a damaged tip during use of a laser probe.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0351-2025');
INSERT INTO safety_incidents VALUES ('be78d7424d79c5eda584772d4219324eeca6a282', 'FDA', '', 0, nan, 'USA', 'United States', 'Sweden', 'Medical Devices', 'Brand Name: RayStation  Product Name: RayStation/RayPlan  Model/Catalog Number: 15.2.0, 15.1.3  Software Version: RayStation 2024A SP1, RayStation 2024A SP2  Product Description: Radiation Therapy Treatment Planning System  Component: No', 'Radiation', 'Radiation', 'Radiation Exposure', 'Potential for the invalidation for calculated radiation dose does not work as intended for certain Regions of Interest (ROIs). This issue occurs for some ROI(s) which have no contours and either have a material override defined, or are of type Bolus, Fixation, or Support. In these cases, adding geometry to the ROI, subsequently modifying geometry, or removing the material override does not invalidate dose as intended.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1108-2026');
INSERT INTO safety_incidents VALUES ('88b1f0e2c636d34b65b8a361463738fb0d3728e1', 'FDA', '', 0, nan, 'USA', 'United States', 'France', 'Medical Devices', 'HIGH V+ Spinal Cement System REF T040321K', 'Incorrect Expiry Date.  Product Is Labeled With Expiry Date 2027-02-28.  The Correct Expiration Date Is 2025-02-28.', 'Other', 'Not Specified', 'Incorrect expiry date.  Product is labeled with expiry date 2027-02-28.  The correct expiration date is 2025-02-28.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1099-2023');
INSERT INTO safety_incidents VALUES ('bdeafb452aad5a315ec5ed4b68acfe6a63fe16cf', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'GE Healthcare MR superconducting magnets, a component of GE 0.7T SIGNA OpenSpeed with Excite MR System, nuclear magnetic resonance imaging system.', 'The Magnetic Resonance Systems Could Potentially Have A Cryogen Ventilation System That Does Not Meet The Venting Requirements.', 'Other', 'Not Specified', 'The magnetic resonance systems could potentially have a cryogen ventilation system that does not meet the venting requirements.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0608-2022');
INSERT INTO safety_incidents VALUES ('6e706244a8033440a256f73153d361e0803ee869', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Titanium MPJ (Toe Implant) TOE JOINT TITANIUM NPC MD, Part ID 16814', 'There Is An Incorrect Statement Regarding Mr Compatibility In The Biopro Titanium Mpj Implant Ifu (Ifu Bp102303 Rev 05) And Patient Implant Cards (22266 Rev 00) Which Indicates That The Biopro Mpj Implant Has Been Tested For Safety And Compatibility In The Mr Environment And Is Mr Conditional. Mr Testing Has Not Been Conducted On The Titanium Version Of The Mpj.', 'Other', 'Not Specified', 'There is an incorrect statement regarding MR Compatibility in the BioPro Titanium MPJ implant IFU (IFU BP102303 rev 05) and patient implant cards (22266 rev 00) which indicates that the BioPro MPJ Implant has been tested for safety and compatibility in the MR Environment and is MR Conditional. MR Testing has not been conducted on the titanium version of the MPJ.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0683-2022');
INSERT INTO safety_incidents VALUES ('e8cb7b14d9f8bc10053a8559f49cd74dae5626ae', 'FDA', '', 0, nan, 'USA', 'United States', 'Korea (the Republic of)', 'Medical Devices', 'ProudP Everyday Uroflow Tracker  Software Version 1.x.x    Software Version 1.2.0 or earlier', 'Due To Interference With The Live Listen Feature Of Hearing Aid Or Airpods, The User''S Iphone May Perform Automatic Processing Of The Urination Sound Signal, Resulting In Lower Urination Volume And Velocity Values Than Expected.', 'Other', 'Not Specified', 'Due to interference with the Live Listen feature of hearing aid or AirPods, the user''s iPhone may perform automatic processing of the urination sound signal, resulting in lower urination volume and velocity values than expected.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1292-2022');
INSERT INTO safety_incidents VALUES ('6723fbb865365b9d3b7d1f07f8dbde9fafab99d1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Synapse PACS - Version 7.2.100', 'Measurements On A Secondary Capture 2D Image, That Does Not Have Pixel Spacing In The Dicom Header, When Combined With A Breast Tomo Series Results In Incorrect Measurements.', 'Other', 'Not Specified', 'Measurements on a Secondary Capture 2D image, that does not have pixel spacing in the DICOM header, when combined with a Breast Tomo Series results in incorrect measurements.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1271-2024');
INSERT INTO safety_incidents VALUES ('fb3a4689225a1ecfadf6007f7a92e130fa1ea16c', 'FDA', '2023-01-01', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Cardiohelp-i, blood oxygenation and carbon dioxide removal system, Part Numbers 701072780 (Cardiohelp-i), 701068550 (Slide Rail Holder)', 'It Was Found That The Fixation (Weld) Employed By The Supplier Of The Nut Bolt To The Slide Rail Plate Was Insufficient. The Deficient Weld Allows The Nut Bolt To Break Off From The Slide Rail Plate With Slight Manual Force.', 'Other', 'Not Specified', 'It was found that the fixation (weld) employed by the supplier of the nut bolt to the slide rail plate was insufficient. The deficient weld allows the nut bolt to break off from the slide rail plate with slight manual force.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0290-2024');
INSERT INTO safety_incidents VALUES ('f4fecf239db4d721ba52150ebb33e409d7d9be07', 'FDA', '2022-01-02', 2022, '2022-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Philips SmartPath to Ingenia Elition X MR System, Model Numbers 782118, 782132, 782144', 'Fire', 'Flammability / Overheating', 'Not Specified', 'Gradient Coil may act as a heat source with a potential to produce smoke and/or fire.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0461-2023');
INSERT INTO safety_incidents VALUES ('7f96bf0938a7a70103389cc28bbfd84d15b73f54', 'FDA', '', 0, nan, 'USA', 'United States', 'Ireland', 'Medical Devices', 'Soluble Transferrin Receptors (STFR), Catalog Number TF10159 (Research Use Only). IVD', 'A Customer Reported A Problem With The Reagent And Calibrator. Randox Laboratories Carried Out An Investigation And Confirmed The Issue. The Complaint Is Pertaining To Atypical Calibration Curves That Can Results In Non-Numerical Results. This Affects Siemens Atellica Ch Analysers Only. Customer Have Reported An Atypical Calibration Curve That Results In The Values Around The Low Qc Range To Produce A Non-Numerical Result. It Appears To Be Related To The Bottle Values Of The Calibrator Producing A Curve Shape That Is Too Linear For The Logitlog Calculation To Calculate. This Issue Can Only Be Identified In The Atellica Graphical View Of The Calibration. In Most Of The Cases When This Has Occurred, It Is Picked Up By The Qc Generating A Math Error, However, There Are Reports Of Qc Shifts After Calibration Without The INSERT INTO safety_incidents VALUES ('0bf5e178e080c02c0fe59cc7814a3174df110a62', 'FDA', '2022-01-01', 2022, '2022-01', 'USA', 'United States', 'United States', 'Medical Devices', 'EMBLEM S-ICD, Subcutaneous Implantable Defibrillators, Model A209, sterile.', 'There Is An Incorrect Manufacturing Date/Timestamp Within The Software Which Causes An Inaccurate Display Of Battery Capacity.', 'Other', 'Laceration / Cut', 'There is an incorrect manufacturing date/timestamp within the software which causes an inaccurate display of battery capacity.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0151-2023');
INSERT INTO safety_incidents VALUES ('fed8fd2986cd346bec7a723d2bf05b1d2cb6db32', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Intera 1.5T, Magnetic Resonance System.', 'Patient Support Table Floor Plate May Be Incorrectly Installed.', 'Other', 'Not Specified', 'Patient support table floor plate may be incorrectly installed.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1575-2024');
INSERT INTO safety_incidents VALUES ('05d26890d500a6e2cc2110b0ba915317d3c6b068', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Philips SmartPath to Ingenia Elition X with MR Elastography (MRE).     1. Model Number (REF): 782118.     2. Model Number (REF): 782144.      3. Model Number (REF): 782163.', 'The Potential For Stiffness Value Errors When A Specific Range Of Image Reconstruction Parameters Is Used In Combination With Resoundant''S Algorithm, Leading To The Reconstruction Voxel Size Settings In The Default Mre Scan Protocol Displaying Too Small.', 'Chemical / Toxic Substance', 'Not Specified', 'The potential for stiffness value errors when a specific range of image reconstruction parameters is used in combination with Resoundant''s algorithm, leading to the reconstruction voxel size settings in the default MRE scan protocol displaying too small.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1968-2026');
INSERT INTO safety_incidents VALUES ('cd245274b64e939349eec7892311cf721dbff2b3', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'DeRoyal Sterile Custom Kits packaged as a Piggy Back with the BD PosiFlush SF Saline Flush Syringe, labeled as follows:  a. H* Vein Pack Pgybk, 89-6209.03      b. H* Vein Pack, 89-6209.04     c. PICC Line Tray Pgybk, 89-6150.12     d. Umbilical Arterial Cath, 89-9370.01      e. Port Pack Pgybk, 89-8', 'Deroyal Manufactured Procedure Packs Using Bdposiflush  Syringes Which Were Subsequently Recalled Due Holes In The Packaging.', 'Other', 'Not Specified', 'DeRoyal manufactured procedure packs using BDPosiFlush  syringes which were subsequently recalled due holes in the packaging.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1963-2020');
INSERT INTO safety_incidents VALUES ('fc0ffaa137884d221d7831b2a80d3898e2a4df6b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'QIAstat-Dx Respiratory SARS-CoV-2 Panel (US IVD under FDA EUA 200075); REF 691223', 'The Firm Identified Sixteen (16) Faulty Cartridges In Lot 210209, Which Contain Incorrect Primer-Probe Mixes In The Reaction Chambers. If An Affected Cartridge Is Used, False-Negative, False-Positive, Or Both False-Negative And False-Positive Results Could Occur.', 'Other', 'Respiratory', 'The firm identified sixteen (16) faulty cartridges in LOT 210209, which contain incorrect primer-probe mixes in the reaction chambers. If an affected cartridge is used, false-negative, false-positive, or both false-negative and false-positive results could occur.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0455-2022');
