INSERT INTO safety_incidents VALUES ('b76c5a591db77dfefc89f4b0ce3fc226a6afcca4', 'FDA', '', 0, nan, 'USA', 'United States', 'Spain', 'Medical Devices', 'Model Number 40KWFXPLUS.004, Mobile X-ray system', 'Sedecal Sent An Email To Its Consignees To Remind The Users That The Equipment Is Not Water-Resistant And Must Be Cleaned Strictly According To The Instructions In The Manual, Clearly Outlining The Possible Consequences Of Improper Cleaning.', 'Drowning Risk', 'Not Specified', 'Sedecal sent an email to its consignees to remind the users that the equipment is not water-resistant and must be cleaned strictly according to the instructions in the manual, clearly outlining the possible consequences of improper cleaning.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0248-2026');
