INSERT INTO safety_incidents VALUES ('6adb96add65d8d7769f7179cd467baf886060d4e', 'FDA', '2020-01-02', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'APEX Compounding System Control Panel Module, REF: 601237, Product Code AX1000 - Product Usage: intended for intravascular administration to a patient.', 'There Is The Potential For The Compounding System To Not Immediately Interrupt Compounding And Alert User To The Presence Of An Air Bubble Exceeding 3% Of The Ordered Volume For An Ingredient.  This Could Result In A  A Compounded Drug That Does Not Meet The Specified Accuracy Range For An Individual Ingredient.', 'Other', 'Not Specified', 'There is the potential for the compounding system to not immediately interrupt compounding and alert user to the presence of an air bubble exceeding 3% of the ordered volume for an ingredient.  This could result in a  a compounded drug that does not meet the specified accuracy range for an individual ingredient.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0718-2021');
