INSERT INTO safety_incidents VALUES ('dcd852e331fa3b273c6d993955189afe14154b26', 'FDA', '', 0, nan, 'USA', 'United States', 'Netherlands', 'Medical Devices', 'SmartPath to dStream for 3.0T, Model Number: 782145;', 'Injury', 'Sharp Edges / Points', 'Laceration / Cut', 'The Quadrature Body Coil (QBC) seal adhesive may fail, creating sharp edges that may come in contact with patients. If the QBC seal becomes loose during the scanning process, the risk to the patient may include skin abrasions, bruises, lacerations, hair loss/entanglement, and tissue injury.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1783-2025');
INSERT INTO safety_incidents VALUES ('ffaff583aa3009dbcc84c824e3c33b788c627c65', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'GENOSYL DS; Nitric Oxide Delivery System    Combination Product NDA202860', 'Reports Received Of No Measured Below Desired Dose During Transition Between Primary Console And Backup Console Since Software Version 2.2.3 Was Uploaded To Consoles In The Field.', 'Other', 'Not Specified', 'Reports received of NO measured below desired dose during transition between primary console and backup console since Software Version 2.2.3 was uploaded to consoles in the field.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1863-2021');
INSERT INTO safety_incidents VALUES ('81b177d6ee591e3502de60ddc0d9c079bca38c60', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Verigene Processor SP with assay Luminex, VERIGENE Gram-Negative Blood Culture Nucleic Acid Test, BC-GN, IVD - Product Usage: utilizes a single-use disposable test consumables and a self-contained Verigene Test Cartridge for each sample tested.', 'An Instrument Failure Mode That May Result In A Blood Culture Gram Positive (Bc-Gp) Or Gram Negative (Bc-Gn) False Negative Call.', 'Other', 'Not Specified', 'An instrument failure mode that may result in a Blood Culture Gram Positive (BC-GP) or Gram Negative (BC-GN) false negative call.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2776-2020');
