INSERT INTO safety_incidents VALUES ('5a5e97aa4581c568147c80570d3f021b7bde535e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ABS800 Chemistry Analyzer Part Number BA81F-PA00001, Containing Gas spring YQ-8/18-90-272-180N (Material Code M6T-010001--- (front spring)) and Gas spring YQ6/15-84-235(B-B)-80N (033-000090-00 (rear spring))', 'Injury', 'Other', 'Fracture / Blunt Trauma', 'The gas spring on the front and rear protective cover may fail.  There is a low risk of injury to the user resulting from failure of the gas spring. Injury may include impact to the arms, hands or fingers.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0921-2020');
INSERT INTO safety_incidents VALUES ('482e942bdd1d67a882599779caaa02c6b935a84d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BiPAP V30 Auto Ventilator, Part Number 1111178', 'Potential For Devices To Experience Interruption/Loss Of Therapy During A Ventilator Inoperative Alarm. This May Lead To Hypoventilation, Mild To Severe Hypoxemia, Hypercarbia, Respiratory Failure/Insufficiency, Or Potentially Death In The Most Vulnerable Patients.', 'Chemical / Toxic Substance', 'Respiratory', 'Potential for devices to experience interruption/loss of therapy during a Ventilator Inoperative alarm. This may lead to hypoventilation, mild to severe hypoxemia, hypercarbia, respiratory failure/insufficiency, or potentially death in the most vulnerable patients.', 'Fatal', 0, 0, 'Voluntary: Firm initiated', 'Z-1812-2024');
INSERT INTO safety_incidents VALUES ('5470236b94855dcb7e9b26beed9f4fc617387616', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Palindrome RT Repair Kit 15 FR TAL 55cm, Sterile, Item Code 8888541155', 'This Voluntary Withdrawal Is Being Conducted To Implement Point-Of-Use Labeling On Each Device And Enhancements To The Instructions For Use (Ifu).', 'Other', 'Not Specified', 'This voluntary withdrawal is being conducted to implement point-of-use labeling on each device and enhancements to the Instructions for Use (IFU).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2369-2021');
INSERT INTO safety_incidents VALUES ('ad5c36a396f430f7dccbf31fa6869389a298852b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Bard¿ Nasogastric Sump Tube with PreVent¿ Anti-Reflux Filter with ENFit, 18Fr., 48in Long, REF EN0046180', 'Bd (C.R. Bard) Has Received User Complaints Reporting That During Use Of Bd Bard Ng Sump Tubes With Enfit Connectors, Inadequate Or Reduced Suction, Decompression, And Drainage Occurred.', 'Other', 'Not Specified', 'BD (C.R. Bard) has received user complaints reporting that during use of BD Bard NG Sump Tubes with ENFit Connectors, inadequate or reduced suction, decompression, and drainage occurred.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0800-2024');
INSERT INTO safety_incidents VALUES ('618540173f06dc3efc4ce45250282b9d23a15522', 'FDA', '', 0, nan, 'USA', 'United States', 'Belgium', 'Medical Devices', 'AGFA Digital Radiography X- Ray system DR 800 with TomoSynthesis- a Tomographic X-ray system - Product Usage: TomoSynthesis is used to synthesize tomographic slices from a single tomographic sweep. The DR 800 is not intended for mammography applications', 'Tomosynthesis Image Acquisition Sequence Did Not Stop Automatically After Expected Number Of Exposures.', 'Other', 'Not Specified', 'Tomosynthesis image acquisition sequence did not stop automatically after expected number of exposures.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1502-2020');
INSERT INTO safety_incidents VALUES ('e736d7937ab09fde2b8464ab63f447e336431835', 'FDA', '2021-01-02', 2021, '2021-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Bartels Legionella Urinary Antigen- an adjunct to culture for the presumptive diagnosis of past or current Legionnaire''s Disease by qualitative detection of Legionella Pneumophila seragroup 1 antigen in human urine.  Product Code: B1029-440', 'Contamination', 'Chemical / Toxic Substance', 'Not Specified', 'Contamination of the conjugate may cause a pipetting issue which then could lead to an invalid assay', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0382-2022');
INSERT INTO safety_incidents VALUES ('33602756830fb10c4cff34f890d60ea80cc97b3c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'VITEK 2 Gram-negative Susceptibility Cards Containing o	Polymyxin B (pb02n) o	Ceftazidime/avibactam (cza02n) o	Meropenem/Vaborbactam (mev01n) o	Imipenem (ipm05n) o	Imipenem/Relebactam (ipr01n);  CARD NAME/ PRODUCT REFERENCE:  AST-N399  	423701  AST-N402  	423644  AST-N403  	423645  AST-N404  	423664', 'Potential Risk Of Quality Control Failures And/Or False Resistant Antibiotic Results When Testing Isolates Of Enterobacterales/Enterobacteriaceae Species And/Or Pseudomonas Aeruginosa With The Identified Antibiotic Formulations. Issue May Lead To Qc Failure Or False Resistant Results.', 'Microbiological Contamination', 'Not Specified', 'Potential risk of Quality Control failures and/or false resistant antibiotic results when testing isolates of Enterobacterales/Enterobacteriaceae species and/or Pseudomonas aeruginosa with the identified antibiotic formulations. Issue may lead to QC failure or false resistant results.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1236-2026');
INSERT INTO safety_incidents VALUES ('cf47f2ffa0b35fbab5dbd16b43436a59d0a9b77d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline Probe Cover Kits containing sterile Ultrasound Gel, Labeled as the following:  a)  CATHETERLESS INSERTION KIT, Model Number CVI4510;   b)  VANTEX 7FR 3L 16CM CVC BUNDLE, Model Number STCVC01145B;   c)  VANTEX TRIPLE LUMEN BUNDLE, Model Number STCVC2000;', 'Probe Covers For Use During Diagnostic Ultrasound Procedures May Have An Inadequate Barrier At The Seams.', 'Other', 'Not Specified', 'Probe covers for use during diagnostic ultrasound procedures may have an inadequate barrier at the seams.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2195-2023');
