INSERT INTO safety_incidents VALUES ('6e7b1126d117cfa3e9e84b8be5f1d83e02337229', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Swan-Ganz Jr Catheter, Models: SGPT54, SGPT64P, SGPT755P', 'Catheters May, Due To A Manufacturing Process And Material Changes, Leak/Break From The (Blue) Proximal Injectate Lumen Hub, Which May Lead To Infection, Medication Loss, And/Or Blood Loss.', 'Chemical / Toxic Substance', 'Not Specified', 'Catheters may, due to a manufacturing process and material changes, leak/break from the (blue) proximal injectate lumen hub, which may lead to infection, medication loss, and/or blood loss.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2203-2026');
INSERT INTO safety_incidents VALUES ('72fb957a75e54e36ce2d767b4223dae336e38a8e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Fifty-five (55) cm 8 Contact Extension Kit, part number  M365NM3138550 - Product Usage: The Deep Brain Stimulation (DBS) System is indicated for use in bilateral stimulation of the subthalamic nucleus (STN) as an adjunctive therapy in reducing some of the symptoms of moderate to advanced levodopa-re', 'The Firm Is Initiating A Voluntary Removal Of Certain Spinal Cord Stimulation Leads, Lead Extensions, Adapters, And Deep Brain Stimulation Lead Extensions Due To The  "Use By Date" Displayed On The Label Which Is Later Than The Correct "Use By Date". No Adverse Health Consequence Is Expected To Occur From This Issue.', 'Chemical / Toxic Substance', 'Not Specified', 'The firm is initiating a voluntary removal of certain spinal cord stimulation leads, lead extensions, adapters, and deep brain stimulation lead extensions due to the  "use by date" displayed on the label which is later than the correct "use by date". No adverse health consequence is expected to occur from this issue.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2125-2020');
INSERT INTO safety_incidents VALUES ('319b9b4ac4325f8f4f6ce297553099a8781983fe', 'FDA', '2024-01-02', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE convenience kits labeled as:   1) C-SECTION OR 30 CDS, REF CDS820075V;  2) C-SECTION OR 30 CDS, REF CDS820075W;  3) C-SECTION, REF CDS980774M;  4) C-SECTION KIT, REF CDS981322AB;  5) C-SECTION KIT, REF CDS981322AC;  6) C-SECTION COMBINED CDS, REF CDS982398I;  7) C-SECTION PROCEDURE, REF CDS9', 'Medline Is Recalling Medical Convenience Manufactured Using Certain Lots Of Safeair Smoke Evacuation Pencil Which Were Subsequently Recalled By Stryker.', 'Flammability / Overheating', 'Not Specified', 'Medline is recalling medical convenience manufactured using certain lots of SafeAir Smoke Evacuation Pencil which were subsequently recalled by Stryker.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0645-2025');
INSERT INTO safety_incidents VALUES ('8bb7b14b77f2a8375498f272e88c3241d2bc0d6a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Gambro Cartridge Low Weight-Low Volume Blood Transport System for Hemodialysis Blood Set - Product Usage: is intended for single use in a hemodialysis treatment using Dialysis Delivery Systems.', 'Potential Disconnection Of Tubing Set.', 'Other', 'Not Specified', 'Potential disconnection of tubing set.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2196-2020');
