INSERT INTO safety_incidents VALUES ('9948b3f47aa4b6585326a91e0fdd648a179edf3e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Various Angiography packs/trays', 'Product Was Exposed To Multiple Sterilization Cycles Without Validation For Multiple Exposures.', 'Other', 'Not Specified', 'Product was exposed to multiple sterilization cycles without validation for multiple exposures.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1689-2022');
INSERT INTO safety_incidents VALUES ('86f5f6a1116e15d25992a6f5a64a781b3b30ae02', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Estrone RIA, REF: DSL8700.  Estrone RIA is an IVD used for the quantitative measurement of estrone in human serum and plasma.', 'A Specific Lot Of Bovine Serum Albumin (Bsa) Used For Manufacturing Of Coated Tubes (Ct) That Are Included In The Estrone Ria Kit Lots Caused Different Affinity Of Manufactured Coated Tubes To Patient Samples, Causing Falsely Increased Assay Results For The Impacted Estrone Ria Kits.', 'Other', 'Fracture / Blunt Trauma', 'A specific lot of bovine serum albumin (BSA) used for manufacturing of coated tubes (CT) that are included in the Estrone RIA kit lots caused different affinity of manufactured coated tubes to patient samples, causing falsely increased assay results for the impacted Estrone RIA kits.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2152-2025');
INSERT INTO safety_incidents VALUES ('35c7e771de3da3ec791b0d85e8ee430ceb376078', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'SUNSTAR Butler Clear Dip, 16 FL OZ, SKU #716PA', 'Product May Be Contaminated With Burkholderia Contaminans.', 'Other', 'Not Specified', 'Product may be contaminated with Burkholderia contaminans.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1382-2021');
