INSERT INTO safety_incidents VALUES ('df08247bdf4341d52d0aff460d658c230ac5d05f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'FlexTip Plus Epidural Catheterization Set, Product Code JC-05400-DCS', 'There Is The Potential For Various Failures With The Lor (Loss Of Resistance) Syringes Included In The Kits Resulting In Dural Puncture With Some Also Requiring A Blood Patch.', 'Sharp Edges / Points', 'Not Specified', 'There is the potential for various failures with the LOR (loss of resistance) syringes included in the kits resulting in dural puncture with some also requiring a blood patch.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1202-2020');
