INSERT INTO safety_incidents VALUES ('4238ec36de33acbba4e79f39b378a1470547d2f4', 'FDA', '', 0, nan, 'USA', 'United States', 'United Kingdom', 'Medical Devices', 'OPTILITE IgM Kit, REF: NK012.OPT.A, IVD, UDI: 05051700017565', 'There Is A Potential That Users May Experience Difficulty Validating The Calibration Of The Kit. This Is Indicated By Kit Control Values Reporting Outside The Specified Ranges. This Could Result In Potential False Patient Results Which Could Cause A Delay Until Repeat Testing Is Performed.', 'Other', 'Not Specified', 'There is a potential that users may experience difficulty validating the calibration of the kit. This is indicated by kit control values reporting outside the specified ranges. This could result in potential false patient results which could cause a delay until repeat testing is performed.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1327-2020');
