INSERT INTO safety_incidents VALUES ('a0cfaecf16fef19a8d5fe46af81ab7d31ed9734c', 'FDA', '2024-01-02', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE convenience kits labeled as:   1) MAJOR VASCULAR-LF, REF CDS840232L;  2) AVF-LF, REF CDS840233I;  3) GENERAL AAA #11-RF, REF CDS840261AB;  4) HEART CDS, REF CDS840387T;  5) OPEN HEART CDS PART A, REF CDS840402AF;  6) OPEN HEART CDS PART A, REF CDS840402AI;  7) HEART PACK, REF CDS840459R;  8)', 'Medline Is Recalling Medical Convenience Manufactured Using Certain Lots Of Safeair Smoke Evacuation Pencil Which Were Subsequently Recalled By Stryker.', 'Flammability / Overheating', 'Not Specified', 'Medline is recalling medical convenience manufactured using certain lots of SafeAir Smoke Evacuation Pencil which were subsequently recalled by Stryker.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0625-2025');
INSERT INTO safety_incidents VALUES ('9838975152f72e187fb2f7cbbc0c004fc9ffceac', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Surgical convenience kits labeled as:  MEDLINE BREAST BIOPSY KIT, Reorder Number DYNDA1224B', 'The Recall Is Due To The Perforated Bag Not Allowing For Outside Of The Kit Wrapping To Be Sterile, Therefore, Only The Contents Inside The Kits Wrapping Are Sterile.', 'Other', 'Not Specified', 'The recall is due to the perforated bag not allowing for outside of the kit wrapping to be sterile, therefore, only the contents inside the kits wrapping are sterile.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1114-2023');
