INSERT INTO safety_incidents VALUES ('fb70618d53893c935afc679f0778cee7c141c100', 'FDA', '2023-01-01', 2023, '2023-01', 'USA', 'United States', 'Japan', 'Medical Devices', 'Tracheal fiberscope-airway management, which includes observation to access airway anatomy, endotracheal/endobronchial intubation and management.   Model Numbers: LF-DP, LF-GP, LF-TP.', 'Contamination', 'Drowning Risk', 'Not Specified', 'Channel air drying process was not validated, and that a small percentage of scopes returned to customers after repair had a wet channel. Water remaining in the channel of the endoscopes has the potential for contamination that could lead to the risk of infection', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0338-2024');
INSERT INTO safety_incidents VALUES ('19abe0101fc845da4c3bd72e449578d7611a037a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Neo-Vent Infant T-Piece Resuscitation Circuit With Infant Mask; Circuit for use on compatible Infant Resuscitators. 15mm OD x 10mm ID connector; REF 0420, Qty:10, Length: 60" (1.5cm), Rx Only.', 'A Repair Was Made To An Adapter Mold Resulting In Parts Being Produced With Compliant 10Mm Id Connections And Non-Compliant 15Mm Od Connections.  This Resulted In Facilities With Infant Resuscitators That Connect Via The 15Mm Od Fitting Not Being Able To Use Those Circuits.', 'Microbiological Contamination', 'Not Specified', 'A repair was made to an adapter mold resulting in parts being produced with compliant 10mm ID connections and non-compliant 15mm OD connections.  This resulted in facilities with infant resuscitators that connect via the 15mm OD fitting not being able to use those circuits.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2435-2020');
