INSERT INTO safety_incidents VALUES ('915296e797b521fba1674dc69ca4fc3e5b9c098c', 'FDA', '2022-01-02', 2022, '2022-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Medical Action Industries Inc. Port Access Kit, REF #76511B (on case label), sterile;  and Medical Action Industries Inc. IV Start Kit, REF #78019 (on kit label), sterile.  Kit components are the Port Access Kit.', 'The Port Access Kits Were Incorrectly Labeled As Iv Start Kits On The Kit Label.  The Case Label Was Correctly Labeled As Port Access Kits.', 'Other', 'Not Specified', 'The Port Access Kits were incorrectly labeled as IV Start Kits on the kit label.  The case label was correctly labeled as Port Access Kits.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0464-2023');
INSERT INTO safety_incidents VALUES ('e15c75cee13ba1402a2a2df849e641e5308fe58a', 'FDA', '2021-01-01', 2021, '2021-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Vit Kit-Freeze is intended for use in assisted reproductive procedures for vitrification and storage of human oocytes (MII), pronuclear (PN) zygotes through day 3 cleavage stage embryos and blastocyst stage embryos. This kit is designed for use with CryoTip (Catalog #40709), and Vitrification Thaw K', 'Due To A Component In Kit Being Labeled With The Incorrect Expiration Date', 'Other', 'Not Specified', 'Due to a component in kit being labeled with the incorrect Expiration Date', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0249-2022');
INSERT INTO safety_incidents VALUES ('ce440831b7779e48ca9c17fc83b9e81725d05702', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Hobbs Medical Polypectomy Snare    Catalog Number: 4565-OLY', 'Device Label Display An Incorrect Expiration Date, Extends The Shelf Life Of The Product. Affected Product  Distributed In The United States From 3/25/2018 To 9/28/2020, Expiration Dates Between 2022-11-01 And 2025-09-01 (Devices Have A Lot Number Ending In R, Or Are Kits Containing At Least 1 Device With A Lot Number Ending In R.)', 'Other', 'Not Specified', 'Device label display an incorrect expiration date, extends the shelf life of the product. Affected product  distributed in the United States from 3/25/2018 to 9/28/2020, expiration dates between 2022-11-01 and 2025-09-01 (Devices have a lot number ending in R, or are kits containing at least 1 device with a lot number ending in R.)', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0069-2023');
INSERT INTO safety_incidents VALUES ('e3ec33c9862942fe37927837cb270b30b7cb9cfb', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Vital MIS Spinal Fixation system implants CANN BL POLY EXT 8.5X60MM, Item Number 811M8560 - Product Usage: are non-cervical spinal fixation devices intended for posterior pedicle screw fixation, posterior hook fixation, or anterolateral fixation. Pedicle screw fixation is indicated for skeletally ma', 'There Are Reports Of Inadequate Locking Of The Extended Tab Screws.  Complaints Were Reported Where The Closure Top Backed Out Of The Screw Post-Operatively.', 'Other', 'Not Specified', 'There are reports of inadequate locking of the extended tab screws.  Complaints were reported where the closure top backed out of the screw post-operatively.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2232-2020');
INSERT INTO safety_incidents VALUES ('606972e48b9a3f34ff817ccb65bd35d71ce118ed', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BVI CustomEyes Procedure Packs containing Sol-M Luer Lock and Luer Slip 1ml syringes, Part Number: 58001928;', 'Due To A Voluntary Recall Of Low Dead Space Syringes, And Luer Slip Tip Syringes Manufactured By Sol-Millennium Medical (Sol-M), Inc. These Syringes  Manufactured By Sol-M Are Present In Some Of Bvi Customeyes Procedure Packs.', 'Other', 'Eye Injury', 'Due to a voluntary recall of low dead space syringes, and luer slip tip syringes manufactured by Sol-Millennium Medical (Sol-M), Inc. These syringes  manufactured by Sol-M are present in some of BVI CustomEyes Procedure Packs.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2924-2024');
INSERT INTO safety_incidents VALUES ('808012b106689945d4cdbc3f9a9b1d465623512d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LivaNova Heater-Cooler System 3T - Product Usage: The Heater-Cooler 3T System is used to circulate water through heat exchangers to warm or cool a patient during cardiopulmonary bypass procedures lasting 6 hours or less.', 'Contamination', 'Drowning Risk', 'Not Specified', 'The firm is providing validated cleaning and disinfection instructions in their revised operating instructions to reduce the risk of NTM contamination.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1498-2020');
INSERT INTO safety_incidents VALUES ('d49f2cc6c4df3804435f43812f2467b817f9128e', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'The product is a handheld ultraviolet-C germicidal wand and contains a narrow-diameter, tubular lamps with a peak emission wavelength in the 254 nm range.', 'Radiation', 'Radiation', 'Radiation Exposure', 'The subject product emits unsafe level of UVC radiation (i.e., the product reaches the exposure limit for Risk Group 3 (high risk) in about 2.2 minutes). The product has a radiation safety defect, in that these radiation emissions are unnecessary to the accomplishment of the product s primary purpose of disinfecting objects and surfaces, and create a risk of skin and/or eye injuries to user and nearby persons.', 'Serious', 0, 0, 'FDA Mandated', 'Z-2571-2025');
INSERT INTO safety_incidents VALUES ('40b74583acccf31e9a1fe9e65f3bc7b77ffcbc73', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Cytal Burn Matrix 10x15 cm. Product ID: BMM1015.', 'Increased Rate Of Out-Of-Specification Endotoxin Results.', 'Other', 'Burns', 'Increased rate of out-of-specification endotoxin results.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1820-2026');
INSERT INTO safety_incidents VALUES ('744adafd0a91b9837de05e13ff197291a636d79c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'nanoDot D2DNS, for custom calibrate, OTO, Model Numbers 03034-OTO; radiation monitoring dosimeter used with the microSTAR readers', 'Radiation', 'Radiation', 'Radiation Exposure', 'LANDAUER received reports indicating that some nanoDots may potentially be outside of the specified range of +/-5.5% accuracy. Investigation of nanoDots indicated the presence of a potential non-conformance in the Optical Stimulated Luminescence (OSL) material that is beamed after exposure and emits fluorescence proportional to radiation exposure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2539-2023');
INSERT INTO safety_incidents VALUES ('73ae0806ca4ab7b0b54620e98bf7795e14c349f6', 'FDA', '', 0, nan, 'USA', 'United States', 'Denmark', 'Medical Devices', 'Blood gases (PCO2, PO2) and blood pH test system; ABL800 FLEX; Model Number 393-800; UDI (01)05700693938004. Model 393-800 is available in the following configurations: ABL835, ABL830, ABL827, ABL825, ABL825, ABL820, ABL817, ABL815, ABL810, ABL805 and ABL810 BG only and ABL800Basic. The FlexQ module', 'Potential Risk Of Patient Mix-Up On Analyzers Due To Software Issues.', 'Other', 'Not Specified', 'Potential risk of patient mix-up on analyzers due to software issues.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2493-2020');
INSERT INTO safety_incidents VALUES ('3ecadc3c4b4289d4fe9e2fcc6d673a70897092b0', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Preview Strep A, Streptococcal A rapid test kits, Part Numbers:  a) PRE-STA-25, b) PRE-STA-A-10', 'Wondfo Usa Has Identified Unauthorized Distribution Of The Preview Strep A Test Kit. Unauthorized Distribution Of This Device Would Include Sales And Distribution Of This Test For At-Home Use, Non-Prescription Use, Over-The-Counter Use, Or Direct-To-Consumer Customers.', 'Other', 'Not Specified', 'Wondfo USA has identified unauthorized distribution of the Preview Strep A Test Kit. Unauthorized distribution of this device would include sales and distribution of this test for at-home use, non-prescription use, over-the-counter use, or direct-to-consumer customers.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2030-2024');
INSERT INTO safety_incidents VALUES ('2a8e0ffe804de6a9e14986abbedaf2aa06d749b4', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Acrysof, IQ IOL w/UltraSert System, AcrySof IQ ASPHERIC IOL, 20.5 D, SP ACRYLIC FOLDABLE LENS, w/UltraSert DELIVERY SYSTEM, UV w/BLUE LIGHT FILTER. 13.0mm. LENGTH, 6.0mm ANTERIOR ASYMMETRIC BICONVEX OPTIC, PLANAR HAPTICS.', 'Incorrect Iol Diopter', 'Radiation', 'Not Specified', 'Incorrect IOL diopter', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2287-2020');
INSERT INTO safety_incidents VALUES ('94d372f6860197d490478535520e463ddac2c424', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', '13 IN(33cm) APPX 1.0 ml, SMALLBORE SET, 4 MicroClave Clear, NanoClave T-Conn, Filter; 1 unit per pouch, 50 pouches per case. UDI:(01)10887709085210(17)250101(30)50(10)4572801;  (01)10887709085227(17)250101(30)50(10)4589920;  (01)10887709085227(17)250101(30)50(10)4572950.     The Intravascular Admini', 'Identification Of A  Potential  Manufacturing Defect On The Internal Surface Of The Nanoclave Within Specific Lots Of Nanoclave Sets, Which May Inhibit A Proper Seal With The Nanoclave Spike.', 'Mechanical Failure', 'Not Specified', 'Identification of a  potential  manufacturing defect on the internal surface of the NanoClave within specific lots of NanoClave sets, which may inhibit a proper seal with the NanoClave spike.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0207-2021');
INSERT INTO safety_incidents VALUES ('db5620d512bb1752fce5eabf796b405bcaf645db', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Philips V60 Ventilators with Power Management PCBA part number 1055906', 'Solder Connection Failure On Power Management Printed Circuit Board Assembly Of Ventilators May Cause 1) Blower To Lose Power, Spool Down, And Trigger Visual And Audible High Priority Check Vent Alarm Indicating A Need For Alternative Ventilation, Or 2) Intermittent Connection May Disrupt Expected Operation And Trigger Unexpected Shutdown Without Alarm. Failures May Lead To Hypercarbia/Hypoxemia', 'Chemical / Toxic Substance', 'Not Specified', 'Solder connection failure on Power Management printed circuit board assembly of ventilators may cause 1) Blower to lose power, spool down, and trigger visual and audible High Priority Check Vent alarm indicating a need for alternative ventilation, or 2) Intermittent connection may disrupt expected operation and trigger unexpected shutdown without alarm. Failures may lead to hypercarbia/hypoxemia', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1622-2020');
INSERT INTO safety_incidents VALUES ('81fd99d353c0f6482dfdde54548ad5b1a251c161', 'FDA', '', 0, nan, 'USA', 'United States', 'Austria', 'Medical Devices', 'GE Voluson IC9-RS intracavitary probes, Model Number J48691PJ,  Diagnostic ultrasound imaging and fluid flow analysis', 'Ge Healthcare Has Become Aware Of An Issue With Certain Ic9-Rs Ultrasound Probes (See Affected Products List) That Can Result In A Double Image Artifact Creating A Ghost Image With Realistic Features. An Unrecognized Artifact May Lead To Misdiagnosis.', 'Chemical / Toxic Substance', 'Not Specified', 'GE HealthCare has become aware of an issue with certain IC9-RS ultrasound probes (see Affected Products List) that can result in a double image artifact creating a ghost image with realistic features. An unrecognized artifact may lead to misdiagnosis.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0865-2024');
INSERT INTO safety_incidents VALUES ('cc537b52a86e017bbdad0c941b0d37c009c213ea', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'FlexTip Plus Epidural Catheterization Set for Pediatric Lumbar Placement, Product Code EC-05520-P', 'There Is The Potential For Various Failures With The Lor (Loss Of Resistance) Syringes Included In The Kits Resulting In Dural Puncture With Some Also Requiring A Blood Patch.', 'Sharp Edges / Points', 'Not Specified', 'There is the potential for various failures with the LOR (loss of resistance) syringes included in the kits resulting in dural puncture with some also requiring a blood patch.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1196-2020');
INSERT INTO safety_incidents VALUES ('a6e503241824976182cbd5f241724376a3a8898e', 'FDA', '2022-01-01', 2022, '2022-01', 'USA', 'United States', 'United States', 'Medical Devices', 'BD Multitest 6-Color TBNK with optional BD Trucount Tubes (Cat. No. 662995), for use with BD FACSLyric, BD FACSCanto II, and BD FACSCanto flow cytometers to determine the percentages and absolute counts of human lymphocyte subsets in peripheral whole blood for immunophenotyping.', 'Due To Partial Label Detachment On Tubes. This Can Cause Tubes To Become Stuck Together In The Pouch Or Cause Automation Errors When Used With The Automated Loader For The Wash Assistant.', 'Mechanical Failure', 'Not Specified', 'Due to partial label detachment on tubes. This can cause tubes to become stuck together in the pouch or cause automation errors when used with the automated loader for the wash assistant.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0173-2023');
INSERT INTO safety_incidents VALUES ('948c18b7d0ece8f409389e465b0f47cb169f04e0', 'FDA', '', 0, nan, 'USA', 'United States', 'Japan', 'Medical Devices', 'INJECTOR FORCEMAX LOWER 25G 6MM, model no. NM-400U-0625 - Product Usage: Used with endoscopes to perform endoscopic injection for the treatment of esophageal and gastric varices and for submucosal injection in the digestive tract.', 'Inspection Confirmed A Small Percentage Of Sterile Packages With Inadequate Package Seal (Partial Heat Seal). Patients May Develop Infections If Non-Sterile Equipment Is Used.', 'Other', 'Not Specified', 'Inspection confirmed a small percentage of sterile packages with inadequate package seal (partial heat seal). Patients may develop infections if non-sterile equipment is used.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1022-2021');
INSERT INTO safety_incidents VALUES ('741590ad9972605c1093ea3829430d261e7516a7', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Echelon -14, 45 Tip Shape, REF 145-5092150, sterile EO, Rx Only', 'Outer Carton Packaging Of Microcatheters Were Exposed To Wet Substance During Transport.', 'Other', 'Not Specified', 'Outer carton packaging of microcatheters were exposed to wet substance during transport.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1556-2022');
INSERT INTO safety_incidents VALUES ('4b04757c8e2b0d13dd2b45364428bd059032b08c', 'FDA', '2021-01-01', 2021, '2021-01', 'USA', 'United States', 'United States', 'Medical Devices', 'IPL Coupling Gel, I L (AX1009013), 12 pack of 0.25 L (AX1009018), 6 pack of 1 L (AX1009019 or AX1009063); and IPL Coupling Gel or EcoGel 200, 0.25 L (AX1009012) manufactured by Eco-Med Pharmaceutical', 'Contamination', 'Microbiological Contamination', 'Not Specified', 'Ultrasound gels and lotions manufactured by Eco-Med Pharmaceutical, Inc. may contain bacterial contamination. On August 18, 2021, FDA published a Letter to Health Care Providers to further address this issue: https://www.fda.gov/medical-devices/letters-health-care-providers/stop-using-all-eco-med-ultrasound-gels-and-lotions-due-risk-bacterial-contamination-letter-health.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0194-2022');
INSERT INTO safety_incidents VALUES ('b34f275ecb77d16b1443445b73b87fdac43d37e2', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Titan Pump Assembly, Catalog Number 5177701400; inflatable penile Prosthesis', 'A Decrease In Wall Thickness Has The Potential For A Premature Pump Failure, Compared To A Pump With Standard Wall Thickness, Based On The Number Of Interactions With The Pump To Inflate And Deflate The Penile Prosthesis.', 'Other', 'Not Specified', 'A decrease in wall thickness has the potential for a premature pump failure, compared to a pump with standard wall thickness, based on the number of interactions with the pump to inflate and deflate the penile prosthesis.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1360-2023');
INSERT INTO safety_incidents VALUES ('49d3e91a6f3173a545809f38a9d316dd8d8e7c6a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Battery Operated infusion pumps. t:slim X2 G5, Replacement, Refurbished, REF: 1000911;  t:slim X2 GS Classic, Replacement, Refurbished, REF: 1003808;  t: slim X2, Basal-IQ, mg/dl, REF: 1004219;  Pump, t:slim X2, Clinical Use Only, REF: 1004484;  Pump, t:slim X2, Control-IQ, REF: 1005611;  Pump, t:sl', 'Injury', 'Mechanical Failure', 'Eye Injury', 'Insulin pumps manufactured with speakers from Revision A and B may malfunction ("Malfunction 16") which prevents audible alerts and causes the pumps to become inoperable and stop infusing insulin which could result in a hyperglycemic event, which may lead to injury and/or hospitalization.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2343-2025');
INSERT INTO safety_incidents VALUES ('85599567d64157e2cdb28547eec27832437ed9ab', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 't:slim X2 Insulin Pump with Dexcom G5 Mobile CGM, and t:slim X2 Insulin Pump with Basal-IQ Technology', 'Falls', 'Chemical / Toxic Substance', 'Fall Injury', 'Insulin pumps may display unexpected fluctuation of the remaining battery life so ensure pump battery life does not fall below 25% remaining power. If the battery life drops to less than 5%, insulin delivery will continue for 30 minutes and then the pump will power off and insulin delivery will stop. If the battery reaches 1%, then insulin delivery will stop, which could lead to hyperglycemia.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1258-2022');
INSERT INTO safety_incidents VALUES ('81a4f54dbd3b8cf3d130fb1cb6a770963357d36c', 'FDA', '2024-01-02', 2024, '2024-01', 'USA', 'United States', 'Australia', 'Medical Devices', 'MICRO-X Rover Mobile X-ray System, # MXU-RV35', 'Shots Were Terminated By The Mas Integrator; However, The 4 Ms Exposure Time Did Not Allow Enough Tolerance To Achieve Diagnostic Exposures Due To Variations In Hardware And How Different Timers Are Started.', 'Other', 'Not Specified', 'Shots were terminated by the mAs integrator; however, the 4 ms exposure time did not allow enough tolerance to achieve diagnostic exposures due to variations in hardware and how different timers are started.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0664-2025');
INSERT INTO safety_incidents VALUES ('189ba3797484745bfdd7074c76b92d236c9ba56c', 'FDA', '2024-01-01', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Stryker Neptune SafeAir Rocker-Switch Smoke Evacuation Pencil, Non-coated, 70mm - Designed for general electrosurgical applications including cutting and coagulation and for removing smoke generated by electrosurgery when used in conjunction with an effective smoke evacuation system.    Catalog Numb', 'Burns', 'Electrical Fault', 'Burns', 'There is a potential for the product to activate without manual input when plugged into a power source or remain active after buttons are released. Unintentional activation of the device may result in localized burns to the patient or physician from electrical currents  carried through conductive objects or fluids. Medical/surgical intervention may be needed to correct these injuries', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0367-2025');
INSERT INTO safety_incidents VALUES ('bde39c7fea7f6663db80c6249cba5842ff713924', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'IVENIX INFUSION SYSTEM LVP Blood Products Administration Set, Dual-Inlet, Low-Sorbing, Y-Site, Mesh Filter, 15 mL. Intravascular Administration Set.', 'Mis-Assembly Error Of Blood Products Administrations Sets Where The 200-Micron Drip Chamber Filter May Be Incorrectly Positioned And Unable To Filter Out Large Blood Particulates.', 'Other', 'Not Specified', 'Mis-assembly error of Blood Products Administrations Sets where the 200-micron drip chamber filter may be incorrectly positioned and unable to filter out large blood particulates.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1869-2025');
INSERT INTO safety_incidents VALUES ('18ffaa360c2c4196ba9fe863b9f86386878b3d45', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'TRAY RING COVER, REF OM271000, CONTAINS (1) TRAY RING COVER, STERILE R, Rx Only,', 'Potential Breach In The Sterility Barrier For Tray Ring Covers.', 'Other', 'Not Specified', 'Potential breach in the sterility barrier for tray ring covers.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1033-2022');
INSERT INTO safety_incidents VALUES ('7c0ef026f3eb26b000d4cbcc993a17f5d165cddd', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Expo 5F Selective Angiographic Catheters, MODEL - 5F EXPO FR4 (5PK), REF H74908526022; cardiac catheter', 'An Increase In Complaints Related To An Inability To Advance The Guidewire Through The Lumen Of The Device For Certain Batches. There Is Evidence Of The Polyurethane Layer Delaminating And In Some Instances Material Detachment In The Catheters Inner Lining.', 'Mechanical Failure', 'Not Specified', 'An increase in complaints related to an inability to advance the guidewire through the lumen of the device for certain batches. There is evidence of the polyurethane layer delaminating and in some instances material detachment in the catheters inner lining.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1639-2024');
INSERT INTO safety_incidents VALUES ('b0eedc6947a5fb0ff1258a6274111eb7c5ae91d1', 'FDA', '2022-01-01', 2022, '2022-01', 'USA', 'United States', 'United States', 'Medical Devices', '18239: ASM Omnipod Dash PDM, insulin delivery system.    PT-000010: Assembly, Dash Final PDM U100, mg/dL  PT-000011: Assembly, Dash Final PDM U100, mmol/L  PT-000030: Assembly, DASH PDM, Canada    Remote Controller (Personal Diabetes Manager or PDM) associated with Insulin Pump (Pod)      *The part ', 'Fire', 'Flammability / Overheating', 'Not Specified', 'The firm has become aware of PDM battery issues, including battery swelling, fluid leaking from the battery, and extreme overheating, which may pose a fire hazard. The firm has received a complaint alleging fire as a result of thermal energy from a DASH PDM.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0154-2023');
INSERT INTO safety_incidents VALUES ('77e6437449d5c8ac11428b016db318df61c7dd30', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'ACL ELITE PRO-Analyzer designed specifically for clinical use in the hemostasis laboratory, for coagulation and/or fibrinolysis testing.  Part Number: 0001000311', 'Removes The Test Definition For Hemosil Liquid Anti-Xa (Pn 0020302600 And 0020302601) From The Acl Elite/Elite Pro Instruments', 'Other', 'Not Specified', 'Removes the test definition for HemosIL Liquid Anti-Xa (PN 0020302600 and 0020302601) from the ACL Elite/Elite Pro instruments', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1305-2023');
INSERT INTO safety_incidents VALUES ('aad1114e47d53fc3e9625943e1a68df3acd19448', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Omnipod DASH Insulin Management System User Guide (OUS  Only)  Product Catalog Number:   PT 000002 XXX XXX XX  PT 000318  PT 000319    Distributed to: Canada (French only), the Netherlands, France, Austria, Germany, Belgium, Greece, Turkey, Norway, Sweden, Denmark, and Finland', 'Certain Foreign User Guides Include A Misprint Which Could Lead To An Incorrect Bolus Delivery And Hypoglycemia.  Only Outside The Us (Ous): Error In The Omnipod Dash User Guide Text, Page 6 Of The User Guide, The Text States That The Comma (,) Is Not Used For The Decimal On The Pdm, When In Fact It Is The Period (.) That Is Not Used.If A User Were To Use The Period As A Decimal Separator When Entering A Bolus Value, This Decimal Separator Would Not Be Recognized By The Device And Any Numbers Entered After The Period Could Result In A Larger Value Than Intended', 'Chemical / Toxic Substance', 'Not Specified', 'Certain foreign user guides include a misprint which could lead to an incorrect bolus delivery and hypoglycemia.  Only Outside the US (OUS): Error in the Omnipod DASH User Guide text, page 6 of the User Guide, the text states that the comma (,) is not used for the decimal on the PDM, when in fact it is the period (.) that is not used.If a user were to use the period as a decimal separator when entering a bolus value, this decimal separator would not be recognized by the device and any numbers en', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1203-2021');
INSERT INTO safety_incidents VALUES ('c7be0771c0595e765f00b0dc6e8864377bb95d45', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medivance Neonatal ArcticGel Pads, REF: 31802, 3180202, 31802C', 'Neonatal Pads Are Experiencing Reduced Water Flow, Which May Reduce Or Prevent Water Heating Or Cooling  Performance Of The Pads That Are Part Of A Temperature Management System.', 'Drowning Risk', 'Not Specified', 'Neonatal pads are experiencing reduced water flow, which may reduce or prevent water heating or cooling  performance of the pads that are part of a temperature management system.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1381-2024');
INSERT INTO safety_incidents VALUES ('07e984fb897ba859eb795951ad933b49053f2544', 'FDA', '', 0, nan, 'USA', 'United States', 'Canada', 'Medical Devices', 'CARA (Computer Assisted Retinal Analysis), Product ID: +B543CARA0/$$+7V4.7.2/16D202111179', 'Retinal Analysis System Software Has Some Features, Based On Artificial Intelligence, That Potentially Lack Appropriate Market Approval, So It Is Recommended To Use A Specific Prior Software Version.', 'Other', 'Not Specified', 'Retinal analysis system software has some features, based on artificial intelligence, that potentially lack appropriate market approval, so it is recommended to use a specific prior software version.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0826-2022');
INSERT INTO safety_incidents VALUES ('7e8bfbb45ded371377b1375cafeecad6b13225f8', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'WATCHMAN TruSeal Access System SGL, US, Material Number (UPN) M635TU70010; intended to provide vascular and transseptal access for all WATCHMAN Left Atrial Appendage Closure Devices with Delivery Systems.', 'Boston Scientific Has Identified A Higher Likelihood Of Air Embolism Events When Procedures Are Performed Without Positive Pressure-Controlled Ventilation. According To Published Literature And Clinical Data, In Percutaneous Procedures Requiring Transseptal Access To The Left Atrium When Conscious Or Deep Sedation Is Used, Patients Have An Approximately Three-Times Higher Risk (U.S. Study) Of Negative Left Atrium Pressure And Air Ingress.    This Risk Is Especially Prevalent In Patients With Pre-Existing Low Left Atrial Pressure, Hypovolemia, And Partial Upper Airway Collapse.', 'Mechanical Failure', 'Laceration / Cut', 'Boston Scientific has identified a higher likelihood of air embolism events when procedures are performed without positive pressure-controlled ventilation. According to published literature and clinical data, in percutaneous procedures requiring transseptal access to the left atrium when conscious or deep sedation is used, patients have an approximately three-times higher risk (U.S. study) of negative left atrium pressure and air ingress.    This risk is especially prevalent in patients with pre', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2431-2025');
INSERT INTO safety_incidents VALUES ('601657b663ece0958826dcb8425eb1de83ccb7cc', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CS5/5+ Fastpacks, 225 mL, 20¿ Res Autotransfusion Device - Product Usage: its related accessory components are intended to be used for the recovery and processing of blood shed during or subsequent to an operation or as a result of trauma.', 'Potential To Develop Leaks At The Inner Core Of Cell Saver¿ 5/5+ And Cell Saver¿ Elite¿/Elite¿ +125Ml And 225Ml Bowl Sets. Which Could Result In Fluid Being Trapped Inside The Bowl Core, Causing A Long Empty Device Error Message With The Possibility Of Incomplete Washing.', 'Entrapment', 'Not Specified', 'Potential to develop leaks at the inner core of Cell Saver¿ 5/5+ and Cell Saver¿ Elite¿/Elite¿ +125ml and 225ml bowl sets. Which could result in fluid being trapped inside the bowl core, causing a long empty device error message with the possibility of incomplete washing.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0890-2020');
INSERT INTO safety_incidents VALUES ('7f97a5e3b88b449b710d91c69af7b380cc27fa7b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Allwell Inflation Device, for angiographic use REF: IS-30-A', 'Inflation Device Handle May Detach From The Syringe During Procedure.', 'Mechanical Failure', 'Not Specified', 'Inflation device handle may detach from the syringe during procedure.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1124-2026');
