INSERT INTO safety_incidents VALUES ('4ca73b5fec8f2808adfa917afb6ce98891e89f79', 'FDA', '2024-01-02', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE convenience kits labeled as:    1) BASIC NEURO PACK, REF CDS780202P;   2) BASIC NEURO PACK, REF CDS780202Q;   3) BASIC NEURO PACK, REF CDS780202R;   4) ACDF CDS, REF CDS941061M;   5) NEURO KIT, REF CDS981327Q;   6) ZALE V-P SHUNT CDS, REF CDS983186J;   7) NEURO PACK-LF, REF DYNJ0038440C;   8', 'Medline Is Recalling Medical Convenience Manufactured Using Certain Lots Of Safeair Smoke Evacuation Pencil Which Were Subsequently Recalled By Stryker.', 'Flammability / Overheating', 'Not Specified', 'Medline is recalling medical convenience manufactured using certain lots of SafeAir Smoke Evacuation Pencil which were subsequently recalled by Stryker.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0640-2025');
INSERT INTO safety_incidents VALUES ('c1feb80cbe57d639a5be130b42cadefadeb121a0', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CervAlign Anterior Cervical Plate System-Cervalign, 3 Level, 45mm Material Number: 66-345 - Product Usage: intended for anterior cervical fixation (C2-C7) for the following conditions: degenerative disc disease (DDD) defined as neck pain of discogenic origin with degeneration of the disc confirmed b', 'Locking Mechanism Has Been Observed To Disassociate Either Intraoperatively Or Postoperatively Resulting In Replacement/Revision', 'Mechanical Failure', 'Fracture / Blunt Trauma', 'Locking mechanism has been observed to disassociate either intraoperatively or postoperatively resulting in replacement/revision', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1221-2021');
INSERT INTO safety_incidents VALUES ('01b94f9bbe8bf5b8cbff4c4738cd550435c11357', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Siemens ADVIA Centaur Folate 100 test kit-for IVD of folate in serum or red blood cells  SMN:10310308', 'Homocysteine Assay May Cause Elevated Results In The Folate Assay', 'Other', 'Not Specified', 'Homocysteine Assay May Cause Elevated Results in the Folate Assay', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0829-2020');
INSERT INTO safety_incidents VALUES ('e6c587186bdec468225de67273b6468550528190', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medline Convenience Kits:  1) SCC RF PAIN MGMT, Model Number:DYNJ56436A;   2) SCC RF PAIN MGMT, Model Number:DYNJ56436B;   3) SCC RF PAIN MGMT, Model Number:DYNJ56436C;   4) CPNB SETUP TRAY, Model Number:DYNJRA1979;   5) CPNB SETUP TRAY, Model Number:DYNJRA1979A;   6) CPNB SETUP TRAY, Model Number:D', 'Medline Has Identified Issues Related To Calibration Of The Equipment Used To Sterilize And Package The Devices. All Products Were Exposed To The Validated Sterilization And Packaging Cycles; However, The Identified Calibration Issues Have The Potential To Impact The Sterility Assurance Level (Sal) Of The Recalled Products.', 'Other', 'Fracture / Blunt Trauma', 'Medline has identified issues related to calibration of the equipment used to sterilize and package the devices. All products were exposed to the validated sterilization and packaging cycles; however, the identified calibration issues have the potential to impact the sterility assurance level (SAL) of the Recalled Products.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2090-2026');
INSERT INTO safety_incidents VALUES ('64f64039997c5fc43e1eba2f17bf0fe9cd237c27', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'WALLFLEX ESOPHAGEAL FC 23/28MMX12CM- Wallflex Esophageal Partially Covered and Fully Covered Stent System is Intended for maintaining esophageal luminal patency in esophageal strictures caused by intrinsic and/or extrinsic malignant tumors, and occlusion of concurrent esophageal fistulas    Material', 'Wallflextm Esophageal Stent System And Agiletm Esophageal Over The Wire (Otw) Stent System Due To The Potential For Delivery Catheter Tip Detachment.', 'Mechanical Failure', 'Not Specified', 'WallFlexTM Esophageal Stent System and AgileTM Esophageal Over the Wire (OTW) Stent System due to the potential for delivery catheter tip detachment.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-3279-2024');
