INSERT INTO safety_incidents VALUES ('71b14003976dfc4617650411d248365aed7d52c3', 'FDA', '2024-01-01', 2024, '2024-01', 'USA', 'United States', 'United States', 'Medical Devices', 'DeRoyal CHILDREN''S LAPTRACEPACK, 89-9362.06', 'Deroyal Is Recalling Certain Lots Of Surgical Procedure Pack Products That Contain A Stryker Safeair Smoke Evacuation Pencil. The Recall Is Due To Stryker Receiving Reports That The Pencil Is Activating Without Manual Input When Plugged Into A Power Source Or Remains Active After Buttons Are Released.', 'Flammability / Overheating', 'Not Specified', 'DeRoyal is recalling certain lots of surgical procedure pack products that contain a Stryker SafeAir Smoke Evacuation Pencil. The recall is due to Stryker receiving reports that the pencil is activating without manual input when plugged into a power source or remains active after buttons are released.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0309-2025');
