INSERT INTO safety_incidents VALUES ('30b1aa945ffd54c619cea8624258ce392355e9a3', 'FDA', '2022-01-01', 2022, '2022-01', 'USA', 'United States', 'United States', 'Medical Devices', 'MEDLINE ADLT BLOOD CLUTURE COLLECT KIT, Reorder #:  DYNDH1245', 'Adult Blood Culture Collect Kit And Pre-Op Changing Bathing Kit Contain An Incorrect Expiration Date On A Component With The Kit. Chg Solution With The Pre-Op Changing Bathing Kit And Bactec Bottle Plastic Both Have An Expiration Date That Does Not Match The Date Listed On The Kit.', 'Other', 'Not Specified', 'Adult Blood Culture Collect kit and Pre-Op Changing Bathing Kit contain an incorrect expiration date on a component with the kit. CHG Solution with the Pre-Op Changing Bathing Kit and Bactec bottle plastic both have an expiration date that does not match the date listed on the kit.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0120-2023');
