INSERT INTO safety_incidents VALUES ('e0a152e1a0d492eb216865dcc37932f7642f2e4a', 'FDA', '2020-01-02', 2020, '2020-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Oxford Fixed Lateral, Item numbers 154330, 154370, 154373  154376 - Product Usage: indicated for use in the lateral compartment and intended to be implanted with bone cement.', 'Specific Lots Of Multiple Sterile Medical Devices May Have A Breach In The Sterile Seal. A Breach In The Packaging Seal Could Lead To Loss Of Sterility Of The Device.', 'Chemical / Toxic Substance', 'Not Specified', 'Specific lots of multiple sterile medical devices may have a breach in the sterile seal. A breach in the packaging seal could lead to loss of sterility of the device.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0624-2021');
INSERT INTO safety_incidents VALUES ('bc8438a9eb2447c3f5df2bb1970a2633ac6f1f2a', 'FDA', '', 0, nan, 'USA', 'United States', 'Brazil', 'Medical Devices', 'Implant Epikut S Plus CM 16-Degrees 4,5 X 18,0 mm, REF: ILM 4518N', 'Dental Implant Box Incorrectly Labels The Diameter As 4,5 X 18,0 Mm, But The Internal Label Correctly Labels The Diameter As 4,0 X 18,0 Mm; If The Dentist Drills The Bone With The Larger Diameter Stated On The Box, The Smaller Diameter Implant, Will Become Loose And Will Not Fit, Which May Necessitate An Additional Surgery.', 'Other', 'Not Specified', 'Dental implant box incorrectly labels the diameter as 4,5 X 18,0 mm, but the internal label correctly labels the diameter as 4,0 X 18,0 mm; if the dentist drills the bone with the larger diameter stated on the box, the smaller diameter implant, will become loose and will not fit, which may necessitate an additional surgery.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0920-2025');
INSERT INTO safety_incidents VALUES ('e48a5eb461fe063680a0c1f5a30ccad57cdbc919', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Infusomat Space Volumetric Pump Administration Set, Product Code 490100', 'There Is A Potential For The Anti-Free Flow Clip Of The Administration Set To Be Inverted Which May Cause Unintended Free Flow If The User Fails To Follow On Screen Prompt To Close The Roller Clamp Prior To Set Removal From The Pump.', 'Other', 'Not Specified', 'There is a potential for the Anti-free flow clip of the administration set to be inverted which may cause unintended free flow if the user fails to follow on screen prompt to close the roller clamp prior to set removal from the pump.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2137-2021');
