INSERT INTO safety_incidents VALUES ('22ac4d088422d5c61cfa230e5fa5e3da29b273e9', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Impella RP with SmartAssist. Product Code: 0046-0035.', 'Differential Pressure (Dp) Sensor In Impella Rp Devices May Malfunction, Causing Sensor Values To Drift.', 'Mechanical Failure', 'Not Specified', 'Differential pressure (dP) sensor in Impella RP devices may malfunction, causing sensor values to drift.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1469-2026');
INSERT INTO safety_incidents VALUES ('3fc6c50d0d05fdb162907166bfa3aea889a180f5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Alinity ci-series System Control Module, REF: 03R70-01', 'There Are Potential Performance Issues Found In The Alinity Ci-Series System Software Versions 3.4.0 And Lower, Including: 1) Scc Reagent Load Error During Daily Maintenance; 2) Sample Laboratory Report Error; 3) Customer Requests Mechanism To Prevent User Error When Creating New Lots Of Value Assigned Calibrators; 4) Error In Processing Tests After Cccintcontroller Encountered An Error With The Assay Information Downloaded From Scc; 5) The Assay Editor Does Not Correctly Check Sample Dilution Total Volume Limits; 6) User-Applied Labels Not Adhering To Reagent Bottles; 7) Ict Module Did Not Expire After Warranty Was Exceeded. These Performance Issues Could Lead To Erroneous Results For Multiple Analytes.', 'Chemical / Toxic Substance', 'Not Specified', 'There are potential performance issues found in the Alinity ci-series System software versions 3.4.0 and lower, including: 1) SCC Reagent load error during daily maintenance; 2) Sample Laboratory Report error; 3) Customer requests mechanism to prevent user error when creating new lots of value assigned Calibrators; 4) Error in processing tests after CCCintController encountered an error with the assay information downloaded from SCC; 5) The assay editor does not correctly check sample dilution t', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0613-2024');
INSERT INTO safety_incidents VALUES ('c1f6ddb370586553bfce8a866571df85a4ffeb22', 'FDA', '', 0, nan, 'USA', 'United States', 'Denmark', 'Medical Devices', 'ABL90 FLEX, model no. 393-090; and Spare Part Hemolyzer Units (902-980): R0526 - R0941  - Product Usage: are intended for use by trained technologists, nurses, physicians and therapists. It is intended for use in a laboratory environment, near patient or point-of-care setting.', 'The Analyzers Fail On S7950 (Range +) Qc Measurements Due To The Hemolyzer Cuvettes, A Subcomponent Of The Optical System Which Measures Cthb And Derivates. In A Cuvette With Light Shunt, Some Of The Received Light Has Not Been Transmitted Through The Sample. This Will Lead To A Perturbed And Non-Linear Absorbance Spectrum Which Results In Measurement Errors.', 'Chemical / Toxic Substance', 'Not Specified', 'The analyzers fail on S7950 (Range +) QC measurements due to the hemolyzer cuvettes, a subcomponent of the optical system which measures ctHb and derivates. In a cuvette with light shunt, some of the received light has not been transmitted through the sample. This will lead to a perturbed and non-linear absorbance spectrum which results in measurement errors.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2139-2020');
INSERT INTO safety_incidents VALUES ('4338983cd9917e09f2a2a39efeac15244e055841', 'FDA', '2021-01-01', 2021, '2021-01', 'USA', 'United States', 'Brazil', 'Medical Devices', 'GM Helix Acqua Implant 3.5x10, Article No. 140.944', '3.5X11.5Mm Implants Were Mislabeled As 3.5X10Mm Implants. In Borderline Cases Where The Bone Quality Is Low And The Bone Ridge Has A Maximum Indication For The Implant Height (10Mm), If The Incorrect Implant Is Installed, It Could Result In Damage To The Nerve Or Adjacent Bone Structures/Cavities.', 'Other', 'Not Specified', '3.5x11.5mm implants were mislabeled as 3.5x10mm implants. In borderline cases where the bone quality is low and the bone ridge has a maximum indication for the implant height (10mm), if the incorrect implant is installed, it could result in damage to the nerve or adjacent bone structures/cavities.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0203-2022');
INSERT INTO safety_incidents VALUES ('a5b306c2b7e76fb04f25d91e206b692074d64a15', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'COVIDIEN Emprint Ablation Catheter with Thermosphere Technology, Bronchoscopic Ablation, REF CA108L1', 'The Product Is Labeled With The Incorrect Expiration Date.', 'Other', 'Not Specified', 'The product is labeled with the incorrect expiration date.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0955-2023');
