INSERT INTO safety_incidents VALUES ('35aca4ae91f8cbd922a8264f32f83eabc81b24ba', 'FDA', '', 0, nan, 'USA', 'United States', 'Netherlands', 'Medical Devices', 'Allura Xper FD20/15 OR Table; System Code: 722059;', 'Philips Has Identified Instances Where X-Ray Imaging May Not Be Initiated Or May Occur Intermittently When Using The Wired Foot Switch.', 'Other', 'Not Specified', 'Philips has identified instances where X-ray imaging may not be initiated or may occur intermittently when using the wired foot switch.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1672-2026');
INSERT INTO safety_incidents VALUES ('2167309b5c8a4e93532fb39c3aa72e7a60b64a94', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'TECNIS Eyhance IOLs are permanent intraocular implants intended for implantation in the capsular bag.  The TECNIS Simplicity Delivery System is designed as a single-use disposable preloaded modular cartridge that functions as both the primary packaging and as a sterile, disposable insertion system f', 'Nonconforming Product Was Distributed In Error.  Product Was Nonconforming Due Endotoxin Levels Higher Than Both The Firm''S Internal Endotoxin Specification Limit And The Fda Recommended Endotoxin Specification Limit.  Product Was Released In Error Based On The Results Of Additional Testing Performed During The Investigation Into Release Testing Nonconformance.', 'Other', 'Eye Injury', 'Nonconforming product was distributed in error.  Product was nonconforming due endotoxin levels higher than both the Firm''s internal endotoxin specification limit and the FDA recommended endotoxin specification limit.  Product was released in error based on the results of additional testing performed during the investigation into release testing nonconformance.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0028-2022');
INSERT INTO safety_incidents VALUES ('dfcb46a88ac00267f7ec0d86a8b67b2b0e4cfb02', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BVI CustomEyes Procedure Packs containing Sol-M Luer Lock and Luer Slip 1ml syringes, Part Number: 58001764;', 'Due To A Voluntary Recall Of Low Dead Space Syringes, And Luer Slip Tip Syringes Manufactured By Sol-Millennium Medical (Sol-M), Inc. These Syringes  Manufactured By Sol-M Are Present In Some Of Bvi Customeyes Procedure Packs.', 'Other', 'Eye Injury', 'Due to a voluntary recall of low dead space syringes, and luer slip tip syringes manufactured by Sol-Millennium Medical (Sol-M), Inc. These syringes  manufactured by Sol-M are present in some of BVI CustomEyes Procedure Packs.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2911-2024');
INSERT INTO safety_incidents VALUES ('cff51bc738a6927ffe33699cb6c26a26806976bd', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BodyGuard Microset, REF: A120-160X2YB', 'Infusion Administration Sets May Have A Delivery Inaccuracy Over Plus/Minus 13%, Ranging From Minus 42.8% To Plus 17.5%. Use Of The Infusion Pump System Could Cause Over-Infusion Or Under-Infusion Of Therapy', 'Other', 'Not Specified', 'Infusion administration sets may have a delivery inaccuracy over plus/minus 13%, ranging from minus 42.8% to plus 17.5%. Use of the infusion pump system could cause over-infusion or under-infusion of therapy', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2566-2020');
INSERT INTO safety_incidents VALUES ('99d24ca86112fd46616ac9950aec20837447aab2', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Custom procedure trays containing medical components needed to facilitate patient procedures and to perform minor and major patient surgeries. Multiple item and lot numbers.', 'Environmental', 'Other', 'Not Specified', 'The medical procedure trays contain one or more recalled surgical gowns.  The gowns were manufactured at locations that did not maintain proper environmental conditions. There is no assurance that the surgical gowns are sterile.  An inadequately sterilized surgical gown could compromise a sterile field and increase the risk of a surgical site infection. Due to the configuration of the trays, the recalled gowns may come into contact with other components within the tray posing a risk of cross con', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1521-2020');
INSERT INTO safety_incidents VALUES ('886e882c4eb6f31106cbaec0f1fe95385443e60b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'SafeStep Huber Needle Set with GuardIVa Antimicrobial Hemostatic Dressing Port Access Kit; Catalog Numbers PA-0031G (UDI 00801741085666), PA-0031YNG (UDI 00801741085673), PA-0032G (UDI 00801741087639), PA-0033G (UDI 00801741096433)', 'Chemical', 'Chemical / Toxic Substance', 'Not Specified', 'Potential development of cracks or breaks in the tubing near the Luer or Y site of the device. Devices that have developed breaks or cracks can cause leakage resulting in exposure to chemicals such a chemotherapeutics or biohazard material (e.g., blood). A crack or break could result in potential blood loss, catheter occlusion, air embolism, under or interrupted infusion, or site contamination which could lead to infection.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2668-2020');
INSERT INTO safety_incidents VALUES ('e8444e7b0b7a3387411532a348d458e1ebd405ab', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', '13 mm Titanium Hindfoot Arthrodesis Cannulated Nails EX, sterile -Intended to facilitate tibiotalocalcaneal arthrodesis to treat severe foot/ankle deformity, arthritis, instability, and skeletal defects after tumor resection.   Part Number: 04.008.378S', 'Products Not Sterilized, Sterility Cannot Be Confirmed', 'Instability / Fall Risk', 'Not Specified', 'Products not sterilized, sterility cannot be confirmed', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1234-2024');
