INSERT INTO safety_incidents VALUES ('4ca99f56163d2d2db888897baa73353b8bd26827', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Dual Flat Panel Monitor (DFPM) accessories for HarmonyAIR A-Series Surgical Lighting Systems', 'The Dfpm Yoke Assembly ("Yoke Assembly") May Detach From The Spring Arm. Should The Yoke Assembly Detach From The Spring Arm, The Yoke Assembly Would Not Be Expected To Fully Detach But Rather Hang From The Wiring Within The Yoke Assembly.', 'Electrical Fault', 'Not Specified', 'The DFPM yoke assembly ("yoke assembly") may detach from the spring arm. Should the yoke assembly detach from the spring arm, the yoke assembly would not be expected to fully detach but rather hang from the wiring within the yoke assembly.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2177-2025');
