INSERT INTO safety_incidents VALUES ('467d6587fd20350454bda03fc5785a4717e8bc5b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'REF CH3011 30" (76 cm)  Appx 3.3 mL, 20 Drop Admin Set w/Integrated ChemoClave Drip Chamber, Spiros  w/Red Cap, Bag Hanger - Product Usage: provides access for the administration of fluids from a container to a patient s vascular system through the administration set s needle or catheter (which is i', 'Due To Molding Defect, There Is A Potential That Certain Lots Of Spinning And Non-Spinning Sprios Male Luers May Exhibit Small Amounts Of Leakage In The Inactivated Position.', 'Mechanical Failure', 'Not Specified', 'Due to molding defect, there is a potential that certain lots of spinning and non-spinning Sprios male luers may exhibit small amounts of leakage in the inactivated position.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1578-2021');
INSERT INTO safety_incidents VALUES ('0991cf8d037215d7bc22aa4e409b53494c6f68b1', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'LYMOL Medical Elite X Class Rigid Bronchoscope System, Part No. BD2410, BB2701, BB2702, BB2401, BB2402, BA2700, BT2000, BT2101, BT2103, BT2105, BT2106, BT2210, BT2201, BT2203, BT2205, BR2200, BP2200, BI2200, BR2000, BP2000, BI2999, BR2103, BP2103, BI2103, BR2101, BP2101, BI2101, BI2001, BDL2420', 'Reprocessing Instructions Were Revised November 15, 2020, To Reflect New Processes And Equipment Used At Consignee User Facilities. New Instructions Were Not Sent To All Consignees Of The Devices At The Time Of The Revision.', 'Other', 'Eye Injury', 'Reprocessing instructions were revised November 15, 2020, to reflect new processes and equipment used at consignee user facilities. New instructions were not sent to all consignees of the devices at the time of the revision.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2562-2021');
INSERT INTO safety_incidents VALUES ('e35f577b72dfdbd2761093e2860072c25327b43f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Vanguard Knee System AS Tibial Bearing / DCM ArCom, 12 MM X 75 MM; Model Number 189082. The product is placed into a foil pouch with protective packaging in the form of a  polyurethane bag, and sealed closed (inner barrier). The inner barrier is then placed  into a PETG tray and sealed with Tyvek li', 'Possible Damage To The Vanguard Knee System As Tibial Bearing Caused During The Manufacturing Process.', 'Other', 'Not Specified', 'Possible damage to the Vanguard Knee System AS Tibial Bearing caused during the manufacturing process.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1607-2024');
