INSERT INTO safety_incidents VALUES ('2e6719d8824a9b0b79ed7babe64642ded15c7c1f', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'JAPAN DISP SET, 261J, 205J, HAR - Product Usage: its related accessory components are intended to be used for the recovery and processing of blood shed during or subsequent to an operation or as a result of trauma. The recovered blood is processed by a centrifugation and washing procedure before pum', 'Potential To Develop Leaks At The Inner Core Of Cell Saver¿ 5/5+ And Cell Saver¿ Elite¿/Elite¿ +125Ml And 225Ml Bowl Sets. Which Could Result In Fluid Being Trapped Inside The Bowl Core, Causing A Long Empty Device Error Message With The Possibility Of Incomplete Washing.', 'Entrapment', 'Not Specified', 'Potential to develop leaks at the inner core of Cell Saver¿ 5/5+ and Cell Saver¿ Elite¿/Elite¿ +125ml and 225ml bowl sets. Which could result in fluid being trapped inside the bowl core, causing a long empty device error message with the possibility of incomplete washing.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0900-2020');
INSERT INTO safety_incidents VALUES ('df2bda33bce2627295cdb25963540099aa1acac5', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'stryker 3.0MM Neuro Match Head, REF 5820-107-430, used to cut bone and bone cement during neurosurgery', 'There Is Potential The Device Inside The Package May Not Match The Product Information On The Outer Label (E.G., Label States 5820-107-430 But Package Contains A 5820-107-530 Device Or Vice Versa).', 'Other', 'Laceration / Cut', 'There is potential the device inside the package may not match the product information on the outer label (e.g., label states 5820-107-430 but package contains a 5820-107-530 device or vice versa).', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0981-2025');
