INSERT INTO safety_incidents VALUES ('6e759ae784d1f6a9b103442fc419c737d9b27140', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Avalon Elite Vascular Access Kit, Model No. 70106.3540, UDI 04037691831039', 'A Lot Of Avalon Elite Vascular Access Kits (Vak) Are Being Recalled Due To A Material Mix-Up With The Needle Portion Of The Kit; 81 Of 255 Kits Were Assembled With An Incorrect Arterial Access Needle Instead Of A  Multi-Purpose Procedure Needle.', 'Other', 'Not Specified', 'A lot of Avalon Elite Vascular Access Kits (VAK) are being recalled due to a material mix-up with the needle portion of the kit; 81 of 255 kits were assembled with an incorrect Arterial Access Needle instead of a  Multi-Purpose Procedure Needle.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1603-2020');
INSERT INTO safety_incidents VALUES ('08e4b01713e6044031d4d8e831127d1bae10fb2b', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Artis Q.zen floor, Model Number 10848353', 'If The Coolant Level In The Cooling Circuit Drops Below A Certain Level, This May Result In A Situation In Which The X-Ray Tube Is No Longer Sufficiently Cooled And The System Will Display The Message "Tube Hot, Have A Break". Several Minutes Later The System Will Block X-Ray To Prevent Further Damage And Display The Message "No Xray: Tube Too Hot".', 'Other', 'Not Specified', 'If the coolant level in the cooling circuit drops below a certain level, this may result in a situation in which the X-ray tube is no longer sufficiently cooled and the system will display the message "TUBE HOT, have a break". Several minutes later the system will block X-ray to prevent further damage and display the message "NO XRAY: TUBE TOO HOT".', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0978-2022');
INSERT INTO safety_incidents VALUES ('e04fe565713027a2f4e55b6a9199c3eb8e8594a8', 'FDA', '', 0, nan, 'USA', 'United States', 'United Kingdom', 'Medical Devices', 'Philips Tempus LS-Manual Defibrillator, Part Number: 00-3020', 'Defibrillator/Pacemaker Module (Dpm) May Encounter A Problem Causing Communication From The Mainboard  To The Dpm To Fail, Leading To No Or Ineffective Pacing With Displayed Error Message "Hw Failure Dpm".', 'Chemical / Toxic Substance', 'Not Specified', 'Defibrillator/pacemaker module (DPM) may encounter a problem causing communication from the Mainboard  to the DPM to fail, leading to no or ineffective pacing with displayed error message "HW failure DPM".', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1825-2023');
INSERT INTO safety_incidents VALUES ('c334db975e7d35b3acbfd65fdac9440a93045e1d', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Abbott Infinity 7, Implantable Pulse Generator, REF: 6663, SterileEO, Rx Only', 'Their Is A Potential That The Implantable Pulse Generator Replacement Indicator And End Of Service Date May Be Shorter Than Indicated In The Product Labeling Potentially  Resulting In Loss Of Therapy.', 'Other', 'Not Specified', 'Their is a potential that the implantable pulse generator replacement indicator and end of service date may be shorter than indicated in the product labeling potentially  resulting in loss of therapy.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-2432-2024');
