INSERT INTO safety_incidents VALUES ('5245148d1942f3f40e0bb959324e863f96d6da1a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Medtronic HVAD Controller, Product Numbers:  1400, 1401, 1401AU, 1401BR, 1401CA, 1401CH, 1401DE, 1401GB, 1401IL, 1401IN, 1401IT, 1401JP, 1401US, 1403US, 1407AR, 1407AU, 1407BR, 1407CA, 1407CA-CLIN, 1407CH, 1407DE, 1407GB, 1407IL, 1407IN, 1407IT, 1407JP, 1407KR', 'There Is The Potential For The Controller Power Cables (Ac Adapter, Dc Adapter, And Battery Cables), Hvad Alarm Adapter, And Hvad Monitor Data Cables To Cause Damage To The Hvad Controller Ports When Inserting The Cables Into The Controller Ports, Due To Wear  From Misalignment Of The Cables To The Port.', 'Other', 'Not Specified', 'There is the potential for the Controller power cables (AC Adapter, DC Adapter, and Battery cables), HVAD Alarm Adapter, and HVAD Monitor data cables to cause damage to the HVAD Controller ports when inserting the cables into the Controller ports, due to wear  from misalignment of the cables to the port.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1336-2021');
INSERT INTO safety_incidents VALUES ('3e25ab9998226ff6917fbb192846c545030aa054', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'CRTD DTMC2QQ COMPIA MRI QUAD OUS DF4, Model Number DTMC2QQ;  Implantable Cardioverter Defibrillators', 'There Is A Rare Potential For Reduced- Or No-Energy Output During High Voltage (Hv) Therapy (Typically 0-12J) In Implantable Cardioverter Defibrillators (Icds) And Cardiac Resynchronization Therapy Defibrillators (Crt-Ds) Manufactured With A Specific (Glassed) Feedthrough, Including Currently Available Icds And Crt-Ds.', 'Electrical Fault', 'Not Specified', 'There is a rare potential for reduced- or no-energy output during high voltage (HV) therapy (typically 0-12J) in implantable cardioverter defibrillators (ICDs) and cardiac resynchronization therapy defibrillators (CRT-Ds) manufactured with a specific (glassed) feedthrough, including currently available ICDs and CRT-Ds.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1773-2023');
INSERT INTO safety_incidents VALUES ('f86dd6cc3fe41abef372bc0113714a3cc9def746', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'Proxima Drape labeled as PACK,BASIC,SIRUS,V,5/CS; PACK,BASIC IV,SIRUS,5/CS; PACK,SET UP,NO DRAPE,12/CS; PACK,SET UP,NO DRAPE,12/CS; PACK,SET UP,NO DRAPE,12/CS; PACK,SET UP,NO DRAPE,12/CS; PACK,SET UP,NO DRAPE,12/CS; PACK,UNIVERSAL II,SIRUS,7/CS; PACK,LAPAROTOMY,NO GOWN,10/CS; PACK,CYSTOSCOPY,PK VI,1', 'Potential Breach In Pouch Packaging Which Could Lead To Loss Of Sterility.', 'Chemical / Toxic Substance', 'Not Specified', 'Potential breach in pouch packaging which could lead to loss of sterility.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1364-2025');
