INSERT INTO safety_incidents VALUES ('4520284e2126fa29b124693cb8aa7e2522f9a478', 'FDA', '2023-01-01', 2023, '2023-01', 'USA', 'United States', 'United States', 'Medical Devices', 'Medline manual resuscitators with integrated manometer, multiple accessory configurations to include:     1. Adult Resuscitator REF #s: CPRM1116FPM, CPRM1116FPM4, CPRM1116M, CPRM1116MC, CPRM1116PM, CPRM1116PMT, CPRM1126FM, CPRM1126FPM, CPRM1126FPWM, CPRM1126M;     2. Infant Resuscitator REF #s: CPRM', 'A Backwards Leak Present In The Integrated Manometer Of The Patient Valve Allows For Co2 Rebreathing.', 'Other', 'Respiratory', 'A backwards leak present in the integrated manometer of the patient valve allows for CO2 rebreathing.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-0369-2024');
