INSERT INTO safety_incidents VALUES ('ed169fcbdb69d668f9e525d0444261085dcf59ab', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Medical Devices', 'BD Pyxis: MedStation ES, REF: 323; Anesthesia Station ES, REF: 327; MedStation ES Tower, REF: 352;', 'Automated Dispensing Cabinets, Running Affected Software, And Windows 10 Operating System May Experience The Application Randomly Hang, Freeze And/Or Crash, Which May Result In Delays In Medication Access, And Potential Data Loss.', 'Other', 'Skin Irritation', 'Automated dispensing cabinets, running affected software, and Windows 10 operating system may experience the application randomly hang, freeze and/or crash, which may result in delays in medication access, and potential data loss.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'Z-1223-2024');
