INSERT INTO safety_incidents VALUES ('ce3863599835eaa381cf01165c06fbec88862a9a', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Food & Food Contact', 'Willamette Valley Pie Company Raspberry Rhubarb Pie, packaged in clamshells container, six containers per case.  Each pie weighs 10 oz. and sold as individual pies to consumers. UPC: 0 22518 87931 2.    The label on a clamshell container is read in parts: "***HANDMADE All-Natural Raspberry Rhubarb P', 'Raspberry Rhubarb Pie Packages Were Recalled Due To Undeclared Artificial Almond. The Actual Product Inside A Clamshell Package Is Cherry Pie, Which Contains Artificial Almond Extract, But It Was Mislabeled As Raspberry Rhubarb Pie.  The Rhubarb Pie Label Does Not Declare Artificial Almond Extract.', 'Allergen', 'Not Specified', 'Raspberry Rhubarb Pie packages were recalled due to undeclared artificial almond. The actual product inside a clamshell package is Cherry Pie, which contains artificial almond extract, but it was mislabeled as Raspberry Rhubarb Pie.  The Rhubarb Pie label does not declare artificial almond extract.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'F-0969-2020');
