INSERT INTO safety_incidents VALUES ('42aeba3d33723c822b5fb6e0104752caf2545a2c', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Food & Food Contact', 'Little Salad Bar Asian Chopped Salad Kit 12 oz., UPC 4099100086966,  Green & red cabbage, green leaf lettuce, carrots & green onions', 'Ready To Eat Salad Products Containing Iceberg Lettuce, Red Cabbage And/Or Carrot Ingredients Are Recalled Due To A Possible Health Risk From Cyclospora.', 'Other', 'Not Specified', 'Ready to Eat salad products containing iceberg lettuce, red cabbage and/or carrot ingredients are recalled due to a possible health risk from Cyclospora.', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'F-1111-2020');
INSERT INTO safety_incidents VALUES ('af39c0a3b8342d23c809ee6ea68bbfd274c082f6', 'FDA', '', 0, nan, 'USA', 'United States', 'United States', 'Food & Food Contact', 'HiPP HA Germany Hypoallergenic Stage PRE Combiotic Infant Milk Formula', 'The Required Pre-Market Notifications For These New  Infant Formulas Have Not Been Submitted To The Fda. Some Products Contain Less Than 1 Milligram Of Iron Per 100 Calories And May Not Provide Adequate Iron For Some Infants, Particularly Infants Born Prematurely Or With A Low Birth Weight, Had Low Iron Levels At Birth, Or Are At Risk For Becoming Iron Deficient Due To Illness. All Products Are Not Labeled As Required By 21 Cfr 107 .10 And 107.20 And Do Not Bear Mandatory Labeling Statements In English.', 'Allergen', 'Allergic Reaction', 'The required pre-market notifications for these new  infant formulas have not been submitted to the FDA. Some products contain less than 1 milligram of iron per 100 Calories and may not provide adequate iron for some infants, particularly infants born prematurely or with a low birth weight, had low iron levels at birth, or are at risk for becoming iron deficient due to illness. All products are not labeled as required by 21 CFR 107 .10 and 107.20 and do not bear mandatory labeling statements in ', 'Serious', 0, 0, 'Voluntary: Firm initiated', 'F-0910-2021');
